# ============================================================================
# 🧹 پاکسازیِ دیتا - صفحه‌ی «چی پاک می‌شه، کِی، و چقدر جا آزاد شد»
# ----------------------------------------------------------------------------
# موتورش db_cleanup.py ـه (همون حلقه‌ای که قبلاً بی‌صدا و بدونِ هیچ کنترلی از
# داخلِ ربات اجرا می‌شد). این صفحه سه چیز به ادمین می‌ده که قبلاً نداشت:
#   ۱) دیدنِ وضعیت: آخرین دور کِی بود، چقدر حذف شد، چقدر جا آزاد شد، دورِ بعدی کِی
#   ۲) تغییرِ فاصله‌ی پاکسازی (ساعت) - بدونِ ری‌استارت و بدونِ متغیرِ محیطی
#   ۳) اجرایِ فوریِ یه دور
# اعدادش *همون* اعدادِ پنلِ «📊 منابعِ سرور» ـه: هر دو از db_cleanup.state()/
# status_lines() می‌خونن، پس امکان نداره دو جا دو عدد نشون بدن.
# ============================================================================
DB_CLEANUP_TARGETS = [
    "ردیف‌هایِ اکانت‌هایِ حذف‌شده در همه‌ی جدول‌ها (یتیم‌ها)",
    "عضویتِ کانال‌هایی که دیگه در هیچ بخشی ثبت نیستن",
    "سفارش‌هایِ تمام‌شده‌یِ بازدید/ری‌اکشن/شیر، ۲۴ ساعت بعدِ تمام‌شدنشون "
    "(ردیفِ در انتظار هیچ‌وقت پاک نمی‌شه)",
    "تاریخچه‌یِ بازدیدکننده‌ها و دوره‌هایِ تمام‌شده",
    "لاگِ عملیات، بکاپ، فعالیتِ روزانه و پنجره‌هایِ آنلاینِ قدیمی",
    "جدول‌هایِ مرده‌ای که هیچ‌جای ربات ازشون استفاده نمی‌کنه",
]


async def _data_cleanup_text() -> str:
    """متنِ صفحه‌ی «🧹 پاکسازیِ دیتا»."""
    interval = await db_cleanup.current_interval_hours()
    st = db_cleanup.state()
    rep = st.get("report") or {}

    lines = [
        "🧹 پاکسازیِ دیتا",
        "",
        "ربات خودکار داده‌هایِ بی‌استفاده رو از دیتابیس پاک می‌کنه و فضایِ آزاد رو "
        "واقعاً به سیستم‌عامل برمی‌گردونه (auto_vacuum + جمع‌کردنِ فایلِ WAL) - "
        "یعنی هم حجمِ دیتابیس پایین می‌مونه، هم فضایِ دیسکِ سرور.",
        "",
        f"⏱ فاصله‌یِ فعلی: هر {db_cleanup._fmt_hours(interval)} یک‌بار",
        f"💾 حجمِ فعلیِ دیتابیس: {st['size_mb']:.1f} مگابایت (همون عددِ «📊 منابعِ سرور»)",
    ]
    if st.get("running"):
        lines.append("⏳ وضعیت: همین الان یه دور در جریانه...")
    elif st.get("next_at"):
        lines.append(f"⏭ دورِ بعدی: {fmt_tehran(st['next_at'], '%Y-%m-%d %H:%M')}")
    if not st.get("loop_alive"):
        lines.append("⚠️ حلقه‌یِ خودکارِ پاکسازی روشن نیست - با «🧹 پاکسازیِ فوری» "
                     "دستی اجراش کن و لاگِ راه‌اندازی رو چک کن.")

    lines += ["", "📋 آخرین دور:"]
    if not rep:
        lines.append("   هنوز اجرا نشده.")
    else:
        lines.append(f"   🕐 {rep.get('at', '؟')} ({rep.get('source', 'خودکار')}"
                     + (f" · {rep['duration_seconds']:g} ثانیه" if rep.get("duration_seconds") else "")
                     + ")")
        lines.append(f"   🗑 {rep.get('total_deleted', 0):,} ردیف حذف شد "
                     f"({rep.get('total_orphans', 0):,} ردیفِ یتیم)")
        lines.append(f"   💾 حجم: {rep.get('size_before_mb', 0)} → "
                     f"{rep.get('size_after_mb', 0)} مگابایت "
                     f"({rep.get('freed_mb', 0)} آزاد شد)")
        lines.extend(db_cleanup._report_detail_lines(rep))

    if st.get("runs"):
        lines += [
            "",
            f"📈 از شروعِ این اجرا: {st['runs']} دور "
            f"({st.get('manual_runs', 0)} دستی) · {st.get('deleted_total', 0):,} ردیف · "
            f"{st.get('freed_mb_total', 0)} مگابایت آزاد شد",
        ]
    if st.get("defers"):
        lines.append(f"⏸ {st['defers']} بار به‌خاطرِ فشارِ سرور عقب افتاد "
                     f"(آستانه {int(db_cleanup.DEFER_AT_PRESSURE * 100)}٪ - "
                     "پاکسازی وسطِ اوجِ مصرف اجرا نمی‌شه)")
    if st.get("last_error"):
        lines.append(f"⚠️ آخرین خطا: {str(st['last_error'])[:120]}")

    lines += ["", "🧾 چی پاک می‌شه:"]
    lines.extend(f"   • {item}" for item in DB_CLEANUP_TARGETS)
    lines += [
        "",
        "🔒 چی هیچ‌وقت پاک نمی‌شه: اکانت‌ها، کانال‌ها، تنظیمات، سفارش‌هایِ در انتظار، "
        "و لاگِ اکانت‌هایِ حذف‌شده (برایِ بازیابی/حسابرسی).",
    ]
    return "\n".join(lines)


def _data_cleanup_keyboard() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🧹 پاکسازیِ فوری", callback_data="dbclean_run")],
        [InlineKeyboardButton("⏱ تغییرِ فاصله‌یِ پاکسازی", callback_data="dbclean_interval")],
        [InlineKeyboardButton("🔄 به‌روزرسانیِ وضعیت", callback_data="dbclean_refresh")],
    ])


ACCOUNTS_PAGE_SIZE = 20


_ACCOUNT_SOURCE_LABELS = {
    "manual": "👤 اکانت‌هایِ دستی (شماره+کد)",
    "session": "📥 اکانت‌هایِ سشن (فایل)",
}


async def build_accounts_menu(page: int = 0, source_filter: str = "manual", order_desc: bool = True):
    """لیستِ اکانت‌هایِ *یک* دسته (manual یا session - نگاه کن به _ACCOUNT_SOURCE_LABELS)
    به‌صورتِ inline (چون هرکدوم باید مقصدِ خودشو داشته باشه). دکمه‌هایِ عملیاتِ ثابت
    (افزودن/سلامت/پاکسازی/بازگشت) جدا، به‌صورتِ کیبوردِ پایینِ صفحه‌ن - نه شیشه‌ای -
    نگاه کن به accounts_action_keyboard/send_accounts_menu.

    صفحه‌بندی: جدیدترین اکانت‌ها (بزرگ‌ترین id) اول نشون داده می‌شن. «صفحه‌یِ قبلی»
    یعنی برو عقب‌تر در زمان (اکانت‌هایِ قدیمی‌تر)، «صفحه‌یِ بعدی» برگرد به جدیدترها.
    """
    label = _ACCOUNT_SOURCE_LABELS[source_filter]
    accounts = await get_all_accounts()
    accounts = [a for a in accounts if (a.get("source") or "manual") == source_filter]
    if not accounts:
        return f"{label}\nهیچ اکانتی توی این دسته نیست.", None

    # ترتیبِ پیش‌فرض: جدیدترین به قدیمی‌ترین. با دکمه‌ی «🔃 ترتیب» این حالت برعکس می‌شود.
    accounts = sorted(accounts, key=lambda a: int(a.get("id") or 0), reverse=order_desc)
    total = len(accounts)
    total_pages = max(1, -(-total // ACCOUNTS_PAGE_SIZE))
    page = max(0, min(page, total_pages - 1))
    start = page * ACCOUNTS_PAGE_SIZE
    page_accounts = accounts[start:start + ACCOUNTS_PAGE_SIZE]

    kb = []
    for acc in page_accounts:
        # فریزشده همیشه قرمزه، حتی اگه is_logged_in هنوز True باشه - چون فریز یعنی
        # سشن معتبره ولی تلگرام جلویِ اکثرِ عملیات‌ها رو گرفته (نگاه کن به
        # database.set_account_frozen و telethon_handler.is_frozen_error).
        status = "❌" if (not acc["is_logged_in"] or acc.get("is_frozen")) else "✅"
        flag = acc.get("country_flag") or ""
        # نشانگرِ رنگی: اگه هر ۵ تسکِ امنیتی/آماده‌سازی (2FA/hint/ایمیلِ بازیابی/
        # ایمیلِ لاگین/پروفایل) رویِ این اکانت انجام شده باشه، سبز (🟢)؛ وگرنه
        # بی‌رنگ/خنثی (⚪) - نگاه کن به database._TASK_COLUMNS و show_account_detail.
        all_done = all([
            acc.get("task_2fa_done"), acc.get("task_hint_done"),
            acc.get("task_recovery_email_done"), acc.get("task_login_email_done"),
            acc.get("task_profile_done"),
        ])
        color_marker = "🟢" if all_done else "⚪"
        kb.append([InlineKeyboardButton(
            f"{color_marker} {status} {flag} {acc['nickname'] or acc['phone']}",
            callback_data=f"acc_view_{acc['id']}"
        )])

    if total_pages > 1:
        nav_row = []
        if page > 0:
            nav_row.append(InlineKeyboardButton("⬅️ صفحه قبلی", callback_data=f"acc_page_{source_filter}_{page - 1}"))
        if page < total_pages - 1:
            nav_row.append(InlineKeyboardButton("➡️ صفحه بعدی", callback_data=f"acc_page_{source_filter}_{page + 1}"))
        if nav_row:
            kb.append(nav_row)

    kb.append([InlineKeyboardButton(
        "🔃 ترتیب",
        callback_data=f"acc_order_{source_filter}"
    )])

    order_label = "جدیدترین → قدیمی‌ترین" if order_desc else "قدیمی‌ترین → جدیدترین"
    text = f"{label} ({total} عدد - صفحه‌یِ {page + 1} از {total_pages} - هر صفحه {ACCOUNTS_PAGE_SIZE} اکانت)\nترتیب: {order_label}"
    return text, InlineKeyboardMarkup(kb)


_SESSION_WIZARD_CANCEL = "⏹ انصراف - فقط اکانت‌ها اضافه بشن"

# ---------------------------------------------------------------------------
# تشخیصِ *مقاومِ* دکمه‌هایِ ناوبری (بازگشت/انصراف)
#
# باگی که این‌جا حل می‌شه: مقایسه‌یِ تحت‌اللفظیِ `text == "🔙 بازگشت"` فقط وقتی جواب
# می‌داد که متن **دقیقاً** با ایموجی و فاصله‌یِ درست برسه. ولی کاربر ممکنه کلمه رو
# دستی تایپ کنه، یا ایموجی موقعِ کپی/پیست بیفته، یا فاصله‌یِ بینِ ایموجی و کلمه نباشه.
# اون‌وقت متن به شاخه‌یِ ناوبری نمی‌رسید و می‌افتاد دستِ هندلرِ *مقدار* - یعنی کلمه‌یِ
# «بازگشت» به‌عنوانِ رمزِ دومرحله‌ای/هینت/ایمیل/یوزرنیمِ کانال ثبت می‌شد.
#
# راهِ‌حل: متن رو به یه شکلِ متعارف برمی‌گردونیم (ایموجی/نیم‌فاصله/اعرابِ فارسی حذف،
# ی و ک عربی به فارسی، فاصله‌هایِ اضافه جمع) و بعد مقایسه می‌کنیم.
# ---------------------------------------------------------------------------

_NAV_STRIP_RE = re.compile(
    "[\U0001F000-\U0001FAFF\u2190-\u21FF\u2300-\u27BF\uFE00-\uFE0F\u200c\u200f\u200e]"
)
_NAV_DIACRITICS_RE = re.compile("[\u064B-\u0652\u0640]")


def _normalize_nav_text(text: str) -> str:
    """متنِ یه دکمه‌یِ ناوبری رو به شکلِ متعارفش برمی‌گردونه."""
    if not text:
        return ""
    t = _NAV_STRIP_RE.sub(" ", text)
    t = _NAV_DIACRITICS_RE.sub("", t)
    t = t.replace("ي", "ی").replace("ك", "ک").replace("ۀ", "ه").replace("ة", "ه")
    return " ".join(t.split()).strip()


def _matches_button(text: str, label: str) -> bool:
    """
    مقایسه‌ی متنِ دریافتی با برچسبِ یه دکمه‌یِ ثابت - نرمالایزشده، نه == خام.

    ⚠️ باگی که این‌جا حل شده: مقایسه‌یِ نرمالایزشده (بی‌حساسیت به وجود/عدمِ
    variation-selectorِ ایموجی، نیم‌فاصله، یا حروفِ عربی/فارسی) قبلاً فقط برایِ
    دکمه‌هایِ «بازگشت»/«انصراف» انجام می‌شد. بقیه‌یِ دکمه‌هایِ ثابتِ ویزاردها (مثلِ
    «🔓 بدونِ رمز»، گزینه‌هایِ کارهایِ خودکار، انتخابِ مهاجرتِ سشن) با == خام مقایسه
    می‌شدن - اگه کیبوردِ گوشیِ کاربر همون ایموجی رو با بایت‌هایِ کمی فرق‌دار
    می‌فرستاد، دکمه بی‌صدا هیچ کاری نمی‌کرد (نه خطا، نه واکنش) و دقیقاً مثلِ یه
    دکمه‌یِ خراب/الکی به‌نظر می‌رسید. الان همه‌ی این مقایسه‌ها از همینْ یه تابع
    استفاده می‌کنن.
    """
    return _normalize_nav_text(text) == _normalize_nav_text(label)


# همه‌ی شکل‌هایِ «بازگشت» که توی ربات به‌عنوانِ دکمه استفاده می‌شن
_NAV_BACK_TEXTS = frozenset({
    "بازگشت",
    "بازگشت به منو",
    "بازگشت به منوی قبلی",
    "بازگشت به لیست",
    "بازگشت به تنظیمات",
    "بازگشت به انتخاب",
    "بازگشت به دسته ها",
    "بازگشت به دستهها",
})


def _is_back_text(text: str) -> bool:
    """آیا این متن یعنی «بازگشت»؟ - بدونِ حساسیت به ایموجی/فاصله/نیم‌فاصله."""
    return _normalize_nav_text(text) in _NAV_BACK_TEXTS


def _is_wizard_cancel_text(text: str) -> bool:
    """آیا این متن یعنی «انصراف - فقط اکانت‌ها اضافه بشن»؟"""
    return _normalize_nav_text(text) == _normalize_nav_text(_SESSION_WIZARD_CANCEL)


def _looks_like_email(value: str) -> bool:
    """یه اعتبارسنجیِ سبک - جلویِ اشتباهاتِ آشکار (فاصله، نبودِ @ یا دامنه) رو می‌گیره."""
    if not value or len(value) > 254:
        return False
    if any(ch.isspace() for ch in value):
        return False
    return bool(re.fullmatch(r"[^@]+@[^@]+\.[A-Za-z]{2,}", value))


def _is_nav_text(text: str) -> bool:
    """هر متنی که «ناوبری» است و هیچ‌وقت نباید به‌عنوانِ *مقدار* ثبت بشه."""
    return _is_back_text(text) or _is_wizard_cancel_text(text)

# مرحله‌هایِ ویزاردِ «📥 افزودن با فایلِ سشن» که *بعد* از آپلودِ فایل‌ها میان. توی همه‌یِ
# این مرحله‌ها فایل‌هایِ سشن از قبل روی دیسک جمع شدن، پس نه «بازگشت» و نه «انصراف»
# نباید اونا رو دور بریزه - نگاه کن به _session_wizard_step_back و
# _cancel_session_wizard_and_import.
