def _session_auto_tasks_keyboard():
    """کیبوردِ انتخابِ اینکه بعدِ افزودنِ موفقِ هر اکانت، کدوم کارهایِ خودکار
    (تغییرِ پروفایل / تغییرِ رمزِ دومرحله‌ای) هم بلافاصله روش انجام بشه."""
    kb = [
        ["✅ بله - پروفایل + رمزِ دومرحله‌ای"],
        ["🖼 فقط تغییرِ پروفایل"],
        ["🔐 فقط تغییرِ رمزِ دومرحله‌ای"],
        ["⏭ نه، فقط افزودن"],
        [_SESSION_WIZARD_CANCEL],
        ["🔙 بازگشت"],
    ]
    return ReplyKeyboardMarkup(kb, resize_keyboard=True)


_SESSION_MIGRATE_YES = "✅ بله - سشنِ جدید بساز و قدیمی رو باطل کن"
_SESSION_MIGRATE_NO = "⏭ نه، همون سشنِ وارد‌شده کافیه"


def _session_migrate_choice_keyboard():
    """کیبوردِ سؤالِ امنیتیِ آخرِ ویزاردِ ایمپورت - مهاجرتِ سشن."""
    return ReplyKeyboardMarkup(
        [[_SESSION_MIGRATE_YES], [_SESSION_MIGRATE_NO], [_SESSION_WIZARD_CANCEL], ["🔙 بازگشت"]],
        resize_keyboard=True,
    )


def _staged_session_count(context) -> int:
    """تعدادِ فایل‌هایِ .session که تا الان توی پوشه‌یِ staging جمع شدن."""
    staging = context.user_data.get("session_staging_dir")
    if not staging or not os.path.isdir(staging):
        return 0
    try:
        return len([f for f in os.listdir(staging) if f.endswith(".session")])
    except Exception:
        return 0


def _staged_sessions_all_have_json_password(context) -> bool:
    """
    آیا *همه‌ی* سشن‌هایِ آماده، کنارشون یه فایلِ هم‌نامِ .json با رمزِ دومرحله‌ای دارن؟

    اگه آره، پرسیدنِ رمز از ادمین کاملاً بی‌فایده‌ست: رمزِ اختصاصیِ خودِ هر اکانت از
    همون json خونده می‌شه و در اولویتِ اوله (نگاه کن به _import_one_session_file).
    پس اون مرحله رو کامل رد می‌کنیم. اگه حتی یه سشن رمزِ json نداشته باشه، مرحله
    نشون داده می‌شه - چون ممکنه همون یکی به رمزِ مشترکِ دستی نیاز داشته باشه.
    """
    staging = context.user_data.get("session_staging_dir")
    if not staging or not os.path.isdir(staging):
        return False
    try:
        names = [f for f in os.listdir(staging) if f.endswith(".session")]
    except Exception:
        return False
    if not names:
        return False
    for name in names:
        json_path = os.path.join(staging, name[:-len(".session")] + ".json")
        meta = parse_session_json(json_path)
        if not (meta or {}).get("twofa_password"):
            return False
    return True


