async def _prompt_2fa_current_password(message):
    """قدمِ تازه‌یِ ویزارد: پرسیدنِ رمزِ *فعلیِ* اکانت‌هایی که ممکنه از قبل رمزِ
    دومرحله‌ای داشته باشن - تا تغییرِ رمز رویِ اونا هم جواب بده، نه فقط اکانت‌هایِ
    بدونِ رمز."""
    await message.reply_text(
        "🔐 اگه بعضی از اکانت‌ها از قبل رمزِ دومرحله‌ای دارن و می‌خوای رمزِ اونا رو "
        "هم عوض کنی، رمزِ *فعلیِ* مشترکشون رو بفرست.\n\n"
        "اگه نمی‌دونی یا مطمئن نیستی، «فارغ» رو بفرست - در این حالت، تغییرِ رمز "
        "فقط رویِ اکانت‌هایی جواب می‌ده که از قبل اصلاً رمز نداشته باشن.",
        reply_markup=_session_wizard_step_keyboard()
    )


async def _goto_2fa_current_password_step(message, context):
    """
    ورود به قدمِ «رمزِ فعلیِ دومرحله‌ای».

    اگه رمزِ *همه‌ی* سشن‌ها از قبل توی فایلِ jsonِ کنارِ خودشون بوده، این سؤال
    بی‌فایده‌ست و رد می‌شه: موقعِ ایمپورت، رمزِ اختصاصیِ هر اکانت جدا توی ستونِ
    twofa_password ذخیره شده و change_2fa.process_next_account همون رو در
    *اولویتِ اول* امتحان می‌کنه - یعنی هر اکانت دقیقاً با رمزِ خودش پیش می‌ره،
    حتی اگه رمزِ هر فایل با بقیه فرق داشته باشه. رمزِ مشترکِ دستی فقط یه
    fallback ه که این‌جا اصلاً لازم نیست.
    """
    if _staged_sessions_all_have_json_password(context):
        context.user_data["session_auto_2fa_current_password"] = None
        context.user_data["awaiting"] = "session_auto_2fa_password"
        await message.reply_text(
            "🔑 رمزِ دومرحله‌ایِ فعلیِ هر اکانت از فایلِ jsonِ خودش برداشته می‌شه - "
            "نیازی به واردکردنِ دستی نیست."
        )
        await _prompt_session_2fa_new_password(message)
        return
    context.user_data["awaiting"] = "session_auto_2fa_current_password"
    await _prompt_2fa_current_password(message)


async def _apply_session_profile_channel(message, context, channel_ref):
    """کانالِ انتخاب‌شده برایِ «🖼 تغییرِ پروفایلِ خودکار» رو ثبت می‌کنه و ویزارد رو یه
    قدم جلو می‌بره. هم هندلرِ متن و هم هندلرِ سند ازش استفاده می‌کنن - تا فورواردکردنِ
    یه پستِ عکس/فایل از کانال دقیقاً مثلِ فورواردِ یه پستِ متنی کار کنه."""
    context.user_data["session_auto_profile_channel"] = channel_ref
    tasks = context.user_data.get("session_auto_tasks") or {}
    if tasks.get("twofa"):
        await _goto_2fa_current_password_step(message, context)
    else:
        context.user_data["awaiting"] = "session_auto_migrate_choice"
        await _prompt_session_migrate_choice(message)


async def _session_wizard_step_back(update, context):
    """
    «🔙 بازگشت» داخلِ ویزاردِ «📥 افزودن با فایلِ سشن» = دقیقاً یک قدم عقب، بدونِ
    دورریختنِ فایل‌هایِ آپلودشده.

    قبلاً این دکمه به هندلرِ عمومیِ بازگشت می‌رسید و _go_back کلِ پوشه‌یِ staging رو
    پاک می‌کرد - یعنی همه‌یِ فایل‌هایِ فرستاده‌شده از دست می‌رفت و کاربر باید از صفر
    دوباره آپلود می‌کرد. (شاخه‌هایِ «🔙 بازگشت» که داخلِ خودِ مرحله‌ها نوشته شده بودن
    هیچ‌وقت اجرا نمی‌شدن، چون هندلرِ عمومی بالاترشون بود و اول می‌گرفتشون.)
    """
    awaiting = context.user_data.get("awaiting")
    tasks = context.user_data.get("session_auto_tasks") or {}

    if awaiting == "session_2fa_password":
        context.user_data["awaiting"] = "session_file_upload"
        await _prompt_session_upload_step(update.message, _staged_session_count(context))
        return

    if awaiting == "session_auto_tasks_choice":
        # اگه مرحله‌یِ رمزِ ایمپورت رد شده بود (رمزها از json خونده می‌شن)، بازگشت
        # نباید کاربر رو ببره به همون مرحله‌یِ ردشده - یه قدم عقب‌تر می‌ریم
        if _staged_sessions_all_have_json_password(context):
            context.user_data["awaiting"] = "session_file_upload"
            await _prompt_session_upload_step(update.message, _staged_session_count(context))
            return
        context.user_data["awaiting"] = "session_2fa_password"
        await _prompt_session_password_step(update.message, _staged_session_count(context))
        return

    if awaiting == "session_auto_profile_channel":
        context.user_data["awaiting"] = "session_auto_tasks_choice"
        await _prompt_session_auto_tasks(update.message)
        return

    if awaiting == "session_auto_2fa_current_password":
        if tasks.get("profile"):
            context.user_data["awaiting"] = "session_auto_profile_channel"
            await _prompt_session_profile_channel(update.message)
        else:
            context.user_data["awaiting"] = "session_auto_tasks_choice"
            await _prompt_session_auto_tasks(update.message)
        return

    if awaiting == "session_auto_2fa_password":
        # اگه مرحله‌یِ «رمزِ فعلی» رد شده بود (رمزها از json خونده می‌شن)، بازگشت
        # نباید کاربر رو توی همون مرحله‌یِ ردشده گیر بندازه - یه قدم عقب‌ترش می‌ریم
        if _staged_sessions_all_have_json_password(context):
            if tasks.get("profile"):
                context.user_data["awaiting"] = "session_auto_profile_channel"
                await _prompt_session_profile_channel(update.message)
            else:
                context.user_data["awaiting"] = "session_auto_tasks_choice"
                await _prompt_session_auto_tasks(update.message)
            return
        context.user_data["awaiting"] = "session_auto_2fa_current_password"
        await _prompt_2fa_current_password(update.message)
        return

    if awaiting == "session_auto_2fa_hint":
        context.user_data["awaiting"] = "session_auto_2fa_password"
        await _prompt_session_2fa_new_password(update.message)
        return

    if awaiting == "session_auto_2fa_recovery_email":
        context.user_data["awaiting"] = "session_auto_2fa_hint"
        await _prompt_session_2fa_hint(update.message)
        return

    if awaiting == "session_auto_migrate_choice":
        if tasks.get("twofa"):
            context.user_data["awaiting"] = "session_auto_2fa_recovery_email"
            await _prompt_session_2fa_recovery_email(update.message)
        elif tasks.get("profile"):
            context.user_data["awaiting"] = "session_auto_profile_channel"
            await _prompt_session_profile_channel(update.message)
        else:
            context.user_data["awaiting"] = "session_auto_tasks_choice"
            await _prompt_session_auto_tasks(update.message)
        return


async def _cancel_session_wizard_and_import(update, context):
    """
    «⏹ انصراف» وسطِ ویزاردِ «📥 افزودن با فایلِ سشن».

    انصراف یعنی «بقیه‌یِ سؤال‌ها رو نپرس»، نه «همه‌چی رو دور بریز»: فایل‌هایِ سشنی که
    تا اینجا آپلود شدن همین‌جا وارد می‌شن و اکانت‌ها واقعاً ساخته می‌شن؛ فقط کارهایِ
    خودکارِ بعدش (تغییرِ پروفایل / تغییرِ رمزِ دومرحله‌ای / تعویضِ سشن) انجام نمی‌شن.
    همون کارها بعداً از «⚙️ تنظیمات ← 📱 اکانت‌ها ← ⚙️ تنظیماتِ اکانت» رویِ همین
    اکانت‌ها قابلِ اجرا هستن.
    """
    for key in (
        "session_auto_tasks", "session_auto_profile_channel",
        "session_auto_2fa_current_password", "session_auto_2fa_new_password",
        "session_auto_2fa_hint", "session_auto_2fa_recovery_email",
        "session_auto_migrate",
    ):
        context.user_data.pop(key, None)

    if not _staged_session_count(context):
        staging = context.user_data.pop("session_staging_dir", None)
        if staging and os.path.isdir(staging):
            shutil.rmtree(staging, ignore_errors=True)
        context.user_data.pop("awaiting", None)
        context.user_data.pop("session_import_password", None)
        await update.message.reply_text("⏹ ویزارد بسته شد - هیچ فایلی برایِ افزودن نبود.")
        await send_accounts_menu(update.message, context=context)
        return

    await update.message.reply_text(
        "⏹ باشه - بقیه‌یِ سؤال‌ها رو رد می‌کنم.\n\n"
        f"همون {_staged_session_count(context)} فایلی که تا الان فرستادی همین‌جا وارد "
        "می‌شن و اکانت‌ها ساخته می‌شن؛ هیچ‌کدوم از کارهایِ خودکار (تغییرِ پروفایل، "
        "تغییرِ رمزِ دومرحله‌ای، تعویضِ سشن) انجام نمی‌شه.\n\n"
        "هر وقت خواستی، همونا رو از «⚙️ تنظیمات ← 📱 اکانت‌ها ← ⚙️ تنظیماتِ اکانت» "
        "رویِ همین اکانت‌ها اجرا کن."
    )
    password = context.user_data.get("session_import_password")
    await _run_staged_session_import(update, context, password=password)


async def _prompt_session_migrate_choice(message):
    """پرسشِ آخرِ ویزاردِ «📥 افزودن با فایلِ سشن» - قبلِ اینکه واقعاً ایمپورت اجرا بشه."""
    await message.reply_text(
        "🔒 یه سؤالِ امنیتیِ آخر:\n\n"
        "می‌خوای برایِ هر اکانتِ تازه‌واردشده، ربات خودش یه سشنِ کاملاً جدید بسازه و "
        "بعدش سشنِ قدیمی (همونی که همین الان وارد کردی) رو باطل کنه؟ این کار جلویِ "
        "دسترسیِ هر کسِ دیگه‌ای که ممکنه از قبل یه کپی از همین فایلِ سشن رو داشته "
        "باشه (مثلاً منبعی که ازش گرفتیش) رو می‌گیره.\n\n"
        "⏳ توجه: تلگرام به سشن‌هایِ تازه‌ساخته‌شده تا ۲۵ ساعت اجازه‌یِ بستنِ نشست‌هایِ "
        "دیگه رو نمی‌ده - پس ربات اولین تلاش برایِ بستنِ سشنِ قدیمی رو حدودِ ۲۵ ساعتِ "
        "دیگه انجام می‌ده، و اگه نشد، هر ۱ ساعت دوباره امتحان می‌کنه تا بالاخره "
        "موفق بشه - همینجا بهت خبر می‌ده، هیچ کاری لازم نیست دستی انجام بدی.\n\n"
        "⚠️ محدودیتِ فعلی: اکانت‌هایِ دارایِ رمزِ دومرحله‌ای که رمزشون رو نداریم، این "
        "مرحله رو رد می‌کنن (بدونِ اینکه به بقیه‌یِ کارهاشون آسیبی بزنه).",
        reply_markup=_session_migrate_choice_keyboard()
    )


