def account_settings_keyboard():
    """کیبوردِ زیرمنویِ «⚙️ تنظیماتِ اکانت» - عملیات‌هایِ تغییرِ پروفایل/تغییرِ رمزِ
    دومرحله‌ای/تغییرِ ایمیلِ لاگین که قبلاً مستقیم توی منویِ اکانت‌ها بودن، الان همه
    زیرِ همین یه گزینه جمع شدن. («حریمِ خصوصیِ رندوم» عمداً این‌جا نیست - اون یه
    قابلیتِ خودکارِ پس‌زمینه‌ست، زیرِ «🎭 رفتارِ اکانت‌ها»، نه یه عملیاتِ دستی.)"""
    kb = [
        ["🖼 تغییرِ پروفایل"],
        ["🔐 تغییرِ رمزِ دومرحله‌ای"],
        ["📧 تغییرِ ایمیلِ لاگین"],
        ["🧩 ساخت سشن زاپاس"],
        ["🔙 بازگشت"],
    ]
    return ReplyKeyboardMarkup(kb, resize_keyboard=True)


class ChatCleanupSession:
    """نشستِ موقت برایِ انتخاب و اجرایِ پاک‌کردنِ چت‌ها روی چند اکانت.

    لیستِ انتخاب به دو دسته‌یِ جدا (دستی/سشنی) تقسیم می‌شه - هرکدوم صفحه‌بندی و
    ترتیبِ مستقلِ خودشو داره (page_manual/page_session)، ولی selected_accounts
    مشترک و ترکیبیه (هر اکانتی از هرکدوم از دو لیست انتخاب بشه، توی همین یه لیست
    جمع می‌شه) - نگاه کن به _build_chat_cleanup_selector_source."""
    def __init__(self):
        self.selected_accounts: list = []
        self.identity_cache: dict = {}
        self.page_manual: int = 0
        self.page_session: int = 0
        self.order_desc: bool = True
        self.running: bool = False
        self.started_at: float | None = None
        self.selection_message_id = None
        self.live_state: dict = {}
        self.status_message = None
        self.last_publish_at: float = 0.0


def _account_order_key_for_prefix(prefix: str) -> str:
    """کلیدِ ذخیره‌یِ وضعیتِ ترتیبِ لیستِ اکانت‌ها را از prefix استخراج می‌کند."""
    base = prefix.rstrip("_")
    return base.replace("_sel_", "_order_")


def _account_order_desc(context, key: str, default: bool = True) -> bool:
    """ترتیبِ جاریِ یک لیست را برای همین کاربر برمی‌گرداند."""
    return bool(context.user_data.get(key, default))


def _toggle_account_order(context, key: str) -> bool:
    """ترتیب را برای همین کاربر عوض می‌کند و مقدارِ جدید را برمی‌گرداند."""
    new_value = not _account_order_desc(context, key, True)
    context.user_data[key] = new_value
    return new_value


def _chat_cleanup_session(context) -> ChatCleanupSession:
    session = context.user_data.get("chat_cleanup_session")
    if not isinstance(session, ChatCleanupSession):
        session = ChatCleanupSession()
        context.user_data["chat_cleanup_session"] = session
    return session


def _chat_cleanup_selector_text(source_filter: str, total_accounts: int, selected_count_total: int, page: int, total_pages: int, order_desc: bool) -> str:
    """متنِ سرصفحه‌یِ *یکی* از دو لیستِ انتخابِ پاک‌کردنِ چت (دستی یا سشنی) -
    نگاه کن به _build_chat_cleanup_selector_source. selected_count_total تعدادِ
    کلِ انتخاب‌شده‌ها روی *هر دو* لیست هست، نه فقط همین یکی - تا کاربر همیشه
    بدونه روی‌همرفته چند اکانت انتخاب کرده."""
    label = _ACCOUNT_SOURCE_LABELS[source_filter]
    order_label = "جدیدترین → قدیمی‌ترین" if order_desc else "قدیمی‌ترین → جدیدترین"
    return f"""🗂 پاک کردن چت‌ها — {label}

کلِ این دسته: {total_accounts}
انتخاب‌شده (هر دو دسته): {selected_count_total}
صفحه‌یِ فعلی: {page + 1} از {total_pages}
ترتیب: {order_label}

اکانت‌هایی را که می‌خواهی چت‌های قبلی‌شان پاک شود انتخاب کن (یا با «☑️ انتخابِ همه» یک‌جا همه‌یِ همین دسته را انتخاب کن).
بعد از انتخاب از هر دو لیست (دستی و سشنی)، پایینِ پیام‌ها «✅ ادامه» را بزن.
تمامِ کانال‌ها، گروه‌ها، ربات‌ها و چت‌هایِ خصوصیِ هر اکانت پاک می‌شوند.
Saved Messages و چت‌های رسمیِ تلگرام پاک نمی‌شوند."""


def _chat_cleanup_confirm_text(session: ChatCleanupSession) -> str:
    labels = []
    for acc in session.selected_accounts[:12]:
        name = acc.get("nickname") or acc.get("phone") or f"#{acc.get('id')}"
        labels.append(f"• {name}")
    extra = ""
    if len(session.selected_accounts) > 12:
        extra = f"\n… و {len(session.selected_accounts) - 12} اکانتِ دیگر"
    label_block = "\n".join(labels) if labels else "• هیچ اکانتی انتخاب نشده"
    return f"""🗂 تاییدِ پاک کردنِ چت‌ها

تعدادِ اکانت‌هایِ انتخاب‌شده: {len(session.selected_accounts)}

{label_block}{extra}

این کار تمامِ کانال‌ها، گروه‌ها، ربات‌ها و چت‌هایِ خصوصیِ این اکانت‌ها را حذف می‌کند
و فقط Saved Messages / چت‌های رسمیِ تلگرام را نگه می‌دارد.
اکانت‌ها تا {_CC_ACCOUNT_CONCURRENCY} تایِ هم‌زمان پردازش می‌شوند تا سریع‌تر تمام شود.
بعد از شروع، آمارِ لحظه‌ایِ کامل (تعدادِ حذف‌شده، تاریخِ شروع، و...) را می‌بینی و ربات هم‌زمان قابلِ استفاده می‌ماند.

شروع شود؟"""


def _chat_cleanup_running_keyboard():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 آپدیت آمار", callback_data="cc_refresh")]
    ])


def _format_duration_seconds(seconds: float) -> str:
    seconds = max(0, int(seconds))
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    parts = []
    if h:
        parts.append(f"{h} ساعت")
    if m:
        parts.append(f"{m} دقیقه")
    if not parts:
        parts.append(f"{s} ثانیه")
    return " و ".join(parts)


def _cc_progress_bar(percent: float, width: int = 12) -> str:
    """نوارِ پیشرفتِ متنی برایِ بخشِ «پاک کردن چت‌ها» - کاراکترِ بلوکِ یکدست (نه ایموجی)
    تا با تراکمِ اطلاعاتِ این پیام همخونی داشته باشه. اسمش عمداً جدا از
    ``_progress_bar`` (که برایِ نمودارِ ویو با ایموجیِ رنگی استفاده می‌شه) نگه داشته
    شده تا با اون تداخل نکنه."""
    percent = max(0.0, min(100.0, percent))
    filled = int(round((percent / 100.0) * width))
    filled = max(0, min(width, filled))
    return "█" * filled + "░" * (width - filled)


class _SilentEditTarget:
    """برایِ این عملیات فقط همان یک پیام را ویرایش می‌کند و هرگز پیامِ جدید نمی‌سازد."""
    def __init__(self, message):
        self.message = message

    async def edit_message_text(self, text, reply_markup=None):
        try:
            self.message = await self.message.edit_text(text, reply_markup=reply_markup)
        except Exception:
            pass


async def _build_chat_cleanup_selector_source(context, session: ChatCleanupSession, source_filter: str, page: int | None = None):
    """ساختِ متن+کیبوردِ *یکی* از دو لیستِ انتخابِ پاک‌کردنِ چت (source_filter یعنی
    "manual" یا "session") - نگاه کن به _chat_cleanup_action_keyboard برایِ
    دکمه‌هایِ مشترکِ «✅ ادامه»/«🔙 بازگشت» که جدا، توی یه پیامِ سوم نشون داده می‌شن."""
    accounts = await get_all_accounts()
    accounts = [a for a in accounts if (a.get("source") or "manual") == source_filter]
    order_key = "cc_order_manual" if source_filter == "manual" else "cc_order_session"
    order_desc = _account_order_desc(context, order_key, True)
    page_attr = "page_manual" if source_filter == "manual" else "page_session"
    if page is None:
        page = getattr(session, page_attr)
    prefix = f"cc_sel_{source_filter}_"
    select_all_cb = f"cc_selectall_{source_filter}"
    markup, page, total_pages = await _build_2fa_account_keyboard(
        session,
        accounts,
        prefix,
        None,
        None,
        fetch_identity=False,
        page=page,
        order_desc=order_desc,
        select_all_cb=select_all_cb,
    )
    setattr(session, page_attr, page)
    text = _chat_cleanup_selector_text(source_filter, len(accounts), len(session.selected_accounts), page, total_pages, order_desc)
    return text, markup, page, total_pages, accounts


def _chat_cleanup_action_keyboard():
    """کیبوردِ مشترکِ «✅ ادامه»/«🔙 بازگشت» - زیرِ هر دو لیستِ (دستی/سشنی)، توی
    پیامِ سوم و جدا نشون داده می‌شه. همین پیام موقعِ زدنِ «✅ ادامه» به صفحه‌یِ
    تاییدِ نهایی (cc_confirm) و بعداً به صفحه‌یِ اجرایِ زنده (cc_run) تبدیل می‌شه."""
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("✅ ادامه", callback_data="cc_confirm")],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="menu_accounts")],
    ])


def _paginate_accounts(accounts: list, page: int, order_desc: bool = True) -> tuple[list, int, int]:
    """
    مرتب‌سازی + صفحه‌بندیِ ۲۰تاییِ یک لیستِ اکانت - دقیقاً همون منطقی که
    _build_2fa_account_keyboard برایِ ساختِ کیبورد استفاده می‌کنه؛ این‌جا جدا شده
    تا «☑️ انتخابِ این صفحه» هم بتونه دقیقاً همون اکانت‌هایِ همون صفحه‌یِ نمایش‌داده‌شده
    رو پیدا کنه، بدونِ تکرارِ منطقِ مرتب‌سازی/برش در چند جایِ مختلف.

    خروجی: (اکانت‌هایِ همین صفحه، شماره‌یِ صفحه‌یِ نهایی/کلمپ‌شده، تعدادِ کلِ صفحات)
    """
    accounts = sorted(accounts, key=lambda a: int(a.get("id") or 0), reverse=order_desc)
    total = len(accounts)
    total_pages = max(1, -(-total // ACCOUNTS_PAGE_SIZE))
    page = max(0, min(int(page), total_pages - 1))
    start = page * ACCOUNTS_PAGE_SIZE
    return accounts[start:start + ACCOUNTS_PAGE_SIZE], page, total_pages


async def _build_2fa_account_keyboard(
    session: "TwoFAChangeSession",
    accounts: list,
    prefix: str,
    start_cb: str | None,
    back_cb: str | None,
    fetch_identity: bool = False,
    page: int = 0,
    task_key: str | None = None,
    order_desc: bool = True,
    select_all_cb: str | None = None,
) -> tuple[InlineKeyboardMarkup, int, int]:
    """
    ساختِ کیبوردِ انتخابِ چندتاییِ اکانت‌ها با صفحه‌بندیِ ۲۰تایی.

    ``prefix`` باید مثلِ ``2fa_sel_manual_`` / ``le_sel_session_`` /
    ``pf_sel_manual_`` باشد. شناسه‌ی صفحه قبل از شناسه‌ی اکانت در callback ذخیره
    می‌شود تا انتخابِ اکانت روی صفحه‌های مختلف بدونِ گم‌شدنِ وضعیت کار کند.

    ``start_cb``/``back_cb`` اختیاری‌ان (None یعنی اون ردیفِ دکمه اصلاً اضافه
    نشه) - برایِ مواردی مثلِ پاک‌کردنِ چت که «✅ ادامه»/«🔙 بازگشت» توی یه پیامِ
    جدا (مشترک بینِ چند لیست) نشون داده می‌شن، نه زیرِ خودِ هر لیست.

    دکمه‌ی «☑️ انتخابِ این صفحه» (برخلافِ select_all_cb که اختیاریه) همیشه اضافه
    می‌شه - چون callback_dataاش مثلِ ردیفِ ناوبریِ صفحه، مستقیم از prefix ساخته
    می‌شه (نیازی به پارامترِ جدا در call siteها نیست) و همه‌ی چهار خانواده‌یِ فعلی
    (2fa/cc/le/pf) هم هندلرشون رو دارن - نگاه کن به on_callback.
    """
    # اکانتِ فریز (Frozen) هیچ‌کدوم از این عملیات‌ها (2FA/ایمیلِ لاگین/پروفایل/...)
    # روش کار نمی‌کنه - پس اصلاً قابلِ‌انتخاب نمی‌ذاریمش تا کاربر وقتش رو با
    # انتخابِ یه اکانتی که از قبل معلومه شکست می‌خوره هدر نده (نگاه کن به
    # database.set_account_frozen - همون‌جایی که این علامت ثبت می‌شه).
    accounts = [a for a in accounts if not a.get("is_frozen")]
    selected_ids = {a["id"] for a in session.selected_accounts}
    page_accounts, page, total_pages = _paginate_accounts(accounts, page, order_desc)
    total = len(accounts)

    # مشخص می‌کنیم این لیست مربوط به کدام عملیات است تا سابقه‌ی انجام‌شده‌ی همان
    # عملیات کنار نام هر اکانت نمایش داده شود. اگر task_key صریح داده نشده باشد،
    # از prefix استنتاجش می‌کنیم تا در آینده با اضافه‌شدنِ call-site جدید،
    # احتمالِ جاافتادنِ نشانگر کمتر شود.
    if task_key is None:
        if prefix.startswith("2fa_"):
            task_key = "2fa"
        elif prefix.startswith("le_"):
            task_key = "login_email"
        elif prefix.startswith("pf_"):
            task_key = "profile"

    task_column_by_key = {
        "2fa": "task_2fa_done",
        "login_email": "task_login_email_done",
        "profile": "task_profile_done",
    }
    task_column = task_column_by_key.get(task_key)

    kb = []
    if select_all_cb:
        all_selected = total > 0 and len(selected_ids) >= total
        select_all_label = "❌ لغوِ انتخابِ همه" if all_selected else f"☑️ انتخابِ همه ({total} اکانت)"
        kb.append([InlineKeyboardButton(select_all_label, callback_data=select_all_cb)])
    if page_accounts:
        page_ids = {a["id"] for a in page_accounts}
        page_all_selected = page_ids.issubset(selected_ids)
        select_page_label = "❌ لغوِ انتخابِ این صفحه" if page_all_selected else f"☑️ انتخابِ این صفحه ({len(page_accounts)} اکانت)"
        kb.append([InlineKeyboardButton(
            select_page_label,
            callback_data=f"{prefix.replace('_sel_', '_selpage_')}{page}"
        )])
    for acc in page_accounts:
        identity = None
        if fetch_identity:
            identity = session.identity_cache.get(acc["id"])
            if identity is None:
                identity = await get_account_identity(acc["session_file"])
                session.identity_cache[acc["id"]] = identity
        label = format_account_label(acc, identity, acc["id"] in selected_ids)

        # علامتِ مستقلِ «قبلاً انجام شده»؛ از فیلدِ ذخیره‌شده در دیتابیس می‌خوانیم
        # تا با رفتن بین صفحات یا بازشدنِ دوباره‌ی منو، وضعیت از بین نرود.
        if task_column and bool(acc.get(task_column)):
            label = f"{label} ✅"

        kb.append([InlineKeyboardButton(
            label,
            callback_data=f"{prefix}{page}_{acc['id']}"
        )])

    nav_row = []
    if page > 0:
        nav_row.append(InlineKeyboardButton(
            "⬅️ صفحه قبلی",
            callback_data=f"{prefix.replace('_sel_', '_page_')}{page - 1}"
        ))
    if page < total_pages - 1:
        nav_row.append(InlineKeyboardButton(
            "➡️ صفحه بعدی",
            callback_data=f"{prefix.replace('_sel_', '_page_')}{page + 1}"
        ))
    if nav_row:
        kb.append(nav_row)

    order_key = _account_order_key_for_prefix(prefix)
    order_label = "جدیدترین → قدیمی‌ترین" if order_desc else "قدیمی‌ترین → جدیدترین"
    kb.append([InlineKeyboardButton(
        f"🔃 ترتیب ({order_label})",
        callback_data=order_key
    )])

    if start_cb:
        kb.append([InlineKeyboardButton("✅ ادامه", callback_data=start_cb)])
    if back_cb:
        kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data=back_cb)])
    return InlineKeyboardMarkup(kb), page, total_pages


async def _session_accounts_for_2fa_change(accounts: list) -> list:
    """
    اکانت‌هایِ سشنیِ *واقعاً نیازمندِ* تغییرِ رمزِ دومرحله‌ای - یعنی:
      ۱) source == "session"
      ۲) قبلاً موفق تغییر نکرده (task_2fa_done)
      ۳) توی لیستِ «رمزِ فعلی اشتباسه، نمیشه تغییر داد» بلاک نشده (account_task_
         blocked با task='2fa')

    این تنها تعریفِ «نیاز به تغییر» برایِ بخشِ 2FA ـه - همه‌ی مسیرها (صفحه‌بندی،
    تیک‌زدن، مرتب‌سازی، صفحه‌یِ خانه) از همینِ یکی استفاده می‌کنن تا سه لیست
    (تغییرکرده/نیازمندِ‌تغییر/بلاک‌شده) هیچ‌وقت اکانتِ مشترک نداشته باشن.
    اکانتِ فریز رو _build_2fa_account_keyboard خودش کنار می‌ذاره.
    """
    blocked_ids = await get_blocked_account_ids_for_task("2fa")
    return [
        a for a in accounts
        if a.get("source") == "session"
        and not a.get("task_2fa_done")
        and a["id"] not in blocked_ids
    ]


async def _session_accounts_for_login_email_change(accounts: list) -> list:
    """دقیقاً همون منطقِ بالا، برایِ «📧 تغییرِ ایمیلِ لاگین» (task='login_email')."""
    blocked_ids = await get_blocked_account_ids_for_task("login_email")
    return [
        a for a in accounts
        if a.get("source") == "session"
        and not a.get("task_login_email_done")
        and a["id"] not in blocked_ids
    ]


async def _t2fa_home_payload():
    """
    متن + کیبوردِ صفحه‌یِ خانه‌یِ «🔐 تغییرِ رمزِ دومرحله‌ای ← 📄 سشن‌های فایلی» -
    سه لیستِ بدونِ اکانتِ مشترک: تغییرکرده‌ها / نیازمندِ تغییر / رمزِ فعلی اشتباسه.
    """
    accounts = await get_all_accounts()
    session_accounts = [a for a in accounts if a.get("source") == "session"]
    blocked = await get_blocked_accounts_for_task("2fa")
    blocked_ids = {a["id"] for a in blocked}
    changed = [a for a in session_accounts if a.get("task_2fa_done") and a["id"] not in blocked_ids]
    need_change = await _session_accounts_for_2fa_change(accounts)

    text = "\n".join([
        "🔐 تغییرِ رمزِ دومرحله‌ای - سشن‌های فایلی",
        "",
        f"مجموعِ سشن‌هایِ فایلی: {len(session_accounts)}",
        "",
        f"✅ تغییر کرده‌ها: {len(changed)}",
        f"🔄 نیاز به تغییر: {len(need_change)}",
        f"❌ رمزِ فعلی اشتباسه، نمیشه تغییر داد: {len(blocked)}",
        "",
        "کدوم لیست؟",
    ])
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"✅ تغییر کرده‌ها ({len(changed)})", callback_data="t2fa_changed_0")],
        [InlineKeyboardButton(f"🔄 نیاز به تغییر ({len(need_change)})", callback_data="t2fa_need_go")],
        [InlineKeyboardButton(f"❌ رمزِ فعلی اشتباسه ({len(blocked)})", callback_data="t2fa_blocked_0")],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="2fa_back_to_type")],
    ])
    return text, kb


async def _le_home_payload():
    """همون چیزِ بالا، برایِ «📧 تغییرِ ایمیلِ لاگین ← 📄 سشن‌های فایلی»."""
    accounts = await get_all_accounts()
    session_accounts = [a for a in accounts if a.get("source") == "session"]
    blocked = await get_blocked_accounts_for_task("login_email")
    blocked_ids = {a["id"] for a in blocked}
    changed = [a for a in session_accounts if a.get("task_login_email_done") and a["id"] not in blocked_ids]
    need_change = await _session_accounts_for_login_email_change(accounts)

    text = "\n".join([
        "📧 تغییرِ ایمیلِ لاگین - سشن‌های فایلی",
        "",
        f"مجموعِ سشن‌هایِ فایلی: {len(session_accounts)}",
        "",
        f"✅ تغییر کرده‌ها: {len(changed)}",
        f"🔄 نیاز به تغییر: {len(need_change)}",
        f"❌ ایمیلِ لاگین نمیشه تنظیم کرد: {len(blocked)}",
        "",
        "کدوم لیست؟",
    ])
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"✅ تغییر کرده‌ها ({len(changed)})", callback_data="le_changed_0")],
        [InlineKeyboardButton(f"🔄 نیاز به تغییر ({len(need_change)})", callback_data="le_need_go")],
        [InlineKeyboardButton(f"❌ ایمیل نمیشه تنظیم کرد ({len(blocked)})", callback_data="le_blocked_0")],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="le_back_to_type")],
    ])
    return text, kb


def _format_blocked_task_page(accounts: list, category_title: str, page: int = 0):
    """
    یه صفحه از لیستِ فقط‌خواندنیِ اکانت‌هایِ بلاک‌شده‌یِ یه تسک (account_task_
    blocked) - همراه با دلیل/آخرین خطا/تعدادِ تلاش، دقیقاً همون سبکِ
    _format_pending_2fa_page در بخشِ تعویضِ سشن.
    """
    accounts_sorted = sorted(accounts, key=lambda a: int(a.get("id") or 0))
    total = len(accounts_sorted)
    total_pages = max(1, -(-total // ACCOUNTS_PAGE_SIZE))
    page = max(0, min(page, total_pages - 1))
    start = page * ACCOUNTS_PAGE_SIZE
    page_accounts = accounts_sorted[start:start + ACCOUNTS_PAGE_SIZE]

    lines = [f"{category_title} ({total} اکانت)", ""]
    if not page_accounts:
        lines.append("هیچ اکانتی توی این دسته نیست. 🎉")
    else:
        for i, acc in enumerate(page_accounts, start=start + 1):
            name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
            phone = acc.get("phone", "")
            head = f"{i}. {name} ({phone})" if phone and phone != name else f"{i}. {name}"
            reason = acc.get("_blocked_last_error") or acc.get("_blocked_reason")
            if reason:
                head += f"\n     ⚠️ {reason}"
            tries = acc.get("_blocked_attempts") or 0
            if tries > 1:
                head += f"\n     ↻ {tries} بار تلاش شده"
            lines.append(head)
    lines.append("")
    lines.append(f"صفحه‌یِ {page + 1} از {total_pages}")
    return "\n".join(lines), page, total_pages


