def _split_long_text(text: str, limit: int = 3500) -> list:
    """
    شکستنِ یه متنِ طولانی به چند تکه‌یِ کوچیک‌تر از سقفِ پیامِ تلگرام (۴۰۹۶ کاراکتر) -
    اول سرِ خط‌هایِ خالی بریده می‌شه تا وسطِ یه گزارشِ اکانت قطع نشه.

    ⚠️ باگی که این‌جا حل شده: نسخه‌یِ قبلی *فقط* رویِ «\\n\\n» می‌برید. اگه خودِ یه
    قطعه از سقف بزرگ‌تر بود، دست‌نخورده برمی‌گشت و تلگرام با خطایِ «Message is too
    long» ردش می‌کرد - و چون هیچ‌جا گرفته نمی‌شد، کلِ تابعِ صداکننده نصفه‌کاره
    متوقف می‌شد. دقیقاً همین باعث شد گزارشِ نهاییِ «تغییرِ ایمیلِ لاگین» با ۶۷
    اکانت فقط سرتیترش نمایش داده بشه: گزارش با «\\n» ساخته می‌شه، پس همه‌ی
    ۶۷ خط یه قطعه‌یِ واحدِ ~۴۸۰۰ کاراکتری می‌شدن. حالا قطعه‌هایِ بزرگ‌تر از سقف،
    خط‌به‌خط (و در نهایت کاراکتری) هم شکسته می‌شن.
    """
    if len(text) <= limit:
        return [text]

    def _split_oversized(block: str) -> list:
        """یه قطعه‌یِ بزرگ‌تر از سقف رو خط‌به‌خط می‌شکنه؛ اگه خودِ یه خط هم از سقف
        بزرگ‌تر بود (مثلاً یه نامِ خیلی طولانی)، همون خط رو کاراکتری می‌بره."""
        out, cur = [], ""
        for line in block.split("\n"):
            while len(line) > limit:
                if cur:
                    out.append(cur)
                    cur = ""
                out.append(line[:limit])
                line = line[limit:]
            candidate = f"{cur}\n{line}" if cur else line
            if len(candidate) > limit and cur:
                out.append(cur)
                cur = line
            else:
                cur = candidate
        if cur:
            out.append(cur)
        return out

    parts = text.split("\n\n")
    chunks = []
    current = ""
    for part in parts:
        candidate = f"{current}\n\n{part}" if current else part
        if len(candidate) > limit and current:
            chunks.append(current)
            current = part
        else:
            current = candidate
    if current:
        chunks.append(current)

    # هر قطعه‌ای که هنوز از سقف بزرگ‌تره رو بیشتر بشکن
    final = []
    for chunk in chunks:
        if len(chunk) > limit:
            final.extend(_split_oversized(chunk))
        else:
            final.append(chunk)
    # قطعه‌یِ خالی رو تلگرام قبول نمی‌کنه - حذفشون کن
    return [c for c in final if c.strip()]


async def _run_2fa_queue(update: Update, context: ContextTypes.DEFAULT_TYPE, session: "TwoFAChangeSession", status_msg):
    """
    موتورِ اصلیِ اجرایِ صفِ تغییرِ 2FA - تا وقتی که یا صف تموم بشه یا به یه اکانتی
    برسه که منتظرِ کدِ ایمیله، قدم‌به‌قدم جلو می‌ره. پیامِ status_msg مرتب ادیت می‌شه
    تا کاربر پیشرفت رو ببینه.
    """
    while True:
        acc = session.current_account()
        acc_name = (acc.get("nickname") or acc.get("phone")) if acc else "؟"

        # حالتِ «🎲 رندوم از ایمیل‌هایِ فعال»: برایِ *هر* اکانت یه آدرسِ تازه از
        # استخر انتخاب می‌شه - نه یه ایمیلِ ثابت برایِ کلِ دسته. لیستِ انتخاب‌ها موقعِ
        # تأییدِ صف یه‌بار کش شده (email_pool_choices)، پس این‌جا فقط رندوم می‌کنیم،
        # دوباره از دیتابیس نمی‌خونیم.
        if session.random_email_pool and session.email_pool_choices:
            session.recovery_email = random.choice(session.email_pool_choices)

        try:
            await status_msg.edit_text(
                f"⏳ در حالِ انجامِ تغییرات...\n\n"
                f"اکانتِ {session.queue_index + 1} از {len(session.selected_accounts)}: {acc_name}"
            )
        except Exception:
            pass

        step = await process_next_account(session)

        if step["action"] == "need_email_code":
            acc = step["account"]
            acc_name = acc.get("nickname") or acc.get("phone")

            # ---- تلاش برایِ خواندنِ خودکارِ کدِ ایمیلِ بازیابی (اگه تنظیم شده) ----
            # دقیقاً همون منطقِ «تغییرِ ایمیلِ لاگین» (نگاه کن به _try_auto_email_code)،
            # فقط برایِ ایمیلِ بازیابیِ 2FA. اگه موفق شد بدونِ دخالتِ کاربر جلو می‌ره؛
            # اگه هر جا شکست خورد بی‌صدا به حالتِ دستیِ همیشگی برمی‌گرده.
            auto = await _try_auto_email_code_2fa(update, context, session, status_msg, acc_name)
            if auto is not None:
                return auto

            context.user_data["awaiting"] = "twofa_waiting_email_code"
            await update.message.reply_text(
                _recovery_email_text(
                    acc_name, session.recovery_email, step.get("code_length"),
                    prefix="(رمزِ دومرحله‌ای از قبل عوض شد - فقط ایمیل مونده)\n\n",
                ),
                reply_markup=_recovery_email_keyboard("twofa"),
            )
            return  # اینجا متوقف می‌شیم - ادامه با پیامِ بعدیِ کاربر

        if step["action"] == "account_done":
            if step["has_more"]:
                continue  # برو سراغِ اکانتِ بعدی
            break  # صف تموم شد

        if step["action"] == "all_done":
            break

    await _finish_2fa_queue(update, context, session, status_msg)


async def _finish_2fa_queue(update: Update, context: ContextTypes.DEFAULT_TYPE, session: "TwoFAChangeSession", status_msg):
    """ساختنِ گزارشِ نهایی (تفکیک‌شده به ۱-رمز ۲-hint ۳-ایمیل برایِ هر اکانت) و
    بازگشت به منویِ اکانت‌ها."""
    report_parts = []
    for acc in session.selected_accounts:
        entry = session.results.get(acc["id"], {"status": "error", "message": "این اکانت پردازش نشد"})
        # ایمیلِ *همین* اکانت رو نشون بده، نه ایمیلِ مشترکِ سراسریِ صف - چون در حالتِ
        # «🎲 رندوم از ایمیل‌هایِ فعال»، هر اکانت ممکنه ایمیلِ متفاوتی گرفته باشه
        # (نگاه کن به change_2fa.py::process_next_account و recovery_email_used).
        email_used = entry.get("recovery_email_used")
        report_parts.append(format_account_result(acc, entry, session.new_twofa_code, session.hint, email_used))

        # بروزرسانیِ فلگ‌هایِ ۵-تسکی (نگاه کن به build_accounts_menu و show_account_detail) -
        # فقط وقتی هرکدوم *واقعاً* طبقِ گزارشِ before/after اتفاق افتاده باشه ثبت می‌شه
        if entry.get("status") == "success":
            await set_account_task_done(acc["id"], "2fa", True)
            after = entry.get("after") or {}
            if session.hint and after.get("hint") == session.hint:
                await set_account_task_done(acc["id"], "hint", True)
            if email_used and not entry.get("email_error"):
                await set_account_task_done(acc["id"], "recovery_email", True)
            # اگه این اکانت قبلاً توی لیستِ «رمزِ فعلی اشتباسه» بلاک شده بود، حالا حل
            # شد - برایِ همیشه بلاک نمی‌مونه.
            try:
                await resolve_account_task_blocked(acc["id"], "2fa", resolution="success")
            except Exception:
                pass
        elif entry.get("status") == "wrong_password":
            # ⚠️ این تنها حالتیه که «قطعاً بلاکه» به‌حساب میاد - نه خطایِ گذرا
            # (فلود/شبکه). ثبتِ پایدار می‌شه تا این اکانت دیگه توی لیستِ «نیاز به
            # تغییر» ظاهر نشه و توی لیستِ سومِ «رمزِ فعلی اشتباسه» بیفته (نگاه کن
            # به _t2fa_home_payload / _session_accounts_for_2fa_change).
            try:
                await mark_account_task_blocked(
                    acc["id"], "2fa",
                    reason="رمزِ فعلی اشتباسه، نمیشه تغییر داد",
                    last_error=entry.get("message"),
                )
            except Exception:
                pass

    full_text = "🔐 تغییرِ رمزِ دومرحله‌ای - نتایج\n\n" + "\n\n".join(report_parts)

    try:
        await status_msg.delete()
    except Exception:
        pass

    # مثلِ _finish_le_queue: شکستِ ارسالِ یه قطعه نباید جلویِ بقیه‌یِ گزارش و
    # برگشتن به منو رو بگیره
    sent_any = False
    for chunk in _split_long_text(full_text):
        try:
            await update.message.reply_text(chunk)
            sent_any = True
        except Exception:
            continue
    if not sent_any:
        try:
            await update.message.reply_text(
                "🔐 تغییرِ رمزِ دومرحله‌ای تموم شد، ولی نمایشِ گزارش با خطا مواجه شد.\n"
                "وضعیتِ هر اکانت توی لیستِ اکانت‌ها با علامتِ ✅ مشخصه."
            )
        except Exception:
            pass

    _reset_flow(context)
    try:
        await send_accounts_menu(update.message, context=context)
    except Exception:
        pass


async def _delete_auto_email_safely(message_id: str, address: str = None):
    """
    ایمیلِ خونده‌شده رو (با UIDش) از صندوقِ *مشخص‌شده* پاک می‌کنه تا دفعه‌یِ بعد با
    کدِ اکانتِ دیگه قاطی نشه. هر شکستی این‌جا بی‌صداست - پاک‌نشدنِ یه ایمیل نباید
    فلوی اصلی رو بشکنه (فیلترِ since_epoch خودش محافظِ دومه).

    address لازمه چون استخر چندتاییه - بدونِ دونستنِ اینکه کد از کدوم صندوق خونده
    شده، نمی‌شه فهمید کدوم رمزِ استخر رو برایِ حذف استفاده کنیم.
    """
    if not message_id or not address:
        return
    try:
        entry = await find_auto_email_pool_entry_by_address(address)
        if not entry:
            return
        import email_reader
        await asyncio.to_thread(
            email_reader.delete_email, entry["address"], entry["password"], message_id
        )
    except Exception:
        pass


async def _poll_auto_email_code(update, status_msg, progress_text: str, recovery_email: str):
    """
    هسته‌یِ مشترکِ خواندنِ خودکارِ کدِ ایمیلِ بازیابی - هر دو مسیرِ تغییرِ رمزِ دومرحله‌ای
    (دستی و خودکارِ بعدِ ایمپورتِ سشن) از همین استفاده می‌کنن تا رفتارشون دقیقاً یکی باشه.

    خروجی:
      {"status": "off"}                                    → هیچ ایمیلِ روشنی توی استخر
                                                             با آدرسِ این صف یکی نیست
      {"status": "found", "code": "...", "message_id": ...} → کد پیدا شد
      {"status": "error", "message": ...}                  → خطایِ اتصال/لاگینِ ایمیل
      {"status": "timeout"}                                → کد توی مهلت (~۱۲۰ ثانیه) نرسید
    """
    creds = await find_auto_email_pool_entry_by_address(recovery_email)
    if not creds:
        return {"status": "off"}

    # لحظه‌یِ شروع - فقط کدهایی که *بعد* از الان می‌رسن قبولن (کدِ اکانتِ قبلی رو
    # اشتباهی نخونیم). چند ثانیه ارفاق چون ساعتِ سرورِ ایمیل ممکنه کمی جلو/عقب باشه.
    import time as _time
    since = _time.time() - 20

    if status_msg is not None:
        try:
            await status_msg.edit_text(progress_text)
        except Exception:
            pass

    # ایمیل ممکنه چند ثانیه دیر برسه - چند بار با فاصله چک می‌کنیم (تا ~۱۲۰ ثانیه).
    import email_reader
    for _attempt in range(24):
        try:
            result = await asyncio.to_thread(
                email_reader.fetch_latest_telegram_code,
                creds["address"], creds["password"], since,
            )
        except Exception:
            result = {"status": "error", "message": "خطایِ داخلی هنگامِ خواندنِ ایمیل"}

        if result.get("status") == "found":
            return {
                "status": "found",
                "code": result["code"],
                "message_id": result.get("message_id"),
            }
        if result.get("status") == "error":
            return {"status": "error", "message": result.get("message", "نامشخص")}
        await asyncio.sleep(5)  # not_found - هنوز نرسیده، صبر کن

    return {"status": "timeout"}


async def _try_auto_email_code_2fa(update, context, session, status_msg, acc_name):
    """
    خواندنِ خودکارِ کدِ ایمیلِ بازیابی برایِ صفِ *دستیِ* «🔐 تغییرِ رمزِ دومرحله‌ای».

    هوشمندی‌ها:
      • تا ~۱۲۰ ثانیه منتظرِ رسیدنِ کد می‌مونه.
      • اگه کدِ خونده‌شده اشتباه بود، خودش «ارسالِ مجددِ کد» رو می‌زنه و دوباره
        می‌خونه - تا ۲ دورِ کامل، قبل از اینکه به حالتِ دستی برگرده.
      • بعدِ اعمالِ موفق، ایمیلِ خونده‌شده رو از صندوق پاک می‌کنه تا با اکانتِ بعدی قاطی نشه.

    خروجی:
      None       → خودکار انجام نشد - صداکننده باید به حالتِ دستی برگرده.
      "handled"  → کار انجام شد (یا منتظرِ کاربر موندیم) - صداکننده باید return کنه.
    """
    # چند دورِ کامل: خواندن → (اگه اشتباه) ارسالِ مجدد → خواندنِ دوباره
    for round_idx in range(3):
        progress = (
            f"📧 اکانتِ «{acc_name}»: در حالِ خواندنِ خودکارِ کدِ ایمیلِ بازیابی...\n"
            f"({session.queue_index + 1} از {len(session.selected_accounts)})"
        )
        polled = await _poll_auto_email_code(update, status_msg, progress, session.recovery_email)

        if polled["status"] == "off":
            return None

        if polled["status"] == "error":
            try:
                await update.message.reply_text(
                    f"⚠️ خواندنِ خودکارِ ایمیل ممکن نشد: {polled['message']}\n"
                    "به حالتِ دستی برگشتیم - کد رو خودت بفرست."
                )
            except Exception:
                pass
            return None

        if polled["status"] == "timeout":
            # کد نرسید - اگه هنوز دور داریم، «ارسالِ مجدد» بزن و دوباره صبر کن
            if round_idx < 2:
                resend = await resend_pending_email_code(session)
                if resend.get("status") == "success":
                    try:
                        await update.message.reply_text(
                            f"🔄 «{acc_name}»: کد نرسید - خودکار درخواستِ ارسالِ مجددِ کد زده شد..."
                        )
                    except Exception:
                        pass
                    continue  # دورِ بعدی: دوباره از صندوق بخون
            # دیگه دوری نمونده یا ارسالِ مجدد نشد - به حالتِ دستی برگرد
            try:
                await update.message.reply_text(
                    f"⏳ کدِ ایمیلِ اکانتِ «{acc_name}» توی مهلتِ خودکار نرسید.\n"
                    "کد رو دستی بفرست (یا از دکمه‌هایِ زیر استفاده کن):",
                    reply_markup=_recovery_email_keyboard("twofa")
                )
            except Exception:
                pass
            context.user_data["awaiting"] = "twofa_waiting_email_code"
            return "handled"

        # ---- کد پیدا شد؛ اعمالش کن ----
        code = polled["code"]
        msg_id = polled.get("message_id")
        step2 = await confirm_pending_email_code(session, code)

        if step2["action"] == "wrong_code":
            # کدِ خونده‌شده اشتباه بود - اون ایمیلِ خونده‌شده رو پاک کن و اگه هنوز
            # دور داریم، «ارسالِ مجدد» بزن و دوباره امتحان کن.
            await _delete_auto_email_safely(msg_id, session.recovery_email)
            if round_idx < 2:
                resend = await resend_pending_email_code(session)
                if resend.get("status") == "success":
                    try:
                        await update.message.reply_text(
                            f"🔄 «{acc_name}»: کدِ خونده‌شده اشتباه بود - خودکار ارسالِ مجددِ کد زده شد..."
                        )
                    except Exception:
                        pass
                    await asyncio.sleep(3)  # مهلتِ کوتاه تا کدِ تازه برسه
                    continue  # دورِ بعدی
            try:
                await update.message.reply_text(
                    f"❌ کدی که خودکار از ایمیل خونده شد برایِ «{acc_name}» درست نبود.\n"
                    "کد رو دستی بفرست:",
                    reply_markup=_recovery_email_keyboard("twofa")
                )
            except Exception:
                pass
            context.user_data["awaiting"] = "twofa_waiting_email_code"
            return "handled"

        # account_done - موفق. ایمیل رو پاک کن و برو اکانتِ بعدی (کاملاً خودکار)
        await _delete_auto_email_safely(msg_id, session.recovery_email)
        try:
            await update.message.reply_text(f"✅ «{acc_name}» - کدِ ایمیلِ بازیابی خودکار از صندوق خونده و اعمال شد.")
        except Exception:
            pass
        if step2["has_more"]:
            await _run_2fa_queue(update, context, session, status_msg)
        else:
            await _finish_2fa_queue(update, context, session, status_msg)
        return "handled"

    # اگه هر ۳ دور تموم شد بدونِ نتیجه (خیلی بعیده) - به حالتِ دستی برگرد
    context.user_data["awaiting"] = "twofa_waiting_email_code"
    return "handled"


def _recovery_email_keyboard(scope: str) -> InlineKeyboardMarkup:
    """
    کیبوردِ یکپارچه‌یِ مرحله‌یِ «منتظرِ کدِ ایمیلِ بازیابی».

    قبلاً هر مسیرِ ربات کیبوردِ خودش رو داشت (یکی فقط «ارسالِ مجدد» داشت، اون‌یکی
    هیچ دکمه‌ای) و «تغییرِ ایمیل» اصلاً وجود نداشت - یعنی اگه ایمیل رو اشتباه زده
    بودی، هیچ راهی جز لغوِ کلِ عملیات نداشتی. حالا همه‌جا همین یه کیبورده.

    scope مشخص می‌کنه کدوم نشست دستِ کاره:
      "twofa"        → تغییرِ رمزِ دومرحله‌ایِ دستی (twofa_session)
      "session_auto" → صفِ خودکارِ بعدِ ایمپورتِ سشن (session_auto_2fa_session)
    """
    rows = [
        [InlineKeyboardButton("🔄 ارسالِ مجددِ کد", callback_data=f"recmail_resend_{scope}")],
        [InlineKeyboardButton("✏️ تغییرِ ایمیل", callback_data=f"recmail_change_{scope}")],
    ]
    if scope == "twofa":
        # فقط برایِ مسیرِ دستیِ «🔐 تغییرِ رمزِ دومرحله‌ای» - امکانِ ردشدن از همین
        # اکانت (بدونِ نیاز به کدِ ایمیل) و رفتن سراغِ اکانتِ بعدیِ صف. مسیرِ خودکارِ
        # بعدِ ایمپورت (session_auto) از قبل کیبوردِ فیزیکیِ خودش رو برایِ این کار داره.
        rows.append([InlineKeyboardButton("⏭ رد شدن", callback_data=f"recmail_skip_{scope}")])
    return InlineKeyboardMarkup(rows)


def _recovery_email_session(context, scope: str):
    """نشستِ این scope رو برمی‌گردونه - (session, awaiting_state)."""
    if scope == "twofa":
        return context.user_data.get("twofa_session"), "twofa_waiting_email_code"
    if scope == "session_auto":
        return context.user_data.get("session_auto_2fa_session"), "session_auto_2fa_waiting_email_code"
    return None, None


def _recovery_email_text(acc_name: str, email: str, code_length=None, prefix: str = "") -> str:
    """متنِ یکدستِ مرحله‌یِ کدِ ایمیل - همه‌ی مسیرها از همین استفاده می‌کنن."""
    length_text = f"{code_length} رقمیِ " if code_length else ""
    return (
        f"{prefix}📧 برایِ اکانتِ «{acc_name}» یه کدِ {length_text}تأیید به ایمیلِ "
        f"«{email}» فرستاده شد.\n\n"
        f"کد رو همین‌جا بفرست، یا اگه ایمیل اشتباهه از دکمه‌یِ زیر عوضش کن:"
    )


def _le_waiting_code_keyboard() -> InlineKeyboardMarkup:
    """
    کیبوردِ یکپارچه‌یِ مرحله‌یِ «منتظرِ کدِ تأییدِ ایمیلِ لاگین» - قبلاً این سه‌دکمه
    (ارسالِ مجدد/تغییرِ ایمیل) توی ۷ جایِ مختلفِ کد جدا-جدا تکرار شده بود؛ حالا همه‌جا
    از همینْ یه تابع استفاده می‌کنن، پس اضافه‌کردنِ دکمه‌یِ «رد شدن» یه‌بار همه‌جا اثر
    می‌کنه و دیگه هیچ‌کدوم از اون هفت‌تا از بقیه عقب نمی‌مونن.

    «⏭ رد شدن» دقیقاً مثلِ همین دکمه توی «🔐 تغییرِ رمزِ دومرحله‌ای» عمل می‌کنه: فقط
    اکانتِ *فعلی* رو (با وضعیتِ ناموفق - چون برخلافِ 2FA این‌جا هیچ تغییرِ واقعی‌ای
    هنوز رخ نداده) رد می‌کنه و صف رو یه قدم جلو می‌بره؛ اکانت‌هایِ قبلی (که نتیجه‌شون
    از قبل توی session.results ثبت شده) و بعدی (که هنوز نوبتشون نرسیده) دست‌نخورده
    می‌مونن - نگاه کن به le_mark_current_account_failed در callback handler.
    """
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 ارسال کد مجدد", callback_data="le_resend_code")],
        [InlineKeyboardButton("✏️ تغییر ایمیل", callback_data="le_change_email")],
        [InlineKeyboardButton("⏭ رد شدن", callback_data="le_skip_account")],
    ])


def _le_waiting_new_email_keyboard() -> InlineKeyboardMarkup:
    """
    کیبوردِ مرحله‌یِ «منتظرِ ایمیلِ جدید» (بعدِ ردشدنِ یه ایمیل توسطِ تلگرام یا
    خطایی که به‌اشتباه شبیهِ ردشدنِ ایمیل به‌نظر می‌رسه - مثلِ AuthKeyDuplicatedError
    وقتی سشن هم‌زمان جایِ دیگه استفاده شده و اصلاً ربطی به ایمیل نداره). فقط یه
    دکمه‌یِ «⏭ رد شدن» داره - چون این مرحله انتظارِ *تایپِ* یه ایمیلِ جدید رو داره،
    نه انتخاب از بینِ چندتا گزینه‌یِ ثابت؛ اگه کاربر بخواد به‌جایِ حدس‌زدنِ ایمیلِ
    جدید برایِ اکانتی که مشکوکه، مستقیم از این اکانت رد بشه، همینْ یه دکمه کافیه.
    """
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("⏭ رد شدن", callback_data="le_skip_account")],
    ])


# تلگرام اجازه می‌ده هر ایمیل حداکثر برایِ همین تعداد اکانت به‌عنوانِ ایمیلِ لاگین
# تنظیم بشه. بعد از رسیدن به این سقف، صندوقِ موقتِ تازه ساخته می‌شه (نگاه کن به
# _run_le_queue). اگه تلگرام این محدودیت رو عوض کرد، فقط همین عدد رو تغییر بده.
MAX_ACCOUNTS_PER_TEMP_EMAIL = 2

# اگه تلگرام ایمیلِ موقت رو رد کنه، با یه صندوقِ تازه دوباره امتحان می‌کنیم - ولی
# حداکثر همین تعداد بار برایِ *یک* اکانت. بعدش اون اکانت به‌عنوانِ «قطعاً بلاک» رد
# می‌شه (وگرنه اگه تلگرام کلاً دامنه‌یِ mail.tm رو مسدود کرده باشه، توی حلقه‌یِ
# بی‌پایانِ ساختِ صندوق گیر می‌کنیم).
MAX_TEMP_EMAIL_RETRIES_PER_ACCOUNT = 3


# تایم‌اوتِ کلیِ هر عملیاتِ شبکه‌ایِ ایمیلِ موقت (ساختِ صندوق / خواندنِ یه صفحه از
# inbox). ⚠️ چرا این تایم‌اوتِ بیرونی لازمه با اینکه tempmail.py خودش timeout=15
# به urlopen می‌ده: پارامترِ timeoutِ urlopen فقط *بعد از برقراریِ اتصال* اثر
# می‌کنه - جستجویِ DNS (که قبل از اتصاله) هیچ محدودیتِ زمانی نداره. اگه DNSِ
# api.mail.tm رویِ سرور کند/مسدود باشه، درخواست می‌تونه برایِ همیشه معلق بمونه و
# کلِ صفِ «ایمیلِ موقتِ خودکار» رو بی‌صدا گیر بندازه. asyncio.wait_for این‌جا
# ضمانت می‌کنه که حتی اگه ترد پس‌زمینه گیر کرد، حلقه‌ی ربات آزاد بمونه و کاربر
# پیامِ خطا ببینه، نه یه پیامِ «در حالِ ساخت...» که هیچ‌وقت عوض نمی‌شه.
TEMPMAIL_OP_TIMEOUT = int(os.getenv("TEMPMAIL_OP_TIMEOUT", "40"))


async def _try_auto_email_code_tempmail(update, context, session, status_msg, acc_name):
    """
    نسخه‌یِ «ایمیلِ موقت» (mail.tm) یِ _try_auto_email_code: کد رو از صندوقِ موقتی
    که همین الان برایِ این اکانت ساخته شد (session.temp_inbox) می‌خونه و اعمال می‌کنه.

    خروجی و قاعده‌ها دقیقاً مثلِ _try_auto_email_code:
      None       → به هر دلیل نشد؛ صداکننده به حالتِ دستی برمی‌گرده.
      "handled"  → کار انجام شد (موفق یا رد) و صف خودش جلو رفت.
    """
    import tempmail
    inbox = session.temp_inbox
    if not inbox or not inbox.get("token"):
        # نباید پیش بیاد (چون _run_le_queue قبلش صندوق می‌سازه)، ولی محکم‌کاری
        return None

    import time as _time
    since = _time.time() - 20  # فقط کدهایِ بعد از این لحظه

    try:
        await status_msg.edit_text(
            f"📧 اکانتِ «{acc_name}»: در حالِ خواندنِ خودکارِ کد از ایمیلِ موقت...\n"
            f"({session.queue_index + 1} از {len(session.selected_accounts)})"
        )
    except Exception:
        pass

    # کد ممکنه چند ثانیه دیر برسه - تا ~۹۰ ثانیه چند بار چک می‌کنیم (مثلِ IMAP).
    # هر تلاش خودش زیرِ wait_for جداگانه‌ست (نگاه کن به توضیحِ TEMPMAIL_OP_TIMEOUT) -
    # وگرنه یه بارِ گیرکردنِ DNS/شبکه توی *یکی* از این ۱۸ تلاش، کلِ صف رو تا
    # همیشه معلق نگه می‌داشت.
    #
    # ⚠️ تایم‌اوتِ گذرا (یه بار DNS/شبکه کند بود) با خطایِ واقعیِ API فرق داره: یه
    # timeoutِ تک‌افتاده نباید فوراً کلِ صف رو به حالتِ دستی بندازه - چند بار
    # تحمل می‌کنیم، ولی نه بی‌نهایت (وگرنه ۱۸×۴۰ثانیه = تا ۱۲ دقیقه معطلی).
    code = None
    code_msg_id = None
    consecutive_timeouts = 0
    MAX_CONSECUTIVE_TIMEOUTS = 3
    for attempt in range(18):
        try:
            result = await asyncio.wait_for(
                asyncio.to_thread(
                    tempmail.fetch_telegram_code, inbox["token"], since,
                    getattr(session, "temp_baseline_ids", None) or set(),
                    getattr(session, "temp_used_codes", None) or set(),
                ),
                timeout=TEMPMAIL_OP_TIMEOUT,
            )
        except asyncio.TimeoutError:
            consecutive_timeouts += 1
            if consecutive_timeouts >= MAX_CONSECUTIVE_TIMEOUTS:
                result = {
                    "status": "error",
                    "message": (
                        f"{MAX_CONSECUTIVE_TIMEOUTS} بار پشتِ‌سرِهم بیش از "
                        f"{TEMPMAIL_OP_TIMEOUT} ثانیه طول کشید (احتمالاً DNS/اتصالِ سرور "
                        f"به mail.tm مسدوده)"
                    ),
                }
            else:
                await asyncio.sleep(5)
                continue
        except Exception:
            result = {"status": "error", "message": "خطایِ داخلی هنگامِ خواندنِ ایمیلِ موقت"}
        else:
            consecutive_timeouts = 0

        if result.get("status") == "found":
            code = result["code"]
            code_msg_id = result.get("message_id")
            break
        if result.get("status") == "error":
            try:
                await update.message.reply_text(
                    f"⚠️ خواندنِ خودکارِ ایمیلِ موقت ممکن نشد: {result.get('message', 'نامشخص')}\n"
                    "به حالتِ دستی برگشتیم - کد رو خودت از پنلِ mail.tm بردار و بفرست."
                )
            except Exception:
                pass
            return None
        await asyncio.sleep(5)  # not_found - هنوز نرسیده، صبر کن

    if not code:
        try:
            await update.message.reply_text(
                f"⏳ کدِ ایمیلِ موقتِ اکانتِ «{acc_name}» توی مهلتِ خودکار نرسید.\n"
                f"(آدرس: {inbox.get('address')})\n"
                "کد رو دستی بفرست، یا «🔄 ارسال کد مجدد» رو بزن:",
                reply_markup=_le_waiting_code_keyboard()
            )
        except Exception:
            pass
        context.user_data["awaiting"] = "le_waiting_code"
        return "handled"

    # ---- کد پیدا شد؛ اول ثبتش کن که دیگه هیچ‌وقت تکرار نشه، بعد اعمالش کن ----
    # ⚠️ عمداً *قبل* از le_confirm_pending_code: حتی اگه این کد اشتباه از آب دربیاد،
    # نباید دفعه‌یِ بعد دوباره همین کد از صندوق برداشته بشه.
    try:
        session.temp_used_codes.add(code)
    except Exception:
        pass
    # پیامِ خونده‌شده رو از صندوق پاک کن تا برایِ اکانتِ بعدی (که از همین صندوق
    # استفاده می‌کنه) اصلاً وجود نداشته باشه - لایه‌یِ سومِ محافظت در برابرِ کدِ کهنه.
    if code_msg_id:
        try:
            await asyncio.wait_for(
                asyncio.to_thread(tempmail.delete_message, inbox["token"], code_msg_id),
                timeout=TEMPMAIL_OP_TIMEOUT,
            )
        except Exception:
            pass

    step2 = await le_confirm_pending_code(session, code)

    if step2["action"] == "wrong_code":
        try:
            await update.message.reply_text(
                f"❌ کدی که خودکار از ایمیلِ موقت خونده شد برایِ «{acc_name}» درست نبود.\n"
                "کد رو دستی بفرست:",
                reply_markup=_le_waiting_code_keyboard()
            )
        except Exception:
            pass
        context.user_data["awaiting"] = "le_waiting_code"
        return "handled"

    if step2["action"] == "need_new_email":
        # تلگرام این ایمیل رو رد کرد. با یه ایمیلِ موقتِ *تازه* دوباره امتحان می‌کنیم -
        # ولی نه بی‌نهایت: اگه تلگرام کلاً دامنه‌یِ mail.tm رو قبول نکنه، هر صندوقِ
        # تازه هم همون جواب رو می‌گیره و توی یه حلقه‌یِ بی‌پایان گیر می‌کنیم. پس
        # تعدادِ تلاشِ ساختِ صندوقِ تازه *برایِ همین اکانت* رو محدود می‌کنیم؛ بعدِ اون
        # این اکانت رو به‌عنوانِ «قطعاً بلاک» رد می‌کنیم (می‌ره توی لیستِ سومِ «ایمیلِ
        # لاگین نمیشه تنظیم کرد») و سراغِ اکانتِ بعدی می‌ریم.
        acc2 = step2["account"]
        n2 = acc2.get("nickname") or acc2.get("phone")
        retries = context.user_data.get("le_tempmail_retries", 0) + 1
        if retries > MAX_TEMP_EMAIL_RETRIES_PER_ACCOUNT:
            context.user_data.pop("le_tempmail_retries", None)
            await update.message.reply_text(
                f"⏭ «{n2}» رد شد: تلگرام بعد از {MAX_TEMP_EMAIL_RETRIES_PER_ACCOUNT} "
                f"ایمیلِ موقت هم قبول نکرد. احتمالاً دامنه‌یِ ایمیلِ موقت رو مسدود کرده. "
                f"این اکانت رد شد."
            )
            le_mark_current_account_failed(
                session, "تلگرام ایمیل‌هایِ موقت رو برایِ این اکانت قبول نکرد", permanent=True,
            )
            await _cleanup_temp_inbox_safely(session)
            await _run_le_queue(update, context, session, status_msg)
            return "handled"
        context.user_data["le_tempmail_retries"] = retries
        await update.message.reply_text(
            f"⚠️ ایمیلِ موقت برایِ «{n2}» رد شد؛ با یه ایمیلِ موقتِ تازه دوباره امتحان می‌کنم "
            f"(تلاشِ {retries} از {MAX_TEMP_EMAIL_RETRIES_PER_ACCOUNT})."
        )
        # صندوقِ قبلی به‌دردنخوره - پاکش کن و بذار _run_le_queue یکیِ جدید بسازه
        await _cleanup_temp_inbox_safely(session)
        await _run_le_queue(update, context, session, status_msg)
        return "handled"

    if step2["action"] in ("flood", "account_failed"):
        await update.message.reply_text(f"⏭ «{acc_name}» رد شد: {step2.get('message', 'مشکلی پیش اومد')}")
        le_mark_current_account_failed(
            session, step2.get("message", "مشکلی پیش اومد"),
            permanent=(step2["action"] == "account_failed"),
        )
        context.user_data.pop("le_tempmail_retries", None)
        await _cleanup_temp_inbox_safely(session)
        await _run_le_queue(update, context, session, status_msg)
        return "handled"

    # account_done - ثبت کن و برو اکانتِ بعدی
    context.user_data.pop("le_tempmail_retries", None)  # شمارنده‌یِ تلاشِ این اکانت ریست
    try:
        await set_account_task_done(step2["account"]["id"], "login_email", True)
        await resolve_account_task_blocked(step2["account"]["id"], "login_email", resolution="success")
    except Exception:
        pass
    # این صندوق یه بارِ *موفق* دیگه استفاده شد. صندوق رو پاک *نمی‌کنیم* تا اکانتِ
    # بعدی هم (اگه هنوز به سقفِ MAX_ACCOUNTS_PER_TEMP_EMAIL نرسیده) از همینش
    # استفاده کنه؛ _run_le_queue خودش وقتی به سقف رسید صندوقِ تازه می‌سازه.
    session.temp_inbox_uses = getattr(session, "temp_inbox_uses", 0) + 1
    remaining = MAX_ACCOUNTS_PER_TEMP_EMAIL - session.temp_inbox_uses
    reuse_note = (
        f" (این ایمیل برایِ ۱ اکانتِ دیگه هم استفاده می‌شه)"
        if remaining >= 1 else
        f" (این ایمیل به سقفِ {MAX_ACCOUNTS_PER_TEMP_EMAIL} اکانت رسید؛ بعدی ایمیلِ تازه می‌گیره)"
    )
    try:
        await update.message.reply_text(
            f"✅ «{acc_name}» - ایمیلِ موقت «{inbox.get('address')}» ثبت و کدش خودکار اعمال شد."
            + reuse_note
        )
    except Exception:
        pass
    if step2["has_more"]:
        await _run_le_queue(update, context, session, status_msg)
    else:
        # آخرِ صف - صندوقِ باقی‌مانده رو تمیز کن
        await _cleanup_temp_inbox_safely(session)
        await _finish_le_queue(update, context, session, status_msg)
    return "handled"


async def _cleanup_temp_inbox_safely(session):
    """صندوقِ موقتِ فعلی رو (اگه هست) حذف و از session پاک می‌کنه، و شمارنده‌یِ
    استفاده‌ش رو صفر می‌کنه. هیچ‌وقت استثنا پرت نمی‌کنه - شکستِ حذف بی‌اهمیته چون
    mail.tm خودش بعداً پاکش می‌کنه."""
    inbox = getattr(session, "temp_inbox", None)
    session.temp_inbox = None
    session.temp_inbox_uses = 0
    # وضعیتِ مربوط به صندوقِ قبلی دیگه بی‌معنیه - صندوقِ بعدی کاملاً تازه‌ست
    session.temp_baseline_ids = set()
    session.temp_used_codes = set()
    if not inbox:
        return
    try:
        import tempmail
        await asyncio.to_thread(
            tempmail.delete_temp_inbox, inbox.get("token"), inbox.get("account_id")
        )
    except Exception:
        pass


async def _try_auto_email_code(update, context, session, status_msg, acc_name):
    """
    تلاش برایِ خواندنِ خودکارِ کدِ تأیید از ایمیل و اعمالش، برایِ اکانتِ فعلیِ صفِ
    «تغییرِ ایمیلِ لاگین».

    خروجی:
      None  → خودکار انجام نشد (به هر دلیل) - صداکننده باید به حالتِ دستی برگرده.
      (چیزِ دیگه) → کار انجام شد و صف جلو رفت؛ صداکننده باید همون رو return کنه.

    قاعده‌یِ کلی: هر شکستی این‌جا بی‌صدا None برمی‌گردونه تا تجربه هیچ‌وقت بدتر از
    حالتِ دستیِ فعلی نشه. فقط وقتی کد *واقعاً* پیدا و *با موفقیت* اعمال بشه، مسیرِ
    خودکار رو کامل می‌کنه.
    """
    # ---- مسیرِ «ایمیلِ موقتِ خودکار» (mail.tm) ----
    # اگه این صف با temp-mail کار می‌کنه، کد رو از API mail.tm می‌خونیم، نه IMAP.
    # این مسیر عمداً *قبل* از چکِ استخرِ IMAP میاد چون آدرسِ temp-mail هیچ‌وقت توی
    # اون استخر نیست.
    if getattr(session, "use_temp_mail", False):
        return await _try_auto_email_code_tempmail(update, context, session, status_msg, acc_name)

    creds = await find_auto_email_pool_entry_by_address(session.email)
    if not creds:
        return None  # این آدرس توی استخرِ ایمیلِ خودکار نیست (یا استخر خالیه)

    # لحظه‌یِ شروع - فقط کدهایی که *بعد* از الان می‌رسن قبولن (کدِ اکانتِ قبلی رو
    # اشتباهی نخونیم). چند ثانیه ارفاق می‌دیم چون ساعتِ سرورِ ایمیل ممکنه کمی جلو/عقب باشه.
    import time as _time
    since = _time.time() - 20

    try:
        await status_msg.edit_text(
            f"📧 اکانتِ «{acc_name}»: در حالِ خواندنِ خودکارِ کد از ایمیل...\n"
            f"({session.queue_index + 1} از {len(session.selected_accounts)})"
        )
    except Exception:
        pass

    # ایمیل ممکنه چند ثانیه دیر برسه - چند بار با فاصله چک می‌کنیم (تا ~۹۰ ثانیه).
    import email_reader
    code = None
    code_msg_id = None
    for attempt in range(18):
        try:
            result = await asyncio.to_thread(
                email_reader.fetch_latest_telegram_code,
                creds["address"], creds["password"], since,
            )
        except Exception:
            result = {"status": "error", "message": "خطایِ داخلی هنگامِ خواندنِ ایمیل"}

        if result.get("status") == "found":
            code = result["code"]
            code_msg_id = result.get("message_id")
            break
        if result.get("status") == "error":
            # خطایِ اتصال/لاگین - یه‌بار به کاربر بگو و برگرد به حالتِ دستی
            try:
                await update.message.reply_text(
                    f"⚠️ خواندنِ خودکارِ ایمیل ممکن نشد: {result.get('message', 'نامشخص')}\n"
                    "به حالتِ دستی برگشتیم - کد رو خودت بفرست."
                )
            except Exception:
                pass
            return None
        await asyncio.sleep(5)  # not_found - هنوز نرسیده، صبر کن

    if not code:
        # کد توی مهلت نرسید - به حالتِ دستی برگرد (شاید ایمیل با تأخیرِ زیاد بیاد)
        try:
            await update.message.reply_text(
                f"⏳ کدِ ایمیلِ اکانتِ «{acc_name}» توی مهلتِ خودکار نرسید.\n"
                "کد رو دستی بفرست (یا اگه رسید و خودکار برنداشت، «🔄 ارسال کد مجدد» رو بزن):",
                reply_markup=_le_waiting_code_keyboard()
            )
        except Exception:
            pass
        context.user_data["awaiting"] = "le_waiting_code"
        return "handled"  # منتظرِ کاربر می‌مونیم، ولی صف جلو نرفته

    # ---- کد پیدا شد؛ اعمالش کن ----
    step2 = await le_confirm_pending_code(session, code)

    if step2["action"] == "wrong_code":
        # کدِ خونده‌شده اشتباه بود (بعید ولی ممکن) - به حالتِ دستی برگرد
        try:
            await update.message.reply_text(
                f"❌ کدی که خودکار از ایمیل خونده شد برایِ «{acc_name}» درست نبود.\n"
                "کد رو دستی بفرست:",
                reply_markup=_le_waiting_code_keyboard()
            )
        except Exception:
            pass
        context.user_data["awaiting"] = "le_waiting_code"
        return "handled"

    if step2["action"] == "need_new_email":
        acc2 = step2["account"]
        n2 = acc2.get("nickname") or acc2.get("phone")
        context.user_data["awaiting"] = "le_waiting_new_email"
        await update.message.reply_text(
            f"❌ برایِ اکانتِ «{n2}» این ایمیل رد شد: {step2['message']}\n\n"
            "یه ایمیلِ *دیگه* بفرست، یا از این اکانت رد شو:",
            reply_markup=_le_waiting_new_email_keyboard()
        )
        return "handled"

    if step2["action"] in ("flood", "account_failed"):
        # مشکل از خودِ اکانته (نه ایمیل و نه کد) - این اکانت رد می‌شه و صف خودکار
        # می‌ره اکانتِ بعدی، دقیقاً مثلِ مسیرِ دستی.
        await update.message.reply_text(f"⏭ «{acc_name}» رد شد: {step2.get('message', 'مشکلی پیش اومد')}")
        # فقط account_failed یعنی «قطعاً بلاکه» - flood یه محدودیتِ موقتِ تلگرامه،
        # نه یه شکستِ همیشگی، پس نباید توی جدولِ account_task_blocked ثبتِ دائم بشه.
        le_mark_current_account_failed(
            session, step2.get("message", "مشکلی پیش اومد"),
            permanent=(step2["action"] == "account_failed"),
        )
        await _run_le_queue(update, context, session, status_msg)
        return "handled"

    # account_done - همون لحظه ذخیره کن و برو اکانتِ بعدی (کاملاً خودکار)
    try:
        await set_account_task_done(step2["account"]["id"], "login_email", True)
        await resolve_account_task_blocked(step2["account"]["id"], "login_email", resolution="success")
    except Exception:
        pass
    # ایمیلِ خونده‌شده رو پاک کن تا با اکانتِ بعدی قاطی نشه
    await _delete_auto_email_safely(code_msg_id, session.email)
    try:
        await update.message.reply_text(f"✅ «{acc_name}» - کد خودکار از ایمیل خونده و اعمال شد.")
    except Exception:
        pass
    if step2["has_more"]:
        await _run_le_queue(update, context, session, status_msg)
    else:
        await _finish_le_queue(update, context, session, status_msg)
    return "handled"


async def _run_le_queue(update: Update, context: ContextTypes.DEFAULT_TYPE, session: "LoginEmailChangeSession", status_msg):
    """
    موتورِ اصلیِ اجرایِ صفِ تغییرِ ایمیلِ لاگین - برایِ اکانتِ فعلی کدِ تأیید می‌فرسته.
    اگه تلگرام ایمیل رو رد کنه، همینجا متوقف می‌شه و از کاربر ایمیلِ جدید می‌خواد
    (awaiting="le_waiting_new_email") - با همون ایمیلِ جدید دوباره همین تابع صدا
    زده می‌شه (نگاه کن به هندلرِ متنیِ le_waiting_new_email)، یعنی اکانتِ فعلی رو از
    نو امتحان می‌کنه، نه اینکه ردش کنه.
    """
    acc = session.current_account()
    if acc is None:
        await _finish_le_queue(update, context, session, status_msg)
        return

    acc_name = acc.get("nickname") or acc.get("phone")

    # ---- حالتِ «ایمیلِ موقتِ خودکار» ----
    # تلگرام اجازه می‌ده هر ایمیل حداکثر برایِ MAX_ACCOUNTS_PER_TEMP_EMAIL اکانت
    # (=۲) به‌عنوانِ ایمیلِ لاگین استفاده بشه. پس صندوقِ فعلی رو نگه می‌داریم و فقط
    # وقتی صندوق نداریم یا به سقفِ استفاده رسیده، یه صندوقِ تازه می‌سازیم - این‌طوری
    # نصفِ تعدادِ درخواست به mail.tm می‌ره و دیگه به خطایِ «این ایمیل قبلاً استفاده
    # شده» نمی‌خوریم. اگه ساختِ صندوق شکست خورد، این اکانت رد می‌شه و می‌ریم بعدی
    # (نه اینکه کلِ صف بترکه).
    if session.use_temp_mail:
        import tempmail as tempmail_mod
        need_new = (
            session.temp_inbox is None
            or session.temp_inbox_uses >= MAX_ACCOUNTS_PER_TEMP_EMAIL
        )
        if need_new:
            # صندوقِ قبلی (اگه بود) به سقف رسیده - پاکش کن تا نشتِ صندوق نداشته باشیم
            await _cleanup_temp_inbox_safely(session)
            try:
                await status_msg.edit_text(
                    f"🎲 در حالِ ساختِ ایمیلِ موقتِ تازه برایِ «{acc_name}»...\n"
                    f"({session.queue_index + 1} از {len(session.selected_accounts)})"
                )
            except Exception:
                pass
            import tempmail
            reason = "نامشخص"
            try:
                inbox = await asyncio.wait_for(
                    asyncio.to_thread(tempmail_mod.create_temp_inbox),
                    timeout=TEMPMAIL_OP_TIMEOUT,
                )
            except asyncio.TimeoutError:
                inbox = None
                reason = (
                    f"بیش از {TEMPMAIL_OP_TIMEOUT} ثانیه طول کشید - احتمالاً DNS یا "
                    f"اتصالِ سرور به mail.tm کنده/مسدوده"
                )
            except Exception as e:
                inbox = None
                # ⚠️ عمداً جزئیاتِ کاملِ خطا (نه فقط نامِ نوعش): قبلاً برایِ خطاهایِ
                # غیرِ TempMailError فقط «AttributeError» نشون داده می‌شد که هیچ
                # سرنخی از علتِ واقعی نمی‌داد و عیب‌یابی رو غیرممکن می‌کرد.
                reason = str(e) if isinstance(e, tempmail.TempMailError) else f"{type(e).__name__}: {e}"
            if not inbox:
                await update.message.reply_text(
                    f"⚠️ ساختِ ایمیلِ موقت برایِ «{acc_name}» نشد: {reason}\n"
                    f"این اکانت رد شد؛ می‌ریم سراغِ بعدی."
                )
                le_mark_current_account_failed(session, f"ساختِ ایمیلِ موقت نشد: {reason}")
                await _run_le_queue(update, context, session, status_msg)
                return
            session.temp_inbox = inbox
            session.temp_inbox_uses = 0
        session.email = session.temp_inbox["address"]

        # ---- عکسِ لحظه‌ایِ صندوق، *قبل* از اینکه تلگرام کدِ جدید رو بفرسته ----
        # این تنها چیزیه که ۱۰۰٪ جلویِ خواندنِ کدِ اکانتِ قبلی رو می‌گیره: هر پیامی
        # که همین الان توی صندوق هست، مالِ گذشته‌ست و برایِ این اکانت نامعتبره.
        # عمداً همین‌جاست (قبل از le_process_next_account که درخواستِ کد رو می‌فرسته)،
        # نه بعدش - وگرنه ممکنه کدِ جدید بینِ این دو خط برسه و اشتباهی رد بشه.
        try:
            session.temp_baseline_ids = await asyncio.wait_for(
                asyncio.to_thread(tempmail_mod.list_message_ids, session.temp_inbox["token"]),
                timeout=TEMPMAIL_OP_TIMEOUT,
            )
        except Exception:
            session.temp_baseline_ids = set()

    try:
        await status_msg.edit_text(
            f"⏳ در حالِ ارسالِ کد...\n\n"
            f"اکانتِ {session.queue_index + 1} از {len(session.selected_accounts)}: {acc_name}\n"
            f"ایمیل: {session.email}"
        )
    except Exception:
        pass

    step = await le_process_next_account(session)

    if step["action"] == "need_code":
        # ---- تلاش برایِ خواندنِ خودکارِ کد از ایمیل (اگه تنظیم شده) ----
        # نگاه کن به _try_auto_email_code. اگه موفق شد، بدونِ دخالتِ کاربر کد رو
        # اعمال می‌کنه و می‌ره اکانتِ بعدی. اگه هر جا شکست خورد (ایمیل تنظیم نشده،
        # آدرس فرق داره، کد نرسید، خطایِ اتصال) بی‌صدا به حالتِ دستیِ همیشگی
        # برمی‌گرده - یعنی هیچ‌وقت بدتر از قبل نمی‌شه.
        auto = await _try_auto_email_code(update, context, session, status_msg, acc_name)
        if auto is not None:
            return auto

        context.user_data["awaiting"] = "le_waiting_code"
        await update.message.reply_text(
            f"📧 برایِ اکانتِ «{acc_name}» تلگرام یه کدِ {step['code_length']} رقمی به "
            f"ایمیلِ «{session.email}» فرستاد.\n"
            f"کد رو همینجا بفرست:",
            reply_markup=_le_waiting_code_keyboard()
        )
        return  # اینجا متوقف می‌شیم - ادامه با پیامِ بعدیِ کاربر (کد)

    if step["action"] == "need_new_email":
        context.user_data["awaiting"] = "le_waiting_new_email"
        await update.message.reply_text(
            f"❌ برایِ اکانتِ «{acc_name}» این ایمیل رد شد: {step['message']}\n\n"
            f"یه ایمیلِ *دیگه* بفرست تا با اون ادامه بدیم، یا اگه فکر می‌کنی خودِ "
            f"این اکانت مشکل داره (نه ایمیل)، از این اکانت رد شو:",
            reply_markup=_le_waiting_new_email_keyboard()
        )
        return

    if step["action"] == "account_failed":
        # مشکل از خودِ اکانته، نه ایمیل - پس ایمیلِ جدید نمی‌خوایم (وگرنه کاربر
        # توی یه حلقه‌یِ بی‌پایان گیر می‌کرد) و می‌ریم سراغِ اکانتِ بعدی
        await update.message.reply_text(
            f"⏭ اکانتِ «{acc_name}» رد شد: {step['message']}\n\n"
            f"ایمیلِ فرستاده‌شده مشکلی نداشت - می‌ریم سراغِ اکانتِ بعدی."
        )
        le_mark_current_account_failed(session, step["message"], permanent=True)
        await _run_le_queue(update, context, session, status_msg)
        return

    if step["action"] == "flood":
        await update.message.reply_text(f"⏳ {acc_name}: {step['message']} - این اکانت رد شد.")
        le_mark_current_account_failed(session, step["message"])
        await _run_le_queue(update, context, session, status_msg)
        return

    if step["action"] == "all_done":
        await _finish_le_queue(update, context, session, status_msg)
        return


async def _finish_le_queue(update: Update, context: ContextTypes.DEFAULT_TYPE, session: "LoginEmailChangeSession", status_msg):
    """ساختنِ گزارشِ نهاییِ تغییرِ ایمیلِ لاگین و بازگشت به منویِ اکانت‌ها."""
    for acc in session.selected_accounts:
        entry = session.results.get(acc["id"])
        if entry and entry.get("status") == "success":
            await set_account_task_done(acc["id"], "login_email", True)
            # اگه قبلاً بلاک شده بود، حالا حل شد.
            try:
                await resolve_account_task_blocked(acc["id"], "login_email", resolution="success")
            except Exception:
                pass
        elif entry and entry.get("status") == "error" and entry.get("permanent"):
            # ⚠️ فقط خطاهایِ *دائمی* (action_failed - نگاه کن به change_login_email.
            # py::mark_current_account_failed) ثبتِ پایدار می‌شن؛ فلود/شکستِ گذرا
            # عمداً این‌جا نمی‌آن تا اکانتِ سالم به‌اشتباه توی لیستِ سومِ «ایمیل
            # نمیشه تنظیم کرد» گیر نکنه.
            try:
                await mark_account_task_blocked(
                    acc["id"], "login_email",
                    reason="ایمیلِ لاگین نمیشه تنظیم کرد",
                    last_error=entry.get("message"),
                )
            except Exception:
                pass

    full_text = le_format_final_report(session)

    try:
        await status_msg.delete()
    except Exception:
        pass

    # محکم‌کاری: شکستِ ارسالِ یه قطعه (سقفِ طولِ تلگرام، فلود، هرچی) نباید جلویِ
    # بقیه‌یِ گزارش و برگشتن به منو رو بگیره - همون باگی که باعث شد گزارشِ ۶۷
    # اکانتی فقط سرتیترش نمایش داده بشه و منو هم دیگه نیاد.
    sent_any = False
    for chunk in _split_long_text(full_text):
        try:
            await update.message.reply_text(chunk)
            sent_any = True
        except Exception:
            continue
    if not sent_any:
        try:
            await update.message.reply_text(
                "📧 تغییرِ ایمیلِ لاگین تموم شد، ولی نمایشِ گزارش با خطا مواجه شد.\n"
                "وضعیتِ هر اکانت توی لیستِ اکانت‌ها با علامتِ ✅ مشخصه."
            )
        except Exception:
            pass

    _reset_flow(context)
    try:
        await send_accounts_menu(update.message, context=context)
    except Exception:
        pass





# ============================================================================
# رفتارِ اکانت‌ها (humanize) - تنظیماتِ سراسریِ شبیه‌سازیِ رفتارِ انسانی، برایِ
# جلوگیری از دیلیت‌شدنِ اکانت‌ها توسطِ تلگرام. منطقِ واقعیِ اجرا توی humanize.py و
# جدولِ humanize_settings (دیتابیس) زندگی می‌کنه - این بخش فقط رابطِ کاربریِ
# روشن/خاموش‌کردن و ویرایشِ بازه‌هاست.
# ============================================================================

_HUMANIZE_ACTION_LABELS = {
    "saved_message": "📩 پیام در Saved Messages (فردا پاک می‌شه)",
    "story": "📸 استوریِ عکسِ طبیعت (از ~۲۰۰ عکسِ متفاوت - بعدِ ۲۴ ساعت خودش پاک می‌شه)",
    "channel": "📢 ساختِ یه کانال (فردا پاک می‌شه)",
    "pin_chat": "📌 پینِ یکی از چت‌هایِ موجود (فردا آنپین می‌شه)",
}


def _fmt_num(n) -> str:
    """نمایشِ تمیزِ یه عدد - ۵ به‌جایِ ۵.۰، ولی ۵.۵ همون ۵.۵ می‌مونه."""
    n = float(n)
    return f"{n:g}"


# کلیدهایِ کانالِ منبعِ «🖼 تغییرِ پروفایلِ تدریجی» - عیناً همون‌هایی که
# humanize._run_profile_rotation_tick می‌خونه. یه‌جا تعریف شدن تا دو طرف
# هیچ‌وقت از هم جدا نیفتن.
PROFILE_ROTATION_CHANNEL_KEY = "humanize_profile_rotation_channel"
PROFILE_ROTATION_ADMIN_SESSION_KEY = "humanize_profile_rotation_admin_session"
PROFILE_ROTATION_CHANNEL_DISPLAY_KEY = "humanize_profile_rotation_channel_display"


async def _humanize_settings_full() -> dict:
    """
    تنظیماتِ 🎭 رفتارِ اکانت‌ها + اطلاعاتِ کانالِ منبعِ تغییرِ پروفایل.

    ⚠️ همه‌ی مسیرهایی که منویِ رفتارِ اکانت‌ها رو نشون می‌دن باید *همین* رو صدا
    بزنن، نه get_humanize_settings خام - وگرنه اسمِ کانالِ ثبت‌شده توی متن
    نمایش داده نمی‌شه.
    """
    settings = await get_humanize_settings()
    try:
        settings = dict(settings)
        settings["_profile_rotation_channel_display"] = await get_setting(
            PROFILE_ROTATION_CHANNEL_DISPLAY_KEY
        )
    except Exception:
        pass
    return settings


async def _inactivity_guard_status_text() -> str:
    """
    گزارشِ «🛡 محافظت از حذفِ اکانتِ بی‌استفاده»: کدوم اکانت‌ها در خطرن و چند
    روزه آنلاین نشدن.
    """
    settings = await get_humanize_settings()
    ping_days = int(settings.get("inactivity_ping_days", 10) or 10)
    ttl_days = int(settings.get("account_ttl_days", 365) or 365)

    accounts = await get_all_accounts()
    pool = [a for a in accounts if a.get("session_file") and a.get("is_logged_in")]
    try:
        rows = await get_inactivity_guard_rows()
    except Exception:
        rows = {}

    now = utcnow()
    never, fresh, stale, failing = [], 0, [], []
    ttl_ok = 0
    ttl_pending = 0
    ttl_failing = []
    ttl_recent = 0
    for acc in pool:
        row = rows.get(acc["id"]) or {}
        if int(row.get("ttl_days") or 0) >= ttl_days:
            ttl_ok += 1
        else:
            ttl_pending += 1
        if int(row.get("ttl_fail_count") or 0) > 0:
            ttl_failing.append((acc, row))
        try:
            attempted = row.get("ttl_last_attempt_at")
            if attempted:
                parsed = datetime.fromisoformat(
                    str(attempted).replace("Z", "+00:00")).replace(tzinfo=None)
                if (now - parsed).total_seconds() < 86400:
                    ttl_recent += 1
        except Exception:
            pass
        if int(row.get("fail_count") or 0) > 0:
            failing.append((acc, row))
        last_raw = row.get("last_online_at")
        if not last_raw:
            never.append(acc)
            continue
        try:
            last = datetime.fromisoformat(str(last_raw).replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            never.append(acc)
            continue
        days = (now - last).total_seconds() / 86400.0
        if days >= ping_days:
            stale.append((acc, days))
        else:
            fresh += 1

    lines = [
        "🛡 محافظت از حذفِ اکانتِ بی‌استفاده",
        "",
        f"وضعیت: {'✅ روشن' if settings.get('enabled_inactivity_guard', 1) else '❌ خاموش'}",
        f"فاصله‌یِ آنلاین‌کردنِ اجباری: هر {ping_days} روز",
        f"مهلتِ حذفِ خودکارِ تنظیم‌شده رویِ تلگرام: {ttl_days} روز",
        "",
        f"کلِ اکانت‌هایِ لاگین: {len(pool)}",
        f"✅ آنلاینِ به‌روز: {fresh}",
        f"⏳ نوبتِ آنلاین‌شدنشون رسیده: {len(stale)}",
        f"❓ هنوز هیچ‌وقت ثبت نشدن: {len(never)}",
        f"🔒 مهلتِ حذفشون تمدید شده: {ttl_ok} از {len(pool)}",
    ]

    # ---- پیشرفتِ تمدیدِ تدریجی ----
    # ⚠️ این بخش عمداً صریحه: قبلاً تمدیدِ مهلت فقط برایِ اکانت‌هایی انجام می‌شد که
    # «نوبتِ پینگشون» رسیده بود، پس عددِ بالا تقریباً همیشه صفر می‌موند و هیچ‌جا
    # معلوم نبود چرا. حالا هم سرعت، هم سهمِ امروز، هم اکانت‌هایِ مشکل‌دار دیده می‌شن.
    per_day = int(settings.get("ttl_rollout_per_day", 8) or 8)
    rollout_on = bool(settings.get("enabled_ttl_rollout", 1))
    lines += [
        "",
        f"⏳ تمدیدِ تدریجی: {'✅ روشن' if rollout_on else '❌ خاموش'} - "
        f"سرعتِ {per_day} اکانت در ۲۴ ساعت",
        f"   باقی‌مانده: {ttl_pending} اکانت   •   در ۲۴ ساعتِ گذشته: {ttl_recent} تلاش",
    ]
    if rollout_on and ttl_pending:
        days_left = -(-ttl_pending // max(1, per_day))
        lines.append(f"   با این سرعت، حدودِ {days_left} روزِ دیگه همه تمدید می‌شن.")
    if not rollout_on and ttl_pending:
        lines.append("   ⚠️ خاموشه، پس این اکانت‌ها رویِ مهلتِ پیش‌فرضِ ۶ماهه‌یِ تلگرام می‌مونن.")
    if ttl_failing:
        lines.append(f"   ❌ {len(ttl_failing)} اکانت در تمدید به مشکل خوردن:")
        for acc, row in ttl_failing[:4]:
            name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
            lines.append(f"     • {name}: {row.get('ttl_last_error') or 'نامشخص'}")

    if stale:
        stale.sort(key=lambda x: -x[1])
        lines += ["", "قدیمی‌ترین‌ها (به‌زودی خودکار آنلاین می‌شن):"]
        for acc, days in stale[:6]:
            name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
            lines.append(f"• {name}: {int(days)} روز پیش")

    if failing:
        lines += ["", "⚠️ اکانت‌هایی که آنلاین‌شدنشون شکست خورده:"]
        for acc, row in failing[:6]:
            name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
            lines.append(
                f"• {name}: {row.get('fail_count')} تلاشِ ناموفق - {row.get('last_error') or 'نامشخص'}"
            )
        lines.append("سشنِ این‌ها رو بررسی کن؛ اگه درست نشن، تلگرام بالاخره حذفشون می‌کنه.")

    if never and not rows:
        lines += ["", "ℹ️ هنوز هیچ دوری اجرا نشده - اولین دور تا یک ساعتِ دیگه شروع می‌شه."]

    return "\n".join(lines)


async def _profile_rotation_status_text() -> str:
    """
    گزارشِ «🖼 تغییرِ پروفایلِ تدریجی»: چند اکانت هم‌اسمن، چندتاشون عوض شدن، و
    چندتا هنوز توی صفن. از *همون* منطقِ humanize.py استفاده می‌کنه (نه یه کپیِ
    جدا)، تا عددی که این‌جا نشون داده می‌شه دقیقاً همونی باشه که واقعاً پردازش
    می‌شه.
    """
    import humanize as humanize_module

    channel_display = await get_setting(PROFILE_ROTATION_CHANNEL_DISPLAY_KEY)
    admin_session = await get_setting(PROFILE_ROTATION_ADMIN_SESSION_KEY)

    settings = await get_humanize_settings()
    all_accounts = await get_all_accounts()
    # ⬅️ همون تابعی که خودِ حلقه استفاده می‌کنه - تا عددی که این‌جا نشون داده
    # می‌شه دقیقاً همونی باشه که واقعاً پردازش می‌شه
    usable, targets, quarantined = humanize_module.get_profile_rotation_pool(
        all_accounts, settings
    )
    try:
        rows = await get_profile_rotation_rows()
    except Exception:
        rows = {}

    done_ids = {aid for aid, r in rows.items() if r.get("done")}
    done_n = sum(1 for a in targets if a["id"] in done_ids)
    remaining = [a for a in targets if a["id"] not in done_ids]
    # اکانت‌هایی که وسطِ زنجیره‌ی مرحله‌ای‌ان
    in_progress = [
        (a, rows.get(a["id"]))
        for a in targets
        if a["id"] not in done_ids
        and rows.get(a["id"]) and rows[a["id"]].get("stage")
        and rows[a["id"]].get("stage") != "done"
    ]

    # گروه‌بندی برایِ نمایش - همون نرمال‌سازیِ humanize
    groups = {}
    for acc in usable:
        key = humanize_module._normalize_display_name(acc.get("nickname"))
        if key:
            groups.setdefault(key, []).append(acc)
    dup_groups = {k: v for k, v in groups.items() if len(v) > 1}

    lines = [
        "📊 وضعیتِ تغییرِ پروفایلِ تدریجی",
        "",
        f"وضعیت: {'✅ روشن' if settings.get('enabled_profile_rotation', 0) else '❌ خاموش'}",
        f"کانالِ منبع: {channel_display or '⚠️ ثبت نشده'}",
    ]
    if channel_display and not admin_session:
        lines.append("⚠️ اکانتِ ادمینِ کانال ثبت نشده - دوباره کانال رو ثبت کن.")

    # ⚠️ این بخش تازه اضافه شده: قبلاً اگه اسکنِ کانالِ منبع شکست می‌خورد (FloodWait،
    # تایم‌اوت، ادمین‌بودنِ اکانت لغو شده، ...)، هیچ نشونه‌ای *هیچ‌جا* دیده نمی‌شد -
    # فقط «✅ عوض‌شده» و «🔄 وسطِ کار» برایِ همیشه صفر می‌موندن، بدونِ هیچ سرنخی که چرا.
    scan_error = await get_setting(humanize_module.PROFILE_ROTATION_SCAN_ERROR_KEY)
    if scan_error:
        scan_error_at = await get_setting(humanize_module.PROFILE_ROTATION_SCAN_ERROR_AT_KEY)
        lines.append(
            f"❌ آخرین اسکنِ کانالِ منبع شکست خورد"
            + (f" ({scan_error_at})" if scan_error_at else "")
            + f":\n   {scan_error}\n"
            "   (این دلیلِ اصلیِ صفرماندنِ «کاملاً عوض شده» و «وسطِ کار»ه - "
            "معمولاً یعنی اکانتِ ادمین دیگه توی کانال ادمین نیست، سشنش خرابه، یا "
            "به‌خاطرِ فعالیتِ زیاد با FloodWait مواجه شده.)"
        )

    lines += [
        "",
        f"گروه‌هایِ هم‌اسم: {len(dup_groups)}",
        f"اکانتِ هدف (کلِ گروه‌ها منهایِ قدیمی‌ترینِ هر گروه): {len(targets)}",
        f"✅ کاملاً عوض شده: {done_n}",
        f"🔄 وسطِ کار: {len(in_progress)}",
        f"⏳ توی صف: {len(remaining) - len(in_progress)}",
        "",
        "مراحلِ هر اکانت با فاصله انجام می‌شن:",
        f"اسم → {_fmt_num(humanize_module.PROFILE_STAGE_GAP_HOURS['photo'])} ساعت → عکس → "
        f"{_fmt_num(humanize_module.PROFILE_STAGE_GAP_HOURS['bio'])} ساعت → بیو → "
        f"{_fmt_num(humanize_module.PROFILE_STAGE_GAP_HOURS['birthday'])} ساعت → تاریخِ تولد",
    ]

    if in_progress:
        lines += ["", "اکانت‌هایِ وسطِ کار:"]
        for acc, row in in_progress[:6]:
            name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
            stage_label = humanize_module.PROFILE_STAGE_LABELS.get(
                row.get("stage"), row.get("stage")
            )
            progress = row.get("stages_log") or "—"
            when = row.get("next_change_at") or "؟"
            lines.append(f"• {name}: {progress} ← مرحله‌یِ بعدی «{stage_label}» در {when}")

    if dup_groups:
        lines += ["", "چند نمونه از گروه‌هایِ هم‌اسم:"]
        for key, members in sorted(dup_groups.items(), key=lambda kv: -len(kv[1]))[:5]:
            sample_name = members[0].get("nickname") or key
            lines.append(f"• «{sample_name}» → {len(members)} اکانت")

    failed = [(aid, r) for aid, r in rows.items() if r.get("last_error") and not r.get("done")]
    if failed:
        lines += ["", f"❌ آخرین تلاشِ ناموفق: {len(failed)} اکانت (خودکار دوباره امتحان می‌شن)"]
        for aid, r in failed[:3]:
            lines.append(f"• #{aid}: {r.get('last_error')}")

    if quarantined:
        lines += [
            "",
            f"🧪 {len(quarantined)} اکانت توی قرنطینه‌یِ سشنِ تازه‌ن و فعلاً کنار گذاشته "
            "شدن. بعد از تمام‌شدنِ قرنطینه خودکار وارد صف می‌شن.",
        ]

    if not targets:
        lines += ["", "ℹ️ هیچ اکانتِ هم‌اسمی پیدا نشد - همه‌ی اسم‌ها یکتان."]

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# سقفِ طولِ پیامِ تلگرام
# ---------------------------------------------------------------------------
# ⚠️ باگِ اصلیِ رفع‌شده‌یِ بخشِ «🎭 رفتارِ اکانت‌ها»: متنِ وضعیتِ این منو به‌مرورِ
# زمان (با اضافه‌شدنِ قابلیت‌ها و توضیحاتشون) از سقفِ ۴۰۹۶ کاراکتریِ تلگرام رد
# شده بود. نتیجه: *هر* تلاشی برایِ فرستادنِ منو - چه با زدنِ خودِ دکمه‌ی
# «🎭 رفتارِ اکانت‌ها»، چه بعدِ روشن/خاموش‌کردنِ یه گزینه، چه بعدِ تنظیمِ یه عدد -
# با خطایِ «Message is too long» برمی‌گشت و کاربر *هیچ* جوابی نمی‌گرفت؛ یعنی از
# دیدِ کاربر «دکمه کار نمی‌کنه». حالا سه لایه محافظت داریم:
#   ۱) متنِ منو خلاصه‌ست (_format_humanize_settings_text) و توضیحاتِ بلند رفته
#      زیرِ دکمه‌یِ «ℹ️ توضیحاتِ کامل» (_format_humanize_help_text).
#   ۲) هر متنِ بلند خودکار تیکه‌تیکه فرستاده می‌شه (_split_long_text).
#   ۳) اگه بازم به هر دلیلی ارسال شکست بخورد، یه پیامِ حداقلی *همراهِ کیبورد*
#      می‌ره تا منو هیچ‌وقت ناپدید نشه (_send_humanize_menu).
TELEGRAM_MESSAGE_LIMIT = 4096
_SAFE_MESSAGE_LIMIT = 3500


def _split_long_text(text: str, limit: int = _SAFE_MESSAGE_LIMIT) -> list:
    """یه متنِ بلند رو رویِ مرزِ خط‌ها به تیکه‌هایِ کوچک‌ترِ سقفِ تلگرام می‌شکنه."""
    if len(text) <= limit:
        return [text]
    parts, buf = [], ""
    for line in text.split("\n"):
        # یه خطِ تنهایِ خیلی بلند (بدونِ \n) - مجبوریم از وسط ببُریمش
        while len(line) > limit:
            if buf:
                parts.append(buf)
                buf = ""
            parts.append(line[:limit])
            line = line[limit:]
        if not buf:
            buf = line
        elif len(buf) + 1 + len(line) <= limit:
            buf += "\n" + line
        else:
            parts.append(buf)
            buf = line
    if buf:
        parts.append(buf)
    return parts


# پیش‌فرضِ روشن/خاموشِ هر گزینه - *یک* منبعِ حقیقت برایِ متنِ وضعیت، کیبورد و
# هندلرِ toggle.
# ⚠️ باگی که این‌جا حل شد: متنِ وضعیت برایِ privacy_random/account_sorting/
# profile_rotation پیش‌فرضِ ۰ می‌گرفت ولی کیبورد و toggle پیش‌فرضِ ۱ - یعنی اگه
# ستون توی دیتابیس نبود، متن ❌ نشون می‌داد و دکمه ✅، و اولین فشارِ دکمه هم
# چیزی رو که «خاموش» نشون داده می‌شد «خاموش» می‌کرد.
_HUMANIZE_DEFAULT_ENABLED = {
    "saved_message": 1,
    "story": 1,
    "channel": 1,
    "pin_chat": 1,
    "online": 1,
    "read_dialogs": 1,
    "quiet_hours": 1,
    "daily_cap": 1,
    "warmup": 1,
    "quarantine": 1,
    "privacy_random": 0,
    "account_sorting": 0,
    "profile_rotation": 0,
    "inactivity_guard": 1,
    "ttl_rollout": 1,
    "spare_keepalive": 1,
    "spare_autobuild": 1,
}


def _hum_enabled(settings: dict, key: str) -> bool:
    return bool(settings.get(f"enabled_{key}", _HUMANIZE_DEFAULT_ENABLED.get(key, 1)))


def _hum_mark(settings: dict, key: str) -> str:
    return "✅" if _hum_enabled(settings, key) else "❌"


def _format_humanize_settings_text(settings: dict) -> str:
    """
    خلاصه‌یِ وضعیتِ «🎭 رفتارِ اکانت‌ها» - عمداً کوتاه.

    ⚠️ این متن باید *خیلی* کمتر از ۴۰۹۶ کاراکتر بمونه (نگاه کن به کامنتِ بالایِ
    TELEGRAM_MESSAGE_LIMIT). توضیحِ کاملِ هر گزینه توی _format_humanize_help_text
    زندگی می‌کنه و با دکمه‌یِ «ℹ️ توضیحاتِ کامل» دیده می‌شه - پس اگه خواستی
    توضیحی اضافه کنی، اون‌جا اضافه‌ش کن، نه این‌جا.
    """
    g = settings.get

    def m(key):
        return _hum_mark(settings, key)

    channel_display = g("_profile_rotation_channel_display")
    lines = [
        "🎭 رفتارِ اکانت‌ها",
        "شبیه‌سازیِ رفتارِ انسانی، تا تلگرام اکانت‌ها رو حذف نکنه.",
        "",
        "━━ 🎭 فعالیتِ دوره‌ای ━━",
        f"هر {_fmt_num(g('cycle_days_min', 5))} تا {_fmt_num(g('cycle_days_max', 6))} روز، فقط *یکی* از این‌ها (رندوم):",
        f"{m('saved_message')} پیام در Saved     {m('story')} استوریِ عکسِ طبیعت",
        f"{m('channel')} ساختِ یه کانال     {m('pin_chat')} پینِ یه چت",
        "",
        "━━ 🟢 حضورِ روزانه ━━",
        f"{m('online')} آنلاینِ روزانه: {g('online_min_minutes', 60)} تا {g('online_max_minutes', 90)} دقیقه",
        f"{m('read_dialogs')} خوندنِ چت‌ها: هر {g('read_dialogs_min_minutes', 50)} تا {g('read_dialogs_max_minutes', 80)} دقیقه",
        f"{m('quiet_hours')} سکوتِ شبانه: {g('quiet_start_hour', 1)}:00 تا {g('quiet_end_hour', 8)}:00 به وقتِ تهران",
        "",
        "━━ 🛡 سقف و ایمنی ━━",
        f"{m('daily_cap')} سقفِ فعالیتِ روزانه: {g('daily_action_cap', 50)} بازدید/ری‌اکشن",
        f"{m('warmup')} گرم‌کردنِ اکانتِ تازه: {g('warmup_days', 7)} روز، سقفِ {g('warmup_daily_cap', 10)}",
        f"{m('quarantine')} قرنطینه‌یِ سشنِ تازه: {g('quarantine_hours', 24)} ساعتِ اول",
        "",
        "━━ 🔒 محافظت از حذفِ اکانت ━━",
        f"{m('inactivity_guard')} نگهبانِ اکانتِ بی‌استفاده: هر {g('inactivity_ping_days', 10)} روز آنلاین می‌شه",
        f"{m('ttl_rollout')} تمدیدِ مهلتِ حذف: {g('account_ttl_days', 365)} روز - "
        f"{g('ttl_rollout_per_day', 8)} اکانت در ۲۴ ساعت",
        "",
        "━━ 🧩 سشنِ زاپاس ━━",
        f"{m('spare_keepalive')} زنده نگه‌داشتنِ زاپاس: هر {g('spare_keepalive_days', 25)} روز",
        f"{m('spare_autobuild')} نگهبانِ زاپاس: {g('spare_autobuild_per_day', 4)} زاپاس در ۲۴ ساعت",
        "",
        "━━ 🎨 هویت و پاکسازی ━━",
        f"{m('privacy_random')} حریمِ خصوصیِ رندومِ خودکار",
        f"{m('account_sorting')} مرتب سازی اکانت: {g('account_sort_per_day', 20)} اکانت در ۲۴ ساعت",
        f"{m('profile_rotation')} تغییرِ پروفایلِ تدریجی: {g('profile_rotation_per_day', 4)} اکانت در ۲۴ ساعت",
        (f"     └ کانالِ منبع: {channel_display}" if channel_display
         else "     └ ⚠️ کانالِ منبع هنوز ثبت نشده"),
        "",
        "رویِ هر دکمه بزن تا روشن/خاموش بشه؛ دکمه‌یِ کنارش عددها رو عوض می‌کنه.",
        "برایِ توضیحِ کاملِ هر گزینه: «ℹ️ توضیحاتِ کاملِ هر گزینه».",
    ]
    return "\n".join(lines)


def _format_humanize_help_text(settings: dict) -> str:
    """
    توضیحِ کاملِ هر گزینه‌یِ «🎭 رفتارِ اکانت‌ها» - همون متن‌هایِ تفصیلی که قبلاً
    داخلِ خودِ منو بودن و باعثِ ردشدن از سقفِ ۴۰۹۶ کاراکتر می‌شدن. حالا فقط با
    دکمه‌یِ «ℹ️ توضیحاتِ کامل» و به‌صورتِ تیکه‌تیکه فرستاده می‌شه.
    """
    g = settings.get
    parts = [
        "ℹ️ توضیحاتِ کاملِ «🎭 رفتارِ اکانت‌ها»",
        "",
        "🎭 فعالیتِ دوره‌ای",
        f"هر {_fmt_num(g('cycle_days_min', 5))} تا {_fmt_num(g('cycle_days_max', 6))} روز یک‌بار، فقط "
        "یکی از فعالیت‌هایِ فعال (کاملاً رندوم) برایِ هر اکانت انجام می‌شه:",
    ]
    for key in ("saved_message", "story", "channel", "pin_chat"):
        parts.append(f"{_hum_mark(settings, key)} {_HUMANIZE_ACTION_LABELS[key]}")
    parts += [
        "",
        "🟢 آنلاینِ روزانه",
        f"هر روز بینِ {g('online_min_minutes', 60)} تا {g('online_max_minutes', 90)} دقیقه اکانت "
        "آنلاین می‌شه - همون چیزی که تلگرام به‌عنوانِ «کاربرِ زنده» می‌بینه.",
        "",
        "📖 خوندنِ چت‌ها",
        f"هر {g('read_dialogs_min_minutes', 50)} تا {g('read_dialogs_max_minutes', 80)} دقیقه، "
        "کانال/چت‌هایِ خونده‌نشده «خونده» علامت می‌خورن (عددِ قرمزِ unread صفر می‌شه، "
        "انگار کاربر بازشون کرده).",
        "",
        "🌙 سکوتِ شبانه",
        f"از {g('quiet_start_hour', 1)}:00 تا {g('quiet_end_hour', 8)}:00 به وقتِ تهران هیچ "
        "فعالیتی انجام نمی‌شه و پنجره‌یِ آنلاین هم بیرونِ این بازه ساخته می‌شه "
        "(اکانتی که ۳ صبح آنلاینه و استوری می‌ذاره، آشکارا رباته).",
        "",
        "🛡 سقفِ فعالیتِ روزانه",
        f"هر اکانت روزانه حداکثر {g('daily_action_cap', 50)} بازدید/ری‌اکشن - اکانتی که به "
        "سقفش برسه تا فردا از سفارش‌هایِ جدید کنار گذاشته می‌شه.",
        "",
        "🌱 گرم‌کردنِ اکانتِ تازه",
        f"تا {g('warmup_days', 7)} روزِ اولِ اضافه‌شدن، سقفِ روزانه فقط "
        f"{g('warmup_daily_cap', 10)} بار (اکانتِ تازه‌ای که فوراً وارد کارِ انبوه بشه، "
        "خیلی زودتر دیلیت می‌شه).",
        "",
        "🧪 قرنطینه‌یِ سشنِ تازه",
        f"تا {g('quarantine_hours', 24)} ساعتِ اولِ اضافه‌شدن، اکانت *اصلاً* وارد هیچ "
        "بازدید/ری‌اکشن/جوینی نمی‌شه - فقط رفتارِ انسانی (آنلاین‌شدن، خوندنِ چت‌ها) "
        "روش اجرا می‌شه تا مثلِ یه کاربرِ واقعی جا بیفته. این سخت‌گیرانه‌تر از "
        "گرم‌کردنه و اولین ساعت‌ها - که پرخطرترینن - رو کامل خالی می‌ذاره.",
        "",
        "🔒 حریمِ خصوصیِ رندومِ خودکار",
        "به‌مرورِ زمان، در پس‌زمینه و کاملاً بی‌صدا (بدونِ هیچ پیامی)، برایِ هر اکانت "
        "یه‌بار شماره‌یِ تلفن/آخرین‌بازدید/عکسِ پروفایل/فوروارد/تاریخِ‌تولد/بیو رو "
        "رندوم تنظیم می‌کنه و تماس‌ها/دعوت‌به‌گروه رو رویِ «هیچ‌کس» می‌ذاره. هر اکانت "
        "فقط یه‌بار انجام می‌شه و بعدش ثابت می‌مونه - برایِ رندوم‌کردنِ دوباره‌ی همه، "
        "دکمه‌یِ «🔀 دوباره رندوم کن» رو بزن.",
        "",
        "📂 مرتب سازی اکانت",
        f"به‌صورتِ تدریجی و در پس‌زمینه (سرعتِ {g('account_sort_per_day', 20)} اکانت در هر "
        "۲۴ ساعت)، چت‌هایِ اضافیِ اکانت‌ها رو با سرعتِ کم پاکسازی می‌کنه. هرچیزی که "
        "مالِ خودِ رباته محفوظ می‌مونه: کانال‌هایِ بازدید/ری‌اکشن/شیر (هر کانالی که "
        "ربات اکانت رو داخلش جوین کرده) و چتِ خصوصیِ جفتِ شیرِ پست.",
        "",
        "🛡 محافظت از حذفِ اکانتِ بی‌استفاده",
        "تلگرام اکانتی رو که مدتِ طولانی (پیش‌فرضِ خودش ۶ ماه) هیچ فعالیتی نکنه، "
        "*کاملاً و برایِ همیشه* حذف می‌کنه. این نگهبان دو کار می‌کنه: مهلتِ حذف رو "
        f"رویِ {g('account_ttl_days', 365)} روز (بیشترین مقدارِ ممکن) می‌ذاره، و هر "
        f"اکانتی که بیشتر از {g('inactivity_ping_days', 10)} روز آنلاین نشده باشه رو "
        "آنلاین می‌کنه. مستقل از «آنلاینِ روزانه» و «سکوتِ شبانه» کار می‌کنه و اگه "
        "اکانتی چند بار پیاپی جواب نده، بهت هشدار می‌ده.",
        "",
        "⏳ تمدیدِ تدریجیِ مهلتِ حذف",
        "مهلتِ «اگه این‌قدر غایب بودم اکانتم رو حذف کن» رویِ *همه‌ی* اکانت‌ها به‌آرومی "
        f"روی {g('account_ttl_days', 365)} روز (۱۲ ماه) برده می‌شه - بیشترین مقداری که "
        f"تلگرام قبول می‌کنه. سرعت: {g('ttl_rollout_per_day', 8)} اکانت در هر ۲۴ ساعت "
        "(عمداً آهسته: تغییرِ تنظیماتِ حسابِ ده‌ها اکانت در چند دقیقه، خودش الگویِ "
        "مشکوکیه). هر اکانت بعد از یه تلاش تا ۳۰ روز دوباره سراغش نمی‌ره، پس یه "
        "اکانتِ لجباز صف رو قفل نمی‌کنه.",
        "",
        "🧩 زنده نگه‌داشتنِ سشنِ زاپاس",
        "تلگرام نشستی که مدتِ طولانی وصل نشه خودش می‌بنده - و زاپاسِ بسته‌شده دیگه "
        f"زاپاس نیست. هر {g('spare_keepalive_days', 25)} روز، هر زاپاس یه اتصالِ کوتاه "
        "می‌گیره (حداکثر ۲ زاپاس در هر دور).",
        "",
        "🛡 نگهبانِ زاپاس",
        "هر اکانتی که زاپاسِ سالم نداشته باشه (چه هیچ‌وقت نساخته باشه، چه زاپاسش "
        f"مصرف/باطل شده باشه) خودکار زاپاس می‌گیره - حداکثر "
        f"{g('spare_autobuild_per_day', 4)} زاپاس در ۲۴ ساعت و بیرونِ ساعاتِ سکوتِ "
        "شبانه (ساختِ زاپاس یه ورودِ واقعی به حسابِ اکانته، پس عمداً آهسته‌ست). "
        "زاپاس‌هایی که چند بار پیاپی جواب ندن هم بازنشسته و جایگزین می‌شن.",
        "",
        "🖼 تغییرِ پروفایلِ تدریجی",
        "اکانت‌هایی که *اسمِ یکسان/خیلی‌شبیه* دارن (مثلاً سه تا «Anderson Lugo») "
        "شناسایی می‌شن و پروفایلشون - عکس، اسم، بیو و تاریخِ تولد - با اطلاعاتِ "
        "ممبرهایِ واقعیِ یه کانالِ ثبت‌شده جایگزین می‌شه.",
        "مرحله‌ها با فاصله انجام می‌شن (نه یهو): اسم ← ۶ ساعت ← عکس ← ۳ ساعت ← بیو "
        "(فقط اگه از قبل بیو نداشته باشه) ← ۱۰ ساعت ← تاریخِ تولد (سنِ ۱۹ تا ۵۸). "
        "عکس‌هایِ قدیمیِ اکانت هم پاک می‌شن تا ردی از هویتِ قبلی نمونه. از هر گروهِ "
        "هم‌اسم، قدیمی‌ترین اکانت دست‌نخورده می‌مونه و هر اکانت فقط یک‌بار عوض می‌شه.",
        f"سرعت: {g('profile_rotation_per_day', 4)} اکانت در هر ۲۴ ساعت.",
    ]
    channel_display = g("_profile_rotation_channel_display")
    parts.append(
        f"کانالِ منبع: {channel_display}" if channel_display
        else "⚠️ هنوز کانالِ منبعی ثبت نشده - با دکمه‌یِ «📡 کانالِ منبعِ پروفایل» ثبتش کن."
    )
    return "\n".join(parts)


# سرتیترهایِ بخش‌بندیِ کیبوردِ «🎭 رفتارِ اکانت‌ها». دکمه‌ی واقعی نیستن (callback
# آن‌ها humsection است و هیچ کاری نمی‌کنه) - فقط لیستِ بلندِ تنظیمات را به
# گروه‌هایِ خوانا تقسیم می‌کنن، چون تلگرام برایِ کیبوردِ شیشه‌ای «عنوانِ بخش» نداره.
_SECTION_CYCLE = "━━━ 🎭 فعالیتِ دوره‌ای ━━━"
_SECTION_DAILY = "━━━ 🟢 حضورِ روزانه ━━━"
_SECTION_LIMITS = "━━━ 🛡 سقف و ایمنی ━━━"
_SECTION_DELETION = "━━━ 🔒 محافظت از حذفِ اکانت ━━━"
_SECTION_SPARE = "━━━ 🧩 سشنِ زاپاس ━━━"
_SECTION_IDENTITY = "━━━ 🎨 هویت و پاکسازی ━━━"


def _humanize_settings_keyboard(settings: dict) -> InlineKeyboardMarkup:
    """
    کیبوردِ «🎭 رفتارِ اکانت‌ها» - بخش‌بندی‌شده و دوستونه.

    چیدمان عمداً «هر گزینه در یک ردیف، کنارِ دکمه‌یِ عددهایِ خودش» است: قبلاً
    ۳۷ ردیفِ تک‌دکمه‌ای پشتِ‌سرِهم بود و دکمه‌یِ تنظیمِ عددِ هر گزینه ده‌ها ردیف
    دورتر از خودِ گزینه قرار می‌گرفت - پیدا کردنشون توی موبایل عملاً اسکرولِ
    کور بود.
    """
    def _toggle(key, label):
        return InlineKeyboardButton(
            f"{_hum_mark(settings, key)} {label}", callback_data=f"humtoggle_{key}"
        )

    def _act(label, callback):
        return InlineKeyboardButton(label, callback_data=callback)

    def _head(title):
        return [InlineKeyboardButton(title, callback_data="humsection")]

    g = settings.get
    kb = [
        _head(_SECTION_CYCLE),
        [_toggle("saved_message", "پیام در Saved"), _toggle("story", "استوری")],
        [_toggle("channel", "ساختِ کانال"), _toggle("pin_chat", "پینِ چت")],
        [_act(
            f"⏱ فاصله‌یِ چرخه ({_fmt_num(g('cycle_days_min', 5))}-{_fmt_num(g('cycle_days_max', 6))} روز)",
            "humedit_cycle",
        )],

        _head(_SECTION_DAILY),
        [_toggle("online", "آنلاینِ روزانه"),
         _act(f"🟢 {g('online_min_minutes', 60)}-{g('online_max_minutes', 90)} دقیقه", "humedit_online")],
        [_toggle("read_dialogs", "خوندنِ چت‌ها"),
         _act(f"📖 هر {g('read_dialogs_min_minutes', 50)}-{g('read_dialogs_max_minutes', 80)} دقیقه",
              "humedit_read")],
        [_toggle("quiet_hours", "سکوتِ شبانه"),
         _act(f"🌙 {g('quiet_start_hour', 1)}:00-{g('quiet_end_hour', 8)}:00", "humedit_quiet")],

        _head(_SECTION_LIMITS),
        [_toggle("daily_cap", "سقفِ روزانه"),
         _act(f"🛡 {g('daily_action_cap', 50)} بار", "humedit_cap")],
        [_toggle("warmup", "گرم‌کردنِ تازه"),
         _act(f"🌱 {g('warmup_days', 7)} روز / {g('warmup_daily_cap', 10)} بار", "humedit_warmup")],
        [_toggle("quarantine", "قرنطینه‌یِ سشن"),
         _act(f"🧪 {g('quarantine_hours', 24)} ساعت", "humedit_quarantine")],

        _head(_SECTION_DELETION),
        [_toggle("inactivity_guard", "نگهبانِ بی‌استفاده"),
         _act(f"⏱ هر {g('inactivity_ping_days', 10)} روز", "humedit_pingdays")],
        [_toggle("ttl_rollout", "تمدیدِ مهلتِ حذف"),
         _act(f"⚙️ {g('ttl_rollout_per_day', 8)} اکانت/روز", "humedit_ttlspeed")],
        [_act(f"📊 وضعیتِ محافظت (مهلتِ {g('account_ttl_days', 365)} روزه)",
              "humaction_guard_status")],

        _head(_SECTION_SPARE),
        [_toggle("spare_keepalive", "زنده‌نگه‌داشتنِ زاپاس"),
         _act(f"⏱ هر {g('spare_keepalive_days', 25)} روز", "humedit_sparekeepalive")],
        [_toggle("spare_autobuild", "نگهبانِ زاپاس"),
         _act(f"⚙️ {g('spare_autobuild_per_day', 4)} زاپاس/روز", "humedit_sparespeed")],

        _head(_SECTION_IDENTITY),
        [_toggle("privacy_random", "حریمِ خصوصیِ رندوم"),
         _act("🔀 دوباره رندوم کن", "humaction_privacy_reset")],
        [_toggle("account_sorting", "مرتب سازی اکانت"),
         _act(f"⚙️ {g('account_sort_per_day', 20)} اکانت/روز", "humedit_sortspeed")],
        [_toggle("profile_rotation", "تغییرِ پروفایلِ تدریجی"),
         _act(f"⚙️ {g('profile_rotation_per_day', 4)} اکانت/روز", "humedit_profilespeed")],
        [_act("📡 کانالِ منبعِ پروفایل", "humaction_profile_channel"),
         _act("📊 وضعیتِ پروفایل", "humaction_profile_status")],

        [_act("ℹ️ توضیحاتِ کاملِ هر گزینه", "humaction_help")],
        [_act("🔙 بازگشت به ⚙️ تنظیمات", "humaction_exit")],
    ]
    return InlineKeyboardMarkup(kb)


async def _send_humanize_menu(target, notice: str = None):
    """
    *تنها* راهِ نشان‌دادنِ منویِ «🎭 رفتارِ اکانت‌ها» - از هر مسیری: پیامِ متنی
    (Message)، کالبکِ شیشه‌ای (CallbackQuery)، یا بعدِ تنظیمِ یه عدد.

    چرا همه‌چیز از یه‌جا می‌گذره:
      • تنظیمات همیشه با _humanize_settings_full خونده می‌شه (نه
        get_humanize_settings خام) - وگرنه اسمِ کانالِ منبعِ پروفایل توی متن
        نمایش داده نمی‌شه. قبلاً چند مسیر خامش رو صدا می‌زدن.
      • سقفِ ۴۰۹۶ کاراکتریِ تلگرام این‌جا یک‌بار و برایِ همیشه مدیریت می‌شه.
      • اگه ارسال شکست بخورد، *هیچ‌وقت* بی‌صدا رد نمی‌شه: یه پیامِ حداقلی همراهِ
        کیبورد می‌ره تا کاربر بدونِ منو نمونه.
    """
    settings = await _humanize_settings_full()
    markup = _humanize_settings_keyboard(settings)
    chunks = _split_long_text(_format_humanize_settings_text(settings))
    is_query = hasattr(target, "edit_message_text")
    message = getattr(target, "message", target)
    try:
        for index, chunk in enumerate(chunks):
            is_last = index == len(chunks) - 1
            chunk_markup = markup if is_last else None
            if index == 0 and is_query:
                await target.edit_message_text(chunk, reply_markup=chunk_markup)
            else:
                await message.reply_text(chunk, reply_markup=chunk_markup)
        if notice:
            await message.reply_text(notice)
        return
    except Exception as exc:
        # «Message is not modified» یعنی همون محتوا از قبل رویِ صفحه‌ست - خطا نیست.
        if "not modified" in str(exc).lower():
            if notice:
                try:
                    await message.reply_text(notice)
                except Exception:
                    pass
            return
        try:
            await message.reply_text(
                "🎭 رفتارِ اکانت‌ها\n\n"
                f"⚠️ نمایشِ متنِ وضعیت ممکن نشد ({type(exc).__name__})، ولی همه‌ی "
                "دکمه‌ها سالمن:",
                reply_markup=markup,
            )
            if notice:
                await message.reply_text(notice)
        except Exception:
            pass


async def _hum_notice(query, text: str):
    """
    نمایشِ یه پیامِ کوتاه به کاربر از داخلِ یه کالبک.

    ⚠️ on_callback در خطِ اولش *همیشه* query.answer() رو صدا می‌زنه، پس هر
    query.answer(...) دومی از طرفِ تلگرام رد می‌شه (یه کالبک فقط یک‌بار answer
    می‌شه) و استثنا می‌ده - که بعدش به کاربر «❌ خطا» نشون داده می‌شد، درحالی‌که
    عملیات موفق بوده. این‌جا اول توست امتحان می‌شه و اگه نشد، متن به‌صورتِ یه
    پیامِ معمولی فرستاده می‌شه.
    """
    try:
        await query.answer(text, show_alert=True)
        return
    except Exception:
        pass
    try:
        await query.message.reply_text(text)
    except Exception:
        pass


async def send_accounts_menu(target, page_manual: int = 0, page_session: int = 0, context=None):
    """
    نمایشِ کاملِ صفحه‌ی اکانت‌ها - چه از پیامِ متنی (Message) چه از کالبک (CallbackQuery)
    صدا زده بشه: دو لیستِ *جدا* (اکانت‌هایِ دستی و اکانت‌هایِ واردشده با فایلِ سشن -
    نگاه کن به build_accounts_menu/_ACCOUNT_SOURCE_LABELS)، هرکدوم با صفحه‌بندیِ
    مستقلِ خودش، بعد دکمه‌هایِ عملیاتِ ثابت به‌صورتِ کیبوردِ پایینِ صفحه (نه شیشه‌ای).
    """
    manual_order_desc = _account_order_desc(context, "accounts_order_manual") if context is not None else True
    session_order_desc = _account_order_desc(context, "accounts_order_session") if context is not None else True
    text_manual, markup_manual = await build_accounts_menu(page_manual, "manual", manual_order_desc)
    text_session, markup_session = await build_accounts_menu(page_session, "session", session_order_desc)

    if hasattr(target, "edit_message_text"):
        await target.edit_message_text(text_manual, reply_markup=markup_manual)
        reply = target.message.reply_text
    else:
        await target.reply_text(text_manual, reply_markup=markup_manual)
        reply = target.reply_text
    await reply(text_session, reply_markup=markup_session)
    await reply("عملیات:", reply_markup=accounts_action_keyboard())


async def build_channels_menu(admin_id: str):
    """فقط لیستِ خودِ کانال‌ها (inline). دکمه‌هایِ عملیاتِ ثابت جدا - نگاه کن به
    channels_action_keyboard/send_channels_menu."""
    channels = await get_all_channels(admin_id)
    if not channels:
        return "📢 کانال‌هایِ من\nهنوز کانالی ثبت نشده.", None
    kb = []
    for ch in channels:
        badge = "🔒" if ch["is_private"] else "🌐"
        kb.append([InlineKeyboardButton(
            f"{badge} {ch['channel_name'] or ch['channel_username']}",
            callback_data=f"ch_view_{ch['id']}"
        )])
    text = f"📢 کانال‌هایِ من ({len(channels)} عدد)"
    return text, InlineKeyboardMarkup(kb)


def channels_action_keyboard():
    kb = [
        ["➕ اضافه کردن کانال"],
        ["🏠 بازگشت به منو"],
    ]
    return ReplyKeyboardMarkup(kb, resize_keyboard=True)


async def send_channels_menu(target, admin_id: str):
    """مشابهِ send_accounts_menu - لیستِ کانال‌ها inline، عملیاتِ ثابت به‌صورتِ کیبوردِ
    پایینِ صفحه."""
    text, list_markup = await build_channels_menu(admin_id)
    if hasattr(target, "edit_message_text"):
        await target.edit_message_text(text, reply_markup=list_markup)
        reply = target.message.reply_text
    else:
        await target.reply_text(text, reply_markup=list_markup)
        reply = target.reply_text
    await reply("عملیات:", reply_markup=channels_action_keyboard())


class _FakeDetailQuery:
    """یه Message رو طوری می‌پیچه که رابطش (edit_message_text) شبیهِ CallbackQuery بشه -
    برایِ صدازدنِ دوباره‌ی show_account_detail از یه هندلرِ متنی (نه یه callback واقعی).

    ⚠️ باگی که این‌جا حل شده: نسخه‌یِ قبلی (تکراری، دوبار توی کد تعریف شده بود) پارامترِ
    reply_markup رو قبول نمی‌کرد. show_account_detail وقتی اکانت نشست‌هایِ فعالِ دیگه یا
    فایلِ فروشنده‌یِ ذخیره‌شده داشته باشه، دقیقاً با همین پارامتر صداش می‌زنه - پس دکمه‌هایی
    مثلِ «بررسیِ سلامتِ این اکانت» برایِ چنین اکانت‌هایی با TypeError خراب می‌شدن.
    """
    def __init__(self, message):
        self.message = message

    async def edit_message_text(self, text, reply_markup=None):
        if reply_markup is not None:
            await self.message.reply_text(text, reply_markup=reply_markup)
        else:
            await self.message.reply_text(text)


async def show_account_detail(query, account_id, context=None):
    acc = await get_account(account_id)
    if not acc:
        await query.edit_message_text("اکانت پیدا نشد.")
        return
    status = "فعال ✅" if acc["is_logged_in"] else "غیرفعال ❌"
    country_line = f"\n🌍 {acc['country_flag'] or ''} {acc['country_name']}" if acc.get("country_name") else ""
    try:
        active_spares = await get_spare_sessions(account_id=account_id)
    except Exception:
        active_spares = []
    spare_line = (
        f"\n🧩 سشنِ زاپاس: دارد ✅ ({len(active_spares)})"
        if active_spares else "\n🧩 سشنِ زاپاس: ندارد ❌"
    )

    # اطلاعاتِ کاملِ لحظه‌ای از خودِ تلگرام (نه از دیتابیس) - آیدیِ عددی، یوزرنیم،
    # بیو، و لیستِ نشست‌هایِ فعال. فقط برایِ اکانت‌هایِ لاگین‌شده معنی داره.
    id_line = ""
    username_line = ""
    bio_line = ""
    sessions = []
    full_info = None
    if acc["is_logged_in"]:
        full_info = await get_account_full_info(acc["session_file"])
        if full_info["status"] == "success":
            id_line = f"\n🆔 {full_info['id']}"
            username_line = f"\n👤 @{full_info['username']}" if full_info.get("username") else "\n👤 بدونِ یوزرنیم"
            if full_info.get("about"):
                bio_line = f"\n📝 بیو: {full_info['about']}"
            sessions = full_info.get("sessions", [])
        else:
            id_line = f"\n🆔 خطا در خوندنِ اطلاعات: {full_info['message']}"

    # چیزی که این اکانت *واقعاً* به تلگرام گزارش می‌کنه - مهم‌ترینش lang_code ـه که
    # تعیین می‌کنه بازدیدش توی نمودارِ Languagesِ کانال زیرِ کدوم زبان ثبت بشه
    report_line = ""
    if acc["is_logged_in"]:
        try:
            lang_kwargs = await _client_lang_kwargs(acc["session_file"])
            profile = _device_profile(acc["session_file"])
            flag = "🇮🇷" if lang_kwargs["lang_code"] == "fa" else "🇬🇧"
            report_line = (
                f"\n\n📡 چیزی که به تلگرام گزارش می‌شه:"
                f"\n{flag} زبان: {lang_kwargs['lang_code']}  (langpack: {profile['lang_pack']})"
                f"\n📱 دستگاه: {profile['device_model']} · {profile['system_version']}"
            )
        except Exception:
            pass

    # چک‌لیستِ ۵ تسکِ امنیتی/آماده‌سازی - وقتی هر ۵‌تاش تیک بخوره، این اکانت توی
    # لیستِ اکانت‌ها با نشانگرِ سبز (🟢) مشخص می‌شه (نگاه کن به build_accounts_menu)
    task_1 = "✅" if acc.get("task_2fa_done") else "⏳"
    task_2 = "✅" if acc.get("task_hint_done") else "⏳"
    task_3 = "✅" if acc.get("task_recovery_email_done") else "⏳"
    task_4 = "✅" if acc.get("task_login_email_done") else "⏳"
    task_5 = "✅" if acc.get("task_profile_done") else "⏳"
    tasks_line = (
        f"\n\n📋 چک‌لیستِ آماده‌سازی:\n"
        f"{task_1} تغییرِ رمزِ دومرحله‌ای\n"
        f"{task_2} تنظیمِ Hint\n"
        f"{task_3} تنظیمِ ایمیلِ بازیابیِ جدید\n"
        f"{task_4} تغییرِ ایمیلِ لاگین\n"
        f"{task_5} تغییرِ پروفایل"
    )

    # حافظه‌یِ دائمیِ اطلاعاتِ اکانت - رمزِ دومرحله‌ای، hint، ایمیل‌ها. منبعش یا
    # فایلِ jsonِ کنارِ سشن (موقعِ ایمپورت) ـه یا خودِ ربات وقتی واقعاً یه رمز رو
    # تغییر داده/تأیید کرده. نگاه کن به set_account_twofa_credentials و
    # parse_session_json.
    twofa_lines = ""
    stored_password = acc.get("twofa_password")
    stored_recovery_email = acc.get("twofa_recovery_email")
    stored_hint = acc.get("twofa_hint")
    stored_login_email = acc.get("login_email")
    stored_login_email_pw = acc.get("login_email_password")
    if stored_password or stored_recovery_email or stored_hint or stored_login_email:
        twofa_lines = "\n\n🔑 اطلاعاتِ ذخیره‌شده:"
        if stored_password:
            mark = "✅ تأییدشده" if acc.get("twofa_password_verified") else "⚠️ تأییدنشده"
            twofa_lines += f"\n🔐 رمزِ دومرحله‌ای: {stored_password}  ({mark})"
        if stored_hint:
            twofa_lines += f"\n💡 Hint: {stored_hint}"
        if stored_recovery_email:
            twofa_lines += f"\n📧 ایمیلِ بازیابی: {stored_recovery_email}"
        if stored_login_email:
            twofa_lines += f"\n📨 ایمیلِ لاگین: {stored_login_email}"
        if stored_login_email_pw:
            twofa_lines += f"\n🔑 رمزِ ایمیل: {stored_login_email_pw}"

    imported_line = ""
    if acc.get("created_at"):
        imported_line = (
            f"\n📥 ورود سشن به ربات: "
            f"{fmt_tehran(acc['created_at'], '%Y-%m-%d %H:%M:%S')}"
        )
    login_line = ""
    if acc.get("last_login_at"):
        login_line = f"\n🕐 آخرین ورود موفق: {fmt_tehran(acc['last_login_at'], '%Y-%m-%d %H:%M:%S')}"
    migration_line = ""
    try:
        # ⚠️ فقط ردیف‌هایِ *مهاجرتِ واقعی* (source='migration'). قبلاً آخرین ردیفِ
        # هر نوعی خونده می‌شد، پس یه ردیفِ 'terminate_retry' (که فقط یعنی «نشست‌هایِ
        # دیگه هنوز بسته نشدن») به‌اشتباه «تعویض فایل انجام شد» نشون داده می‌شد -
        # حتی رویِ اکانتی که هیچ‌وقت تعویض نشده بود.
        latest = await get_latest_real_session_migration_for_account(account_id)
        if latest:
            started = fmt_tehran(latest.get("created_at"), "%Y-%m-%d %H:%M:%S") if latest.get("created_at") else "—"
            finished = fmt_tehran(latest.get("finished_at"), "%Y-%m-%d %H:%M:%S") if latest.get("finished_at") else "—"
            cleanup = (
                "✅ پاکسازی سشن قدیمی انجام شد"
                if latest.get("done")
                else "⏳ فایل جدید نصب شده؛ پاکسازی سشن قدیمی در انتظار اجراست"
            )
            outcome = f"✅ تعویض فایل old→new انجام شد\n{cleanup}"
            if latest.get("last_error"):
                outcome += f"\n⚠️ آخرین خطا: {str(latest['last_error'])[:180]}"
            migration_line = (f"\n\n🔄 تعویض سشن old→new: {outcome}"
                              f"\nشروع: {started}\nپایان: {finished}")
        elif acc.get("source") == "session":
            migration_line = "\n\n🔄 تعویض سشن old→new: ❌ انجام نشده"
    except Exception:
        pass

    text = (
        f"👤 {acc['nickname'] or acc['phone']}\n📞 {acc['phone']}{id_line}{username_line}"
        f"{bio_line}{country_line}\nوضعیت: {status}{imported_line}{login_line}{migration_line}{spare_line}{report_line}{tasks_line}{twofa_lines}"
    )

    # کیبوردِ inline برایِ نشست‌هایِ فعال - هرکدوم با کلیک قابلِ بیرون‌انداختنه (به‌جز
    # نشستِ current که خودِ همین ارتباطِ رباته)
    inline_kb = []
    if acc.get("session_metadata"):
        inline_kb.append([InlineKeyboardButton(
            "📄 اطلاعاتِ کاملِ فایلِ فروشنده", callback_data=f"acc_meta_{account_id}"
        )])
    other_sessions = [s for s in sessions if not s.get("current")]
    # ⚠️ نشست‌هایِ زاپاسِ خودِ ربات هم در همین لیستن. قبلاً هیچ نشونه‌ای نداشتن و
    # با یه کلیک بسته می‌شدن - یعنی ادمین بدونِ اینکه بفهمه، زاپاسِ همون اکانت رو
    # بیرون می‌انداخت. حالا علامت‌گذاری می‌شن و دکمه‌شون به‌جایِ بستن، توضیح می‌ده.
    try:
        protected_hashes = await get_protected_spare_auth_hashes(acc.get("session_file"))
    except Exception:
        protected_hashes = set()
    if other_sessions:
        inline_kb.append([InlineKeyboardButton(f"🔐 نشست‌هایِ فعال ({len(other_sessions)} + همینِ ربات)", callback_data="noop_label")])
        for s in other_sessions[:15]:  # سقفِ نمایش - جلویِ کیبوردِ خیلی بلند رو می‌گیره
            device = s.get("device_model") or s.get("platform") or "دستگاهِ نامشخص"
            app = s.get("app_name") or ""
            try:
                is_spare = int(s["hash"]) in protected_hashes
            except (TypeError, ValueError, KeyError):
                is_spare = False
            if is_spare:
                label = f"🧩 زاپاسِ ربات · {device}".strip(" ·")
                inline_kb.append([InlineKeyboardButton(label, callback_data=f"sess_spare_info_{account_id}")])
                continue
            label = f"❌ {device} · {app}".strip(" ·")
            inline_kb.append([InlineKeyboardButton(label, callback_data=f"sess_term_{account_id}_{s['hash']}")])
        inline_kb.append([InlineKeyboardButton("🚪 بیرون‌انداختنِ نشست‌هایِ دیگه (زاپاس حفظ می‌شه)", callback_data=f"sess_term_all_{account_id}")])
    elif sessions:
        inline_kb.append([InlineKeyboardButton("✅ فقط همینِ نشستِ ربات فعاله - نشستِ دیگه‌ای نیست", callback_data="noop_label")])
    inline_kb.append([InlineKeyboardButton(
        "🧩 ساخت سشن زاپاس", callback_data=f"acc_spare_{account_id}"
    )])

    # ReplyKeyboard برای دکمه‌های اکانت
    kb = []
    if not acc["is_logged_in"]:
        kb.append(["📨 ارسالِ کد", "🔑 وارد کردنِ کد"])
        # اکانتی که توی لیست ❌ خورده، همیشه واقعاً خراب نیست - گاهی فقط یه خطایِ
        # لحظه‌ای (تایم‌اوت/افتِ شبکه) این پرچم رو اشتباه صفر کرده. پس این‌جا هم
        # دکمه‌ی بررسیِ سلامت رو نشون می‌دیم تا با یه کلیک بشه دوباره (با همون
        # منطقِ دو-دوریِ دقیق) امتحانش کرد - نگاه کن به run_single_account_healthcheck.
        kb.append(["🩺 بررسیِ سلامتِ این اکانت"])
    else:
        kb.append(["📲 گرفتنِ کدِ ورودِ گوشی"])
        # این سه‌تا فقط برایِ اکانت‌هایِ لاگین‌شده معنی دارن - هرسه دقیقاً همون فلوهایِ
        # گروهیِ منویِ «⚙️ تنظیماتِ اکانت» رو صدا می‌زنن، فقط selected_accounts از قبل
        # با همینْ *یک* اکانت پر شده (نگاه کن به بخشِ «دکمه‌های اکانت» در on_text).
        kb.append(["🩺 بررسیِ سلامتِ این اکانت"])
        kb.append(["🔐 تغییرِ رمزِ دومرحله‌ایِ این اکانت"])
        kb.append(["🖼 تغییرِ پروفایلِ این اکانت"])
    kb.append(["🗑 حذفِ اکانت"])
    kb.append(["🔙 بازگشت"])

    if inline_kb:
        await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(inline_kb))
    else:
        await query.edit_message_text(text)
    await query.message.reply_text("گزینه‌ای انتخاب کن:", reply_markup=ReplyKeyboardMarkup(kb, resize_keyboard=True))
    
    # ذخیرِ account_id برای استفاده در on_text + پشته‌ی ناوبری (تا «بازگشت» به لیستِ
    # اکانت‌ها برگرده، نه مستقیم به منویِ اصلی)
    if context:
        context.user_data["current_account_id"] = account_id
        context.user_data["current_account_source"] = acc.get("source") or "manual"
        _push_menu(context, _REGEN_ACCOUNTS_MENU, None)


async def show_channel_detail(query, channel_id, admin_id: str):
    ch = await get_channel(channel_id, admin_id)
    if not ch:
        await query.edit_message_text("کانال پیدا نشد (یا مالِ ادمینِ دیگه‌ایه).")
        return
    kind = "خصوصی 🔒" if ch["is_private"] else "عمومی 🌐"
    text = f"📢 {ch['channel_name'] or ch['channel_username']}\n{ch['channel_username']}\nنوع: {kind}"
    kb = [
        [InlineKeyboardButton("🗑 حذفِ کانال", callback_data=f"ch_delcheck_{channel_id}")],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="menu_channels")],
    ]
    await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(kb))


