def build_reaction_grid(callback_prefix: str, back_callback: str):
    kb = []
    row = []
    for i, emoji in enumerate(REACTIONS):
        row.append(InlineKeyboardButton(emoji, callback_data=f"{callback_prefix}{i}"))
        if len(row) == 6:
            kb.append(row)
            row = []
    if row:
        kb.append(row)
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data=back_callback)])
    return InlineKeyboardMarkup(kb)


def build_multi_reaction_grid(selected: set, callback_prefix: str, confirm_callback: str, back_callback: str):
    """کیبوردِ چندانتخابیِ ری‌اکشن - آیتم‌هایِ انتخاب‌شده با ✅ مشخص می‌شن"""
    kb = []
    row = []
    for i, emoji in enumerate(REACTIONS):
        label = f"✅{emoji}" if i in selected else emoji
        row.append(InlineKeyboardButton(label, callback_data=f"{callback_prefix}{i}"))
        if len(row) == 6:
            kb.append(row)
            row = []
    if row:
        kb.append(row)
    confirm_label = f"✅ تایید ({len(selected)} انتخاب‌شده)" if selected else "✅ تایید انتخاب‌ها"
    kb.append([InlineKeyboardButton(confirm_label, callback_data=confirm_callback)])
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data=back_callback)])
    return InlineKeyboardMarkup(kb)


_AR_BUCKET_LABELS = {
    "with_tag": "پست‌هایِ تگ‌دار",
    "without_tag": "پست‌هایِ بدونِ‌تگ",
    "default": "همه‌ی پست‌ها",
}


def _ar_bucket_total(context, bucket: str) -> int:
    """سقفِ تعدادِ ری‌اکشنِ یه باکت - اگه بازه باشه، عددِ بالاییِ بازه برمی‌گرده (چون
    اعتبارسنجی‌ها باید نسبت به بیشترین حالتِ ممکن انجام بشن)."""
    return _ar_bucket_range(context, bucket)[1]


def _ar_bucket_range(context, bucket: str) -> tuple:
    """بازه‌یِ تعدادِ ری‌اکشنِ یه باکت به‌صورتِ (lo, hi) - برایِ عددِ تکی lo == hi"""
    if bucket == "with_tag":
        return context.user_data.get("ar_range_with_tag", (0, 0))
    if bucket == "without_tag":
        return context.user_data.get("ar_range_without_tag", (0, 0))
    return context.user_data.get("ar_range", (0, 0))


def _ar_is_range(context, bucket: str) -> bool:
    """آیا تعدادِ این باکت بازه‌ایه (یعنی مجموعِ هر پست باید رندوم باشه)؟"""
    lo, hi = _ar_bucket_range(context, bucket)
    return hi > lo


def _ar_fmt_range(context, bucket: str) -> str:
    """نمایشِ خوانا از تعدادِ یه باکت - «۳۰ اکانت» یا «رندوم بینِ ۲۰ تا ۳۰ اکانت»"""
    lo, hi = _ar_bucket_range(context, bucket)
    if hi > lo:
        return f"رندوم بینِ {lo} تا {hi} اکانت"
    return f"{hi} اکانت"


# جوینِ دسته‌ای خیلی زود FloodWait می‌خوره، پس عمداً محافظه‌کارانه‌ست
AR_JOIN_CONCURRENCY = int(os.getenv("AR_JOIN_CONCURRENCY", "4"))


async def _ar_make_invite_link(context, chat_id) -> dict:
    """
    چون ربات ادمینِ کاناله، خودش می‌تونه لینکِ دعوت بسازه - پس لازم نیست از کاربر
    لینک بخوایم. اول export_chat_invite_link (لینکِ اصلیِ کانال) رو امتحان می‌کنیم و
    اگه نشد، یه لینکِ اختصاصیِ جدید می‌سازیم.

    خروجی: {"status": "success", "link": ...} یا {"status": "error", "message": ...}
    """
    try:
        link = await context.bot.export_chat_invite_link(chat_id)
        if link:
            return {"status": "success", "link": link}
    except Exception:
        pass  # معمولاً یعنی ربات دسترسیِ «دعوتِ کاربر» نداره یا لینکِ اصلی وجود نداره

    try:
        invite = await context.bot.create_chat_invite_link(
            chat_id, name="auto-react", creates_join_request=False
        )
        return {"status": "success", "link": invite.invite_link}
    except Exception as e:
        return {
            "status": "error",
            "message": (
                f"نتونستم لینکِ دعوت بسازم: {e}\n\n"
                "مطمئن شو ربات توی این کانال ادمینه و دسترسیِ «Invite Users via Link» داره."
            ),
        }


async def _ar_join_pool_in_background(context, chat_id, ref: dict, pool: list):
    """
    همه‌ی اکانت‌هایِ استخر رو در پس‌زمینه عضوِ کانال می‌کنه - تا موقعی که نوبتِ
    ری‌اکشن‌زدن برسه، از قبل دسترسی داشته باشن.

    این کار *در پس‌زمینه* انجام می‌شه تا ثبتِ کانال معطل نمونه، و با محدودیتِ
    همزمانی، چون جوینِ دسته‌ای خیلی زود FloodWait می‌خوره.
    """
    joined = already = failed = pending = 0
    sem = asyncio.Semaphore(AR_JOIN_CONCURRENCY)

    async def _one(acc):
        nonlocal joined, already, failed, pending
        async with sem:
            try:
                res = await asyncio.wait_for(
                    ensure_member_for_reactions(
                        acc["session_file"],
                        is_private=ref["is_private"], username=ref["username"],
                        channel_id=ref["channel_id"], invite_link=ref["invite_link"],
                    ),
                    timeout=90,
                )
            except Exception:
                res = {"status": "error"}
        status = res.get("status")
        if status == "joined":
            joined += 1
            # فاصله‌یِ کوتاهِ تصادفی بینِ جوین‌ها تا الگو طبیعی بمونه و
            # تلگرام دسته‌ی جوین رو مشکوک نبینه
            await asyncio.sleep(random.uniform(1.5, 4.0))
        elif status == "member":
            already += 1
        elif status == "pending":
            pending += 1
        else:
            failed += 1

    await asyncio.gather(*(_one(a) for a in pool), return_exceptions=True)

    lines = [f"🔗 عضویتِ اکانت‌ها در «{ref['title']}» تموم شد:"]
    if already:
        lines.append(f"✅ از قبل عضو بودن: {already}")
    if joined:
        lines.append(f"➕ تازه عضو شدن: {joined}")
    if pending:
        lines.append(f"⏳ منتظرِ تأییدِ ادمین: {pending} (تا تأیید نشن ری‌اکشن نمی‌زنن)")
    if failed:
        lines.append(f"❌ ناموفق: {failed}")
    if pending or failed:
        lines.append("")
        lines.append("اکانت‌هایِ ناموفق هر بار که نوبتِ ری‌اکشنشون برسه دوباره خودکار امتحان می‌شن.")
    try:
        await context.bot.send_message(chat_id, "\n".join(lines))
    except Exception:
        pass


