def _open_requests_keyboard(job_id: str, show_cancel: bool = True):
    """کیبوردِ سفارشِ «باز کردنِ ممبرِ کانال» - برخلافِ سفارش‌هایِ دیگه، دو دکمه‌ی جدا داره:
    «⏹ توقف» (فوری، بدونِ تأیید) و «❌ لغو» (با یه قدمِ تأییدِ اضافه، چون قصدش نهایی‌تره)."""
    kb = [[InlineKeyboardButton("🔄 آپدیتِ آمار", callback_data=f"jobrefresh_{job_id}")]]
    if show_cancel:
        kb.append([
            InlineKeyboardButton("⏹ توقف", callback_data=f"openreqstop_{job_id}"),
            InlineKeyboardButton("❌ لغو", callback_data=f"openreqcancel_{job_id}"),
        ])
    return InlineKeyboardMarkup(kb)


async def _persist_new_batch_job(progress: BatchProgress, admin_id, kind: str,
                                  resume_kind: str = None, resume_payload: dict = None,
                                  admin_chat_id=None, mode: str = None, total_minutes: float = None,
                                  account_ids_ordered: list = None):
    """
    همزمان با ثبتِ سفارش توی رجیستریِ در-حافظه (register_batch)، یه ردیف توی جدولِ
    batch_jobs هم ساخته می‌شه - تا اگه ربات وسطِ این سفارش ری‌استارت بشه (مثلاً دیپلویِ
    Railway)، آخرین آمارِ شناخته‌شده‌ش (نه فقط این‌که وجود داشته) توی دیتابیس بمونه.
    اگه resume_kind/resume_payload داده بشن، این سفارش قابلِ‌ازسرگیریِ خودکاره - نگاه
    کن به resume_interrupted_batches. شکست‌خوردنِ این نوشتن نباید جلویِ خودِ عملیات رو
    بگیره، برایِ همین فقط لاگ می‌شه.
    """
    try:
        await create_batch_job(
            progress.id, admin_id, kind, progress.title, progress.total,
            progress.start_time.isoformat(timespec="seconds"),
            resume_kind=resume_kind,
            resume_payload=json.dumps(resume_payload, ensure_ascii=False) if resume_payload is not None else None,
            admin_chat_id=admin_chat_id, mode=mode, total_minutes=total_minutes,
            remaining_json=json.dumps(account_ids_ordered) if account_ids_ordered is not None else None,
        )
    except Exception as e:
        print(f"⚠️  ثبتِ batch_job در دیتابیس با خطا مواجه شد: {e}")


async def _progress_ticker(sent_message, progress: BatchProgress, keyboard_fn=None):
    """هر PROGRESS_UPDATE_INTERVAL ثانیه، متنِ پیام رو با آخرین آمار آپدیت می‌کنه و
    آمار رو توی دیتابیس (batch_jobs) هم می‌نویسه - تا اگه ربات همین‌جا ری‌استارت بشه،
    «🗂 سفارش‌ها» آخرین وضعیتِ واقعی رو نشون بده، نه اینکه سفارش بی‌خبر ناپدید بشه.
    تا وقتی عملیات تموم بشه (progress.finished) ادامه داره؛ بعدِ اتمام، هم از
    رجیستری‌هایِ در-حافظه پاک می‌شه و هم ردیفِ دیتابیس به‌عنوانِ «تموم‌شده» بسته می‌شه.
    keyboard_fn (اختیاری): برایِ سفارش‌هایی که کیبوردِ متفاوتی دارن (مثلِ «باز کردنِ
    ممبرِ کانال» که دکمه‌ی «⏹ توقف» جدا از «❌ لغو» داره) - پیش‌فرض همون کیبوردِ
    معمولیِ سفارش‌هاست. اگه این سفارش هیچ‌وقت توی batch_jobs ثبت نشده باشه (مثلِ همون
    «باز کردنِ ممبرِ کانال»)، UPDATE/finish رویِ یه ردیفِ ناموجود فقط ۰ ردیف عوض می‌کنه -
    بدونِ خطا، پس امنه."""
    keyboard_fn = keyboard_fn or _job_refresh_keyboard
    try:
        while not progress.finished:
            await asyncio.sleep(PROGRESS_UPDATE_INTERVAL)
            try:
                await sent_message.edit_text(progress.format(), reply_markup=keyboard_fn(progress.id, show_cancel=not progress.finished))
            except Exception:
                pass  # مثلاً متن تغییر نکرده (BadRequest) - مهم نیست، دورِ بعدی دوباره تلاش می‌شه
            try:
                await update_batch_job_progress(
                    progress.id, progress.done, progress.success, progress.fail, progress.last_error,
                    skipped=progress.skipped, unfilled=progress.unfilled,
                    stop_reason=progress.stop_reason)
            except Exception:
                pass
    finally:
        RUNNING_JOBS.pop(progress.id, None)
        unregister_batch(progress.id)
        try:
            await finish_batch_job(
                progress.id, progress.done, progress.success, progress.fail,
                progress.last_error, cancelled=progress.cancelled,
                skipped=progress.skipped, unfilled=progress.unfilled,
                stop_reason=progress.stop_reason
            )
        except Exception as e:
            print(f"⚠️  بستنِ batch_job در دیتابیس با خطا مواجه شد: {e}")


def _fmt_iso_dt(iso_str: str) -> str:
    """
    نمایشِ خوانا از یه رشته‌ی ISO datetime (که توی دیتابیس UTC ذخیره می‌شه) - تبدیل‌شده
    به‌وقتِ تهران. عمداً پسوندِ منطقه‌ی زمانی رو تکرار نمی‌کنه، چون معمولاً چندین‌بار توی
    یه پیام استفاده می‌شه؛ خودِ پیام یه‌بار در ابتدا ذکر می‌کنه که زمان‌ها به‌وقتِ تهرانن.
    """
    if not iso_str:
        return "؟"
    try:
        return to_tehran(iso_str).strftime("%Y-%m-%d %H:%M")
    except Exception:
        return iso_str


def _fmt_countdown(iso_str: str) -> str:
    """چقدر تا این لحظه (iso_str، UTC) مونده - مثلِ «۳ ساعت و ۱۲ دقیقه» یا «چند لحظه»"""
    if not iso_str:
        return "؟"
    try:
        target = datetime.fromisoformat(iso_str)
    except Exception:
        return "؟"
    delta = (target - utcnow()).total_seconds()
    if delta <= 0:
        return "چند لحظه"
    hours, rem = divmod(int(delta), 3600)
    minutes = rem // 60
    if hours and minutes:
        return f"{hours} ساعت و {minutes} دقیقه"
    if hours:
        return f"{hours} ساعت"
    return f"{minutes} دقیقه"


def _format_interrupted_batch_job(job: dict) -> str:
    """
    نمایشِ یه سفارشِ یک‌باره‌ای که به‌خاطرِ ری‌استارتِ ربات (نه اتمامِ طبیعی) قطع شده -
    با آخرین آماری که تا همون لحظه ثبت شده بود. این جایگزینِ ناپدید-شدنِ بی‌خبرِ
    سفارش از «🗂 سفارش‌ها»ست: به‌جایِ اینکه انگار هیچ‌وقت وجود نداشته، دقیقاً معلومه
    چند تاش قبل از قطع‌شدن انجام شده بود.
    """
    remaining = max(job["total"] - job["done"], 0)
    lines = [
        f"⚠️ {job['title']}",
        "قطع شد (ری‌استارتِ ربات) - قبل از اتمام",
        "",
        f"📊 تا لحظه‌یِ قطع: {job['done']}/{job['total']}",
        f"✅ موفق: {job['success']}    ❌ ناموفق: {job['fail']}    ⏳ باقی‌مونده (انجام‌نشده): {remaining}",
        f"🕐 شروع: {_fmt_iso_dt(job['started_at'])}",
    ]
    if remaining > 0:
        lines.append("این تعداد هیچ‌وقت اجرا نشدن - اگه لازمه، دوباره از منویِ اصلی ثبتش کن.")
    return "\n".join(lines)


def _format_finished_batch_job(job: dict) -> str:
    """
    یه سفارشِ یک‌باره‌یِ تمام‌شده (یا لغوشده) - برایِ «🗂 سفارش‌ها ← ✅ تمام‌شده».
    تا قبل از این، ردیفِ این سفارش‌ها موقعِ اتمام از دیتابیس **حذف** می‌شد، پس
    آمارشون برایِ همیشه گم می‌شد؛ حالا طبقِ همون نگه‌داریِ ۳ روزه می‌مونن.
    """
    total = int(job.get("total") or 0)
    done = int(job.get("done") or 0)
    skipped = int(job.get("skipped") or 0)
    unfilled = int(job.get("unfilled") or 0)
    if job.get("cancelled"):
        head = "🚫 لغو شد"
    elif job.get("stop_reason"):
        head = f"⛔ متوقف شد - {job['stop_reason']}"
    elif (skipped + unfilled) > 0:
        head = "⚠️ تموم شد ولی کامل نشد"
    else:
        head = "✅ تموم شد"
    lines = [job.get("title") or "سفارش", head, "",
             f"📊 اجرا شد: {done}/{total}",
             f"✅ موفق: {job.get('success') or 0}    ❌ ناموفق: {job.get('fail') or 0}"]
    if skipped:
        lines.append(f"⏭ ثبت نشد (عمداً): {skipped}")
    if unfilled:
        lines.append(f"🚫 بی‌اکانت (اجرا نشد): {unfilled}")
    lines.append(f"🕐 شروع: {_fmt_iso_dt(job.get('started_at'))}")
    if job.get("finished_at"):
        lines.append(f"🏁 پایان: {_fmt_iso_dt(job.get('finished_at'))}")
    if job.get("last_error"):
        err = str(job["last_error"])
        lines.append(f"⚠️ آخرین خطا: {err[:200]}")
    return "\n".join(lines)


async def _auto_view_all_status_blocks(admin_id: str):
    """
    برایِ «🗂 سفارش‌ها»: وضعیتِ خلاصه‌یِ هر کانالِ «📅 تمام (پست‌هایِ کانال، روزانه)»
    (و «🎯 تنظیمِ نمودارِ ویو»یِ روش، اگه فعال باشه). عمداً بدونِ هیچ تماسِ شبکه‌ای -
    فقط از رویِ چیزی که همین الان توی دیتابیسه - تا بازکردنِ «🗂 سفارش‌ها» کند نشه؛
    برایِ آمارِ زنده‌ی دقیق، خودِ «📊 آمارِ دقیقِ زنده» توی صفحه‌ی هر کانال هست.

    برخلافِ سفارش‌هایِ یک‌باره، این سیستم دائمی/تکرارشونده‌ست (هر ۲۴:۱۰ ساعت دوباره
    از نو) - پس هیچ‌وقت واقعاً «تمام‌شده» نمی‌شه؛ فقط دو دسته برمی‌گرده:
      - active: حداقل یه اکانتِ شرکت‌کننده یا الان درحالِ دوره یا دستِ‌کم یه دور رو
        قبلاً کامل کرده
      - future: کانالِ تازه‌ثبت‌شده که هنوز هیچ اکانتی توش شروع نکرده
    خروجی: (active_blocks, future_blocks) - هرکدوم لیستی از (text, markup, parse_mode)
    """
    rows = await get_auto_view_all_channels(admin_id)
    active_blocks, future_blocks = [], []
    for row in rows:
        states = await get_all_view_all_account_states(row["id"])
        in_progress = sum(1 for s in states if s.get("next_message_id") is not None)
        finished = sum(1 for s in states if s.get("next_message_id") is None and s.get("last_completed_posts") is not None)
        try:
            participant_ids = json.loads(row["participant_account_ids"]) if row.get("participant_account_ids") else []
        except Exception:
            participant_ids = []
        total_participants = len(participant_ids)
        pending = max(0, total_participants - in_progress - finished)

        lines = [f"📅 {row['display_name']} (تمامِ پست‌ها، روزانه)"]
        lines.append(
            f"🏃 در حالِ دورِ فعلی: {in_progress}    ✅ دورِ اخیرشون تمومه: {finished}    "
            f"⏸ هنوز شروع نکردن: {pending}    (از {total_participants} اکانت)"
        )
        lines.append(f"👁 حجمِ روزانه: {_views_per_post_label(row)} ویو در هر پست")
        if row.get("viewchart_enabled"):
            pct = row.get("viewchart_last_percent")
            pct_txt = f"{pct}٪" if pct is not None else "هنوز اندازه‌گیری نشده"
            lines.append(
                f"🎯 هدفِ نمودارِ ویو: {row['viewchart_target_min']}-{row['viewchart_target_max']}٪ فارسی "
                f"(الان: {pct_txt})"
            )

        block = ("\n".join(lines), None, None)
        if in_progress == 0 and finished == 0:
            future_blocks.append(block)
        else:
            active_blocks.append(block)

    return active_blocks, future_blocks


# ⚠️ send_active_orders / send_future_orders / _view_cycle_line حذف شدن.
# کارشون رو حالا send_orders + orders_view انجام می‌ده (همون مسیری که شیر استفاده
# می‌کرد): یک پیامِ صفحه‌بندی‌شده به‌جایِ یه پیام برایِ هر پست، با آمارِ کاملِ
# لغوشده/پاک‌شده و صفحه‌ی جزئیات. خطِ «وضعیتِ دوره‌ی بازدید» هم به
# orders_view._view_cycle_note منتقل شد تا هر سه بخش یک‌جا رندر بشن.


def build_multi_country_grid(countries: list, selected: set, callback_prefix: str, confirm_callback: str,
                              all_callback: str, back_callback: str):
    """کیبوردِ چندانتخابیِ کشور - آیتم‌هایِ انتخاب‌شده با ✅ مشخص می‌شن + دکمه‌ی «همه‌ی کشورها»
    که مستقیم (بدونِ نیاز به تایید) با همه‌یِ اکانت‌ها جلو می‌ره."""
    kb = []
    for c in countries:
        code = c["country_code"]
        label = f"{c['country_flag'] or ''} {c['country_name']} ({c['cnt']} اکانت)"
        if code in selected:
            label = f"✅ {label}"
        kb.append([InlineKeyboardButton(label, callback_data=f"{callback_prefix}{code}")])
    total_accounts = sum(c["cnt"] for c in countries)
    kb.append([InlineKeyboardButton(f"🌍 همه‌ی کشورها ({total_accounts} اکانت)", callback_data=all_callback)])
    confirm_label = f"✅ تایید ({len(selected)} کشور انتخاب‌شده)" if selected else "✅ تایید انتخاب‌ها"
    kb.append([InlineKeyboardButton(confirm_label, callback_data=confirm_callback)])
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data=back_callback)])
    return InlineKeyboardMarkup(kb)


async def show_view_countries(target, context):
    """target: یا CallbackQuery (edit_message_text) یا Update.message (reply_text) - هردو پشتیبانی می‌شن"""
    countries = await get_country_counts()
    if not countries:
        kb = [[InlineKeyboardButton("🔙 بازگشت", callback_data="opsview_start")]]
        text = "هیچ اکانتِ فعالی با کشورِ مشخص نیست - اول چندتا اکانت لاگین کن."
        markup = InlineKeyboardMarkup(kb)
    else:
        context.user_data["view_country_selected"] = set()
        markup = build_multi_country_grid(
            countries, set(), "opsviewctoggle_", "opsviewcountry_confirm", "opsviewcountry_all", "opsview_start"
        )
        text = "📍 بازدیدِ یک‌باره\nکشور(ها) رو انتخاب کن (چندتا می‌تونی تیک بزنی)، بعد تایید کن:"

    if hasattr(target, "edit_message_text"):
        await target.edit_message_text(text, reply_markup=markup)
    else:
        await target.reply_text(text, reply_markup=markup)


