async def build_autoview_menu(admin_id: str):
    rows = await get_auto_view_channels(admin_id)
    kb = [[InlineKeyboardButton("➕ ثبتِ کانالِ جدید", callback_data="autoview_add")]]
    for r in rows:
        window = (f" ⏱{view_window.fmt_duration(r['view_window_minutes'])}"
                  if r.get("view_window_minutes") else "")
        delay = window or (f" ⏳{r['start_delay_minutes']}دقیقه"
                           if r.get("start_delay_minutes") else "")
        if r.get("views_per_round"):
            spread = f" 🔁هر{r['spread_minutes'] or 1}دقیقه×{r['views_per_round']}"
        else:
            spread = f" 🔀{_fmt_hours(r['spread_minutes'] / 60)}" if r.get("spread_minutes") else ""
        join = " 👥" if r.get("join_before_view") else ""
        country = f" {r['country_code']}" if r.get("country_code") else " 🌍"
        lo = int(r.get("view_count_min") or r["view_count"])
        hi = int(r.get("view_count_max") or r["view_count"])
        count_label = str(lo) if lo == hi else f"{lo}-{hi}"
        followers = int(r.get("follower_percent") if r.get("follower_percent") is not None else 100)
        label = (f"🔁 @{r['channel_username'].lstrip('@')} "
                 f"({count_label} · 👥{followers}٪ · {country}{delay}{spread})")
        kb.append([InlineKeyboardButton(label, callback_data=f"autoview_view_{r['id']}")])
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data="opsview_start")])
    text = (
        f"🔁 بازدیدِ خودکار  ·  {len(rows)} کانال\n\n"
        "برای هر پستِ جدید، تعداد از بازه‌ی تو تصادفی انتخاب می‌شه. سهمِ Followers و "
        "Other هم با درصدی که می‌دی ساخته می‌شه.\n\n"
        "ثبت: کانال ← کشور ← بازه‌ی بازدید ← درصد Followers ← زمان\n"
        "فقط کانالِ عمومی پشتیبانی می‌شه. پست‌های قدیمی دست‌نخورده می‌مونن.\n\n"
        "📊 وضعیت زنده: تنظیمات ← منابعِ سرور"
    )
    return text, InlineKeyboardMarkup(kb)


async def show_autoview_detail(query, autoview_id, admin_id: str):
    row = await get_auto_view_channel(autoview_id, admin_id)
    if not row:
        await query.edit_message_text("پیدا نشد (یا مالِ ادمینِ دیگه‌ایه).")
        return
    last = row["last_message_id"] or "هنوز پستی دیده نشده"
    country_text = row["country_code"] if row.get("country_code") else "همه‌ی کشورها"
    delay = row.get("start_delay_minutes") or 0
    delay_text = f"{delay} دقیقه بعدِ انتشارِ پست" if delay else "بلافاصله بعدِ انتشارِ پست"

    accounts = await get_all_accounts()
    pool_size = len(_pool_by_country(accounts, row.get("country_code")))
    total_min = int(row.get("view_count_min") or row["view_count"])
    total_max = int(row.get("view_count_max") or row["view_count"])
    total = total_max
    follower_percent = int(
        row.get("follower_percent") if row.get("follower_percent") is not None else 100
    )
    per_round = row.get("views_per_round")
    interval = row.get("spread_minutes") or 1

    if per_round:
        rounds = math.ceil(total / per_round) if per_round else 0
        span = (rounds - 1) * interval if rounds else 0
        spread_text = f"هر {interval} دقیقه {per_round} بازدید"
        plan_text = (f"{rounds} دوره، یعنی حدودِ {span} دقیقه بعدِ شروع تمام می‌شه"
                      if rounds > 1 else "همه در یک دوره")
    else:
        spread_text = (f"طیِ {_fmt_hours(row['spread_minutes'] / 60)} به‌طورِ مساوی"
                        if row.get("spread_minutes") else "پشتِ‌سرِهم (فوری)")
        plan_text = "بدونِ دوره‌بندی"

    if row.get("view_window_minutes"):
        window_text = view_window.fmt_duration(row["view_window_minutes"])
        if per_round:
            _p = view_window.plan_view_window(total, row["view_window_minutes"], delay)
            window_text += f" (پایانِ واقعی: ~{view_window.fmt_duration(_p['total_minutes'])})"
    else:
        window_text = "ثبت‌نشده (کانالِ قدیمی - برایِ تنظیمش دوباره ثبتش کن)"

    join_on = bool(row.get("join_before_view"))
    if join_on:
        summary = await get_membership_summary(row["channel_username"])
        members = summary.get("member", 0)
        not_member = summary.get("not_member", 0)
        unknown = max(pool_size - members - not_member, 0)
        join_text = f"✅ روشن — {members} از {pool_size} اکانت عضو شدن"
        if not_member or unknown:
            join_text += f" (در صفِ عضویت: {not_member + unknown})"
    else:
        join_text = "◽️ خاموش — بازدیدها به‌عنوانِ «غیرِ فالوور» ثبت می‌شن"

    # سقفِ واقعی: تلگرام از هر اکانت فقط ۱ بازدید برایِ هر پست می‌شماره
    if pool_size == 0:
        cap_text = "⛔️ هیچ اکانتِ فعالی برایِ این کشور نیست - هیچ بازدیدی ثبت نمی‌شه"
    elif total > pool_size:
        cap_text = (f"⚠️ {total} بازدید خواسته شده ولی فقط {pool_size} اکانتِ فعال داری.\n"
                     f"    تلگرام از هر اکانت فقط ۱ بازدید برایِ هر پست می‌شماره، پس "
                     f"عملاً {pool_size} تا ثبت می‌شه.\n"
                     f"    برایِ {total} بازدید، به {total} اکانت نیاز داری.")
    else:
        cap_text = f"✅ {pool_size} اکانتِ فعال موجوده - این تعداد کاملاً قابلِ ثبته"

    text = (
        f"🔁 @{row['channel_username'].lstrip('@')}\n"
        f"\n"
        f"🎯 بازدیدِ هر پست: {total_min}-{total_max} (تصادفی)\n"
        f"📊 منبع: Followers {follower_percent}٪ · Other {100 - follower_percent}٪\n"
        f"⏱ پنجره‌ی زمانی: {window_text}\n"
        f"🌍 کشورِ اکانت‌ها: {country_text}\n"
        f"⏳ شروعِ بازدید: {delay_text}\n"
        f"🔁 ریتم: {spread_text} ({plan_text})\n"
        f"👥 آماده‌سازی عضویت: {join_text}\n"
        f"\n"
        f"{cap_text}\n"
        f"\n"
        f"🔄 دورِ بعدی: نداره - هر پست فقط یک دوره‌ی ۱۰۰٪ می‌گیره و بعد کنار گذاشته می‌شه\n"
        f"📌 آخرین پستِ دیده‌شده: {last}"
    )
    kb = [
        [InlineKeyboardButton("🗑 غیرفعال‌کردن", callback_data=f"autoview_delcheck_{autoview_id}")],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="opsview_auto")],
    ]
    await query.edit_message_text(text, reply_markup=InlineKeyboardMarkup(kb))


# ============================================================================
# بازدیدِ «تمامِ پست‌هایِ کانال، روزانه»
# ----------------------------------------------------------------------------
# برخلافِ «بازدیدِ خودکار» (که فقط پستِ *جدید* رو می‌بینه)، این هر روز از اولین تا
# آخرین پستِ کانال رو کامل مرور می‌کنه. منطقِ اجرایِ واقعی توی auto_view_all.py زندگی
# می‌کنه؛ این بخش فقط رابطِ کاربریِ ثبت/ویرایش/حذفه.
# ============================================================================

# بازدیدِ «تمامِ پست‌هایِ کانال، روزانه» (منویِ مستقل حذف شد - نگاه کن به بخشِ
# «تنظیمِ نمودارِ ویو» پایین‌تر که الان تنها راهِ ثبت/مدیریتِ این کانال‌هاست)
# ----------------------------------------------------------------------------
def _progress_bar(percent: float, length: int = 12) -> str:
    filled = max(0, min(length, round(percent / 100 * length)))
    return "🟩" * filled + "⬜️" * (length - filled)


# ============================================================================
# تنظیمِ نمودارِ ویو (Languages) - نگاه کن به viewchart.py برایِ منطقِ کاملِ حلقه‌ی
# تطبیقی. این بخش فقط رابطِ کاربریه؛ همیشه رویِ یه کانالِ از قبل ثبت‌شده در
# «تمامِ پست‌ها، روزانه» کار می‌کنه (همون سیستمیه که واقعاً بازدید انجام می‌ده).
# ============================================================================

def _views_per_post_label(row: dict) -> str:
    """برچسبِ نمایشیِ views_per_post - اگه حالتِ «حداکثرِ پویا» فعال باشه، به‌جایِ
    عددِ خام، وضعیتِ پویا بودنش رو هم نشون می‌ده."""
    if row.get("max_accounts_mode"):
        return f"{row['views_per_post']} (حداکثرِ پویا - خودکار با اکانتِ جدید زیاد می‌شه)"
    return str(row["views_per_post"])


def _lang_code_label(code: str) -> str:
    return {"fa": "🇮🇷 فارسی", "en": "🇬🇧 انگلیسی"}.get(code, code or "؟")


