def _minutes_label(minutes: int) -> str:
    if minutes >= 60 and minutes % 60 == 0:
        return f"{minutes // 60} ساعت"
    return f"{minutes} دقیقه"


def _fmt_hours(hours: float) -> str:
    if hours == int(hours):
        return f"{int(hours)} ساعت"
    return f"{hours:g} ساعت"


def _parse_hour_range(text: str):
    """پارسِ بازه‌ی ساعتی از متنِ آزاد - مثلِ «3-24»، «3 تا 24»، «بینِ ۳ و ۲۴»"""
    nums = re.findall(r'\d+(?:\.\d+)?', text)
    if len(nums) < 2:
        return None
    lo, hi = float(nums[0]), float(nums[1])
    if lo <= 0 or hi <= 0 or lo > hi:
        return None
    return lo, hi


def _parse_int_range(text: str):
    """بازه‌ی دو عددِ صحیحِ مثبت؛ اعشار و متنِ اضافه پذیرفته نمی‌شود."""
    normalized = text.translate(_FA_DIGITS).strip()
    match = re.fullmatch(r"\s*(\d+)\s*(?:-|–|—|تا)\s*(\d+)\s*", normalized)
    if not match:
        return None
    lo, hi = map(int, match.groups())
    if lo < 1 or hi < lo:
        return None
    return lo, hi


def _parse_public_channel_username(text: str):
    """
    یوزرنیمِ یه کانالِ **عمومی** رو از متنِ آزاد بیرون می‌کشه - @channelname، channelname،
    یا لینکِ عمومی (t.me/channelname). عمداً لینکِ خصوصی/دعوت (t.me/+HASH یا
    t.me/joinchat/HASH) رو قبول نمی‌کنه (برایِ اون فرمت‌ها، آیدیِ عددی یا فوروارد استفاده
    می‌شه - نگاه کن به _normalize_channel_id_input).
    """
    raw = text.strip()
    if not raw:
        return None
    if "t.me" in raw:
        if "+" in raw or "joinchat" in raw:
            return None  # لینکِ خصوصی/دعوت - با یوزرنیم قابلِ‌تشخیص نیست
        m = re.search(r't\.me/([A-Za-z0-9_]+)(?:/|$)', raw)
        if not m:
            return None
        return f"@{m.group(1)}"
    raw = raw.lstrip("@")
    if not re.fullmatch(r'[A-Za-z0-9_]{4,}', raw):
        return None
    return f"@{raw}"


def _extract_raw_channel_id(n: int) -> int:
    """
    شناسه‌ی «خامِ» یه کانال (همونی که Telethon/PeerChannel می‌خواد) رو از هر فرمتی که
    کاربر یا خودِ تلگرام بده درمیاره:
      - فرمتِ Bot API برایِ سوپرگروه/کانال: -100xxxxxxxxxx (مثلاً forward_origin.chat.id)
      - یا فقط با یه منفی جلوش: -xxxxxxxxxx
      - یا خودِ عددِ خام (بدونِ علامت): xxxxxxxxxx
    هر سه رو به همون عددِ مثبتِ خام تبدیل می‌کنه.
    """
    if n < 0:
        n = -n
        if n > 10**12:
            n -= 10**12
    return n


def _normalize_channel_id_input(text: str):
    """پارسِ آیدیِ عددیِ یه کانالِ خصوصی از متنِ آزاد - نگاه کن به _extract_raw_channel_id."""
    raw = text.strip().translate(_FA_DIGITS)
    if not re.fullmatch(r'-?\d+', raw):
        return None
    try:
        n = int(raw)
    except ValueError:
        return None
    result = _extract_raw_channel_id(n)
    return result if result > 0 else None


def _channel_display(channel_ref) -> str:
    """برچسبِ نمایشیِ یه کانال - چه یوزرنیمِ عمومی (str) چه شناسه‌ی خصوصی (int)."""
    if isinstance(channel_ref, int):
        return f"کانالِ خصوصیِ {channel_ref}"
    return f"@{str(channel_ref).lstrip('@')}"


def _link_info_from_forward_origin(origin):
    """
    اگه origin از نوعِ MessageOriginChannel باشه (یعنی پیام واقعاً از داخلِ یه کانال
    فوروارد شده، نه از یه چتِ شخصی/گروه)، یه link_info دقیقاً همون‌شکلِ خروجیِ
    parse_post_link می‌سازه - قابلِ‌استفاده مستقیم برایِ view_post/react_to_post.
    برایِ کانالِ عمومی از یوزرنیم، برایِ خصوصی از آیدیِ عددی (تبدیل‌شده با
    _extract_raw_channel_id) استفاده می‌کنه. اگه فوروارد نباشه، None برمی‌گردونه.
    """
    if not isinstance(origin, MessageOriginChannel):
        return None
    chat = origin.chat
    message_id = origin.message_id
    username = getattr(chat, "username", None)
    if username:
        return {
            "is_private": False, "username": username, "channel_id": None,
            "message_id": message_id, "url": f"https://t.me/{username}/{message_id}",
        }
    raw_id = _extract_raw_channel_id(chat.id)
    return {
        "is_private": True, "username": None, "channel_id": raw_id,
        "message_id": message_id, "url": f"https://t.me/c/{raw_id}/{message_id}",
    }


async def _mpr_add_forwarded_post(message, context, origin) -> bool:
    """
    اگه پیامِ فوروارد‌شده واقعاً از یه کانال باشه، link_infoشو به لیستِ mpr_posts اضافه
    می‌کنه و پیامِ تأیید می‌فرسته - True برمی‌گردونه. وگرنه False (صداکننده باید پیامِ
    خطایِ مناسب رو بفرسته). این تابع مشترک، از هرسه‌یِ on_text/on_document/
    on_forwarded_media صدا زده می‌شه - چون یه پستِ فوروارد‌شده بسته به نوعش (متن،
    فایل، عکس/ویدیو) به هرکدوم از این سه هندلر می‌رسه.
    """
    link_info = _link_info_from_forward_origin(origin)
    if not link_info:
        return False
    posts = context.user_data.setdefault("mpr_posts", [])
    posts.append(link_info)
    await message.reply_text(f"✅ پستِ {len(posts)} ثبت شد. بازم بفرست یا «✅ تمام - ادامه» رو بزن.")
    return True


def _parse_delay_range(text: str):
    """
    مثلِ _parse_hour_range ولی برایِ «تأخیرِ شروع - پایانِ بازه»؛ برخلافِ اون، شروع=۰
    (یعنی بدونِ تأخیر، همون لحظه) هم مجازه، چون معنیِ متفاوتی داره (این یه فاصله‌ی
    زمانی از خودِ پسته، نه یه بازه‌ی کلیِ مستقل).
    """
    nums = re.findall(r'\d+(?:\.\d+)?', text)
    if len(nums) < 2:
        return None
    lo, hi = float(nums[0]), float(nums[1])
    if lo < 0 or hi <= lo:
        return None
    return lo, hi


def _parse_count_or_range(text: str):
    """
    ورودیِ تعدادِ ری‌اکشن رو می‌خونه - هم عددِ تکی («۲۵») هم بازه («۲۰-۳۰» یا «۲۰ تا ۳۰»).
    خروجی: (lo, hi) که برایِ عددِ تکی lo == hi هست، یا None اگه ورودی معتبر نباشه.
    توجه: توی حالتِ بازه، عددِ پایین باید حداقل ۱ باشه - چون هر ری‌اکشنِ انتخابی باید
    توی کم‌ترین پست هم حداقل یه سهم بگیره (بازه‌ی «۰ تا ۳۰» معنیِ روشنی نداره).
    """
    nums = re.findall(r'\d+', text.translate(_FA_DIGITS))
    if not nums:
        return None
    if len(nums) == 1:
        n = int(nums[0])
        return (n, n)
    lo, hi = int(nums[0]), int(nums[1])
    if hi < lo:
        lo, hi = hi, lo
    if hi > lo and lo < 1:
        return None
    return (lo, hi)


def _pool_by_country(accounts, country_code):
    """فیلترِ اکانت‌های فعال بر اساسِ کشور - None یعنی همه‌ی کشورها"""
    if country_code:
        return [a for a in accounts if a["is_logged_in"] and a["country_code"] == country_code]
    return [a for a in accounts if a["is_logged_in"]]


async def _finalize_autoview(context):
    """ثبتِ نهاییِ بازدیدِ خودکار بعدِ جمع‌شدنِ همه‌ی اطلاعات (یوزرنیم/کشور/تعداد/تأخیر/دوره‌بندی)"""
    chat_id = context.user_data.get("_chat_id")
    admin_id = context.user_data.get("_admin_id")
    username = context.user_data.pop("av_username", None)
    country = context.user_data.pop("av_country", None)
    count = context.user_data.pop("av_count", None)
    count_min = context.user_data.pop("av_count_min", count)
    count_max = context.user_data.pop("av_count_max", count)
    follower_percent = context.user_data.pop("av_follower_percent", 100)
    start_delay = context.user_data.pop("av_start_delay", 1)
    round_interval = context.user_data.pop("av_round_interval", 0)
    views_per_round = context.user_data.pop("av_views_per_round", None)
    window_minutes = context.user_data.pop("av_window_minutes", 0)
    # طبقِ درخواست، عضویتِ قبلِ بازدید همیشه اجباریه - دیگه سؤالی ازش پرسیده نمی‌شه
    join_before_view = context.user_data.pop("av_join_before_view", 1)
    context.user_data.pop("awaiting", None)
    context.user_data.pop("_chat_id", None)
    context.user_data.pop("_admin_id", None)

    accounts = await get_all_accounts()
    pool = _pool_by_country(accounts, country)

    if not pool or not username or not count:
        await context.bot.send_message(chat_id, "مشکلی پیش اومد - از اول امتحان کن.")
        return

    # چکِ دوباره: بینِ مرحله‌ی اولِ ویزارد تا این‌جا ممکنه ادمین ربات رو از کانال
    # حذف کرده باشه. ثبتِ کانالی که ربات توش ادمین نیست یعنی برگشتِ همون مشکلِ فریز.
    probe = await channel_watch.bot_admin_status(username)
    if not probe["ok"]:
        await context.bot.send_message(
            chat_id,
            f"❌ ربات دیگه ادمینِ @{username} نیست، پس ثبت انجام نشد.\n"
            "ربات رو ادمینِ کانال کن و از اول امتحان کن."
        )
        return

    watcher = pool[0]
    # ⚠️ نقطه‌ی شروع فقط از سمتِ ربات تعیین می‌شه - هیچ اکانتی کانال رو نمی‌خونه.
    # قبلاً این‌جا اولین اکانتِ استخر getHistory می‌زد تا «آخرین پستِ کانال» رو
    # بفهمه؛ ولی لازم نیست: ربات فقط پست‌هایی رو می‌بینه که *زنده* بهش پوش شدن، پس
    # هر پستی که از این لحظه به بعد برسه واقعاً جدیده. فقط پست‌هایی که ربات از قبل
    # بافر کرده (چون از قبل ادمین بوده) باید رد بشن - همین latest_seen_id. برایِ
    # اطمینانِ بیشتر، _schedule_new_posts هم پستِ قدیمی‌تر از زمانِ ثبت رو رد می‌کنه.
    last_id = channel_watch.latest_seen_id(username)
    result = await add_auto_view(
        username, count, watcher["id"], last_id, country_code=country, spread_minutes=round_interval,
        admin_id=admin_id, start_delay_minutes=start_delay, join_before_view=join_before_view,
        views_per_round=views_per_round, view_window_minutes=window_minutes,
        view_count_min=count_min, view_count_max=count_max,
        follower_percent=follower_percent,
    )

    if result["status"] == "success":
        country_text = f"کشورِ {country}" if country else "همه‌ی کشورها"
        pool_size = len(pool)
        plan = view_window.plan_view_window(count, window_minutes or 60, start_delay)

        lines = [
            f"✅ بازدیدِ خودکار برایِ @{username} فعال شد.",
            "",
            f"🎯 هر پستِ جدید: {count_min}-{count_max} بازدیدِ تصادفی، طیِ "
            f"{view_window.fmt_duration(window_minutes)}",
            f"📊 منبع: Followers {follower_percent}٪ · Other {100 - follower_percent}٪",
            f"🌍 اکانت‌ها: {country_text} ({pool_size} فعال)",
            f"⏳ شروع: {start_delay} دقیقه بعدِ انتشارِ پست",
            f"🔁 ریتم: هر {round_interval} دقیقه {views_per_round} بازدید "
            f"({plan['rounds']} دوره)",
            f"🏁 پایان: حدودِ {view_window.fmt_duration(plan['total_minutes'])} "
            f"بعدِ انتشارِ هر پست",
            "",
            "• فقط پست‌هایِ *جدید* بازدید می‌گیرن، نه پست‌هایِ قبلی.",
            "• مبنایِ زمان‌بندی، زمانِ خودِ پسته - نه لحظه‌ای که ربات دیدش.",
            "• 👥 فقط سهمِ Followers عضو می‌شه؛ سهمِ Other غیرعضو می‌مونه.",
            "• 🔄 هر پست فقط یک دوره‌ی ۱۰۰٪ می‌گیره و بعد کنار گذاشته می‌شه.",
            "• 🛡 اگه سرور شلوغ بشه یا اکانتی به سقفِ روزانه‌ش برسه، ربات خودش عقب "
            "می‌کشه و جبران می‌کنه - بازدید گم نمی‌شه.",
        ]
        if plan["busy"]:
            lines += [
                "",
                f"⚠️ این ریتم تنده (حدودِ {plan['views_per_minute']} بازدید در دقیقه). "
                f"برایِ رشدِ طبیعی‌تر، پنجره‌ی "
                f"{view_window.fmt_duration(view_window.min_window_minutes_for(count))} "
                f"یا بیشتر بهتره - کانال رو حذف و با عددِ بزرگ‌تر دوباره ثبت کن.",
            ]

        if count > pool_size:
            lines += [
                "",
                f"⚠️ هشدارِ ظرفیت: {count} بازدید خواستی ولی {pool_size} اکانت داری.",
                f"تلگرام از هر اکانت فقط ۱ بازدید برایِ هر پست می‌شماره، پس عملاً "
                f"{pool_size} بازدید ثبت می‌شه. برایِ {count} تا، به {count} اکانت نیاز داری.",
            ]

        lines += ["", "📊 سرعت و عقب‌افتادگیِ لحظه‌ای: «⚙️ تنظیمات» → «📊 منابعِ سرور»"]
        await context.bot.send_message(chat_id, "\n".join(lines))
    else:
        await context.bot.send_message(chat_id, f"❌ خطا: {result.get('message', 'نامشخص')}")

    menu_text, markup = await build_autoview_menu(admin_id)
    await context.bot.send_message(chat_id, menu_text, reply_markup=markup)


async def _finalize_autoreact(context):
    """ثبتِ نهاییِ ری‌اکشنِ خودکار بعدِ جمع‌شدنِ همه‌ی اطلاعات (شاملِ نقشه‌یِ چندری‌اکشنیِ هر باکت)"""
    chat_id = context.user_data.get("_chat_id")
    admin_id = context.user_data.get("_admin_id")
    username = context.user_data.pop("ar_username", None)
    is_private = context.user_data.pop("ar_is_private", False)
    channel_id = context.user_data.pop("ar_channel_id", None)
    invite_link = context.user_data.pop("ar_invite_link", None)
    ar_title = context.user_data.pop("ar_title", None)
    country = context.user_data.pop("ar_country", None)
    spread_start = context.user_data.pop("ar_spread_start", 0)
    spread_end = context.user_data.pop("ar_spread_end", 0)
    tags = context.user_data.pop("ar_tags", None)
    context.user_data.pop("ar_range_with_tag", None)
    context.user_data.pop("ar_range_without_tag", None)
    context.user_data.pop("ar_range", None)
    map_with_tag = context.user_data.pop("ar_map_with_tag", None) or {}
    map_without_tag = context.user_data.pop("ar_map_without_tag", None) or {}
    map_default = context.user_data.pop("ar_map_default", None) or {}
    variety_with_tag = context.user_data.pop("ar_variety_with_tag", None)
    variety_without_tag = context.user_data.pop("ar_variety_without_tag", None)
    variety_default = context.user_data.pop("ar_variety_default", None)
    context.user_data.pop("awaiting", None)
    context.user_data.pop("_chat_id", None)
    context.user_data.pop("_admin_id", None)

    accounts = await get_all_accounts()
    pool = _pool_by_country(accounts, country)

    if tags:
        all_reactions = set(map_with_tag) | set(map_without_tag)
        effective_count = max(sum(map_with_tag.values()), sum(map_without_tag.values()))
    else:
        all_reactions = set(map_default)
        effective_count = sum(map_default.values())

    # برایِ عمومی یوزرنیم لازمه، برایِ خصوصی شناسه‌یِ عددی + لینکِ دعوت
    has_channel = (channel_id and invite_link) if is_private else bool(username)
    if not pool or not has_channel or not all_reactions or not effective_count:
        await context.bot.send_message(chat_id, "مشکلی پیش اومد - از اول امتحان کن.")
        return

    display_reaction = " ".join(sorted(all_reactions))  # فقط برایِ نمایش/سازگاریِ ستونِ قدیمی
    title = ar_title or username or "کانالِ خصوصی"

    ref = {
        "is_private": is_private,
        "username": None if is_private else username,
        "channel_id": int(channel_id) if (is_private and channel_id) else None,
        "invite_link": invite_link,
        "title": title,
    }

    watcher = pool[0]

    # اکانتِ ناظر باید *قبل از* خوندنِ آخرین پست عضوِ کانال باشه، وگرنه برایِ کانالِ
    # خصوصی حتی resolve هم شکست می‌خوره و last_id خالی می‌مونه
    if is_private:
        member = await ensure_member_for_reactions(
            watcher["session_file"], is_private=True,
            channel_id=ref["channel_id"], invite_link=invite_link,
        )
        if member["status"] not in ("member", "joined"):
            await context.bot.send_message(
                chat_id,
                f"❌ اکانتِ ناظر نتونست عضوِ کانال بشه: {member.get('message', member['status'])}\n\n"
                "کانال ثبت نشد - دوباره امتحان کن."
            )
            return

    try:
        if is_private:
            last_id = await get_latest_message_id_private(watcher["session_file"], ref["channel_id"])
        else:
            last_id = await get_latest_message_id(watcher["session_file"], username)
    except Exception:
        last_id = 0

    result = await add_auto_react(
        username, display_reaction, 0, watcher["id"], last_id, country_code=country,
        reaction_count_with_tag=(sum(map_with_tag.values()) if tags else None),
        reaction_count_without_tag=(sum(map_without_tag.values()) if tags else None),
        admin_id=admin_id, spread_start_hours=spread_start, spread_end_hours=spread_end,
        is_private=is_private, channel_id=channel_id, invite_link=invite_link,
        channel_title=title,
    )

    if result["status"] == "success":
        aid = result["id"]
        if tags:
            await add_auto_react_tags(aid, tags)
            if map_with_tag:
                await set_auto_react_reactions(aid, "with_tag", map_with_tag)
                if variety_with_tag:
                    await set_auto_react_variety(aid, "with_tag", *_variety_args(variety_with_tag))
            if map_without_tag:
                await set_auto_react_reactions(aid, "without_tag", map_without_tag)
                if variety_without_tag:
                    await set_auto_react_variety(aid, "without_tag", *_variety_args(variety_without_tag))
        elif map_default:
            await set_auto_react_reactions(aid, "default", map_default)
            if variety_default:
                await set_auto_react_variety(aid, "default", *_variety_args(variety_default))

        if spread_end and spread_end > 0:
            spread_text = f"از {_fmt_hours(spread_start)} تا {_fmt_hours(spread_end)} بعدِ هر پست، رندوم پخش می‌شه"
        else:
            spread_text = "فوری انجام می‌شه"
        country_text = f"کشورِ {country}" if country else "همه‌ی کشورها"

        def _fmt_map(m: dict, v) -> str:
            if not m:
                return "—"
            if v:
                vmin, vmax, tmin, tmax = _variety_args(v)
                tot = (f"مجموع رندوم {tmin}-{tmax}" if tmin and tmax
                       else f"مجموعِ ثابت: {sum(m.values())}")
                return f"🎲 هر پست رندوم: {vmin}-{vmax} نوع از {' '.join(m.keys())} ({tot})"
            return " ".join(f"{r}×{c}" for r, c in m.items())

        if tags:
            detail = (
                f"🆔 {len(tags)} تگ ثبت شد\n"
                f"تگ‌دار: {_fmt_map(map_with_tag, variety_with_tag)}\n"
                f"بدونِ‌تگ: {_fmt_map(map_without_tag, variety_without_tag)}"
            )
        else:
            detail = _fmt_map(map_default, variety_default)
        channel_label = f"«{title}»" if is_private else f"@{username}"
        await context.bot.send_message(
            chat_id,
            f"✅ ری‌اکشنِ خودکار برای {channel_label} فعال شد.\n"
            f"{detail}\n({country_text}) - {spread_text}."
        )
        # اکانت‌هایی که عضوِ کانال نیستن رو در پس‌زمینه عضو می‌کنیم تا موقعِ
        # ری‌اکشن‌زدن از قبل دسترسی داشته باشن. این کار معطلِ ثبتِ کانال نمی‌مونه.
        try:
            asyncio.create_task(_ar_join_pool_in_background(context, chat_id, ref, pool))
        except Exception:
            pass
    else:
        await context.bot.send_message(chat_id, f"❌ خطا: {result.get('message', 'نامشخص')}")

    menu_text, markup = await build_autoreact_menu(admin_id)
    await context.bot.send_message(chat_id, menu_text, reply_markup=markup)


def _make_on_before_account(job_id: str):
    """کالبکی که قبلِ پردازشِ هر اکانت صدا زده می‌شه و لیستِ آیدیِ اکانت‌هایِ باقی‌مونده
    رو توی batch_jobs.remaining_json به‌روز می‌کنه - نگاه کن به update_batch_job_remaining."""
    async def _on_before(remaining_accounts):
        ids = [a["id"] for a in remaining_accounts if a.get("id") is not None]
        await update_batch_job_remaining(job_id, json.dumps(ids))
    return _on_before


def _tehran_day_key() -> str:
    """کلیدِ «امروز» به وقتِ تهران - مبنایِ شمارنده‌یِ فعالیتِ روزانه."""
    return to_tehran(utcnow()).date().isoformat()


def _account_age_days(acc: dict) -> float:
    """چند روز از اضافه‌شدنِ این اکانت به ربات می‌گذره؟ (نازک‌کننده رویِ
    activity_guard - تا منطقِ سن‌سنجی فقط یه جا تعریف شده باشه)"""
    return activity_guard.account_age_days(acc)


async def _classify_order_accounts(run_accounts: list) -> dict:
    """
    اکانت‌هایی که الان حق ندارن کار کنن رو از یه سفارش کنار می‌ذاره - و **دلیلِ
    هرکدوم** رو هم برمی‌گردونه.

    ⚠️ باگی که این‌جا رفع شد (همون «بخشِ ری‌اکشن مشکل داره»): نسخه‌ی قبلی فقط سه
    عدد برمی‌گردوند - سقفِ روزانه، گرم‌کردن، قرنطینه. هر اکانتی که به دلیلِ *دیگه‌ای*
    کنار گذاشته می‌شد (نوبتِ ضرب‌آهنگش نرسیده بود، سقفِ ساعتی، ساعاتِ سکوتِ شبانه،
    مکثِ بعدِ FloodWait، یا حتی لاگین‌نبودن) بی‌هیچ پیامی دور ریخته می‌شد و بعد
    total رویِ همون تعدادِ باقی‌مونده بسته می‌شد. نتیجه‌ی عملی: سفارشِ ۷ ری‌اکشنی با
    ۳ اکانت اجرا می‌شد و کارت می‌گفت «✅ تموم شد · ۱۰۰٪ (۳/۳) · موفق ۳».

    خروجی: {"allowed", "dropped" [(اکانت, دلیل)], "holds" {دلیل: تعداد},
             "settings", "usage"}
    """
    settings = await get_humanize_settings()   # عمداً تازه، نه از کش - تا تغییرِ
    # تنظیمات از منویِ «🎭 رفتارِ اکانت‌ها» بلافاصله روی سفارشِ بعدی اثر کنه
    usage = await activity_guard.daily_usage_map()
    allowed, dropped, holds = [], [], {}
    for acc in run_accounts or []:
        ok, reason = activity_guard.readiness(acc, settings, usage)
        if ok:
            allowed.append(acc)
            continue
        key = react_order.hold_reason(acc, reason, settings)
        holds[key] = holds.get(key, 0) + 1
        dropped.append((acc, key))
    return {"allowed": allowed, "dropped": dropped, "holds": holds,
            "settings": settings, "usage": usage}


async def _launch_batch(message, run_accounts, action_fn, minutes: int, random_range,
                         op_label: str, title_immediate: str, title_scheduled: str, title_random: str,
                         admin_id: str = None, kind: str = "other",
                         resume_kind: str = None, resume_payload: dict = None,
                         progress_seed: dict = None,
                         action_timeout: float = None, max_parallel: int = 1,
                         gap_range: tuple = None,
                         requested_total: int = None, substitutes: list = None,
                         guard_fn=None, activity_weight: int = 1):
    """
    اجرایِ یک دسته (فوری/پخش‌شده/رندوم) با نمایشِ آمارِ زنده روی خودِ پیام (پیشرفت،
    موفق/ناموفق، باقی‌مونده، زمانِ شروع، تخمینِ پایان) که هر چند ثانیه خودکار آپدیت
    می‌شه و یه دکمه‌ی «🔄 آپدیتِ آمار» زیرش هست برایِ رفرشِ دستی. همچنین توی رجیستریِ
    سفارش‌هایِ فعال ثبت می‌شه (با admin_id) تا از منویِ «🗂 سفارش‌ها» هم
    قابلِ‌پیگیری/لغو باشه.

    resume_kind/resume_payload (اختیاری): اگه داده بشن، این سفارش قابلِ‌ازسرگیریِ خودکاره -
    اگه ربات وسطِ اجرا ری‌استارت بشه، موقعِ بالا اومدنِ دوباره از رویِ اکانت‌هایِ باقی‌مونده
    ادامه پیدا می‌کنه (نگاه کن به resume_interrupted_batches).
    progress_seed (اختیاری): فقط موقعِ ازسرگیریِ یه سفارشِ قدیمی استفاده می‌شه - آمارِ
    واقعیِ تا لحظه‌یِ قطع‌شدن + job_id/زمانِ شروعِ اصلی رو حفظ می‌کنه (نه از صفر شروع کنه).
    """
    # ---- قرنطینه، سقفِ فعالیتِ روزانه و دوره‌یِ گرم‌کردن ----
    # اکانتِ فریزشده، اکانتِ توی قرنطینه‌یِ ساعت‌هایِ اول، و اکانتی که امروز به سقفش
    # رسیده اصلاً وارد این سفارش نمی‌شن. همه‌ی سفارش‌هایِ *دستیِ* بازدید/ری‌اکشن از
    # همین‌جا رد می‌شن؛ حلقه‌هایِ خودکار هم دقیقاً همین قوانین رو - از طریقِ همون
    # ماژولِ activity_guard - جداگانه اعمال می‌کنن.
    original_count = len(run_accounts)
    # «کلِ سفارش» = چیزی که کاربر خواسته، نه چیزی که بعدِ فیلترها باقی مونده.
    target_total = max(int(requested_total or 0), 0) or original_count
    holds: dict = {}
    dropped: list = []
    guard_settings: dict = {}
    usage = None
    try:
        classified = await _classify_order_accounts(run_accounts)
        run_accounts = classified["allowed"]
        dropped = classified["dropped"]
        holds = dict(classified["holds"])
        guard_settings = classified["settings"]
        usage = classified["usage"]
    except Exception:
        # خطا هیچ‌وقت نباید جلویِ خودِ سفارش رو بگیره
        holds, dropped = {}, []

    # ---- جانشین‌گیری: جایِ هر اکانتِ کنارگذاشته‌شده، یه اکانتِ آماده‌یِ دیگه می‌آد ----
    # این دقیقاً همون جاییه که سفارش آب می‌رفت: قبلاً هر اکانتی که کنار گذاشته می‌شد،
    # یه ری‌اکشن/بازدیدِ سفارشِ مشتری رو هم با خودش می‌بُرد - حتی وقتی ده‌ها اکانتِ
    # آزادِ دیگه توی استخر بود.
    if dropped and substitutes:
        try:
            used_ids = {a.get("id") for a in run_accounts}
            spare_pool = [a for a in substitutes if a.get("id") not in used_ids]
            pick = await react_order.pick_ready(
                spare_pool, len(dropped), settings=guard_settings or None, usage=usage)
            for (item, reason), sub in zip(dropped, pick["chosen"]):
                merged = dict(sub)
                for carry in ("assigned_reaction", "assigned_link"):
                    if carry in item:
                        merged[carry] = item[carry]
                run_accounts.append(merged)
                holds[reason] = max(0, holds.get(reason, 0) - 1)
            holds = {k: v for k, v in holds.items() if v}
        except Exception:
            pass

    shortfall = max(target_total - len(run_accounts), 0)
    unfilled_note = (react_order.order_shortfall_note(target_total, len(run_accounts), holds)
                     if shortfall else None)

    if holds and run_accounts:
        try:
            note = ("🛡 " + react_order.holds_summary(holds) +
                    " - برایِ کاهشِ ریسکِ دیلیت‌شدن، این دور کنار گذاشته شدن.\n"
                    f"با {len(run_accounts)} اکانت از {target_total} تا ادامه می‌دیم.")
            if shortfall:
                note += f"\n⚠️ {shortfall} تا از سفارش اکانتِ آماده نداشت و ثبت نمی‌شه."
            hint = react_order.holds_hint(holds)
            if hint:
                note += "\n" + hint
            await message.reply_text(note)
        except Exception:
            pass

    if not run_accounts:
        # دلیلِ دقیق رو می‌گیم، نه یه پیامِ کلی - چون هر دلیل راهِ‌حلِ کاملاً
        # متفاوتی داره (یکی «فردا بیا»، اون یکی «چند دقیقه صبر کن»)
        quarantined_count = holds.get("quarantine", 0)
        if quarantined_count and len(holds) == 1:
            reason = (
                f"🧪 همه‌ی {quarantined_count} اکانتِ انتخاب‌شده هنوز توی قرنطینه‌یِ "
                "ساعت‌هایِ اولِ اضافه‌شدنن، پس این سفارش اجرا نشد.\n\n"
                "چند ساعتِ دیگه خودشون آزاد می‌شن. اگه عجله داری، از «🎭 رفتارِ "
                "اکانت‌ها ← 🧪 قرنطینه‌یِ سشنِ تازه» می‌تونی مدتش رو کم کنی یا "
                "خاموشش کنی - ولی بدون که کارگرفتن از سشنِ تازه، ریسکِ دیلیت‌شدنش "
                "رو زیاد می‌کنه."
            )
        else:
            summary = react_order.holds_summary(holds) or "هیچ اکانتِ آماده‌ای نبود"
            reason = ("🛡 این سفارش اجرا نشد - " + summary + ".\n\n" +
                      (react_order.holds_hint(holds) or
                       "می‌تونی بعداً دوباره امتحان کنی، یا از «🎭 رفتارِ اکانت‌ها» "
                       "محدودیت‌ها رو تغییر بدی/خاموش کنی."))
        try:
            await message.reply_text(reason)
        except Exception:
            pass
        return

    # شمارنده‌یِ فعالیت رو دورِ خودِ action_fn می‌پیچیم - این‌طوری هر عملیاتی که
    # واقعاً اجرا بشه شمرده می‌شه، بدونِ اینکه هیچ‌کدوم از صداکننده‌ها لازم باشه
    # چیزی رو تغییر بدن.
    _inner_action_fn = action_fn

    async def action_fn(acc):
        # ⚠️ اینجا یه نبودِ مهم رفع شد: سفارشِ دستی فقط شمارنده‌یِ *روزانه* رو زیاد
        # می‌کرد و لایه‌یِ ضرب‌آهنگ/سقفِ ساعتی (activity_guard.mark_used) رو هیچ‌وقت
        # مهر نمی‌زد. یعنی ده سفارشِ پشتِ‌سرِهم می‌تونستن همون یه اکانت رو بی‌فاصله
        # بکوبن (ریسکِ فریز)، ولی همون اکانت به‌خاطرِ مهرهایِ حلقه‌هایِ *خودکار* از
        # سفارش‌ها کنار گذاشته می‌شد - یه بی‌تقارنیِ کامل.
        activity_guard.mark_used(acc.get("id"), weight=activity_weight,
                                 acc=acc, settings=guard_settings or None)
        result = await _inner_action_fn(acc)
        # کاری که عمداً انجام نشد (مثلاً پستِ پاک‌شده) سهمیه‌یِ روزانه مصرف نمی‌کنه
        if not isinstance(result, dict) or result.get("status") not in ("deleted", "skipped"):
            await increment_account_activity(acc.get("id"), _tehran_day_key())
        return result

    n = len(run_accounts)
    cancel_event = asyncio.Event()
    admin_chat_id = getattr(message, "chat_id", None) or getattr(getattr(message, "chat", None), "id", None)
    progress_seed = progress_seed or {}

    if random_range:
        min_h, max_h = random_range
        # معنایِ درستِ «بازه‌ی رندومِ min تا max ساعت»: کلِ اجرا داخلِ پنجره‌یِ
        # [min, max] پخش می‌شه - یعنی **هیچ‌چیز زودتر از min ساعت اجرا نمی‌شه** و
        # آخرینش هم دیرتر از max نیست. (قبلاً اشتباهاً یه مدتِ کلیِ رندوم بینِ min و max
        # انتخاب می‌شد و از همون لحظه‌ی صفر پخش می‌شد - برایِ همین اولین ری‌اکشن درجا
        # زده می‌شد.) این دقیقاً همون منطقِ auto_react._build_schedule‌ه.
        start_offset_minutes = progress_seed.get("start_offset_minutes")
        if start_offset_minutes is None:
            start_offset_minutes = min_h * 60
        total_minutes = progress_seed.get("total_minutes")
        if total_minutes is None:
            total_minutes = max(max_h - min_h, 0) * 60
        progress_title = (
            f"{op_label}\n🎲 بازه‌ی رندوم: {min_h:g} تا {max_h:g} ساعت "
            f"(اولین اجرا بعدِ {_minutes_label(round(start_offset_minutes))}، "
            f"آخرین تا {_minutes_label(round(start_offset_minutes + total_minutes))})"
        )
        progress = BatchProgress(
            progress_seed.get("total", target_total), progress_title,
            expected_duration_seconds=(start_offset_minutes + total_minutes) * 60,
            job_id=progress_seed.get("job_id"), done=progress_seed.get("done", 0),
            success=progress_seed.get("success", 0), fail=progress_seed.get("fail", 0),
            start_time=progress_seed.get("start_time"),
        )
        if shortfall:
            progress.note_unfilled(shortfall, unfilled_note)
        sent = await message.reply_text(progress.format(), reply_markup=_job_refresh_keyboard(progress.id))
        RUNNING_JOBS[progress.id] = progress
        register_batch(progress, admin_id, cancel_event, kind)
        if not progress_seed:
            await _persist_new_batch_job(
                progress, admin_id, kind, resume_kind=resume_kind, resume_payload=resume_payload,
                admin_chat_id=admin_chat_id, mode="random",
                total_minutes=start_offset_minutes + total_minutes,
                account_ids_ordered=[a["id"] for a in run_accounts if a.get("id") is not None],
            )
        asyncio.create_task(_progress_ticker(sent, progress))

        async def _report(success, fail, fail_details):
            report = format_bulk_report(success, fail, fail_details, title_random, progress=progress)
            await sent.edit_text(report, reply_markup=BACK_TO_MAIN_KB)

        asyncio.create_task(run_random_batch(
            run_accounts, action_fn, total_minutes, _report, progress=progress, cancel_event=cancel_event,
            on_before_account=_make_on_before_account(progress.id),
            start_offset_minutes=start_offset_minutes,
            action_timeout=action_timeout, guard_fn=guard_fn,
        ))
        return

    if minutes > 0:
        progress_title = f"{op_label}\n🕐 زمان‌بندی‌شده - طیِ {_minutes_label(minutes)}"
        progress = BatchProgress(
            progress_seed.get("total", target_total), progress_title, expected_duration_seconds=minutes * 60,
            job_id=progress_seed.get("job_id"), done=progress_seed.get("done", 0),
            success=progress_seed.get("success", 0), fail=progress_seed.get("fail", 0),
            start_time=progress_seed.get("start_time"),
        )
    else:
        progress_title = f"{op_label}\n⚡ فوری"
        progress = BatchProgress(
            progress_seed.get("total", target_total), progress_title, expected_duration_seconds=None,
            job_id=progress_seed.get("job_id"), done=progress_seed.get("done", 0),
            success=progress_seed.get("success", 0), fail=progress_seed.get("fail", 0),
            start_time=progress_seed.get("start_time"),
        )

    if shortfall:
        progress.note_unfilled(shortfall, unfilled_note)
    sent = await message.reply_text(progress.format(), reply_markup=_job_refresh_keyboard(progress.id))
    RUNNING_JOBS[progress.id] = progress
    register_batch(progress, admin_id, cancel_event, kind)
    if not progress_seed:
        await _persist_new_batch_job(
            progress, admin_id, kind, resume_kind=resume_kind, resume_payload=resume_payload,
            admin_chat_id=admin_chat_id, mode=("scheduled" if minutes > 0 else "immediate"),
            total_minutes=(minutes if minutes > 0 else None),
            account_ids_ordered=[a["id"] for a in run_accounts if a.get("id") is not None],
        )
    asyncio.create_task(_progress_ticker(sent, progress))

    async def _report(success, fail, fail_details):
        title = title_scheduled if minutes > 0 else title_immediate
        report = format_bulk_report(success, fail, fail_details, title, progress=progress)
        await sent.edit_text(report, reply_markup=BACK_TO_MAIN_KB)

    asyncio.create_task(run_scheduled_batch(
        run_accounts, action_fn, minutes, _report, progress=progress, cancel_event=cancel_event,
        on_before_account=_make_on_before_account(progress.id),
        action_timeout=action_timeout, max_parallel=max_parallel, gap_range=gap_range,
        guard_fn=guard_fn,
    ))


async def _run_view_batch(message, context, minutes: int = 0, random_range=None, admin_id: str = None):
    """اجرایِ بازدیدِ یک‌باره (فوری / پخش‌شده‌ی مساوی بر اساسِ minutes / کاملاً رندوم بر اساسِ random_range)"""
    link_info = context.user_data.pop("pending_view_link", None)
    pool_ids = context.user_data.get("bulk_pool", [])
    count = context.user_data.get("bulk_count", 0)
    chosen_ids = random.sample(pool_ids, count) if count < len(pool_ids) else pool_ids
    accounts = [await get_account(aid) for aid in chosen_ids]
    run_accounts = [a for a in accounts if a]

    # طبقِ خواسته: تفکیکِ Followers/Other رو خودِ تلگرام بر اساسِ عضویتِ *واقعیِ* هر
    # اکانتِ خاص تعیین می‌کنه - نه یه انتخابِ یکسان («مثلِ فالوور بشه یا نه؟») برایِ کلِ
    # سفارش. پس برایِ هر اکانت جدا چک می‌کنیم که واقعاً عضوِ این کاناله یا نه، و طبقش
    # تصمیم می‌گیریم که مثلِ یه فالوورِ واقعی رفتار کنه (تاریخچه رو بخونه، بعد بازدید
    # بزنه) یا فقط ساده بازدید بزنه. اگه واقعاً عضو نباشه، همیشه به‌عنوانِ «other» ثبت
    # می‌شه - هیچ راهی برایِ تقلبی «follower» نشون‌دادنِ یه غیرعضو وجود نداره.
    #
    # ⚠️ باگی که این‌جا حل شده: قبلاً این چک برایِ *همه‌ی* اکانت‌ها این‌جا، یکی‌یکی و
    # با await مستقیم (نه توی یه تسکِ پس‌زمینه‌ای)، *قبلِ* لانچِ سفارش انجام می‌شد.
    # چون ربات آپدیت‌ها رو سریالی پردازش می‌کنه، برایِ چند صدتا اکانت این یعنی کلِ
    # ربات تا چند دقیقه (یا بیشتر) کاملاً قفل می‌شد - و کاربر هیچ پیامِ آمارِ زنده‌ای
    # هم نمی‌دید، چون _launch_batch اصلاً هنوز صدا زده نشده بود. حالا این چک به داخلِ
    # action_fn منتقل شده: دقیقاً همون‌جایی که خودِ بازدید هم اتفاق می‌افته - یعنی
    # توی تسکِ پس‌زمینه‌ایِ run_scheduled_batch/run_random_batch (که _launch_batch
    # با asyncio.create_task راه می‌ندازه)، با فاصله‌یِ طبیعیِ همیشگی بینِ اکانت‌ها.
    # نتیجه: ربات بلافاصله پیامِ آمارِ زنده (با دکمه‌یِ «🔄 آپدیتِ آمار» و «❌ لغوِ
    # سفارش» - نگاه کن به _job_refresh_keyboard) رو نشون می‌ده و کاملاً در دسترس
    # می‌مونه، درست مثلِ «🩺 بررسیِ سلامتِ اکانت‌ها».
    async def action_fn(acc):
        membership = await check_channel_membership(
            acc["session_file"],
            channel_username=link_info.get("username") if link_info else None,
            is_private=bool(link_info.get("is_private")) if link_info else False,
            entity_id=link_info.get("channel_id") if link_info else None,
        )
        as_follower = membership.get("status") == "member"
        return await view_post(acc["session_file"], link_info, as_follower=as_follower)

    await _launch_batch(
        message, run_accounts, action_fn,
        minutes, random_range,
        op_label="👁 بازدید",
        title_immediate="👁 نتیجه‌ی بازدید",
        title_scheduled="👁 نتیجه‌ی بازدیدِ زمان‌بندی‌شده",
        title_random="👁 نتیجه‌ی بازدیدِ رندوم",
        admin_id=admin_id,
        kind="view",
        resume_kind="view",
        resume_payload={"link": link_info},
    )



async def _react_live_pool(pool_ids: list) -> list:
    """
    اکانت‌هایِ این سفارش، **همین لحظه** از دیتابیس - نه عکسی که موقعِ شروعِ ویزارد
    گرفته شده بود.

    ⚠️ چرا مهمه: بینِ «چند اکانت ری‌اکشن بزنن؟» و لحظه‌ی اجرا، ممکنه چند دقیقه
    گذشته باشه (انتخابِ ری‌اکشن‌ها، تقسیمِ تعداد، فرستادنِ لینک، انتخابِ زمان‌بندی).
    قبلاً لیستِ همون لحظه‌ی اول استفاده می‌شد و بدونِ هیچ چکی به react_to_post
    می‌رفت - یعنی اکانتی که وسطِ راه لاگ‌اوت یا فریز شده بود، یه ری‌اکشنِ سفارش رو
    با یه خطا می‌سوزوند.
    """
    accounts = []
    for account_id in pool_ids or []:
        try:
            acc = await get_account(account_id)
        except Exception:
            acc = None
        if acc and activity_guard.is_usable(acc):
            accounts.append(acc)
    return accounts


def _make_post_guard(accounts: list) -> react_order.PostLivenessGuard:
    """
    پاسبانِ «پست پاک نشده باشه» برایِ سفارش‌هایِ یک‌باره.

    ⚠️ این بخش کاملاً غایب بود: «ری‌اکشنِ خودکار» پاسبانِ پستِ پاک‌شده داشت، ولی
    سفارشِ دستی نه. سفارشِ زمان‌بندی‌شده‌یِ چندساعته بعدِ پاک‌شدنِ پست، تا آخرین
    اکانت ادامه می‌داد و همه‌ی سهمیه رو رویِ یه پیامِ ناموجود خرج می‌کرد (و همه‌شون
    هم «ناموفق» ثبت می‌شدن، پس به‌نظر می‌رسید اکانت‌ها خراب‌ان).

    چکش فقط-خواندنیه (check_posts_exist) و با کش، پس هزینه‌ی شبکه‌ش ناچیزه.
    """
    sessions = [a["session_file"] for a in accounts if a.get("session_file")]

    def _pick_session():
        return random.choice(sessions) if sessions else None

    return react_order.PostLivenessGuard(check_posts_exist, _pick_session)


def _post_deleted_message(link_info: dict) -> str:
    where = (link_info or {}).get("url") or "این پست"
    return ("⛔ این پست الان در کانال وجود نداره (پاک شده) - پس هیچ ری‌اکشنی براش ثبت "
            f"نشد و هیچ اکانتی خرج نشد.\n{where}\n\n"
            "اگه پست رو دوباره فرستادی، لینکِ جدیدش رو بده.")


async def _run_react_batch(message, context, minutes: int = 0, random_range=None, admin_id: str = None):
    """
    اجرایِ ری‌اکشنِ یک‌باره (فوری / پخش‌شده‌ی مساوی بر اساسِ minutes / کاملاً رندوم
    بر اساسِ random_range).

    سه چیزی که این‌جا اصلاح شد (همون «بخشِ ری‌اکشن مشکل داره»):
      ۱) اکانت‌ها *بعد از* چکِ آمادگی شمرده می‌شن، نه قبلش: قبلاً به‌اندازه‌یِ سفارش
         اکانت رندوم انتخاب می‌شد و بعد هرکدوم که آماده نبود بی‌صدا حذف می‌شد - پس
         سفارشِ ۷تایی با ۳ اکانت اجرا می‌شد و کارت «۱۰۰٪ (۳/۳)» نشون می‌داد. حالا
         اول اکانتِ آماده انتخاب می‌شه (از کلِ استخر، با جانشین‌گیری) و اگه بازم کم
         بود، همون کمبود صریحاً به کاربر و به کارتِ آمار گفته می‌شه.
      ۲) پستِ پاک‌شده: قبل از شروع چک می‌شه، و وسطِ سفارش هم پاسبان مراقبه.
      ۳) لینکِ گم‌شده دیگه باعثِ یه سفارشِ کاملاً ناموفق نمی‌شه.
    """
    # ⚠️ عمداً get و نه pop: اگه این سفارش قبل از شروع رد بشه (پستِ پاک‌شده، اکانتِ
    # ناکافی)، لینک باید سرِ جاش بمونه تا کاربر بتونه دوباره امتحان کنه.
    link_info = context.user_data.get("pending_react_link")
    if not link_info:
        await message.reply_text(
            "❌ لینکِ پستِ این سفارش پیدا نشد (احتمالاً منقضی شده) - از «👍 ری‌اکشن» "
            "دوباره شروع کن."
        )
        return

    pool_ids = context.user_data.get("bulk_pool", [])
    reactions_map = context.user_data.get("bulk_reactions_map")
    if reactions_map:
        requested_counts = {r: int(c) for r, c in reactions_map.items() if int(c or 0) > 0}
    else:
        # حالتِ قدیمی: همه با یه ری‌اکشنِ یکسان
        requested_counts = {
            context.user_data.get("bulk_reaction", "👍"):
                int(context.user_data.get("bulk_count", 0) or 0)
        }
    requested_total = sum(requested_counts.values())
    if requested_total <= 0:
        await message.reply_text("❌ تعدادِ این سفارش مشخص نیست - از اول امتحان کن.")
        return

    live = await _react_live_pool(pool_ids)
    if not live:
        await message.reply_text(
            "❌ هیچ‌کدوم از اکانت‌هایِ این سفارش الان فعال نیستن (لاگین نیستن یا فریز "
            "شدن) - از «📱 اکانت‌ها ← 🩺 بررسیِ سلامتِ اکانت‌ها» چکشون کن."
        )
        return

    # ---- پاسبانِ پستِ پاک‌شده: قبل از خرج‌کردنِ حتی یک اکانت ----
    guard = _make_post_guard(live)
    alive, _why = await guard.preflight(link_info)
    if not alive:
        await message.reply_text(_post_deleted_message(link_info))
        return

    # ---- انتخابِ اکانتِ *واقعاً آماده* به‌اندازه‌ی سفارش ----
    pick = await react_order.pick_ready(live, requested_total)
    ready, spare, holds = pick["chosen"], pick["spare"], pick["holds"]
    counts = react_order.shrink_counts(requested_counts, len(ready))
    run_accounts = react_order.assign_reactions(ready, counts, link_info=link_info)

    if not run_accounts:
        note = react_order.order_shortfall_note(requested_total, 0, holds)
        await message.reply_text(
            "🛡 این سفارش اجرا نشد - هیچ اکانتِ آماده‌ای براش نبود.\n\n" + (note or "")
        )
        return

    # از این‌جا به بعد سفارش واقعاً شروع می‌شه، پس حالا حالتِ ویزارد پاک می‌شه
    context.user_data.pop("pending_react_link", None)
    context.user_data.pop("bulk_reactions_map", None)

    async def action_fn(item):
        link = item.get("assigned_link") or link_info
        # پاسبان: اگه پست پاک شده، هیچ درخواستی به تلگرام نمی‌ره
        ok, reason = await guard.is_live(link)
        if not ok:
            guard.note_skipped()
            return {"status": "deleted", "message": reason or "پست از کانال پاک شده"}
        result = await react_to_post(item["session_file"], link, item["assigned_reaction"])
        if isinstance(result, dict) and result.get("status") == "deleted":
            # سرنخ از خودِ تلگرام - حکمِ نهایی رو چکِ بعدیِ پاسبان می‌ده
            guard.note_hint(link)
        return result

    async def guard_fn():
        return await guard.is_live(link_info)

    # برچسبِ سفارش همیشه از *خواسته‌یِ کاربر* ساخته می‌شه، نه از تعدادی که اجرا شد -
    # تا کارتِ آمار با سفارش جور باشه و کمبود هم به‌جایِ پنهان‌شدن، دیده بشه.
    reaction_label = " ".join(f"{r}×{c}" for r, c in requested_counts.items())
    if len(requested_counts) == 1:
        only_reaction = next(iter(requested_counts))
        op_label = f"👍 ری‌اکشنِ {reaction_label}"
        title_immediate = f"👍 نتیجه‌ی ری‌اکشنِ {only_reaction}"
        title_scheduled = f"👍 نتیجه‌ی ری‌اکشنِ زمان‌بندی‌شده‌ی {only_reaction}"
        title_random = f"👍 نتیجه‌ی ری‌اکشنِ رندومِ {only_reaction}"
        resume_kind = "react_single"
        resume_payload = {"link": link_info, "reaction": only_reaction}
    else:
        op_label = f"👍 ری‌اکشن ({reaction_label})"
        title_immediate = f"👍 نتیجه‌ی ری‌اکشن ({reaction_label})"
        title_scheduled = f"👍 نتیجه‌ی ری‌اکشنِ زمان‌بندی‌شده ({reaction_label})"
        title_random = f"👍 نتیجه‌ی ری‌اکشنِ رندوم ({reaction_label})"
        resume_kind = "react_multi"
        resume_payload = {
            "link": link_info,
            "reactions_by_account": {
                str(a["id"]): a["assigned_reaction"]
                for a in run_accounts if a.get("id") is not None
            },
        }

    await _launch_batch(
        message, run_accounts, action_fn, minutes, random_range,
        op_label=op_label,
        title_immediate=title_immediate,
        title_scheduled=title_scheduled,
        title_random=title_random,
        admin_id=admin_id,
        kind="react",
        resume_kind=resume_kind,
        resume_payload=resume_payload,
        requested_total=requested_total,
        substitutes=spare,
        guard_fn=guard_fn,
    )


# ============================================================================
# ری‌اکشن چند پست - همون منطقِ رندومِ «ری‌اکشنِ خودکار» ولی برایِ چند پستِ فوروارد‌شده
# ----------------------------------------------------------------------------
# برایِ **هر پست به‌صورتِ مستقل**، هم مجموعِ کل (بینِ mpr_count_min و mpr_count_max) و
# هم تنوعِ نوع‌ها (بینِ mpr_variety_min و mpr_variety_max از میانِ نوع‌هایِ انتخابی) از نو
# رندوم می‌شن - دقیقاً با همون تابعِ auto_react._apply_variety که ری‌اکشنِ خودکار ازش
# استفاده می‌کنه، تا رندوم‌بودنش کاملاً یکی و دقیق باشه.
# ============================================================================

async def _show_mpr_summary(message, context):
    """بعدِ تکمیلِ کاملِ ویزارد (پست‌ها + بازه‌ی تعداد + نوع‌ها + بازه‌ی تنوع)، خلاصه رو
    نشون می‌ده و می‌پرسه فوری بخوره یا زمان‌بندی‌شده - دقیقاً همون الگویِ ری‌اکشنِ یک‌باره."""
    posts = context.user_data.get("mpr_posts", [])
    cmin = context.user_data.get("mpr_count_min")
    cmax = context.user_data.get("mpr_count_max")
    reactions_list = context.user_data.get("mpr_reactions_list", [])
    vmin = context.user_data.get("mpr_variety_min")
    vmax = context.user_data.get("mpr_variety_max")
    summary = (
        f"📋 خلاصه‌یِ ری‌اکشن چند پست\n\n"
        f"📌 تعدادِ پست‌ها: {len(posts)}\n"
        f"🔢 ری‌اکشن برایِ هر پست: بینِ {cmin} تا {cmax} (رندومِ مستقل برایِ هر پست)\n"
        f"😀 نوع‌هایِ انتخابی: {' '.join(reactions_list)}\n"
        f"🎲 تنوع: هر پست بینِ {vmin} تا {vmax} نوع از این {len(reactions_list)} تا (رندومِ مستقل برایِ هر پست)\n\n"
        "چطور ثبت بشه؟"
    )
    await message.reply_text(summary, reply_markup=timing_picker_keyboard("mprtiming_immediate", "mprtiming_scheduled"))


def _build_mpr_run_items(posts, reactions_list, count_min, count_max, variety_min, variety_max, pool):
    """
    برایِ هر پست به‌صورتِ کاملاً مستقل، یه مجموعِ رندوم (بینِ count_min و count_max، با
    سقفِ تعدادِ اکانت‌هایِ موجود) و یه تنوعِ رندوم (چند نوع از reactions_list، بینِ
    variety_min و variety_max) انتخاب می‌کنه، اون مجموع رو بینِ نوع‌هایِ انتخاب‌شده
    تقسیمِ رندومِ طبیعی می‌کنه (auto_react._apply_variety -> random_split)، و همون‌تعداد
    اکانتِ متمایز (بدونِ تکرار در همون پست - چون یه اکانت روی یه پست فقط یه ری‌اکشن
    می‌تونه بذاره) رو رندوم از پول انتخاب می‌کنه. اکانت‌ها بینِ پست‌هایِ مختلف می‌تونن
    تکرار بشن (طبیعیه - هرکدوم پستِ جداست).

    خروجی: (items, warning) - items لیستِ مسطحِ همه‌یِ پست‌ها باهم (برایِ اجرا به‌عنوانِ
    یه batchِ واحد، دقیقاً مثلِ حالتِ چند-ری‌اکشنیِ تک‌پستی)، warning یه پیامِ کوتاه اگه
    موجودیِ اکانت برایِ رسیدن به بازه‌ی خواسته‌شده کافی نبوده (وگرنه None).
    """
    placeholder_counts = {r: 0 for r in reactions_list}
    items = []
    capped = False
    for link_info in posts:
        total_wanted = random.randint(count_min, count_max)
        total = min(total_wanted, len(pool))
        if total < total_wanted:
            capped = True
        if total <= 0:
            continue
        assignment = _apply_variety(placeholder_counts, variety_min, variety_max, total, total)
        chosen_accounts = random.sample(pool, total)
        idx = 0
        for reaction, cnt in assignment.items():
            for acc in chosen_accounts[idx:idx + cnt]:
                items.append({
                    "id": acc["id"],
                    "session_file": acc["session_file"],
                    "assigned_link": link_info,
                    "assigned_reaction": reaction,
                })
            idx += cnt
    random.shuffle(items)  # ترتیبِ کلی هم قاطی بشه - نه اول همه‌ی ری‌اکشن‌هایِ پستِ ۱، بعد پستِ ۲
    warning = (
        f"⚠️ موجودیِ اکانتِ فعال ({len(pool)}) از بازه‌ی خواسته‌شده کمتر بود - برایِ بعضی "
        f"پست‌ها سقف همون {len(pool)} اکانت شد."
    ) if capped else None
    return items, warning


async def _launch_mpr_job(message, admin_id: str, context, minutes: int, random_range):
    """ساختِ لیستِ نهاییِ (اکانت+پست+ری‌اکشن) برایِ همه‌ی پست‌ها باهم و اجرا از طریقِ
    همون _launch_batchِ مشترک - آمارِ زنده، دکمه‌ی لغو و همه‌چی دقیقاً مثلِ بقیه‌ی سفارش‌ها.

    ⚠️ مثلِ «باز کردنِ ممبرِ کانال»، این سفارش توی batch_jobs ذخیره نمی‌شه - یعنی
    ازسرگیریِ خودکار بعدِ ری‌استارتِ سرور نداره."""
    posts = context.user_data.pop("mpr_posts", [])
    count_min = context.user_data.pop("mpr_count_min", 1)
    count_max = context.user_data.pop("mpr_count_max", 1)
    reactions_list = context.user_data.pop("mpr_reactions_list", [])
    variety_min = context.user_data.pop("mpr_variety_min", 1)
    variety_max = context.user_data.pop("mpr_variety_max", 1)
    context.user_data.pop("mpr_selected", None)

    if not posts or not reactions_list:
        await message.reply_text("❌ اطلاعاتِ این سفارش ناقصه یا منقضی شده - از اول امتحان کن.")
        return

    accounts = await get_all_accounts()
    # ⚠️ قبلاً فقط is_logged_in چک می‌شد، پس اکانتِ فریز/در-قرنطینه/به-سقف-رسیده هم
    # وارد محاسبه‌ی ظرفیت می‌شد و بعد در _launch_batch بی‌صدا حذف می‌شد - یعنی همون
    # آب‌رفتنِ سفارش، این‌بار برایِ چند پست.
    usable = [a for a in accounts if activity_guard.is_usable(a)]
    if not usable:
        await message.reply_text("❌ هیچ اکانتِ فعالی نیست")
        return
    pick = await react_order.pick_ready(usable, len(usable))
    pool, holds = pick["chosen"], pick["holds"]
    if not pool:
        await message.reply_text(
            "🛡 این سفارش اجرا نشد - " +
            (react_order.holds_summary(holds) or "هیچ اکانتِ آماده‌ای نبود") + ".\n" +
            (react_order.holds_hint(holds) or "")
        )
        return

    run_accounts, warning = _build_mpr_run_items(posts, reactions_list, count_min, count_max, variety_min, variety_max, pool)
    if not run_accounts:
        await message.reply_text("❌ با این تنظیمات هیچ ری‌اکشنی قابلِ ثبت نبود.")
        return

    if warning:
        await message.reply_text(warning)

    # پاسبانِ پستِ پاک‌شده - این‌جا برایِ *هر پست جداگانه*: پستی که وسطِ سفارش پاک
    # بشه، ری‌اکشنِ بعدی‌ش ثبت نمی‌شه، ولی بقیه‌ی پست‌ها سرِ جاشون ادامه می‌دن.
    guard = _make_post_guard(pool)

    async def action_fn(item):
        link = item["assigned_link"]
        ok, reason = await guard.is_live(link)
        if not ok:
            guard.note_skipped()
            return {"status": "deleted", "message": reason or "پست از کانال پاک شده"}
        result = await react_to_post(item["session_file"], link, item["assigned_reaction"])
        if isinstance(result, dict) and result.get("status") == "deleted":
            guard.note_hint(link)
        return result

    await _launch_batch(
        message, run_accounts, action_fn, minutes, random_range,
        op_label=f"📋 ری‌اکشن چند پست ({len(posts)} پست)",
        title_immediate="📋 نتیجه‌ی ری‌اکشن چند پست",
        title_scheduled="📋 نتیجه‌ی ری‌اکشن چند پستِ زمان‌بندی‌شده",
        title_random="📋 نتیجه‌ی ری‌اکشن چند پستِ رندوم",
        admin_id=admin_id,
        kind="react",
        requested_total=len(run_accounts),
    )


# ============================================================================
# باز کردنِ ممبرِ کانال - تأییدِ دسته‌ایِ درخواست‌هایِ عضویتِ درحالِ‌انتظار
# ----------------------------------------------------------------------------
# ادمین فقط یوزرنیمِ کانال رو می‌ده؛ ربات خودش می‌گرده تا اکانتی که توی اون کانال
# ادمینه رو پیدا کنه و با همون اکانت (نه لزوماً یه اکانتِ دیگه) کارو پیش می‌بره -
# دقیقاً همون اکانتی که در واقعیت باید این کار رو دستی انجام می‌داد.
# ============================================================================

# فاصله‌ی بینِ دو تأییدِ پشتِ‌سرِهم - عمداً از IMMEDIATE_GAPِ view/react جداست، چون اونا
# رو چندین اکانتِ مختلف پخش می‌کنن (فاصله‌ی هرکدوم بیشتر بی‌خطره)، ولی اینجا **یک** اکانت
# داره پشتِ‌سرِهم رویِ درخواست‌ها کلیک می‌کنه - باید به‌اندازه‌ی کافی سریع باشه که حجمِ
# بالا (ده‌ها هزارتا) در زمانِ معقولی تموم بشه، ولی نه اونقدر سریع که به‌نظرِ تلگرام
# اسکریپت‌مانند/مشکوک بیاد. رندوم‌بودنش هم برایِ همینه - نه فاصله‌ی ثابتِ ماشینی.
OPEN_REQUEST_GAP_MIN = 0.45
OPEN_REQUEST_GAP_MAX = 0.95


async def _approve_one_with_timeout(session_file: str, channel_username: str) -> dict:
    """مثلِ _run_action_with_timeout توی scheduling.py، ولی مخصوصِ همین یه عملیات - اگه
    یه تأیید بیش‌ازحد طول بکشه (مثلاً مشکلِ شبکه)، رد می‌شه و به بعدی می‌ره، به‌جایِ
    اینکه کلِ فرآیند برایِ همیشه معلق بمونه."""
    try:
        return await asyncio.wait_for(
            approve_next_join_request(session_file, channel_username),
            timeout=ACCOUNT_ACTION_TIMEOUT,
        )
    except asyncio.TimeoutError:
        return {"status": "error", "message": f"بیش از {ACCOUNT_ACTION_TIMEOUT} ثانیه طول کشید - رد شد"}


async def _run_open_requests_job(session_file: str, channel_username: str, target: int,
                                  progress: BatchProgress, cancel_event: asyncio.Event, report_cb):
    """
    حلقه‌ی اصلی: دقیقاً `target` تا درخواستِ عضویت رو یکی‌یکی (نه گروهی) تأیید می‌کنه -
    با یه فاصله‌ی کوتاهِ رندوم بینِ هرکدوم، دقیقاً مثلِ یه ادمینِ واقعی که پشتِ‌سرِهم
    رویِ دکمه‌ها کلیک می‌کنه (نه یه فراخوانیِ دسته‌ای/انبوه).

    اگه صف زودتر از رسیدن به target خالی بشه (یعنی دیگه درخواستِ درحالِ‌انتظاری نمونده)،
    همینجا با پیامِ روشن متوقف می‌شه - به‌جایِ اینکه بی‌خبر تا آخرِ target ادامه بده و
    فقط پشتِ‌سرِهم خطایِ «خالیه» جمع کنه.
    """
    success, fail = 0, 0
    fail_details = []
    ran_out = False

    while progress.done < target:
        if cancel_event.is_set():
            progress.cancelled = True
            break

        result = await _approve_one_with_timeout(session_file, channel_username)
        status = result.get("status")

        if status == "success":
            success += 1
            progress.record(True)
        elif status == "empty":
            ran_out = True
            progress.last_error = "دیگه درخواستِ درحالِ‌انتظاری برایِ این کانال نمونده - زودتر از هدف متوقف شد."
            break
        else:
            fail += 1
            msg = result.get("message", "خطا")
            fail_details.append(msg)
            progress.record(False, msg)

        if progress.done < target and not cancel_event.is_set() and not ran_out:
            await asyncio.sleep(random.uniform(OPEN_REQUEST_GAP_MIN, OPEN_REQUEST_GAP_MAX))

    progress.finished = True
    if report_cb:
        try:
            await report_cb(success, fail, fail_details, ran_out)
        except Exception:
            pass


async def _resolve_openreq_channel(message, context, admin_id: str, channel_ref):
    """
    وقتی کاربر کانال رو معرفی کرد (یوزرنیم/آیدیِ عددی/فوروارد)، این تابع مشترک:
    ۱) اکانتِ ادمینِ همون کانال رو پیدا می‌کنه (find_admin_account_for_channel)
    ۲) تعدادِ درخواست‌هایِ درحالِ‌انتظار رو می‌خونه
    ۳) گزینه‌یِ «همه» / «تعدادِ دلخواه» رو نشون می‌ده
    هم از on_text (متن/فوروارد‌شده‌یِ متنی) و هم از on_document (فوروارد‌شده‌یِ رسانه‌ای)
    صدا زده می‌شه - نگاه کن به awaiting == "openreq_channel" در هردو.
    """
    label = _channel_display(channel_ref)
    wait_msg = await message.reply_text(
        f"🔍 در حالِ پیدا کردنِ اکانتِ ادمین برایِ {label}...\n"
        "(بینِ اکانت‌هایِ ثبت‌شده می‌گرده - ممکنه چند ثانیه طول بکشه)"
    )
    accounts = await get_all_accounts()
    admin_result = await find_admin_account_for_channel(channel_ref, accounts)
    if admin_result["status"] != "success":
        await wait_msg.edit_text(f"❌ {admin_result['message']}")
        return
    found_acc = admin_result["account"]

    count_result = await get_channel_pending_requests_count(found_acc["session_file"], channel_ref)
    if count_result["status"] != "success":
        await wait_msg.edit_text(f"❌ خطا در خوندنِ تعدادِ درخواست‌ها: {count_result['message']}")
        return
    pending = count_result["pending"]
    if pending <= 0:
        await wait_msg.edit_text(f"ℹ️ {label} الان هیچ درخواستِ عضویتِ درحالِ‌انتظاری نداره.")
        return

    context.user_data["openreq_channel"] = channel_ref
    context.user_data["openreq_account_id"] = found_acc["id"]
    context.user_data["openreq_session_file"] = found_acc["session_file"]
    context.user_data["openreq_pending"] = pending

    acc_label = found_acc.get("nickname") or found_acc.get("phone")
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton(f"✅ همه ({pending})", callback_data="openreq_all")],
        [InlineKeyboardButton("🔢 تعدادِ دلخواه", callback_data="openreq_custom")],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="menu_main")],
    ])
    await wait_msg.edit_text(
        f"✅ اکانتِ ادمینِ {label} پیدا شد: {acc_label}\n"
        f"📊 تعدادِ درخواست‌هایِ درحالِ‌انتظار: {pending}\n\n"
        "چند تا از این درخواست‌ها تأیید بشن؟",
        reply_markup=kb,
    )


def _bulk_jl_prompt_text(action: str) -> str:
    label = "جوین" if action == "join" else "ترک"
    return (
        f"{label}ِ کانال\n\n"
        "کانال رو با یکی از این سه راه معرفی کن:\n"
        "۱) یوزرنیمِ عمومی: @channelname\n"
        "۲) آیدیِ عددیِ کانالِ خصوصی (مثلاً 1234567890 یا -1001234567890)\n"
        "۳) یا یه پست رو مستقیم از همون کانال فوروارد کن"
    )


MEMBERSHIP_CHECK_CONCURRENCY = int(os.getenv("MEMBERSHIP_CHECK_CONCURRENCY", "20"))


async def _start_bulk_membership_check(message, context, admin_id: str, action: str,
                                        channel_ref, display_name: str, invite_raw: str = None):
    """
    ادامه‌یِ فلوِ «➕ جوین کانال»/«➖ ترک کانال» بعدِ اینکه کانال معرفی شد (و اگه
    خصوصی+جوین بود، لینکِ دعوت هم گرفته شد): چکِ واقعیِ عضویتِ همه‌ی اکانت‌هایِ فعال،
    و اگه واقعاً نیاز بود، پرسیدنِ تعداد (ادامه‌ش awaiting == "bulk_smart_count" هست،
    که از قبل وجود داشت و دست‌نخورده می‌مونه).

    ردیفِ جدولِ channels (که join_channel/leave_channel بهش نیاز دارن) فقط *اگه واقعاً
    لازم شد* (یعنی eligible خالی نبود) ساخته/پیدا می‌شه - نه زودتر، تا کانال‌هایی که
    بی‌خودی چک شدن (و نیازی به جوین/ترک نبود) بی‌جهت ثبت نشن.
    """
    accounts = await get_all_accounts()
    pool = [a for a in accounts if a["is_logged_in"]]
    if not pool:
        await message.reply_text("هیچ اکانتِ فعالی نیست")
        return

    is_private = isinstance(channel_ref, int)
    entity_id = str(channel_ref) if is_private else None
    username = channel_ref if not is_private else None
    label = "جوین" if action == "join" else "ترک"

    wait_msg = await message.reply_text(
        f"🔎 در حالِ چکِ واقعیِ عضویتِ اکانت‌ها توی {display_name}... (۰/{len(pool)})"
    )

    # هر اکانت سشن/کلاینتِ کاملاً مستقلِ خودش رو داره - پس چکِ عضویتِ اکانت‌هایِ مختلف
    # هیچ تداخلی با هم ندارن و می‌تونن هم‌زمان اجرا بشن. قبلاً این حلقه یکی‌یکی
    # (کاملاً سریال) اجرا می‌شد که با تعدادِ زیادِ اکانت (مثلاً ۳۰۰+) خیلی کند بود.
    # با Semaphore، حداکثرِ MEMBERSHIP_CHECK_CONCURRENCY تا هم‌زمان اجرا می‌شن.
    members, non_members = [], []
    done = 0
    lock = asyncio.Lock()
    sem = asyncio.Semaphore(MEMBERSHIP_CHECK_CONCURRENCY)
    last_publish_at = 0.0

    async def _publish(force: bool = False):
        nonlocal last_publish_at
        now = time.monotonic()
        if not force and now - last_publish_at < 2.0:
            return
        last_publish_at = now
        try:
            await wait_msg.edit_text(
                f"🔎 در حالِ چکِ واقعیِ عضویتِ اکانت‌ها توی {display_name}... ({done}/{len(pool)})\n"
                f"✅ عضو: {len(members)}    ◽️ غیرعضو: {len(non_members)}"
            )
        except Exception:
            pass

    async def _check_one(acc):
        nonlocal done
        async with sem:
            try:
                res = await check_channel_membership(
                    acc["session_file"], channel_username=username,
                    is_private=is_private, entity_id=entity_id
                )
            except Exception:
                res = {"status": "error"}
        async with lock:
            done += 1
            if res["status"] == "member":
                members.append(acc["id"])
            else:
                # not_member / flood / error - همه رو محافظه‌کارانه «غیرعضو» حساب می‌کنیم؛
                # اگه واقعاً مشکلِ دیگه‌ای باشه، خودِ عملیاتِ جوین/ترک با خطایِ روشن جواب می‌ده
                non_members.append(acc["id"])
            is_last = done == len(pool)
        await _publish(force=is_last)

    await asyncio.gather(*(_check_one(acc) for acc in pool))

    eligible = non_members if action == "join" else members
    eligible_word = "غیرعضو" if action == "join" else "عضو"

    if not eligible:
        already = "قبلاً عضوِ همه‌شونی" if action == "join" else "توی هیچ‌کدومشون عضو نیستی"
        await wait_msg.edit_text(
            f"✅ نیازی به {label} نیست - {already}.\n"
            f"(کلِ اکانت‌هایِ فعال: {len(pool)}، عضو: {len(members)}، غیرعضو: {len(non_members)})"
        )
        return

    try:
        if is_private:
            if action == "join":
                res = await add_channel(invite_raw, display_name, admin_id)
                if res["status"] != "success":
                    existing = await get_channel_by_username(invite_raw)
                    if not existing:
                        await wait_msg.edit_text(f"❌ {res['message']}")
                        return
                    ch_id = existing["id"]
                else:
                    created = await get_channel_by_username(invite_raw)
                    ch_id = created["id"]
                await update_channel_entity(ch_id, str(channel_ref), None)
            else:
                ch_id = await create_private_channel_stub(channel_ref, display_name, admin_id)
        else:
            existing = await get_channel_by_username(username)
            if existing:
                ch_id = existing["id"]
            else:
                res = await add_channel(username, display_name, admin_id)
                if res["status"] != "success":
                    existing = await get_channel_by_username(username)
                    if not existing:
                        await wait_msg.edit_text(f"❌ {res['message']}")
                        return
                    ch_id = existing["id"]
                else:
                    created = await get_channel_by_username(username)
                    ch_id = created["id"]
    except Exception as e:
        await wait_msg.edit_text(f"❌ ثبتِ کانال شکست خورد: {e}")
        return

    context.user_data["bulk_channel_id"] = ch_id
    context.user_data["bulk_eligible"] = eligible
    context.user_data["bulk_action"] = action
    context.user_data["awaiting"] = "bulk_smart_count"
    await wait_msg.edit_text(
        f"🔎 نتیجه‌یِ چک برایِ {display_name}\n\n"
        f"👥 کلِ اکانت‌هایِ فعال: {len(pool)}\n"
        f"✅ عضو: {len(members)}\n"
        f"◽️ غیرعضو: {len(non_members)}\n\n"
        f"چند تا اکانتِ {eligible_word} {label} کنن؟ یه عدد بینِ ۱ تا {len(eligible)} بفرست:"
    )


async def _resolve_bulk_jl_forward(message, context, admin_id: str, origin) -> bool:
    """
    مشترک بینِ on_text/on_document/on_forwarded_media: پردازشِ فورواردشدنِ یه پست
    برایِ awaiting == "bulk_jl_channel". خروجی: True اگه واقعاً یه فورواردِ کانال بود
    (چه موفق چه با خطایِ مناسب جواب داده شده باشه)، False اگه اصلاً فوروارد نبود
    (تا caller بتونه پیامِ«این فوروارد نیست» رو خودش نشون بده).
    """
    if not isinstance(origin, MessageOriginChannel):
        return False

    chat = origin.chat
    if getattr(chat, "username", None):
        channel_ref = f"@{chat.username}"
        display_name = getattr(chat, "title", None) or channel_ref
    else:
        channel_ref = _extract_raw_channel_id(chat.id)
        display_name = getattr(chat, "title", None) or _channel_display(channel_ref)

    action = context.user_data.get("bulk_action", "join")
    is_private = isinstance(channel_ref, int)

    if is_private and action == "join":
        context.user_data["bulk_jl_channel_ref"] = channel_ref
        context.user_data["bulk_jl_display_name"] = display_name
        context.user_data["awaiting"] = "bulk_jl_invite"
        await message.reply_text(
            f"✅ {display_name} شناسایی شد.\n\n"
            "این کانال خصوصیه - برایِ جوین‌شدن، تلگرام به لینکِ دعوت نیاز داره (نه فقط "
            "آیدیِ عددی). لینکِ دعوتِ کانال رو بفرست (مثلِ t.me/+HASH یا t.me/joinchat/HASH):"
        )
        return True

    context.user_data.pop("awaiting", None)
    await _start_bulk_membership_check(message, context, admin_id, action, channel_ref, display_name)
    return True


async def _resolve_vad_channel(message, context, admin_id: str, channel_ref, display_name: str):
    """
    وقتی کاربر کانال رو برایِ «بازدیدِ تمامِ پست‌ها، روزانه» معرفی کرد: فقط چک می‌کنه
    حداقل یه اکانت بهش دسترسی داره (نه لزوماً ادمین - برایِ بازدید فقط resolveِ موفق
    کافیه)، بعد کشور(ها) رو می‌پرسه.
    """
    wait_msg = await message.reply_text(f"🔍 در حالِ بررسیِ دسترسی به {display_name}...")
    accounts = await get_all_accounts()
    result = await find_any_account_for_channel(channel_ref, [a for a in accounts if a["is_logged_in"]])
    if result["status"] != "success":
        await wait_msg.edit_text(f"❌ {result['message']}")
        return

    context.user_data["vad_channel_ref"] = channel_ref
    context.user_data["vad_display_name"] = display_name
    context.user_data["vad_is_private"] = isinstance(channel_ref, int)
    context.user_data["vad_selected_countries"] = set()

    countries = await get_country_counts()
    if not countries:
        await wait_msg.edit_text("هیچ اکانتِ فعالی با کشورِ مشخص نیست - اول چندتا اکانت لاگین کن.")
        return
    markup = build_multi_country_grid(
        countries, set(), "vadctoggle_", "vadcountry_confirm", "vadcountry_all", "vc_list"
    )
    await wait_msg.edit_text(
        f"✅ دسترسی به {display_name} تأیید شد.\n\n"
        "کشور(ها) رو انتخاب کن (چندتا می‌تونی تیک بزنی)، بعد تایید کن:",
        reply_markup=markup
    )


async def _start_open_requests_job(message, admin_id: str, channel_ref,
                                    session_file: str, target: int):
    """
    شروعِ سفارشِ «باز کردنِ ممبرِ کانال» - دقیقاً همون زیرساختِ آمارِ زنده‌یِ بقیه‌ی
    سفارش‌ها (BatchProgress + تیکرِ خودکار + دکمه‌ی آپدیت)، به‌علاوه‌ی دو دکمه‌ی جداگانه‌ی
    «⏹ توقف» و «❌ لغو» (نگاه کن به _open_requests_keyboard). channel_ref: یوزرنیم (str)
    یا شناسه‌ی عددیِ کانالِ خصوصی (int).

    ⚠️ برخلافِ بازدید/ری‌اکشن/جوین‌وترک، این سفارش توی batch_jobs ذخیره نمی‌شه - یعنی
    اگه سرور دقیقاً وسطِ این عملیات ری‌استارت بشه، ازسرگیریِ خودکار نداره (فقط با آخرین
    آمارِ نمایش‌داده‌شده متوقف می‌مونه). با توجه به حجمِ خیلی بالا و زمانِ طولانیِ ممکنِ
    این عملیات، اگه لازم شد می‌شه بعداً همون قابلیتِ ازسرگیری رو برایِ این هم اضافه کرد.
    """
    label = _channel_display(channel_ref)
    cancel_event = asyncio.Event()
    progress = BatchProgress(
        target, f"🔓 باز کردنِ ممبرِ کانال\n{label} - هدف: {target} تأیید",
        expected_duration_seconds=target * ((OPEN_REQUEST_GAP_MIN + OPEN_REQUEST_GAP_MAX) / 2),
    )
    sent = await message.reply_text(progress.format(), reply_markup=_open_requests_keyboard(progress.id))
    RUNNING_JOBS[progress.id] = progress
    register_batch(progress, admin_id, cancel_event, kind="open_requests")
    asyncio.create_task(_progress_ticker(sent, progress, keyboard_fn=_open_requests_keyboard))

    async def _report(success, fail, fail_details, ran_out):
        lines = [
            f"🔓 نتیجه‌ی باز کردنِ ممبرِ کانال - {label}",
            "",
            f"✅ تأییدشده: {success}",
            f"❌ ناموفق: {fail}",
        ]
        if ran_out:
            lines.append("\nℹ️ صفِ درخواست‌ها زودتر از رسیدن به هدف خالی شد.")
        if fail_details:
            shown = fail_details[:5]
            lines.append("\nجزئیاتِ خطاها:\n" + "\n".join(f"• {d}" for d in shown))
            if len(fail_details) > 5:
                lines.append(f"… و {len(fail_details) - 5} موردِ دیگه")
        await sent.edit_text("\n".join(lines), reply_markup=BACK_TO_MAIN_KB)

    asyncio.create_task(_run_open_requests_job(session_file, channel_ref, target, progress, cancel_event, _report))


# ============================================================================
# بخشِ کاملاً مستقل و جدا: «گرفتنِ کدِ ورودِ گوشی» برایِ اکانتِ از قبل ثبت‌شده در ربات
# ----------------------------------------------------------------------------
# کاربرد: وقتی می‌خوای یه اکانتی که از قبل توی ربات لاگینه رو همزمان توی گوشیِ خودت هم
# وارد کنی، تلگرام کدِ ورود رو (نه پیامک، بلکه) به‌صورتِ پیام از طرفِ خودِ تلگرام داخلِ
# همون اکانت می‌فرسته. چون این اکانت از طریقِ ربات لاگینه، ربات همون پیام رو می‌خونه و
# کد رو مستقیم برات می‌فرسته - بدونِ نیاز به پیامک یا دسترسیِ همزمان به چتِ گوشی.
# این بخش با متغیرها/توابعِ خودش کار می‌کنه (هیچ‌کدوم جایِ دیگه‌ای استفاده نمی‌شن) تا
# کاملاً مستقل بمونه و با هیچ بخشِ دیگه‌ای قاطی نشه.
# ============================================================================

LOGIN_CODE_WAIT_SECONDS = 120   # حداکثر چقدر منتظرِ رسیدنِ کد بمونه
LOGIN_CODE_POLL_INTERVAL = 1.5    # هر چند ثانیه یه‌بار چک کنه (کاهش داده شد: 3 → 1.5)

# رجیستریِ تسک‌هایِ در حالِ انتظار - کلید: account_id - برایِ اینکه بشه لغوش کرد یا
# اگه دوباره همون اکانت رو زدی، انتظارِ قبلی خودکار جایگزین بشه (نه اینکه قاطی بشن)
_LOGIN_CODE_WAITERS = {}


async def _wait_for_phone_login_code(chat_id: int, context: ContextTypes.DEFAULT_TYPE,
                                      account_id: int, session_file: str, baseline_id: int):
    """
    تسکِ مستقلی که در پس‌زمینه اجرا می‌شه (asyncio.create_task) و منتظرِ رسیدنِ کدِ ورودِ
    جدید می‌مونه - بدونِ اینکه چیزِ دیگه‌ای توی ربات رو بلاک کنه. به‌محضِ پیدا شدنِ کد (یا
    اتمامِ زمان یا لغو)، یه پیامِ جدید مستقیم به همون چت می‌فرسته.
    """
    try:
        elapsed = 0
        while elapsed < LOGIN_CODE_WAIT_SECONDS:
            await asyncio.sleep(LOGIN_CODE_POLL_INTERVAL)
            elapsed += LOGIN_CODE_POLL_INTERVAL
            try:
                code, raw = await check_for_login_code(session_file, baseline_id)
            except Exception as e:
                await context.bot.send_message(chat_id, f"❌ خطا در چکِ کد: {e}")
                return
            if code:
                await context.bot.send_message(
                    chat_id,
                    f"📲 کدِ ورود رسید:\n\n`{code}`\n\nهمینو توی گوشیت وارد کن.",
                    parse_mode="Markdown"
                )
                return
        await context.bot.send_message(
            chat_id,
            "⌛ تا ۲ دقیقه کدی نرسید - لغو شد.\n"
            "اگه هنوز نیاز داری، دوباره از «📲 گرفتنِ کدِ ورودِ گوشی» امتحان کن (فقط بعدِ "
            "اینکه واقعاً توی گوشیت درخواستِ کد داده باشی)."
        )
    except asyncio.CancelledError:
        pass
    finally:
        _LOGIN_CODE_WAITERS.pop(account_id, None)


def _login_code_cancel_keyboard(account_id: int):
    return InlineKeyboardMarkup([[InlineKeyboardButton("❌ لغوِ انتظار", callback_data=f"logincode_cancel_{account_id}")]])


# ============================================================================
# منطقِ مشترکِ «بررسیِ سلامت» و «پاکسازیِ اکانت‌هایِ خراب» - یه‌بار نوشته شده و از هم از
# دکمه‌ی شیشه‌ای (وقتی از داخلِ یه پیامِ دیگه صدا زده می‌شه) هم از کیبوردِ پایینِ صفحه
# (ورودیِ مستقیمِ کاربر) استفاده می‌شه - بدونِ کپی‌کردنِ کد.
# ============================================================================

class _EditTarget:
    """یه Message رو طوری می‌پیچه که رابطش (edit_message_text) شبیهِ CallbackQuery بشه."""
    def __init__(self, message):
        self.message = message

    async def edit_message_text(self, text, reply_markup=None):
        # ⚠️ باگی که این‌جا حل شده: قبلاً *هر* خطایی توی ویرایش باعث می‌شد یه پیامِ
        # کاملاً جدید فرستاده بشه. رایج‌ترین خطا هم «Message is not modified» بود -
        # که وقتی پیش میاد که متنِ جدید عیناً همون متنِ قبلیه (توی گزارشِ پیشرفت
        # مدام اتفاق می‌افته). نتیجه: به‌جایِ آپدیتِ همون پیام، ربات پشتِ‌هم پیامِ
        # تازه می‌فرستاد. حالا این حالت اصلاً خطا حساب نمی‌شه.
        try:
            self.message = await self.message.edit_text(text, reply_markup=reply_markup)
            return
        except Exception as e:
            if "not modified" in str(e).lower():
                return  # پیام از قبل همینه - کاری لازم نیست
            # فقط وقتی پیام واقعاً قابلِ ویرایش نیست (پاک شده / خیلی قدیمیه)
            # یه پیامِ جدید می‌سازیم و از این به بعد همون رو ویرایش می‌کنیم
            try:
                self.message = await self.message.reply_text(text, reply_markup=reply_markup)
            except Exception:
                pass


# ============================================================================
# «🩺 بررسیِ سلامتِ اکانت‌ها» - اجرایِ پس‌زمینه‌ای، موازی و قابلِ لغو
# ----------------------------------------------------------------------------
# سه تا مشکلِ نسخه‌ی قبلی که اینجا حل شده:
#   ۱) کاملاً سریالی بود (یه اکانت در لحظه) و چون داخلِ خودِ هندلرِ آپدیت اجرا می‌شد،
#      تا آخرِ کار کلِ ربات قفل می‌موند. الان به‌صورتِ asyncio task در پس‌زمینه و با
#      هم‌زمانیِ محدود اجرا می‌شه - ربات کاملاً در دسترس می‌مونه.
#   ۲) هیچ راهِ لغوی نداشت.
#   ۳) با «🔄 تعویضِ سشنِ قدیمی به سشنِ جدید» هماهنگ نبود؛ حالا check_account_alive
#      رویِ قفلِ مشترکِ هر سشن کار می‌کنه، پس اگه اکانتی همین الان در حالِ مهاجرته،
#      بررسی منتظر می‌مونه و بعد رویِ *سشنِ جدید* تست می‌گیره (نگاه کن به
#      telethon_handler.session_lock / bump_session_generation).
# ============================================================================

HEALTHCHECK_CONCURRENCY = int(os.getenv("HEALTHCHECK_CONCURRENCY", "8"))
HEALTHCHECK_PER_ACCOUNT_TIMEOUT = float(os.getenv("HEALTHCHECK_PER_ACCOUNT_TIMEOUT", "20"))
# دورِ دومِ تأییدی: هم‌زمانیِ کمتر (فشارِ کمتر رویِ کانکشن/دیتابیس) + یه مکثِ کوتاه
# قبلِ شروع، تا خطاهایِ لحظه‌ایِ دورِ اول (تایم‌اوت، قفلِ موقتِ SQLite، افتِ کوتاهِ
# شبکه) فرصتِ رفع‌شدن داشته باشن - نگاه کن به _run_healthcheck_job.
HEALTHCHECK_RETRY_CONCURRENCY = int(os.getenv("HEALTHCHECK_RETRY_CONCURRENCY", "4"))
HEALTHCHECK_RETRY_DELAY = float(os.getenv("HEALTHCHECK_RETRY_DELAY", "3"))

# جاب‌هایِ در حالِ اجرا - کلید: شناسه‌یِ کوتاهِ جاب (توی callback_data میاد)
_HEALTHCHECK_JOBS: Dict[str, dict] = {}

# نتیجه‌های خرابِ آخرین بررسی‌های سلامتِ زاپاس. موقعِ کلیک دوباره تست می‌شن تا
# یه خطای موقت باعثِ بازنشسته‌کردنِ زاپاس سالم نشه.
_SPARE_HEALTH_BROKEN: Dict[str, list] = {}


def _healthcheck_keyboard(job_id: str, finished: bool = False):
    if finished:
        return BACK_TO_MAIN_KB
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 آپدیتِ آمار", callback_data=f"acc_hc_refresh_{job_id}")],
        [InlineKeyboardButton("❌ لغوِ بررسی", callback_data=f"acc_hc_cancel_{job_id}")],
    ])


def _healthcheck_progress_text(state: dict) -> str:
    total = state["total"]
    done = state["done"]
    pct = int(done * 100 / total) if total else 0
    elapsed = int(time.monotonic() - state["started_at"])
    lines = [
        "🩺 بررسیِ سلامتِ اکانت‌ها",
        "",
        f"پیشرفت: {done}/{total}  ({pct}٪)",
        f"✅ سالم: {state['alive_count']}    ❌ خراب: {state['dead_count']}",
    ]
    if state.get("recheck_pending_count"):
        lines.append(f"🔁 منتظرِ تأییدِ دورِ دوم (خطایِ احتمالاً موقتی): {state['recheck_pending_count']}")
    if state.get("retry_total"):
        lines.append(f"🔁 دورِ دومِ تأییدی در حالِ اجرا: {state['retry_done']}/{state['retry_total']}")
    if state.get("skipped_count"):
        lines.append(f"⏭ بررسی‌نشده (مشغولِ تعویضِ سشن): {state['skipped_count']}")
    if state.get("waiting_migration"):
        lines.append(f"⏳ منتظرِ پایانِ تعویضِ سشن: {state['waiting_migration']}")
    lines.append(f"⏱ زمانِ سپری‌شده: {elapsed} ثانیه")
    if done and total > done:
        remaining = int((elapsed / done) * (total - done))
        lines.append(f"⏳ تخمینِ باقی‌مانده: حدودِ {remaining} ثانیه")
    lines += ["", "🔀 بررسی موازی انجام می‌شه و ربات همین الان هم قابلِ استفاده‌ست."]
    return "\n".join(lines)


def _healthcheck_final_text(state: dict) -> str:
    alive, dead = state["alive"], state["dead"]
    elapsed = int(time.monotonic() - state["started_at"])
    header = "🩺 نتیجه‌ی بررسیِ سلامتِ اکانت‌ها"
    if state.get("cancelled"):
        header = "🩺 بررسیِ سلامتِ اکانت‌ها - لغو شد"
    lines = [
        header,
        "",
        f"✅ سالم و آماده: {len(alive)}",
        f"❌ لاگین باطل شده: {len(dead)}",
    ]
    if state.get("recovered_count"):
        lines.append(
            f"🔁 {state['recovered_count']} اکانت توی بررسیِ اول خطایِ موقتی داد، ولی توی "
            "بررسیِ دومِ تأییدی سالم دراومد - به‌اشتباه «خراب» ثبت نشد."
        )
    # تفکیکِ نوعِ خرابی - تا معلوم باشه چندتاشون فریز، چندتا حذف‌شده و چندتا فقط
    # سشنشون باطل شده (که این آخری با لاگینِ دوباره قابلِ برگردوندنه)
    by_state = state.get("by_state") or {}
    if by_state:
        labels = [
            ("frozen", "🧊 فریز شده"),
            ("deleted", "🚮 حذف‌شده/غیرفعال"),
            ("restricted", "⚠️ محدود شده"),
            ("banned", "⛔ بن شده"),
            ("revoked", "🔑 سشن باطل شده"),
            ("invalid", "❓ سشنِ نامعتبر"),
            ("error", "❌ خطایِ دیگر"),
        ]
        parts = [f"{label}: {by_state[key]}" for key, label in labels if by_state.get(key)]
        if parts:
            lines += ["", "🔎 تفکیکِ اکانت‌هایِ خراب:"] + [f"   {p}" for p in parts]
    if state.get("rescued_count"):
        lines.append("")
        lines.append(f"♻️ با سشنِ زاپاس نجات پیدا کرد: {state['rescued_count']}")
        lines += [f"   • {r}" for r in (state.get("rescued") or [])[:10]]
        lines.append(
            "   سشنِ خرابشون با زاپاس جایگزین شد و «سالم» حساب شدن. زاپاسشون مصرف "
            "شده، پس دوباره توی «🧩 ساخت سشن زاپاس» در نوبتِ ساختِ زاپاسِ تازه‌ان "
            "(نگهبانِ خودکار هم خودش سراغشون می‌ره)."
        )
    if state.get("skipped"):
        lines.append(f"⏭ بررسی‌نشده (مشغولِ تعویضِ سشن): {len(state['skipped'])}")
    if state.get("cancelled"):
        not_checked = state["total"] - state["done"]
        lines.append(f"⏭ بررسی‌نشده: {not_checked}")
        lines.append("")
        lines.append(
            "به اکانت‌هایِ بررسی‌نشده هیچ دست نخورد - نه وضعیتشون توی دیتابیس عوض شد، "
            "نه اتصالی ازشون قطع شد."
        )
    lines.append(f"⏱ زمانِ کل: {elapsed} ثانیه")
    if state.get("migration_waits"):
        lines.append(
            f"🔄 {state['migration_waits']} اکانت وسطِ تعویضِ سشن بودن - "
            "بعد از پایانِ تعویض، رویِ سشنِ جدیدشون تست شدن."
        )
    if dead:
        lines += ["", "اکانت‌هایِ خراب (هرکدوم دو بارِ پشتِ‌سرِهم چک شده و هردو بار خراب بوده):"]
        items = state.get("dead_items") or []
        if items:
            # اسم + شماره + نامِ فایلِ سشن، تا دقیقاً معلوم باشه کدوم اکانته
            for item in items[:15]:
                acc = item["acc"]
                name = acc.get("nickname") or "بی‌نام"
                phone = acc.get("phone") or "بدونِ شماره"
                sess = os.path.basename(acc.get("session_file") or "") or "نامشخص"
                lines.append(f"❌ {name} ({phone})")
                lines.append(f"   دلیل: {item['reason']}")
                lines.append(f"   سشن: {sess}.session")
            if len(items) > 15:
                lines.append(f"… و {len(items) - 15} موردِ دیگه (همه‌شون توی زیپ هستن)")
        else:
            lines += [f"• {d}" for d in dead[:15]]
            if len(dead) > 15:
                lines.append(f"… و {len(dead) - 15} موردِ دیگه")
        lines += [
            "",
            "📦 فایلِ سشنِ همه‌ی این اکانت‌ها رو توی یه زیپ جدا برات می‌فرستم.",
            "⚠️ اگه ربات هم‌زمان روی لپ‌تاپ و سرور اجرا بشه، تلگرام سشن‌ها رو باطل می‌کنه - "
            "فقط یکی رو روشن نگه دار.",
        ]
    return "\n".join(lines)


async def run_account_healthcheck(editable):
    """
    شروعِ بررسیِ سلامت. خودِ کار توی یه task جداگانه اجرا می‌شه و این تابع بلافاصله
    برمی‌گرده - پس هندلرِ آپدیت آزاد می‌شه و ربات گیر نمی‌کنه.

    editable: یا CallbackQuery یا _EditTarget - هردو edit_message_text دارن
    """
    accounts = await get_all_accounts()
    if not accounts:
        await editable.edit_message_text("هیچ اکانتی ثبت نشده.", reply_markup=BACK_TO_MAIN_KB)
        return

    # اگه یه بررسی همین الان در جریانه، بررسیِ دوم راه نمی‌ندازیم - وگرنه دو تا
    # پیامِ گزارشِ جدا با آمارهایِ متفاوت هم‌زمان آپدیت می‌شن و کاربر گیج می‌شه
    running = next(
        (jid for jid, j in _HEALTHCHECK_JOBS.items() if not j["state"].get("finished")),
        None,
    )
    if running:
        await editable.edit_message_text(
            "🩺 یه بررسیِ سلامت همین الان در جریانه.\n\n"
            "آمارِ زنده‌ش رویِ همون پیامِ قبلی به‌روز می‌شه - از همون‌جا دنبالش کن. "
            "اگه می‌خوای از اول شروع کنی، اول با «❌ لغوِ بررسی» متوقفش کن.",
            reply_markup=BACK_TO_MAIN_KB,
        )
        return

    job_id = f"{int(time.time())}{random.randint(100, 999)}"
    state = {
        "total": len(accounts), "done": 0,
        "alive": [], "dead": [], "skipped": [],
        # اطلاعاتِ کاملِ اکانت‌هایِ خراب (نه فقط یه رشته‌یِ نمایشی) - برایِ گزارشِ
        # تفصیلی و ساختنِ زیپِ سشن‌هاشون در پایانِ کار
        "dead_items": [],
        # تفکیکِ نوعِ خرابی: frozen / deleted / restricted / revoked / banned / error
        "by_state": {},
        "alive_count": 0, "dead_count": 0, "skipped_count": 0,
        "waiting_migration": 0, "migration_waits": 0,
        # دورِ دومِ تأییدی برایِ اکانت‌هایِ خرابِ دورِ اول - نگاه کن به _run_healthcheck_job
        "recheck_pending_count": 0, "retry_total": 0, "retry_done": 0, "recovered_count": 0,
        "started_at": time.monotonic(), "cancelled": False, "finished": False,
        "last_publish_at": 0.0, "last_text": None,
    }
    cancel_event = asyncio.Event()
    _HEALTHCHECK_JOBS[job_id] = {"state": state, "cancel": cancel_event, "editable": editable}

    await editable.edit_message_text(
        _healthcheck_progress_text(state), reply_markup=_healthcheck_keyboard(job_id)
    )
    asyncio.create_task(_run_healthcheck_job(job_id, accounts))


async def _healthcheck_sync_login_status(acc, alive: bool):
    """فقط وقتی وضعیت واقعاً فرق کرده بنویس - نوشتنِ بی‌دلیل روی دیتابیس هم کنده هم
    قفلِ SQLite رو بی‌خود درگیر می‌کنه. مشترک بینِ بررسیِ سلامتِ گروهی و تکی."""
    if bool(acc.get("is_logged_in")) != alive:
        try:
            await update_account_login_status(acc["id"], alive)
        except Exception:
            pass


async def _run_healthcheck_job(job_id: str, accounts: list):
    job = _HEALTHCHECK_JOBS.get(job_id)
    if not job:
        return
    state, cancel_event, editable = job["state"], job["cancel"], job["editable"]
    lock = asyncio.Lock()
    sem = asyncio.Semaphore(HEALTHCHECK_CONCURRENCY)
    # اکانت‌هایی که توی دورِ اول «خراب» تشخیص داده شدن ولی هنوز قطعی نیست - چون خیلی
    # از خطاها (تایم‌اوتِ لحظه‌ای، قفلِ موقتِ SQLite به‌خاطرِ بررسیِ هم‌زمانِ چندتا
    # اکانت، افتِ کوتاهِ شبکه) واقعاً به‌معنیِ خرابیِ اکانت نیستن. بعدِ اتمامِ دورِ
    # اول، همین‌ها با هم‌زمانیِ کمتر یه‌بارِ دیگه چک می‌شن (پایینِ همین تابع) و فقط
    # اونایی که دومین بار هم خراب دربیان قطعی حساب می‌شن.
    pending_retry: list = []

    async def publish(force: bool = False):
        now = time.monotonic()
        if not force and now - state["last_publish_at"] < 3.0:
            return
        text = _healthcheck_progress_text(state)
        # اگه متن عیناً همونیه که آخرین بار فرستادیم، اصلاً تلگرام رو صدا نزن -
        # این‌طوری خطایِ «Message is not modified» از ریشه پیش نمیاد
        if text == state.get("last_text"):
            return
        state["last_publish_at"] = now
        state["last_text"] = text
        try:
            await editable.edit_message_text(
                text, reply_markup=_healthcheck_keyboard(job_id)
            )
        except Exception:
            pass

    async def _check_one(acc):
        # لغو = «هیچ اکانتِ جدیدی رو شروع نکن». اکانت‌هایِ شروع‌نشده اصلاً لمس نمی‌شن،
        # پس وضعیتشون توی دیتابیس هم دست‌نخورده می‌مونه.
        if cancel_event.is_set():
            return
        async with sem:
            if cancel_event.is_set():
                return
            was_migrating = is_session_migrating(acc["session_file"])
            if was_migrating:
                async with lock:
                    state["waiting_migration"] += 1
                await publish(force=True)
            try:
                result = await check_account_alive(
                    acc["session_file"], timeout=HEALTHCHECK_PER_ACCOUNT_TIMEOUT
                )
            except asyncio.CancelledError:
                raise
            except Exception as e:
                result = {"alive": False, "reason": f"{type(e).__name__}: {e}"}
            finally:
                if was_migrating:
                    async with lock:
                        state["waiting_migration"] -= 1
                        state["migration_waits"] += 1

            label = acc.get("nickname") or acc.get("phone")
            async with lock:
                if result.get("alive") is None:
                    # «نمی‌دونیم» - نه سالم حسابش می‌کنیم نه خراب، و دیتابیس رو هم
                    # دست نمی‌زنیم. تنها حالتی که اینجا میاد، سشنِ مشغولِ تعویضه.
                    state["skipped"].append(f"{label} — {result.get('reason', 'بررسی نشد')}")
                    state["skipped_count"] += 1
                    state["done"] += 1
                    await publish()
                    return
                if result["alive"]:
                    state["alive"].append(label)
                    state["alive_count"] += 1
                    state["done"] += 1
                else:
                    # هنوز قطعی نیست - می‌ذاریمش برایِ دورِ دومِ تأییدی (پایینِ همین تابع)
                    pending_retry.append((acc, result["reason"]))
                    state["recheck_pending_count"] = state.get("recheck_pending_count", 0) + 1
                    state["done"] += 1
            if result["alive"]:
                await _healthcheck_sync_login_status(acc, True)
            await publish()

    async def _retry_one(acc, first_reason, retry_sem):
        async def _mark_cancelled():
            async with lock:
                label = acc.get("nickname") or acc.get("phone")
                state["skipped"].append(
                    f"{label} — بررسیِ دومِ تأییدی لغو شد (نتیجه‌یِ دورِ اول: {first_reason})"
                )
                state["skipped_count"] += 1
                state["retry_done"] += 1

        if cancel_event.is_set():
            await _mark_cancelled()
            return
        async with retry_sem:
            if cancel_event.is_set():
                await _mark_cancelled()
                return
            try:
                result = await check_account_alive(
                    acc["session_file"], timeout=HEALTHCHECK_PER_ACCOUNT_TIMEOUT
                )
            except asyncio.CancelledError:
                raise
            except Exception as e:
                result = {"alive": False, "reason": f"{type(e).__name__}: {e}"}

            label = acc.get("nickname") or acc.get("phone")
            async with lock:
                state["retry_done"] += 1
                if result.get("alive") is None:
                    state["skipped"].append(f"{label} — {result.get('reason', 'بررسی نشد')}")
                    state["skipped_count"] += 1
                elif result["alive"]:
                    # دورِ اول خطایِ موقتی بود - این اکانت سالمه
                    state["alive"].append(label)
                    state["alive_count"] += 1
                    state["recovered_count"] = state.get("recovered_count", 0) + 1
                else:
                    # دو بار پشتِ‌سرِهم خراب دراومد - حالا قطعیه
                    state["dead"].append(f"{label} — {result['reason']}")
                    state["dead_items"].append({
                        "acc": acc, "reason": result["reason"],
                        # نوعِ خرابی این‌جا هم نگه داشته می‌شه تا اگه اکانتی با
                        # زاپاس نجات پیدا کرد، تفکیکِ گزارش درست بازسازی بشه
                        # (نگاه کن به _apply_spare_rescue_to_state)
                        "state": result.get("state") or "error",
                    })
                    state["dead_count"] += 1
                    # تفکیکِ نوعِ خرابی (فریز / حذف‌شده / باطل‌شده / ...) - نگاه کن به
                    # فیلدِ state در check_account_alive و _healthcheck_final_text
                    st = result.get("state") or "error"
                    state["by_state"][st] = state["by_state"].get(st, 0) + 1
            if result.get("alive") is not None:
                await _healthcheck_sync_login_status(acc, bool(result["alive"]))
            await publish(force=True)

    try:
        await asyncio.gather(*(_check_one(a) for a in accounts), return_exceptions=True)

        if pending_retry:
            state["retry_total"] = len(pending_retry)
            state["retry_done"] = 0
            state["recheck_pending_count"] = 0
            await publish(force=True)
            if cancel_event.is_set():
                # لغو شده - دورِ دوم اصلاً شروع نمی‌شه؛ اکانت‌هایِ در انتظار رو
                # «بررسی‌نشده» حساب کن، نه خراب (طبقِ همون قاعده‌یِ لغو: دست‌نخورده بمونن)
                for acc, reason in pending_retry:
                    label = acc.get("nickname") or acc.get("phone")
                    state["skipped"].append(
                        f"{label} — بررسیِ دومِ تأییدی لغو شد (نتیجه‌یِ دورِ اول: {reason})"
                    )
                    state["skipped_count"] += 1
                    state["retry_done"] += 1
            else:
                # یه مکثِ کوتاه قبلِ دورِ دوم، تا خطاهایِ لحظه‌ای (مثلاً یه قطعیِ کوتاهِ
                # شبکه) فرصتِ رفع‌شدن داشته باشن، بعد با هم‌زمانیِ کمتر (فشارِ کمتر رویِ
                # کانکشن/دیتابیس) دوباره چک می‌کنیم
                await asyncio.sleep(HEALTHCHECK_RETRY_DELAY)
                retry_sem = asyncio.Semaphore(HEALTHCHECK_RETRY_CONCURRENCY)
                await asyncio.gather(
                    *(_retry_one(acc, reason, retry_sem) for acc, reason in pending_retry),
                    return_exceptions=True,
                )

        # ---- آخرین مرحله: اکانتِ خرابی که سشنِ زاپاس داره، نجات داده می‌شه ----
        # کلِ دلیلِ وجودیِ زاپاس همین لحظه‌ست: تا وقتی زاپاسِ سالمی هست، هیچ اکانتی
        # نباید «خراب» گزارش بشه و رها بمونه. نگاه کن به
        # _rescue_dead_accounts_with_spare (همون تابعی که پاکسازی هم استفاده می‌کنه).
        if state.get("dead_items") and not cancel_event.is_set():
            try:
                await editable.edit_message_text(
                    f"♻️ {len(state['dead_items'])} اکانتِ خراب پیدا شد - "
                    "در حالِ تست و استفاده از سشن‌هایِ زاپاسشون..."
                )
            except Exception:
                pass
            try:
                rescued, still_dead = await _rescue_dead_accounts_with_spare(
                    state["dead_items"])
                _apply_spare_rescue_to_state(state, rescued, still_dead)
            except Exception as e:
                print(f"⚠️  نجات با زاپاس در بررسیِ سلامت انجام نشد: {e}")
    finally:
        state["finished"] = True
        _HEALTHCHECK_JOBS.pop(job_id, None)
        try:
            await editable.edit_message_text(
                _healthcheck_final_text(state), reply_markup=_healthcheck_keyboard(job_id, finished=True)
            )
        except Exception:
            pass
        # فایلِ سشن (و jsonِ) اکانت‌هایِ خراب رو جدا می‌فرستیم تا معلوم باشه دقیقاً
        # کدوم فایل‌ها مشکل دارن. شکستِ این کار نباید گزارشِ اصلی رو خراب کنه.
        try:
            await _send_broken_accounts_zip(editable, state.get("dead_items") or [])
        except Exception:
            pass


_REVOKED_SESSION_REASON_MARKERS = (
    "auth_key دیگه معتبر نیست",
    "این سشن از سمتِ اکانت بسته شده",
    "این سشن هم‌زمان جایِ دیگه‌ای استفاده شده",
)


def _is_revoked_session_reason(reason: str) -> bool:
    """
    آیا دلیلِ خرابیِ اکانت، از جنسِ «تلگرام auth_key رو باطل کرده» است؟ (نه یه
    خطایِ لحظه‌ایِ شبکه یا هر مشکلِ دیگه). دقیقاً همون سه دلیلی که
    check_account_alive برایِ AuthKeyUnregisteredError/SessionRevokedError/
    AuthKeyDuplicatedError برمی‌گردونه - نگاه کن به دکمه‌یِ «🔓 فعال‌سازی» در
    run_single_account_healthcheck.
    """
    reason = reason or ""
    return any(marker in reason for marker in _REVOKED_SESSION_REASON_MARKERS)


async def run_single_account_healthcheck(message, account: dict):
    """
    بررسیِ سلامتِ فقط *یک* اکانت - از صفحه‌یِ جزئیاتِ همون اکانت («🩺 بررسیِ سلامتِ این
    اکانت»). دقیقاً همون منطقِ دو-دوریِ بررسیِ سلامتِ گروهی رو داره (نگاه کن به
    _run_healthcheck_job): اگه بارِ اول خراب دراومد، فوراً قطعی حسابش نمی‌کنیم؛ بعدِ یه
    مکثِ کوتاه یه‌بارِ دیگه چک می‌کنیم و فقط اگه دومین بار هم خراب بود قطعی گزارشش
    می‌کنیم و دیتابیس رو آپدیت می‌کنیم - تا یه خطایِ لحظه‌ای (تایم‌اوت/افتِ شبکه) باعث
    نشه اکانتِ سالم به‌اشتباه «خراب» ثبت بشه.
    """
    name = account.get("nickname") or account.get("phone") or str(account.get("id"))
    status_msg = await message.reply_text(f"🩺 در حالِ بررسیِ سلامتِ «{name}»...")

    try:
        result = await check_account_alive(account["session_file"], timeout=HEALTHCHECK_PER_ACCOUNT_TIMEOUT)
    except Exception as e:
        result = {"alive": False, "reason": f"{type(e).__name__}: {e}"}

    if result.get("alive") is None:
        try:
            await status_msg.edit_text(
                f"⏳ الان نمی‌شه «{name}» رو چک کرد: {result.get('reason', 'سشن مشغولِ کارِ دیگه‌ایه')}\n"
                "چند لحظه‌ی دیگه دوباره امتحان کن."
            )
        except Exception:
            pass
        return

    if result["alive"]:
        await _healthcheck_sync_login_status(account, True)
        try:
            await status_msg.edit_text(f"✅ «{name}» سالم و آماده‌ست.")
        except Exception:
            pass
        return

    # بارِ اول خراب دراومد - هنوز قطعی نیست؛ بعدِ یه مکثِ کوتاه یه‌بارِ دیگه چک کن
    first_reason = result["reason"]
    try:
        await status_msg.edit_text(
            f"⚠️ «{name}» توی بررسیِ اول خطا داد: {first_reason}\n"
            "در حالِ تأییدِ دوباره (دورِ دوم) تا مطمئن بشیم موقتی نبوده..."
        )
    except Exception:
        pass

    await asyncio.sleep(HEALTHCHECK_RETRY_DELAY)
    try:
        result2 = await check_account_alive(account["session_file"], timeout=HEALTHCHECK_PER_ACCOUNT_TIMEOUT)
    except Exception as e:
        result2 = {"alive": False, "reason": f"{type(e).__name__}: {e}"}

    if result2.get("alive") is None:
        try:
            await status_msg.edit_text(
                f"⏳ دورِ دومِ تأییدی هم الان ممکن نشد: {result2.get('reason', 'سشن مشغولِ کارِ دیگه‌ایه')}\n"
                "چند لحظه‌ی دیگه دوباره امتحان کن."
            )
        except Exception:
            pass
        return

    if result2["alive"]:
        await _healthcheck_sync_login_status(account, True)
        try:
            await status_msg.edit_text(
                f"✅ «{name}» سالمه - توی بررسیِ اول خطایِ موقتی داد ({first_reason})، "
                "ولی توی دورِ دومِ تأییدی سالم دراومد."
            )
        except Exception:
            pass
        return

    # دو بار پشتِ‌سرِهم خراب دراومد - حالا قطعیه
    await _healthcheck_sync_login_status(account, False)
    final_text = (
        f"❌ «{name}» خراب تشخیص داده شد (دو بار پشتِ‌سرِهم تأیید شد).\n"
        f"دلیل: {result2['reason']}"
    )
    # توضیحِ کوتاهِ «یعنی چی» بر اساسِ نوعِ خرابی - تا معلوم باشه اصلاً قابلِ
    # برگردوندن هست یا نه (نگاه کن به فیلدِ state در check_account_alive)
    account_state = result2.get("state")
    if account_state == "frozen":
        final_text += (
            "\n\n🧊 این اکانت از سمتِ تلگرام فریز شده. فریز معمولاً موقتیه و با "
            "گذشتِ زمان یا اعتراض به پشتیبانیِ تلگرام برداشته می‌شه - از سمتِ ربات "
            "کاری براش نمی‌شه کرد."
        )
    elif account_state == "deleted":
        final_text += (
            "\n\n🚮 این اکانت حذف/غیرفعال شده. این حالت برگشت‌ناپذیره و اکانت دیگه "
            "قابلِ استفاده نیست - می‌تونی از «🗑 پاکسازیِ اکانت‌هایِ خراب» حذفش کنی."
        )
    elif account_state == "banned":
        final_text += "\n\n⛔ شماره‌یِ این اکانت توسطِ تلگرام بن شده و قابلِ برگردوندن نیست."
    elif account_state == "restricted":
        final_text += "\n\n⚠️ این اکانت محدود شده - بخشی از قابلیت‌هاش از سمتِ تلگرام بسته‌ست."

    reply_markup = None
    if _is_revoked_session_reason(result2["reason"]):
        # این دسته از دلایل («باطل شده»/«هم‌زمان جایِ دیگه استفاده شده») ممکنه
        # واقعاً یه باطلیِ همیشگیِ سمتِ تلگرام نباشه، بلکه فقط یه کلاینتِ کش‌شده‌یِ
        # خرابِ سمتِ خودِ ربات باشه - دکمه‌یِ فعال‌سازی این رو با یه اتصالِ کاملاً
        # تازه دوباره امتحان می‌کنه (نگاه کن به acc_reactivate_).
        final_text += "\n\nمی‌تونی یه‌بار دیگه با یه اتصالِ کاملاً تازه امتحان کنی:"
        reply_markup = InlineKeyboardMarkup([
            [InlineKeyboardButton("🔓 فعال‌سازی", callback_data=f"acc_reactivate_{account['id']}")]
        ])
    try:
        await status_msg.edit_text(final_text, reply_markup=reply_markup)
    except Exception:
        pass


async def _run_account_reactivation(status_msg, account_id: int, acc: dict, name: str, context):
    """
    «🔓 فعال‌سازی» - در پس‌زمینه اجرا می‌شه (نگاه کن به هندلرِ acc_reactivate_ در
    on_callback) تا ربات حینِ اجرا کاملاً در دسترس بمونه، دقیقاً مثلِ «🩺 بررسیِ
    سلامتِ اکانت‌ها».

    status_msg همون پیامیه که هندلر قبلاً با متنِ «در حالِ فعال‌سازی...» ادیتش کرده؛
    این تابع فقط نتیجه رو رویِ همون پیام می‌نویسه.
    """
    try:
        result = await reactivate_account_session(acc["session_file"])
    except Exception as e:
        result = {"status": "still_dead", "reason": f"{type(e).__name__}: {e}"}

    if result["status"] == "busy":
        try:
            await status_msg.edit_text(
                f"⏳ الان نمی‌شه «{name}» رو فعال کرد: {result['message']}",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("🔓 فعال‌سازی", callback_data=f"acc_reactivate_{account_id}")]
                ])
            )
        except Exception:
            pass
        return

    if result["status"] == "still_dead":
        # صادقانه: اگه واقعاً auth_key توسطِ تلگرام باطل شده باشه، هیچ APIای
        # نمی‌تونه زنده‌اش کنه - تنها راه، لاگینِ دوباره‌ست (دکمه‌هایِ «ارسالِ
        # کد»/«واردکردنِ کد» همین‌جا، توی صفحه‌یِ جزئیاتِ اکانت هست).
        try:
            await status_msg.edit_text(
                f"❌ «{name}» هنوز خرابه.\nدلیل: {result['reason']}\n\n"
                "اگه تلگرام واقعاً این سشن رو باطل کرده باشه (که این خطاها "
                "معمولاً همینو می‌گن)، هیچ راهی برایِ فعال‌سازیِ دوباره‌اش از "
                "همین‌جا نیست - باید از «📨 ارسالِ کد» یه لاگینِ کاملاً تازه "
                "انجام بدی."
            )
        except Exception:
            pass
        return

    # موفق: سالم دراومد - دیتابیس رو هم به‌روز کن (همون کاری که
    # _healthcheck_sync_login_status توی بررسیِ سلامتِ معمولی می‌کنه)
    if not acc.get("is_logged_in"):
        try:
            await update_account_login_status(account_id, True)
        except Exception:
            pass
    terminate = result.get("terminate_result") or {}
    lines = [f"✅ «{name}» با موفقیت فعال شد."]
    if terminate.get("status") == "success":
        lines.append("🔒 همه‌یِ نشست‌هایِ دیگه‌ای که ممکن بود هم‌زمان روشن مونده باشن هم بسته شدن.")
    elif terminate.get("status") == "busy":
        # گاردِ جدیدِ terminate_all_other_sessions: عملیات عمداً انجام نشد تا وسطِ
        # یه مهاجرت/عملیاتِ دیگه به سشن آسیب نرسه
        lines.append(
            "⏳ بستنِ نشست‌هایِ دیگه انجام نشد چون این اکانت مشغولِ عملیاتِ دیگه‌ای بود "
            f"({terminate.get('message', 'نامشخص')}). خودِ فعال‌سازی موفق بود؛ اگه لازم شد، "
            "بعداً از دکمه‌یِ «🚪 بیرون‌انداختنِ همه‌یِ نشست‌هایِ دیگه» استفاده کن."
        )
    elif terminate.get("status") == "error":
        lines.append(
            "⚠️ فعال‌سازی خودش موفق بود، ولی بستنِ نشست‌هایِ دیگه ممکن نشد "
            f"({terminate.get('message', 'نامشخص')}). اگه دوباره این خطا تکرار شد، "
            "یه دورِ دیگه از همین دکمه امتحان کن."
        )
    try:
        await status_msg.edit_text("\n".join(lines))
    except Exception:
        pass
    # صفحه‌یِ جزئیاتِ اکانت رو توی یه پیامِ *جدا* دوباره نشون بده - نه با
    # جایگزین‌کردنِ همینْ پیامِ تأیید (که تازه ادیتش کردیم) - وگرنه کاربر
    # اصلاً فرصتِ دیدنِ پیامِ «✅ فعال شد...» رو پیدا نمی‌کنه.
    try:
        fake_query = _FakeDetailQuery(status_msg)
        await show_account_detail(fake_query, account_id, context)
    except Exception:
        pass


def _app_password_instructions(address: str) -> str:
    """
    راهنمایِ ساختنِ App Password رو بر اساسِ دامنه‌یِ ایمیل برمی‌گردونه - چون مسیرِ
    تنظیماتِ Gmail و Outlook کاملاً فرق دارن. اگه دامنه شناخته‌نشده بود، هر دو راهنما
    رو نشون می‌ده (بی‌ضرره و کاربر خودش تشخیص می‌ده کدومه).
    """
    domain = address.rsplit("@", 1)[-1].lower() if "@" in address else ""
    is_gmail = domain in ("gmail.com", "googlemail.com")
    is_outlook = domain in ("outlook.com", "hotmail.com", "live.com", "msn.com")

    gmail_guide = (
        "برایِ Gmail، دو چیز لازمه:\n"
        "۱) IMAP رو فعال کن: از Gmail ← تنظیمات (⚙️) ← «See all settings» ← تبِ "
        "«Forwarding and POP/IMAP» ← گزینه‌یِ «Enable IMAP» رو بزن و ذخیره کن.\n"
        "۲) App Password بساز: اول از myaccount.google.com ← Security، «2-Step "
        "Verification» رو فعال کن (اگه نیست - بدونش App Password اصلاً نشون داده "
        "نمی‌شه). بعد از همون صفحه‌یِ Security برو به «App passwords»، یه اسمِ دلخواه "
        "(مثلاً «Telegram Bot») بده و رمزِ ۱۶ کاراکتری‌ای که می‌سازه رو (با فاصله یا "
        "بدون فاصله - فرقی نداره) همینجا بفرست."
    )
    outlook_guide = (
        "برایِ Outlook/Hotmail: از account.microsoft.com ← Security ← "
        "Advanced security options ← App passwords یه رمز بساز.\n"
        "⚠️ توجه: مایکروسافت رویِ خیلی از صندوق‌هایِ Outlook/Hotmail، ورودِ IMAP با "
        "App Password رو کلاً غیرفعال کرده (حتی رمزِ درست هم کار نمی‌کنه) - اگه بعداً "
        "خطایِ «Basic authentication is disabled» گرفتی، یعنی این صندوق از اون دسته‌ست "
        "و باید یه ایمیلِ Gmail جایگزینش کنی."
    )

    if is_gmail:
        return gmail_guide
    if is_outlook:
        return outlook_guide
    return gmail_guide + "\n\n" + outlook_guide


def _auto_email_menu(entries: list = None):
    """
    منویِ «📧 ایمیلِ خودکارِ کد» - استخرِ چندتاییِ ایمیل، هرکدوم با تیکِ روشن/خاموش.

    ایمیل‌هایِ *روشن* دو جا استفاده می‌شن:
      ۱) تشخیصِ خودکارِ کد: هروقت ایمیلِ بازیابی/لاگینِ یه اکانت با یکی از این‌ها
         یکی باشه، ربات خودش کدِ تلگرام رو از همون صندوق می‌خونه و اعمال می‌کنه -
         نگاه کن به _poll_auto_email_code.
      ۲) «🎲 رندومِ ایمیل‌هایِ فعال» در «🔐 تغییرِ رمزِ دومرحله‌ای»: برایِ هر اکانت یه
         آدرس از همین لیست تصادفی انتخاب می‌شه.
    """
    entries = entries or []
    if entries:
        enabled_n = sum(1 for e in entries if e.get("enabled"))
        text = (
            "📧 ایمیلِ خودکارِ کد\n\n"
            f"{len(entries)} ایمیل ثبت شده ({enabled_n} تا روشن).\n\n"
            "رویِ هرکدوم بزن تا روشن/خاموشش کنی؛ 🗑 برایِ حذفِ کامل:"
        )
    else:
        text = (
            "📧 ایمیلِ خودکارِ کد\n\n"
            "هنوز ایمیلی اضافه نشده. اگه اضافه کنی، هم می‌تونه کدِ اکانت‌هایی که "
            "ایمیلشون همینه رو خودکار بخونه، هم توی «🔐 تغییرِ رمزِ دومرحله‌ای» برایِ "
            "انتخابِ رندوم استفاده بشه.\n\n"
            "⚠️ نکاتِ مهم:\n"
            "• حتماً «App Password» بده، نه رمزِ اصلیِ ایمیل (رمزِ اصلی کار نمی‌کنه).\n"
            "• روی ایمیلت باید two-step verification فعال باشه تا بتونی App Password بسازی.\n"
            "• بهتره ایمیل‌هایِ اختصاصی باشن، نه ایمیلِ شخصیت.\n"
            "• رمز رمزنگاری‌شده ذخیره می‌شه، ولی ذخیره‌ی هر رمزی روی سرور ریسک داره."
        )

    kb = []
    for e in entries:
        mark = "✅" if e.get("enabled") else "❌"
        kb.append([
            InlineKeyboardButton(f"{mark} {e['address']}", callback_data=f"autoemailpool_toggle_{e['id']}"),
            InlineKeyboardButton("🗑", callback_data=f"autoemailpool_del_{e['id']}"),
        ])
    kb.append([InlineKeyboardButton("➕ افزودنِ ایمیلِ جدید", callback_data="autoemail_set")])
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data="menu_accounts")])
    return text, InlineKeyboardMarkup(kb)




# ============================================================================
# «🗑 پاکسازیِ اکانت‌هایِ خراب» - دقیقاً دو مرحله، مثلِ «🩺 بررسیِ سلامتِ اکانت‌ها»:
#   ۱) run_account_cleanup_scan / _run_cleanup_scan_job: بررسیِ کاملِ پس‌زمینه‌ای و
#      قابلِ لغوِ همه‌ی اکانت‌ها (عیناً همون منطقِ دو-دوریِ _run_healthcheck_job) -
#      هیچی پاک نمی‌شه، فقط گزارش می‌ده.
#   ۲) بعدِ اتمامِ بررسی، گزارشِ کامل (چندتا سالم، چندتا خراب و چرا) نشون داده
#      می‌شه و از کاربر تاییدِ نهایی گرفته می‌شه - فقط با زدنِ «✅ بله، پاک‌سازی رو
#      انجام بده»، _finalize_account_cleanup حذفِ واقعی رو انجام می‌ده.
# ============================================================================

_CLEANUP_JOBS: Dict[str, dict] = {}


def _cleanup_scan_keyboard(job_id: str, phase: str = "running"):
    """
    phase:
      - "running":  بررسی در حالِ اجراست - فقط آپدیتِ آمار/لغو
      - "confirm":  بررسی تموم شده - منتظرِ تاییدِ کاربر برایِ حذفِ واقعی
      - "finished": کارِ این جاب تموم شده (لغو شد / حذف انجام شد / بیخیال شدیم)
    """
    if phase == "confirm":
        return InlineKeyboardMarkup([
            [InlineKeyboardButton("✅ بله، پاک‌سازی رو انجام بده", callback_data=f"acc_cleanup_do_{job_id}")],
            [InlineKeyboardButton("❌ بیخیال، هیچی پاک نشه", callback_data=f"acc_cleanup_discard_{job_id}")],
        ])
    if phase == "finished":
        return BACK_TO_MAIN_KB
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 آپدیتِ آمار", callback_data=f"acc_cleanup_refresh_{job_id}")],
        [InlineKeyboardButton("❌ لغوِ بررسی", callback_data=f"acc_cleanup_cancel_{job_id}")],
    ])


def _cleanup_scan_progress_text(state: dict) -> str:
    total = state["total"]
    done = state["done"]
    pct = int(done * 100 / total) if total else 0
    elapsed = int(time.monotonic() - state["started_at"])
    lines = [
        "🗑 پاکسازیِ اکانت‌هایِ خراب - در حالِ بررسیِ کامل",
        "",
        f"پیشرفت: {done}/{total}  ({pct}٪)",
        f"✅ سالم: {state['alive_count']}    ❌ خراب: {state['dead_count']}",
    ]
    if state.get("recheck_pending_count"):
        lines.append(f"🔁 منتظرِ تأییدِ دورِ دوم (خطایِ احتمالاً موقتی): {state['recheck_pending_count']}")
    if state.get("retry_total"):
        lines.append(f"🔁 دورِ دومِ تأییدی در حالِ اجرا: {state['retry_done']}/{state['retry_total']}")
    if state.get("skipped_count"):
        lines.append(f"⏭ بررسی‌نشده (مشغولِ تعویضِ سشن): {state['skipped_count']}")
    if state.get("waiting_migration"):
        lines.append(f"⏳ منتظرِ پایانِ تعویضِ سشن: {state['waiting_migration']}")
    lines.append(f"⏱ زمانِ سپری‌شده: {elapsed} ثانیه")
    if done and total > done:
        remaining = int((elapsed / done) * (total - done))
        lines.append(f"⏳ تخمینِ باقی‌مانده: حدودِ {remaining} ثانیه")
    lines += [
        "",
        "🔀 بررسی موازی انجام می‌شه و ربات همین الان هم قابلِ استفاده‌ست.",
        "⚠️ هنوز هیچی پاک نشده - فقط در حالِ بررسیِ کاملیم؛ آخرِ کار گزارشِ دقیق می‌دم "
        "و بعدش ازت تاییدِ نهایی می‌گیرم.",
    ]
    return "\n".join(lines)


def _cleanup_report_text(state: dict) -> str:
    """گزارشِ پایانِ بررسی - عیناً شکلِ _healthcheck_final_text، با این تفاوت که
    به‌جایِ اعلامِ نتیجه‌ی یه کارِ انجام‌شده، می‌پرسه که آیا حذفِ واقعی انجام بشه یا نه."""
    alive, dead = state["alive"], state["dead"]
    elapsed = int(time.monotonic() - state["started_at"])
    header = "🗑 نتیجه‌ی بررسیِ پاکسازی"
    if state.get("cancelled"):
        header = "🗑 بررسیِ پاکسازی - لغو شد"
    lines = [
        header,
        "",
        f"✅ سالم و آماده: {len(alive)}",
        f"❌ خراب (نامزدِ حذف): {len(dead)}",
    ]
    if state.get("recovered_count"):
        lines.append(
            f"🔁 {state['recovered_count']} اکانت توی بررسیِ اول خطایِ موقتی داد، ولی توی "
            "بررسیِ دومِ تأییدی سالم دراومد - پاک نمی‌شه."
        )
    by_state = state.get("by_state") or {}
    if by_state:
        labels = [
            ("frozen", "🧊 فریز شده"),
            ("deleted", "🚮 حذف‌شده/غیرفعال"),
            ("restricted", "⚠️ محدود شده"),
            ("banned", "⛔ بن شده"),
            ("revoked", "🔑 سشن باطل شده"),
            ("invalid", "❓ سشنِ نامعتبر"),
            ("error", "❌ خطایِ دیگر"),
        ]
        parts = [f"{label}: {by_state[key]}" for key, label in labels if by_state.get(key)]
        if parts:
            lines += ["", "🔎 تفکیکِ اکانت‌هایِ خراب:"] + [f"   {p}" for p in parts]
    if state.get("skipped"):
        lines.append(f"⏭ بررسی‌نشده (مشغولِ تعویضِ سشن): {len(state['skipped'])}")

    if state.get("cancelled"):
        not_checked = state["total"] - state["done"]
        lines.append(f"⏭ بررسی‌نشده: {not_checked}")
        lines.append("")
        lines.append("لغو شد - به هیچ اکانتی دست نخورده؛ چیزی هم پاک نشده.")
        lines.append(f"⏱ زمانِ کل: {elapsed} ثانیه")
        return "\n".join(lines)

    lines.append(f"⏱ زمانِ کل: {elapsed} ثانیه")
    if state.get("migration_waits"):
        lines.append(
            f"🔄 {state['migration_waits']} اکانت وسطِ تعویضِ سشن بودن - "
            "بعد از پایانِ تعویض، رویِ سشنِ جدیدشون تست شدن."
        )

    if dead:
        lines += ["", "این اکانت‌ها خراب تشخیص داده شدن (هرکدوم دو بارِ پشتِ‌سرِهم چک شده و هردو بار خراب بوده):"]
        items = state.get("dead_items") or []
        for item in items[:15]:
            acc = item["acc"]
            name = acc.get("nickname") or "بی‌نام"
            phone = acc.get("phone") or "بدونِ شماره"
            sess = os.path.basename(acc.get("session_file") or "") or "نامشخص"
            lines.append(f"❌ {name} ({phone})")
            lines.append(f"   دلیل: {item['reason']}")
            lines.append(f"   سشن: {sess}.session")
        if len(items) > 15:
            lines.append(f"… و {len(items) - 15} موردِ دیگه (همه‌شون توی زیپ هستن)")
        lines += [
            "",
            "اگه تایید کنی:",
            "۱) فایلِ سشنِ این اکانت‌ها اول توی یه زیپ برات فرستاده می‌شه، بعد خودِ "
            "اکانت از دیتابیس پاک می‌شه (فایلِ سشن به آرشیو منتقل می‌شه، نه حذفِ کامل).",
            "۲) فایل‌هایِ یتیمِ سشن (اگه روی دیسک باشن) هم پاک می‌شن.",
            "",
            "✅ اکانت‌هایِ سالم به هیچ عنوان دست‌نخورده می‌مونن.",
            "",
            "مطمئنی این اکانت‌ها پاک بشن؟",
        ]
    else:
        lines += [
            "",
            "هیچ اکانتِ خرابی پیدا نشد. فقط فایل‌هایِ یتیمِ سشن (اگه روی دیسک مونده "
            "باشن و به هیچ اکانتی توی دیتابیس اشاره نکنن) بررسی و پاک می‌شن.",
            "",
            "ادامه بدم؟",
        ]
    return "\n".join(lines)


async def run_account_cleanup_scan(editable):
    """
    شروعِ مرحله‌یِ بررسی. خودِ کار توی یه task جداگانه اجرا می‌شه، پس هندلرِ آپدیت
    بلافاصله آزاد می‌شه. editable: یا CallbackQuery یا _EditTarget.
    """
    accounts = await get_all_accounts()
    if not accounts:
        await editable.edit_message_text("هیچ اکانتی ثبت نشده.", reply_markup=BACK_TO_MAIN_KB)
        return

    running = next(
        (jid for jid, j in _CLEANUP_JOBS.items() if not j["state"].get("finished")),
        None,
    )
    if running:
        await editable.edit_message_text(
            "🗑 یه بررسیِ پاکسازی همین الان در جریانه.\n\n"
            "آمارِ زنده‌ش رویِ همون پیامِ قبلی به‌روز می‌شه - از همون‌جا دنبالش کن. "
            "اگه می‌خوای از اول شروع کنی، اول با «❌ لغوِ بررسی» متوقفش کن.",
            reply_markup=BACK_TO_MAIN_KB,
        )
        return

    job_id = f"{int(time.time())}{random.randint(100, 999)}"
    state = {
        "total": len(accounts), "done": 0,
        "alive": [], "dead": [], "skipped": [],
        "dead_items": [],
        "by_state": {},
        "alive_count": 0, "dead_count": 0, "skipped_count": 0,
        "waiting_migration": 0, "migration_waits": 0,
        "recheck_pending_count": 0, "retry_total": 0, "retry_done": 0, "recovered_count": 0,
        "started_at": time.monotonic(), "cancelled": False, "finished": False,
        "last_publish_at": 0.0, "last_text": None,
    }
    cancel_event = asyncio.Event()
    _CLEANUP_JOBS[job_id] = {"state": state, "cancel": cancel_event, "editable": editable}

    await editable.edit_message_text(
        _cleanup_scan_progress_text(state), reply_markup=_cleanup_scan_keyboard(job_id, "running")
    )
    asyncio.create_task(_run_cleanup_scan_job(job_id, accounts))


async def _run_cleanup_scan_job(job_id: str, accounts: list):
    """عیناً بدنه‌یِ _run_healthcheck_job (همون منطقِ دو-دوریِ تأیید) - نگاه کن به
    اونجا برایِ توضیحِ کامل. تنها فرق: در پایان به‌جایِ نهایی‌کردنِ گزارش، منتظرِ
    تاییدِ کاربر می‌مونه؛ حذفِ واقعی در _finalize_account_cleanup انجام می‌شه."""
    job = _CLEANUP_JOBS.get(job_id)
    if not job:
        return
    state, cancel_event, editable = job["state"], job["cancel"], job["editable"]
    lock = asyncio.Lock()
    sem = asyncio.Semaphore(HEALTHCHECK_CONCURRENCY)
    pending_retry: list = []

    async def publish(force: bool = False):
        now = time.monotonic()
        if not force and now - state["last_publish_at"] < 3.0:
            return
        text = _cleanup_scan_progress_text(state)
        if text == state.get("last_text"):
            return
        state["last_publish_at"] = now
        state["last_text"] = text
        try:
            await editable.edit_message_text(text, reply_markup=_cleanup_scan_keyboard(job_id, "running"))
        except Exception:
            pass

    async def _check_one(acc):
        if cancel_event.is_set():
            return
        async with sem:
            if cancel_event.is_set():
                return
            was_migrating = is_session_migrating(acc["session_file"])
            if was_migrating:
                async with lock:
                    state["waiting_migration"] += 1
                await publish(force=True)
            try:
                result = await check_account_alive(
                    acc["session_file"], timeout=HEALTHCHECK_PER_ACCOUNT_TIMEOUT
                )
            except asyncio.CancelledError:
                raise
            except Exception as e:
                result = {"alive": False, "reason": f"{type(e).__name__}: {e}"}
            finally:
                if was_migrating:
                    async with lock:
                        state["waiting_migration"] -= 1
                        state["migration_waits"] += 1

            label = acc.get("nickname") or acc.get("phone")
            async with lock:
                if result.get("alive") is None:
                    state["skipped"].append(f"{label} — {result.get('reason', 'بررسی نشد')}")
                    state["skipped_count"] += 1
                    state["done"] += 1
                    await publish()
                    return
                if result["alive"]:
                    state["alive"].append(label)
                    state["alive_count"] += 1
                    state["done"] += 1
                else:
                    pending_retry.append((acc, result["reason"]))
                    state["recheck_pending_count"] = state.get("recheck_pending_count", 0) + 1
                    state["done"] += 1
            if result["alive"]:
                await _healthcheck_sync_login_status(acc, True)
            await publish()

    async def _retry_one(acc, first_reason, retry_sem):
        async def _mark_cancelled():
            async with lock:
                label = acc.get("nickname") or acc.get("phone")
                state["skipped"].append(
                    f"{label} — بررسیِ دومِ تأییدی لغو شد (نتیجه‌یِ دورِ اول: {first_reason})"
                )
                state["skipped_count"] += 1
                state["retry_done"] += 1

        if cancel_event.is_set():
            await _mark_cancelled()
            return
        async with retry_sem:
            if cancel_event.is_set():
                await _mark_cancelled()
                return
            try:
                result = await check_account_alive(
                    acc["session_file"], timeout=HEALTHCHECK_PER_ACCOUNT_TIMEOUT
                )
            except asyncio.CancelledError:
                raise
            except Exception as e:
                result = {"alive": False, "reason": f"{type(e).__name__}: {e}"}

            label = acc.get("nickname") or acc.get("phone")
            async with lock:
                state["retry_done"] += 1
                if result.get("alive") is None:
                    state["skipped"].append(f"{label} — {result.get('reason', 'بررسی نشد')}")
                    state["skipped_count"] += 1
                elif result["alive"]:
                    state["alive"].append(label)
                    state["alive_count"] += 1
                    state["recovered_count"] = state.get("recovered_count", 0) + 1
                else:
                    state["dead"].append(f"{label} — {result['reason']}")
                    state["dead_items"].append({
                        "acc": acc, "reason": result["reason"],
                        # نوعِ خرابی این‌جا هم نگه داشته می‌شه تا اگه اکانتی با
                        # زاپاس نجات پیدا کرد، تفکیکِ گزارش درست بازسازی بشه
                        # (نگاه کن به _apply_spare_rescue_to_state)
                        "state": result.get("state") or "error",
                    })
                    state["dead_count"] += 1
                    st = result.get("state") or "error"
                    state["by_state"][st] = state["by_state"].get(st, 0) + 1
            if result.get("alive") is not None:
                await _healthcheck_sync_login_status(acc, bool(result["alive"]))
            await publish(force=True)

    try:
        await asyncio.gather(*(_check_one(a) for a in accounts), return_exceptions=True)

        if pending_retry:
            state["retry_total"] = len(pending_retry)
            state["retry_done"] = 0
            state["recheck_pending_count"] = 0
            await publish(force=True)
            if cancel_event.is_set():
                for acc, reason in pending_retry:
                    label = acc.get("nickname") or acc.get("phone")
                    state["skipped"].append(
                        f"{label} — بررسیِ دومِ تأییدی لغو شد (نتیجه‌یِ دورِ اول: {reason})"
                    )
                    state["skipped_count"] += 1
                    state["retry_done"] += 1
            else:
                await asyncio.sleep(HEALTHCHECK_RETRY_DELAY)
                retry_sem = asyncio.Semaphore(HEALTHCHECK_RETRY_CONCURRENCY)
                await asyncio.gather(
                    *(_retry_one(acc, reason, retry_sem) for acc, reason in pending_retry),
                    return_exceptions=True,
                )
    finally:
        state["finished"] = True
        cancelled = cancel_event.is_set()
        phase = "finished" if cancelled else "confirm"

        # ⚠️ باگی که این‌جا حل شده: قبلاً اگه ساختنِ متنِ گزارش یا ویرایشِ پیام به هر
        # دلیلی (مثلاً FloodWait بعدِ کلی ویرایشِ پی‌درپی توی یه بررسیِ طولانی) خطا
        # می‌داد، خطا بی‌سروصدا قورت داده می‌شد و کاربر تا ابد همون صفحه‌ی «در حالِ
        # بررسی» رو می‌دید - نه گزارشی، نه دکمه‌ی تاییدی. الان: (۱) اگه خودِ متنِ
        # گزارش خطا بده، یه نسخه‌ی حداقلیِ امن جایگزینش می‌شه، (۲) ویرایش چندبار با
        # فاصله امتحان می‌شه، (۳) اگه بازم نشد، به‌جایِ ویرایش یه پیامِ کاملاً تازه
        # فرستاده می‌شه - تا این مرحله هیچ‌وقت بی‌صدا گم نشه.
        try:
            report_text = _cleanup_report_text(state)
        except Exception as e:
            print(f"⚠️  ساختِ گزارشِ پاکسازی با خطا مواجه شد: {e}")
            report_text = (
                "🗑 بررسیِ پاکسازی تموم شد، ولی ساختنِ گزارشِ کامل با خطا مواجه شد "
                "(جزئیات توی لاگ ثبت شد).\n\n"
                f"✅ سالم: {state.get('alive_count', 0)}    ❌ خراب: {state.get('dead_count', 0)}\n"
                f"بررسی‌شده: {state.get('done', 0)}/{state.get('total', 0)}"
            )
            if not cancelled and state.get("dead_items"):
                report_text += "\n\nمطمئنی اکانت‌هایِ خرابِ بالا پاک بشن؟"

        sent = False
        for attempt in range(3):
            try:
                await editable.edit_message_text(
                    report_text, reply_markup=_cleanup_scan_keyboard(job_id, phase)
                )
                sent = True
                break
            except Exception as e:
                print(f"⚠️  ارسالِ گزارشِ نهاییِ پاکسازی ناموفق بود (تلاشِ {attempt + 1} از ۳): {e}")
                await asyncio.sleep(2 * (attempt + 1))
        if not sent:
            # آخرین چاره: به‌جایِ ویرایشِ همون پیام، یه پیامِ کاملاً تازه بفرست - تا
            # حتماً به کاربر برسه و جاب گم نشه
            try:
                message = getattr(editable, "message", None)
                if message is not None:
                    await message.reply_text(
                        report_text, reply_markup=_cleanup_scan_keyboard(job_id, phase)
                    )
            except Exception as e:
                print(f"⚠️  حتیٰ فرستادنِ پیامِ تازه‌ی گزارشِ پاکسازی هم ناموفق بود: {e}")

        if cancelled:
            # لغو شده - چیزی برایِ تاییدِ بعدی نمونده، جاب رو آزاد کن
            _CLEANUP_JOBS.pop(job_id, None)
        # اگه لغو نشده، جاب رو نگه می‌داریم تا با «✅»/«❌» کاربر (acc_cleanup_do_/
        # acc_cleanup_discard_) تصمیمِ نهایی گرفته بشه - نگاه کن به
        # _finalize_account_cleanup و _discard_account_cleanup.


# ============================================================================
# ♻️ نجاتِ اکانتِ خراب با سشنِ زاپاس - منطقِ *مشترکِ* بررسیِ سلامت و پاکسازی
# ----------------------------------------------------------------------------
# قبلاً این کار فقط توی لحظه‌یِ حذف (پاکسازیِ اکانت‌هایِ خراب) انجام می‌شد؛ یعنی اگه
# فقط «بررسیِ سلامت» می‌گرفتی، اکانتی که زاپاسِ سالم داشت هم «خراب» گزارش می‌شد و
# دست‌نخورده می‌موند. حالا هر دو مسیر از همین یه تابع استفاده می‌کنن.
#
# ترتیبِ کارها عمداً همینه و هیچ قدمی جابه‌جا نمی‌شه:
#   ۱) اول *زاپاس* تست می‌شه (promote_spare_session خودش این کار رو می‌کنه). اگه
#      زاپاس سالم نباشه، به سشنِ اصلی دست نمی‌زنیم - یه سشنِ خرابِ شناخته‌شده بهتر
#      از هیچیه.
#   ۲) بعدِ جایگزینیِ موفق: ردیفِ زاپاس 'promoted' می‌شه، اکانت «لاگین‌شده» علامت
#      می‌خوره، و مهم‌تر از همه needs_rebuild ثبت می‌شه - یعنی این اکانت دوباره
#      واردِ نوبتِ «🧩 ساخت سشن زاپاس» می‌شه، چون زاپاسش مصرف شد.
#   ۳) اکانتی که هیچ زاپاسِ سالمی نداشت، همون‌طور «خراب» می‌مونه.
# ============================================================================

async def _rescue_dead_accounts_with_spare(dead_items: list):
    """
    خروجی: ``(rescued, still_dead)``

    ``rescued`` لیستی از دیکشنری‌هاست: ``{"acc", "reason", "state", "label", "note"}``
    و ``still_dead`` همون آیتم‌هایِ ورودی که زاپاسِ سالمی نداشتن.
    """
    if not dead_items:
        return [], []
    try:
        spare_rows = await get_active_spares_with_account()
    except Exception:
        spare_rows = []
    spares_by_account = {}
    for row in spare_rows:
        spares_by_account.setdefault(int(row["account_id"]), []).append(row)
    if not spares_by_account:
        return [], list(dead_items)

    rescued, still_dead = [], []
    for item in dead_items:
        acc = item["acc"]
        label = acc.get("nickname") or acc.get("phone") or f"#{acc.get('id')}"
        candidates = spares_by_account.get(int(acc["id"])) or []
        promoted = None
        for row in candidates:
            try:
                outcome = await promote_spare_session(
                    row["main_session_file"], row["session_file"],
                    expected_telegram_id=row.get("telegram_id"),
                )
            except Exception as e:
                outcome = {"status": "error", "message": f"{type(e).__name__}: {e}"}
            if outcome.get("status") != "success":
                try:
                    await record_spare_session_error(
                        row["session_file"], outcome.get("message"))
                except Exception:
                    pass
                continue
            try:
                await set_spare_session_status(row["session_file"], "promoted")
                # ⚠️ همین خط تضمین می‌کنه اکانت دوباره توی لیستِ «🧩 ساخت سشن زاپاس»
                # ظاهر بشه - زاپاسش مصرف شد و باید یه زاپاسِ تازه بگیره.
                await mark_spare_needs_rebuild(
                    row["session_file"], "زاپاس جایگزینِ سشنِ خرابِ اکانت شد")
                await update_account_login_status(int(acc["id"]), True)
            except Exception:
                pass
            promoted = {
                "acc": acc, "reason": item.get("reason"),
                "state": item.get("state") or "error",
                "label": label,
                "device": row.get("device_model") or "",
            }
            break
        if promoted:
            rescued.append(promoted)
        else:
            still_dead.append(item)
    return rescued, still_dead


def _apply_spare_rescue_to_state(state: dict, rescued: list, still_dead: list) -> None:
    """
    نتیجه‌یِ نجات رو رویِ وضعیتِ همون جابِ در جریان (بررسیِ سلامت/پاکسازی) اعمال
    می‌کنه: اکانت‌هایِ نجات‌یافته از لیستِ «خراب» درمیان و به «سالم» اضافه می‌شن، و
    تفکیکِ نوعِ خرابی هم از اول و درست بازسازی می‌شه (وگرنه گزارش با خودش نمی‌خوند).
    """
    if not rescued:
        return
    state["dead_items"] = still_dead
    state["dead"] = [
        f"{(i['acc'].get('nickname') or i['acc'].get('phone'))} — {i.get('reason')}"
        for i in still_dead
    ]
    state["dead_count"] = len(still_dead)
    by_state = {}
    for i in still_dead:
        key = i.get("state") or "error"
        by_state[key] = by_state.get(key, 0) + 1
    state["by_state"] = by_state
    for r in rescued:
        state["alive"].append(r["label"])
        state["alive_count"] = int(state.get("alive_count") or 0) + 1
    bucket = state.setdefault("rescued", [])
    for r in rescued:
        device = f" (زاپاس: {r['device']})" if r.get("device") else ""
        bucket.append(f"{r['label']} — با سشنِ زاپاس برگشت{device}")
    state["rescued_count"] = len(bucket)


async def _finalize_account_cleanup(job_id: str, editable):
    """کاربر تایید کرد - همین‌جا حذفِ واقعیِ اکانت‌هایِ خرابِ تاییدشده (نتیجه‌یِ
    قطعیِ همون بررسیِ دو-دوری) + پاکسازیِ فایل‌هایِ یتیمِ سشن انجام می‌شه.
    قبل از حذفِ هر اکانت، زیپِ سشن/jsonش فرستاده می‌شه (نگاه کن به
    _send_broken_accounts_zip) تا اگه لازم شد قابلِ بازیابی باشه."""
    job = _CLEANUP_JOBS.pop(job_id, None)
    if not job:
        await editable.edit_message_text(
            "این درخواستِ پاکسازی دیگه معتبر نیست (شاید قبلاً انجام شده) - از اول امتحان کن.",
            reply_markup=BACK_TO_MAIN_KB,
        )
        return
    state = job["state"]
    dead_items = state.get("dead_items") or []

    await editable.edit_message_text("🗑 در حالِ حذفِ نهایی...")

    if dead_items:
        try:
            await _send_broken_accounts_zip(editable, dead_items)
        except Exception:
            pass

    # ---- آخرین فرصت: اکانتی که سشنِ زاپاس داره حذف نمی‌شه ----
    # کلِ دلیلِ وجودیِ زاپاس همین لحظه‌ست. قبل از هر حذفی، زاپاس تست و (اگه سالم
    # بود) جایگزینِ سشنِ اصلی می‌شه؛ اون اکانت از لیستِ حذف بیرون میاد.
    rescued_items, dead_items = await _rescue_dead_accounts_with_spare(dead_items)
    rescued = [
        f"{r['label']} — با سشنِ زاپاس برگشت"
        + (f" (زاپاس: {r['device']})" if r.get("device") else "")
        for r in rescued_items
    ]

    removed = []
    for item in dead_items:
        acc = item["acc"]
        label = acc.get("nickname") or acc.get("phone")
        try:
            # ⚠️ «پاک» نمی‌شه: ردیفش قبل از برداشته‌شدن کاملاً در deleted_accounts_log
            # اسنپ‌شات می‌شه و فایلِ سشنش به پوشه‌یِ sessions_trash *منتقل* می‌شه (نه
            # os.remove) - پس اگه تشخیص اشتباه بوده باشه، قابلِ برگشته.
            await delete_account(acc["id"], reason="cleanup")
            removed.append(f"{label} — {item['reason']}")
        except Exception as e:
            removed.append(f"{label} — ⚠️ حذف نشد: {e}")

    try:
        await editable.edit_message_text("🗑 در حالِ چکِ فایل‌هایِ یتیمِ سشن...")
    except Exception:
        pass
    try:
        orphans_removed = await cleanup_orphaned_session_files()
    except Exception:
        orphans_removed = 0

    lines = [
        "🗑 نتیجه‌ی پاکسازی",
        "",
        f"✅ سالم و دست‌نخورده موند: {len(state.get('alive') or [])}",
        f"🗑 اکانتِ خراب پاک شد: {len(removed)}",
        f"🗑 فایلِ یتیمِ سشن پاک شد: {orphans_removed}",
    ]
    if rescued:
        lines.insert(3, f"♻️ با سشنِ زاپاس نجات پیدا کرد: {len(rescued)}")
        lines += ["", "این‌ها حذف *نشدن* - زاپاسشون جایگزینِ سشنِ خراب شد:"]
        lines += [f"• {r}" for r in rescued[:10]]
        lines.append("برایِ هرکدوم یه زاپاسِ تازه بساز (زاپاسِ قبلی مصرف شد).")
    if removed:
        lines += ["", "اکانت‌هایِ حذف‌شده:"]
        lines += [f"• {d}" for d in removed[:15]]
        if len(removed) > 15:
            lines.append(f"… و {len(removed) - 15} موردِ دیگه")
        lines += ["", "الان می‌تونی هر شماره‌ای که پاک شده رو دوباره از «➕ اضافه کردن اکانت» وارد کنی."]
    await editable.edit_message_text("\n".join(lines), reply_markup=BACK_TO_MAIN_KB)


async def _discard_account_cleanup(job_id: str, editable):
    """کاربر بیخیال شد - جاب رو دور می‌ندازیم، هیچ اکانت یا فایلی دست‌نخورده می‌مونه."""
    _CLEANUP_JOBS.pop(job_id, None)
    await editable.edit_message_text(
        "❌ بیخیال شدیم - هیچ اکانت یا فایلی پاک نشد.",
        reply_markup=BACK_TO_MAIN_KB,
    )


_CC_PHASE_LABELS = {
    "start": "🚀 آماده‌سازی",
    "running": "🧹 در حالِ پاک‌سازی",
    "deleted": "🧹 در حالِ پاک‌سازی",
    "failed": "🧹 در حالِ پاک‌سازی",
    "verifying": "🔍 راستی‌آزمایی",
    "flood": "⏸ توقفِ موقت (FloodWait)",
    "done": "✅ تمام شد",
    "error": "❌ خطا",
}


# چندتا اکانت هم‌زمان پردازش بشه - چون هر اکانت کلاینت/سشنِ کاملاً جداگانه‌ی خودش را
# دارد، این کار هیچ ریسکِ FloodWaitِ مشترکی ایجاد نمی‌کند و فقط سرعتِ کلیِ کار را
# چند برابر می‌کند.
_CC_ACCOUNT_CONCURRENCY = 3


def _chat_cleanup_status_text(
    total_accounts: int,
    done_accounts: int,
    running_accounts: list,
    queued_count: int,
    overall: dict,
    started_at: float,
    started_at_wall,
    phase: str = "running",
    note: str = "",
) -> str:
    elapsed = max(0.001, time.monotonic() - started_at)
    mm, ss = divmod(int(elapsed), 60)
    hh, mm = divmod(mm, 60)
    elapsed_str = f"{hh:02d}:{mm:02d}:{ss:02d}"

    # ===== درصدِ کلی: میانگینِ درصدِ هر اکانتِ درحالِ اجرا + سهمِ اکانت‌هایِ تمام‌شده =====
    running_percents = []
    for ra in running_accounts:
        st = ra["stats"]
        kept_n = max(int(st.get("kept") or 0), 0)
        actionable = max(int(st.get("total") or 0) - kept_n, 0)
        processed_n = max(int(st.get("processed") or 0), 0)
        running_percents.append((processed_n / actionable * 100.0) if actionable else 0.0)
    overall_percent = ((done_accounts * 100.0) + sum(running_percents)) / total_accounts if total_accounts else 0.0
    overall_percent = max(0.0, min(100.0, overall_percent))

    total_deleted = int(overall.get("deleted", 0) or 0)
    total_kept = int(overall.get("kept", 0) or 0)
    total_failed = int(overall.get("failed", 0) or 0)
    total_actionable_done = total_deleted + total_failed

    throughput = (total_actionable_done / elapsed) if total_actionable_done > 0 else 0.0
    if phase == "done":
        eta_text = "—"
    elif throughput > 0:
        remaining_accounts_est = max(0, total_accounts - done_accounts - len(running_accounts))
        avg_actionable_per_finished = (total_actionable_done / done_accounts) if done_accounts else (
            total_actionable_done / max(1, len(running_accounts))
        )
        remaining_dialogs_est = avg_actionable_per_finished * remaining_accounts_est
        eta_text = _format_duration_seconds(remaining_dialogs_est / throughput) if remaining_dialogs_est > 0 else "به‌زودی"
    else:
        eta_text = "درحالِ محاسبه…"

    bar_overall = _cc_progress_bar(overall_percent)
    by_type = overall.get("by_type") or {}
    sep = "▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️"

    lines = [
        "🗂 پاک کردن چت‌ها",
        f"📅 شروع: {fmt_tehran(started_at_wall, '%Y-%m-%d %H:%M:%S')}",
        sep,
        f"[{bar_overall}]  {overall_percent:.1f}%",
        f"👥 اکانت‌ها: {done_accounts + len(running_accounts)}/{total_accounts}"
        f"   (✅ {done_accounts}  •  🔄 {len(running_accounts)}  •  ⏳ {queued_count})",
        f"⏱ سپری‌شده: {elapsed_str}   •   تخمینِ باقی‌مانده: {eta_text}",
    ]

    if running_accounts:
        lines += [sep, "🔄 درحالِ پردازشِ هم‌زمان"]
        for ra in running_accounts[:6]:
            acc = ra["account"]
            st = ra["stats"]
            label = acc.get("nickname") or acc.get("phone") or f"#{acc.get('id')}"
            kept_n = max(int(st.get("kept") or 0), 0)
            actionable = max(int(st.get("total") or 0) - kept_n, 0)
            processed_n = max(int(st.get("processed") or 0), 0)
            pct = (processed_n / actionable * 100.0) if actionable else 0.0
            bar = _cc_progress_bar(pct, width=8)
            ph = _CC_PHASE_LABELS.get(st.get("phase", "running"), st.get("phase", ""))
            if st.get("phase") == "verifying" and st.get("verification_pass"):
                ph = f"🔍 راستی‌آزمایی (دورِ {st.get('verification_pass')})"
            lines.append(f"▪️ {label}")
            lines.append(f"   [{bar}] {pct:.0f}%  ({processed_n}/{actionable or '؟'})  —  {ph}")
            if st.get("last_name"):
                lines.append(f"   ↳ آخرین چت: {st.get('last_name')}")
        if len(running_accounts) > 6:
            lines.append(f"… و {len(running_accounts) - 6} اکانتِ دیگر هم‌زمان درحالِ اجرا")

    lines += [
        sep,
        "📈 نتایجِ تا این لحظه",
        f"🗑 حذف‌شده: {total_deleted}     💾 نگه‌داشته: {total_kept}     ⚠️ خطا: {total_failed}",
        "",
        f"📢 کانال‌ها: {by_type.get('channel', 0)}   👥 گروه‌ها: {by_type.get('group', 0)}   "
        f"🤖 ربات‌ها: {by_type.get('bot', 0)}   👤 خصوصی: {by_type.get('private', 0)}",
    ]
    if note:
        lines += [sep, note]
    return "\n".join(lines)


async def _run_chat_cleanup_queue(editable, context, session: ChatCleanupSession):
    """پاک‌کردنِ چت‌ها را با چند اکانتِ هم‌زمان (تا سقفِ ``_CC_ACCOUNT_CONCURRENCY``) و
    گزارشِ زنده و کاملِ لحظه‌ای اجرا می‌کند.

    نکته ۱: خودِ ``cleanup_session_dialogs`` دیگر با اولین FloodWait رها نمی‌کند و
    با چند دورِ راستی‌آزمایی مطمئن می‌شود چیزی جا نمی‌ماند - پس این‌جا دیگر نیازی
    به حلقه‌یِ دستیِ «یک‌بار دوباره امتحان کن» نیست.
    نکته ۲: چون هر اکانت کلاینت/سشنِ کاملاً جداگانه‌ی خودش را دارد، پردازشِ هم‌زمانِ
    چند اکانت هیچ ریسکِ FloodWaitِ مشترکی ایجاد نمی‌کند و فقط سرعتِ کلی را بالا می‌برد.
    """
    if session.running:
        try:
            await editable.edit_message_text("⏳ این عملیات همین الان در حال اجراست.")
        except Exception:
            pass
        return

    session.running = True
    session.started_at = time.monotonic()
    session.last_publish_at = 0.0
    started_at_wall = utcnow()
    selected = list(session.selected_accounts)
    total_accounts = len(selected)
    failed_accounts: list[str] = []
    failed_chats_sample: list[str] = []
    done_accounts = 0
    account_states: dict = {}  # acc_id -> {"account": acc, "stats": {...}}

    def _recompute_overall() -> dict:
        deleted = kept = failed = 0
        by_type = {"channel": 0, "group": 0, "bot": 0, "private": 0, "other": 0}
        for entry in account_states.values():
            st = entry["stats"]
            deleted += int(st.get("deleted") or 0)
            kept += int(st.get("kept") or 0)
            failed += int(st.get("failed") or 0)
            for k, v in (st.get("by_type") or {}).items():
                by_type[k] = by_type.get(k, 0) + int(v or 0)
        return {"deleted": deleted, "kept": kept, "failed": failed, "by_type": by_type}

    session.live_state = {
        "total_accounts": total_accounts,
        "done_accounts": 0,
        "running_accounts": [],
        "queued_count": total_accounts,
        "overall": _recompute_overall(),
        "phase": "start",
        "note": "",
        "started_at": session.started_at,
        "started_at_wall": started_at_wall,
    }
    status_message = editable.message
    ticker_task = None

    async def publish(force: bool = False, note: str = ""):
        now = time.monotonic()
        should_publish = force or (now - session.last_publish_at) >= 10.0
        if not should_publish:
            return
        session.last_publish_at = now
        overall_now = _recompute_overall()
        running_list = [v for v in account_states.values() if v["stats"].get("phase") not in {"done", "error"}]
        queued_count = max(0, total_accounts - done_accounts - len(running_list))
        overall_phase = "done" if (total_accounts and done_accounts >= total_accounts) else ("running" if running_list else "start")
        session.live_state = {
            "total_accounts": total_accounts,
            "done_accounts": done_accounts,
            "running_accounts": running_list,
            "queued_count": queued_count,
            "overall": overall_now,
            "phase": overall_phase,
            "note": note,
            "started_at": session.started_at,
            "started_at_wall": started_at_wall,
        }
        text = _chat_cleanup_status_text(
            total_accounts, done_accounts, running_list, queued_count,
            overall_now, session.started_at, started_at_wall,
            phase=overall_phase, note=note,
        )
        try:
            await status_message.edit_text(text, reply_markup=_chat_cleanup_running_keyboard())
        except Exception:
            pass

    async def auto_refresh_loop():
        while session.running:
            await asyncio.sleep(10)
            if not session.running:
                break
            try:
                await publish(force=True)
            except Exception:
                pass

    async def _process_one_account(acc: dict, sem: asyncio.Semaphore):
        nonlocal done_accounts
        async with sem:
            acc = await get_account(acc["id"]) or acc
            stats = {"processed": 0, "total": 0, "deleted": 0, "kept": 0, "failed": 0, "last_name": "", "phase": "running", "by_type": {}}
            account_states[acc["id"]] = {"account": acc, "stats": stats}
            await publish(force=True, note=f"شروعِ اکانت: {acc.get('nickname') or acc.get('phone')}")

            async def progress_cb(info: dict):
                stats.update({
                    "processed": info.get("processed", stats["processed"]),
                    "total": info.get("total", stats.get("total", 0)),
                    "deleted": info.get("deleted", stats["deleted"]),
                    "kept": info.get("kept", stats["kept"]),
                    "failed": info.get("failed", stats["failed"]),
                    "last_name": info.get("last_name", stats.get("last_name", "")),
                    "phase": info.get("phase", stats.get("phase", "running")),
                    "verification_pass": info.get("verification_pass", stats.get("verification_pass")),
                    "by_type": info.get("by_type", stats.get("by_type", {})),
                })
                if stats["phase"] in {"error", "verifying"}:
                    note = info.get("error", "")
                    if stats["phase"] == "verifying":
                        acc_label = acc.get("nickname") or acc.get("phone")
                        note = (
                            f"راستی‌آزمایی دورِ {info.get('verification_pass', '؟')} برایِ {acc_label} — "
                            f"بررسیِ {info.get('remaining_to_verify', '؟')} موردِ باقی‌مانده."
                        )
                    await publish(force=True, note=note)
                else:
                    await publish()

            protected_usernames, protected_peer_ids = await _get_protected_dialog_references()
            # DMِ جفتِ شیر توی مسیرِ دستی هم محفوظه - «پاک کردن چت‌ها» برایِ تمیزکردنِ
            # چت‌هایِ بی‌ربطه، نه برایِ خراب‌کردنِ زیرساختِ خودِ ربات.
            pair_dm_user_ids = await _get_protected_pair_dm_user_ids()
            result = await cleanup_session_dialogs(
                acc["session_file"],
                progress_callback=progress_cb,
                notify_every=20,
                extra_protected_usernames=protected_usernames,
                extra_protected_peer_ids=protected_peer_ids,
                extra_protected_user_ids=pair_dm_user_ids.get(acc.get("id")) or set(),
            )

            status = result.get("status")
            deleted = int(result.get("deleted", 0) or 0)
            kept = int(result.get("kept", 0) or 0)
            failed = int(result.get("failed", 0) or 0)
            stats["deleted"] = deleted
            stats["kept"] = kept
            stats["failed"] = failed
            stats["by_type"] = result.get("by_type") or stats.get("by_type") or {}
            stats["phase"] = "done" if status == "success" else "error"
            stats["processed"] = max(stats.get("processed", 0), deleted + failed)

            acc_label = acc.get("nickname") or acc.get("phone") or acc.get("id")
            if status != "success":
                reason = result.get("message") or status or "error"
                failed_accounts.append(f"{acc_label} — {reason}")
            elif failed:
                # اکانت با موفقیت پردازش شد، ولی چند چتِ خاص (بعدِ همه‌یِ تلاش‌ها و
                # دورهایِ راستی‌آزمایی) واقعاً نشد حذف بشن - این‌جا صادقانه دقیقاً
                # کدوم چت‌ها بودن رو اعلام می‌کنیم، نه اینکه فقط عددِ خطا رو نشون بدیم.
                for name in (result.get("failed_names") or [])[:5]:
                    failed_chats_sample.append(f"{acc_label} ← {name}")

            done_accounts += 1
            await publish(force=True, note=f"{acc_label} تمام شد: {deleted} حذف، {kept} نگه‌داشته، {failed} خطا")

    try:
        if not selected:
            await status_message.edit_text(
                """🗂 پاک کردن چت‌ها

هیچ اکانتی انتخاب نشده.""",
                reply_markup=BACK_TO_ACCOUNTS_KB,
            )
            return

        await publish(
            force=True,
            note=(
                f"همه‌یِ اکانت‌ها (کانال‌ها، گروه‌ها، ربات‌ها و چت‌های خصوصی) پاک می‌شوند - "
                f"تا {_CC_ACCOUNT_CONCURRENCY} اکانت هم‌زمان، برایِ سرعتِ بالاتر. "
                f"الان می‌تونی هم‌زمان از بقیه‌ی بخش‌های ربات استفاده کنی؛ این فرایند در پس‌زمینه ادامه دارد."
            ),
        )
        ticker_task = asyncio.create_task(auto_refresh_loop())

        sem = asyncio.Semaphore(_CC_ACCOUNT_CONCURRENCY)
        await asyncio.gather(*[_process_one_account(acc, sem) for acc in selected])

        ended_at_wall = utcnow()
        overall_final = _recompute_overall()
        by_type_final = overall_final.get("by_type", {})
        duration_seconds = max(0.0, time.monotonic() - session.started_at)
        sep = "▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️▫️"
        final_lines = [
            "🗂 پاک کردن چت‌ها — ✅ تمام شد",
            f"[{_cc_progress_bar(100.0)}]  100%",
            sep,
            f"📅 شروع: {fmt_tehran(started_at_wall, '%Y-%m-%d %H:%M:%S')}",
            f"📅 پایان: {fmt_tehran(ended_at_wall, '%Y-%m-%d %H:%M:%S')}",
            f"⏱ مدتِ کل: {_format_duration_seconds(duration_seconds)}",
            sep,
            f"👥 اکانت‌ها: {done_accounts}/{total_accounts} پردازش شد",
            f"🗑 حذف‌شده: {overall_final['deleted']}     💾 نگه‌داشته: {overall_final['kept']}     ⚠️ خطا: {overall_final['failed']}",
            "",
            f"📢 کانال‌ها: {by_type_final.get('channel', 0)}   👥 گروه‌ها: {by_type_final.get('group', 0)}   "
            f"🤖 ربات‌ها: {by_type_final.get('bot', 0)}   👤 خصوصی: {by_type_final.get('private', 0)}",
        ]
        if by_type_final.get("other"):
            final_lines.append(f"❓ سایر: {by_type_final.get('other', 0)}")
        if failed_accounts:
            final_lines += [sep, "❌ اکانت‌هایِ ناموفق"]
            for item in failed_accounts[:15]:
                final_lines.append(f"▪️ {item}")
            if len(failed_accounts) > 15:
                final_lines.append(f"… و {len(failed_accounts) - 15} موردِ دیگر")
        if failed_chats_sample:
            final_lines += [sep, "⚠️ چت‌هایی که با وجودِ چند بار تلاش و راستی‌آزمایی، حذف نشدن"]
            for item in failed_chats_sample[:15]:
                final_lines.append(f"▪️ {item}")
            if len(failed_chats_sample) > 15:
                final_lines.append(f"… و {len(failed_chats_sample) - 15} موردِ دیگر")
        final_lines += [
            sep,
            "ℹ️ Saved Messages و چت‌های رسمیِ تلگرام حذف نمی‌شوند.",
            "الان می‌توانی دوباره از منوی اکانت‌ها استفاده کنی.",
        ]
        await status_message.edit_text("\n".join(final_lines), reply_markup=BACK_TO_ACCOUNTS_KB)
    except Exception as e:
        try:
            await status_message.edit_text(
                f"❌ پاک کردن چت‌ها با خطا متوقف شد:\n{friendly_error(e)}",
                reply_markup=BACK_TO_ACCOUNTS_KB,
            )
        except Exception:
            pass
    finally:
        session.running = False
        session.started_at = None
        session.live_state = {}
        if ticker_task:
            ticker_task.cancel()
            try:
                await ticker_task
            except Exception:
                pass


# ============================================================================
# 🔀 شیرِ پست - منوها، ویزارد، و اجرا
# ----------------------------------------------------------------------------
# ساختارِ این بخش عیناً از «👍 ری‌اکشن» کپیِ مفهومی شده تا کاربر چیزِ جدیدی یاد
# نگیره: «📍 شیر کردنِ یک‌باره» معادلِ ری‌اکشنِ یک‌باره، و «🔁 شیرِ خودکار» معادلِ
# ری‌اکشنِ خودکار (با همون تگ‌ها، همون بازه‌یِ تعداد، و همون بازه‌یِ زمانی).
#
# تفاوتِ فنیِ مهم: ری‌اکشن رو هر اکانتی به‌تنهایی می‌تونه بزنه، ولی «شیر» فقط وقتی
# توی آمارِ کانال شمرده می‌شه که پست واقعاً به یه چتِ دیگه فوروارد بشه. پس هر اکانت
# باید یه «جفت» داشته باشه که شماره‌ی همدیگه رو مخاطب کردن (نگاه کن به
# peer_share.py) - صفحه‌ی «👥 جفت‌هایِ شیر» همین زیرساخت رو مدیریت و نمایش می‌ده.
# ============================================================================

SHARE_MENU_TEXT = "🔀 شیرِ پست\nکدوم بخش؟"

# 🧠 باکت‌هایِ تعدادِ شیر. پست‌هایِ «تگ‌دار» دیگه یک باکت نیستن: با post_models به
# چهار مدل تفکیک می‌شن و هر مدل تعدادِ مستقلِ خودش رو داره.
_AS_BUCKET_LABELS = {
    "with_tag_m1": "1️⃣ معرفی (اورجینال/نیم‌بها + آیدی)",
    "with_tag_m2": "2️⃣ اطلاعاتی + لینکِ شیشه‌ای",
    "with_tag_m3": "3️⃣ فایلِ فیلم (کیفیت + لینک)",
    "with_tag_m4": "4️⃣ متفرقه (تیزر/کلیپ/اعلان)",
    "with_tag": "🏷 پست‌هایِ تگ‌دار (تنظیمِ قدیمی)",
    "without_tag": "◽️ بی‌تگ و بی‌شکل",
    "default": "⚙️ همه‌ی پست‌ها",
}

# ترتیبی که ویزارد سؤال می‌پرسه و منویِ ویرایش نشون می‌ده
_AS_TAG_BUCKET_ORDER = list(post_models.MODEL_BUCKETS) + ["without_tag"]

# نامِ حالتِ انتظارِ متن برایِ هر باکت (هر باکت سؤالِ خودش رو داره)
_AS_COUNT_AWAITING = {
    "with_tag_m1": "autoshare_count_m1",
    "with_tag_m2": "autoshare_count_m2",
    "with_tag_m3": "autoshare_count_m3",
    "with_tag_m4": "autoshare_count_m4",
    "without_tag": "autoshare_count_without_tag",
    "default": "autoshare_count",
}
_AS_AWAITING_BUCKET = {v: k for k, v in _AS_COUNT_AWAITING.items()}


def _as_next_tag_bucket(bucket: str):
    """باکتِ بعدی توی ویزارد - None یعنی همه‌ی سؤال‌هایِ تعداد تموم شده."""
    if bucket not in _AS_TAG_BUCKET_ORDER:
        return None
    i = _AS_TAG_BUCKET_ORDER.index(bucket) + 1
    return _AS_TAG_BUCKET_ORDER[i] if i < len(_AS_TAG_BUCKET_ORDER) else None


def share_mode_keyboard():
    kb = [
        ["📍 شیر کردنِ یک‌باره"],
        ["🔁 شیرِ خودکار"],
        ["👥 جفت‌هایِ شیر"],
        ["🔙 بازگشت"],
    ]
    return ReplyKeyboardMarkup(kb, resize_keyboard=True)


def _fmt_share_range(rng) -> str:
    """(lo, hi) رو خوانا می‌کنه - برایِ عددِ تکی lo == hi"""
    if not rng:
        return "—"
    lo, hi = rng
    if hi > lo:
        return f"رندوم بینِ {lo} تا {hi}"
    return str(hi)


def _as_channel_label(row) -> str:
    """برچسبِ نمایشیِ کانالِ شیرِ خودکار - عمومی @یوزرنیم، خصوصی عنوانِ کانال"""
    if not row:
        return "پیدا نشد"
    if row.get("is_private"):
        title = row.get("channel_title") or f"کانالِ خصوصی {row.get('channel_id') or ''}"
        return f"🔒 {title}"
    return f"@{(row.get('channel_username') or '').lstrip('@')}"


def _as_bucket_range(context, bucket: str) -> tuple:
    """بازه‌ای که کاربر توی ویزارد برایِ این باکت داده (هنوز ذخیره‌ی دیتابیس نشده)"""
    ranges = context.user_data.get("as_bucket_ranges") or {}
    if bucket in ranges:
        return ranges[bucket]
    # کلیدهایِ نسخه‌یِ قبلی - اگه گفت‌وگویی نیمه‌کاره مونده باشه از دست نره
    if bucket == "without_tag":
        return context.user_data.get("as_range_without_tag", (0, 0))
    if bucket == "default":
        return context.user_data.get("as_range", (0, 0))
    return (0, 0)


def _as_set_bucket_range(context, bucket: str, rng: tuple) -> None:
    context.user_data.setdefault("as_bucket_ranges", {})[bucket] = rng


def _as_wizard_summary(context) -> str:
    """خلاصه‌یِ عددهایی که تا این‌جا برایِ هر مدل گرفته شده"""
    ranges = context.user_data.get("as_bucket_ranges") or {}
    if not ranges:
        return ""
    lines = []
    for b in _AS_TAG_BUCKET_ORDER + ["default"]:
        if b in ranges:
            lines.append(f"• {_AS_BUCKET_LABELS[b]}: {_fmt_share_range(ranges[b])} شیر")
    return "\n".join(lines)


# ===================== ظرفیتِ شیر =====================

async def _share_potential(country_code: str = None) -> dict:
    """
    دو عدد که برایِ اعتبارسنجیِ ورودیِ کاربر لازمن:
      • ready   = چند شیر *همین الان* ممکنه (اکانت‌هایی که جفتشون آماده‌ست)
      • potential = چند شیر *در نهایت* ممکن می‌شه، وقتی همه‌ی جفت‌ها آماده شدن
        (چون مخاطب‌گیری به‌مرورِ زمانه، ثبتِ سفارش نباید معطلِ اون بمونه)
    """
    ready = await peer_share.share_capacity(country_code)
    # برایِ «ظرفیتِ نهایی» عمداً قرنطینه لحاظ نمی‌شه: قرنطینه موقتیه و چند ساعت بعد
    # خودش تموم می‌شه، پس نباید جلویِ *ثبتِ* سفارش رو بگیره - فقط جلویِ اجرایِ
    # همین‌لحظه‌شو می‌گیره (که اون هم خودکار عقب می‌افته، نه شکست).
    accounts = await get_all_accounts()
    usable = [a for a in accounts if activity_guard.is_usable(a)]
    if country_code:
        usable = [a for a in usable if a.get("country_code") == country_code]
    # جفت دو‌نفره‌ست، پس اگه تعداد فرد باشه یکی بی‌جفت می‌مونه و نمی‌تونه شیر کنه
    potential = (len(usable) // 2) * 2
    return {"ready": ready, "potential": max(ready, potential)}


def _share_capacity_hint(cap: dict) -> str:
    if cap["ready"] >= cap["potential"] and cap["ready"] > 0:
        return f"ظرفیتِ شیر: {cap['ready']} (همه‌ی جفت‌ها آماده‌ن ✅)"
    return (
        f"ظرفیتِ شیرِ فعلی: {cap['ready']} - ظرفیتِ نهایی بعدِ آماده‌شدنِ همه‌ی جفت‌ها: "
        f"{cap['potential']}\n"
        "ℹ️ جفت‌ها عمداً به‌مرورِ زمان مخاطبِ همدیگه می‌شن (برایِ سلامتِ اکانت‌ها)، پس "
        "می‌تونی همین حالا عددِ نهایی رو بذاری - هرچی جفت آماده بشه، خودکار استفاده می‌شه."
    )


# ===================== صفحه‌یِ «👥 جفت‌هایِ شیر» =====================

_SP_STATE_LABELS = {
    "pending": "⏳ در صفِ مخاطب‌گیری",
    "contact_exchange": "🤝 در حالِ مخاطب‌شدن",
    "ready": "✅ آماده",
    "failed": "❌ ناموفق",
    "dead": "🪦 مرده",
}

_SP_PAGE_SIZE = 8


async def build_share_pairs_view():
    """
    صفحه‌ی اصلیِ «👥 جفت‌هایِ شیر»: ظرفیت + صف + دکمه‌هایِ مدیریت.
    (جایگزینِ صفحه‌ی قدیمیِ «گروه‌هایِ شیر» - اون روش کاملاً حذف شد.)
    """
    st = await peer_share.status_summary()
    lo, hi = await peer_share.get_build_gap_range()
    autobuild = await peer_share.is_autobuild_enabled()

    lines = [
        "👥 جفت‌هایِ شیر",
        "",
        "هر شیر یه فورواردِ واقعیِ پست توی چتِ خصوصیِ دو اکانتِ جفت‌شده‌ست - چون تلگرام "
        "فقط همین رو به‌عنوانِ Share می‌شماره.",
        "دو اکانتِ هر جفت اول شماره‌یِ همدیگه رو مخاطب می‌کنن، بعد قبلِ فرستادنِ پست "
        "سلام و احوال‌پرسی می‌کنن و بعدِ دیدنِ پست تشکر - با جمله‌هایِ متفاوت، تا "
        "رفتارشون کاملاً طبیعی باشه.",
        "",
        f"🎯 ظرفیتِ شیرِ همین‌الان: {st['share_capacity']}",
        f"✅ جفتِ آماده: {st['ready']} · ⏳ در صف: {st['queued']}"
        + (f" · ❌ ناموفق: {st['failed']}" if st.get("failed") else ""),
        f"👤 اکانت‌هایِ داخلِ جفت‌ها: {st['accounts_in_pairs']}",
        f"🔀 مجموعِ شیرهایِ انجام‌شده: {st['shares_done']}",
        "",
        f"⚙️ جفت‌کردنِ خودکار: {'روشن ▶️' if autobuild else 'خاموش ⏸'}",
        f"⏱ فاصله‌ی مخاطب‌گیری: هر {lo} تا {hi} دقیقه (رندوم)",
        "",
        "ℹ️ مخاطب‌گیری عمداً «قطره‌قطره» انجام می‌شه - اضافه‌کردنِ انبوهِ مخاطب توی "
        "زمانِ کوتاه یکی از واضح‌ترین نشونه‌هایِ رباته.",
    ]

    kb = [
        [InlineKeyboardButton("➕ همین حالا یه جفت آماده کن", callback_data="sg_build")],
        [
            InlineKeyboardButton("⏱ فاصله‌ی مخاطب‌گیری", callback_data="sg_gap"),
            InlineKeyboardButton(
                "⏸ خاموش‌کردنِ جفت‌کردنِ خودکار" if autobuild else "▶️ روشن‌کردنِ جفت‌کردنِ خودکار",
                callback_data="sg_toggle",
            ),
        ],
        [
            InlineKeyboardButton("📋 لیستِ جفت‌ها", callback_data="sg_list_0"),
            InlineKeyboardButton("🧹 پاکسازیِ جفت‌هایِ خراب", callback_data="sg_clean"),
        ],
        [InlineKeyboardButton("🔙 بازگشت", callback_data="as_home")],
    ]
    return "\n".join(lines), InlineKeyboardMarkup(kb)


async def build_share_pairs_list(page: int = 0):
    """لیستِ صفحه‌بندی‌شده‌یِ جفت‌ها - برایِ عیب‌یابی (کدوم جفت گیر کرده و چرا)."""
    pairs = await get_peer_pairs()
    if not pairs:
        return (
            "📋 لیستِ جفت‌هایِ شیر\n\nهنوز هیچ جفتی ثبت نشده.\n"
            "به‌محضِ اینکه ۲ اکانتِ سالمِ بی‌جفت داشته باشی، خودکار جفت می‌شن.",
            InlineKeyboardMarkup([[InlineKeyboardButton("🔙 بازگشت", callback_data="sg_home")]])
        )

    accounts = {a["id"]: a for a in await get_all_accounts()}

    def _label(account_id):
        acc = accounts.get(account_id) or {}
        return acc.get("nickname") or acc.get("phone") or f"#{account_id}"

    pages = max(1, (len(pairs) + _SP_PAGE_SIZE - 1) // _SP_PAGE_SIZE)
    page = max(0, min(int(page or 0), pages - 1))
    chunk = pairs[page * _SP_PAGE_SIZE:(page + 1) * _SP_PAGE_SIZE]

    lines = [f"📋 لیستِ جفت‌هایِ شیر (صفحه‌ی {page + 1} از {pages})", ""]
    for pr in chunk:
        label = _SP_STATE_LABELS.get(pr.get("state"), pr.get("state") or "؟")
        lines.append(
            f"#{pr['id']} · {_label(pr['account_a_id'])} ↔ {_label(pr['account_b_id'])} · {label}"
        )
        lines.append(
            f"   🤝 مخاطب‌شده: {pr.get('members_ready') or 0}/{pr.get('members_total') or 0}"
            f" · 🔀 شیر: {pr.get('shares_done') or 0}"
            f" · 💬 گفت‌وگو: {pr.get('chats_done') or 0}"
        )
        if pr.get("last_error"):
            lines.append(f"   ⚠️ {str(pr['last_error'])[:110]}")
        lines.append("")

    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton("⬅️ قبلی", callback_data=f"sg_list_{page - 1}"))
    if page < pages - 1:
        nav.append(InlineKeyboardButton("بعدی ➡️", callback_data=f"sg_list_{page + 1}"))
    kb = [nav] if nav else []
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data="sg_home")])
    return "\n".join(lines), InlineKeyboardMarkup(kb)


