def _as_fmt_count(count_row) -> str:
    if not count_row:
        return "—"
    lo = count_row.get("total_min")
    hi = count_row.get("total_max")
    if lo and hi and hi > lo:
        return f"🎲 هر پست رندوم بینِ {lo} تا {hi} شیر"
    return f"📌 هر پست {hi or lo or 0} شیر"


