# ===================== 🔬 تستِ تشخیصِ مدلِ پست =====================
# هدف: قبل از اینکه پستِ واقعی بیاد، ادمین بتونه مطمئن بشه ربات هر قالبِ پست رو جزوِ
# کدوم مدل می‌شناسه. عمداً پست رو با اکانتِ ناظر *از خودِ کانال* می‌خونیم و نه از
# پیامِ فوروارد‌شده - چون فورواردِ پست به ربات، دکمه‌هایِ شیشه‌ای (قاطع‌ترین سیگنالِ
# مدل ۲) رو از دست می‌ده و نتیجه‌ی تست با واقعیت فرق می‌کرد.

AS_PROBE_PROMPT = (
    "🔬 تستِ تشخیصِ مدل\n\n"
    "یه پست از داخلِ همین کانال این‌جا فوروارد کن (یا فقط شماره‌ی پست / لینکش رو "
    "بفرست) تا بگم جزوِ کدوم مدل حسابش می‌کنم و چند شیر می‌خوره.\n\n"
    "هر چند پست که خواستی می‌تونی پشتِ‌سرهم بفرستی."
)


def _as_probe_extract_id(message):
    """شماره‌ی پست رو از فورواردِ کانال، لینکِ t.me یا عددِ خالی درمی‌آره."""
    origin = getattr(message, "forward_origin", None)
    if isinstance(origin, MessageOriginChannel):
        mid = getattr(origin, "message_id", None)
        if mid:
            return int(mid)
    raw = (getattr(message, "text", None) or getattr(message, "caption", None) or "")
    raw = raw.strip().translate(_FA_DIGITS)
    nums = re.findall(r"\d+", raw)
    return int(nums[-1]) if nums else None


async def _as_run_probe(message, context, admin_id: str):
    """یه پستِ مشخص رو با همون منطقِ حلقه‌ی شیرِ خودکار تشخیص می‌ده و توضیح می‌ده."""
    asid = context.user_data.get("as_probe_id")
    row = await get_auto_share_channel(asid, admin_id) if asid else None
    if not row:
        context.user_data.pop("awaiting", None)
        context.user_data.pop("as_probe_id", None)
        await message.reply_text("این کانال پیدا نشد (شاید حذف شده).")
        return

    message_id = _as_probe_extract_id(message)
    if not message_id:
        await message.reply_text(
            "نتونستم شماره‌ی پست رو پیدا کنم. یه پست از داخلِ کانال فوروارد کن، یا "
            "شماره‌ی پست (مثلاً 1042) یا لینکش رو بفرست."
        )
        return

    watcher_id = row.get("watcher_account_id")
    watcher = await get_account(watcher_id) if watcher_id else None
    if not watcher or not watcher["is_logged_in"]:
        context.user_data.pop("awaiting", None)
        await message.reply_text(
            "اکانتِ ناظرِ این کانال لاگین نیست - تا وقتی درست نشه نه تست کار می‌کنه نه "
            "خودِ شیرِ خودکار."
        )
        return

    ref = auto_share.channel_ref_from_row(row)
    status = await message.reply_text(f"🔬 در حالِ خوندنِ پستِ #{message_id} از کانال...")
    try:
        post = await fetch_channel_message(
            watcher["session_file"], is_private=ref["is_private"],
            username=ref["username"], channel_id=ref["channel_id"],
            message_id=message_id,
        )
    except Exception as e:
        await status.edit_text(f"❌ نشد پست رو بخونم: {friendly_error(e)}")
        return
    if post is None:
        await status.edit_text(
            f"❌ پستِ #{message_id} توی این کانال پیدا نشد (پاک شده یا شماره‌ش اشتباهه)."
        )
        return

    tags = await get_auto_share_tags(asid)
    tag_usernames = [t["tag_username"] for t in tags]
    tag_matched = bool(tag_usernames) and message_matches_any_tag(post, tag_usernames)
    decision = post_models.resolve_bucket(
        post, tag_matched=tag_matched, has_tags=bool(tag_usernames)
    )
    counts = await get_all_auto_share_counts(asid)
    used = next((b for b in decision["fallbacks"] if b in counts), None)
    cls = decision["classification"]

    lines = [f"🔬 پستِ #{message_id} - {_as_channel_label(row)}", ""]
    lines.append(f"🏷 تگِ ثبت‌شده: {'✅ داره' if tag_matched else '❌ نداره'}")
    if cls:
        f = cls.features
        bits = [f"رسانه: {f.media_kind}"]
        if f.duration:
            bits.append(f"مدت: {f.duration}s")
        if f.buttons:
            bits.append(f"دکمه‌یِ شیشه‌ای: {len(f.buttons)}")
        lines.append("📄 " + " · ".join(bits))
        lines.append("")
        lines.append(cls.explain())
    lines.append("")
    lines.append(f"📦 باکتِ نهایی: {_AS_BUCKET_LABELS.get(decision['bucket'], decision['bucket'])}")
    if used:
        note = ""
        if used != decision["bucket"]:
            note = f" (از تنظیمِ «{_AS_BUCKET_LABELS.get(used, used)}»)"
        lines.append(f"🔢 تعدادِ شیر: {_as_fmt_count(counts.get(used))}{note}")
    else:
        lines.append("⚠️ برایِ این باکت هیچ تعدادی تنظیم نشده - این پست شیر نمی‌خوره. "
                     "از منویِ ویرایش تنظیمش کن.")

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("🔙 پایانِ تست", callback_data=f"as_probe_end_{asid}")],
    ])
    await status.edit_text("\n".join(lines), reply_markup=kb)


# ===================== 🗂 سفارش‌ها (بازدید / ری‌اکشن / شیر) =====================
# کلِ منطقِ رندر و صفحه‌بندی به orders_view.py منتقل شد و هر سه بخش از *همون یک*
# ماژول می‌آن. این‌جا فقط چسبِ تلگرامیه: نقشه‌ی کیبورد → InlineKeyboardMarkup.
#
# چی عوض شد و چرا:
#   • قبلاً فقط شیر نمایِ صفحه‌بندی‌شده داشت. بازدید و ری‌اکشن به‌ازایِ هر پست یه
#     پیامِ جدا می‌فرستادن - با ۴۰ پست یعنی ۴۰ پیام، و آمارِ «لغوشده/پاک‌شده» هم
#     هیچ‌جا دیده نمی‌شد. حالا هر سه: یک پیامِ شیشه‌ای، صفحه‌بندیِ واقعی، خلاصه‌ی
#     آمار، صفحه‌ی جزئیات، و لغوِ باقی‌مونده‌ها.
#   • ⚠️ یه باگِ واقعیِ کنارِ راه هم رفع شد: تابعِ _fmt_numِ این بخش، _fmt_numِ
#     بالاترِ فایل (که «۵.۵» رو ۵.۵ نشون می‌داد) رو *سایه* می‌انداخت - چون هم‌نام
#     بود و پایین‌تر تعریف می‌شد. نتیجه‌ش این بود که همه‌ی عددهایِ اعشاریِ پنلِ
#     «🎭 رفتارِ اکانت‌ها» و «فاصله‌یِ چرخه» گرد و غلط نشون داده می‌شدن
#     (مثلاً «هر ۳ ساعت» به‌جایِ «هر ۳.۴ ساعت»). حالا اون تابع این‌جا نیست.


def _kb(spec):
    """نقشه‌ی کیبوردِ orders_view → کیبوردِ شیشه‌ایِ تلگرام."""
    rows = []
    for row in spec or []:
        buttons = []
        for b in row:
            if b.get("url"):
                buttons.append(InlineKeyboardButton(b["label"], url=b["url"]))
            else:
                buttons.append(InlineKeyboardButton(b["label"], callback_data=b["cb"]))
        if buttons:
            rows.append(buttons)
    return InlineKeyboardMarkup(rows) if rows else None


async def _share_capacity_line():
    """خطِ «ظرفیتِ آماده‌یِ همین‌الان» - فقط شیر ظرفیتِ جفتی داره."""
    try:
        capacity = await peer_share.share_capacity()
    except Exception:
        return None
    if capacity is None:
        return None
    return f"🎯 ظرفیتِ آماده‌یِ همین‌الان: {orders_view.fmt_num(capacity)} جفت"


async def build_orders_page(admin_id: str, kind: str, scope: str = "active", page: int = 0):
    """یه صفحه از «🗂 سفارش‌ها»یِ یه نوع - متن + کیبوردِ شیشه‌ای."""
    capacity_line = await _share_capacity_line() if kind == "share" else None
    text, spec = await orders_view.build_orders_page(
        admin_id, kind, scope, page, capacity_line=capacity_line)
    return text, _kb(spec)


