async def _ord_edit(query, text, markup):
    """
    ادیتِ پیامِ سفارش‌ها - اگه متن عوض نشده باشه تلگرام خطا می‌ده و اون خطا نباید به
    کاربر به‌شکلِ «هیچی نشد» برسه (مثلاً وقتی «🔄 بروزرسانی» رو می‌زنه و واقعاً چیزی
    عوض نشده).
    """
    try:
        await query.edit_message_text(text, reply_markup=markup,
                                      disable_web_page_preview=True)
    except Exception:
        try:
            await query.answer("همون وضعیتِ قبله ✅")
        except Exception:
            pass


# نامِ قبلی، برایِ مسیرهایی که هنوز صداش می‌زنن
_sho_edit = _ord_edit


async def send_orders(message, admin_id: str, kind: str, status: str = "active"):
    """
    «🗂 سفارش‌ها ← (👁 ویو / 👍 ری‌اکشن / 🔀 شیر)». سه دسته، دقیقاً یک رفتار برایِ هر سه:
      active → سفارش‌هایِ یک‌باره‌یِ در حالِ اجرا + لیستِ صفحه‌بندی‌شده‌ی پست‌هایِ صف‌دار
      done   → سفارش‌هایِ یک‌باره‌یِ تمام‌شده/قطع‌شده + لیستِ پست‌هایِ تمام‌شده
      future → کانال‌هایی که ثبت شدن ولی هنوز صفی ندارن (منتظرِ پستِ جدید)

    ⚠️ پنجره‌ی «✅ تمام‌شده» دقیقاً همون FINISHED_ORDER_RETENTION_HOURSِ پاکسازیه
    (۲۴ ساعت): چیزی که نمایش داده می‌شه هنوز در دیتابیسه، و چیزی که از دیتابیس رفته
    ادعای وجود نمی‌کنه. قبلاً این‌جا ۳ روز خونده می‌شد - یعنی پنل سه روز سراغِ
    ردیف‌هایی می‌رفت که خیلی وقت بود پاک شده بودن.
    """
    kind = orders_view.kind_of(kind)
    if status == "future":
        text, markup = await build_future_orders_view(admin_id, kind)
        await message.reply_text(text, reply_markup=markup, disable_web_page_preview=True)
        if kind == "view":
            # «📅 تمام (پست‌هایِ کانال، روزانه)» صفِ ردیفی نداره، پس بلوکِ خودش رو داره
            _, av_future = await _auto_view_all_status_blocks(admin_id)
            for text, kb, mode in av_future:
                await message.reply_text(text, reply_markup=kb, parse_mode=mode)
        return

    want_active = status != "done"
    if want_active:
        for entry in get_active_batches(admin_id, kind):
            progress = entry["progress"]
            await message.reply_text(
                progress.format(),
                reply_markup=_job_refresh_keyboard(progress.id,
                                                   show_cancel=not progress.finished),
            )
    else:
        since_iso = finished_order_cutoff_iso()
        blocks = []
        try:
            for job in await get_recent_finished_batch_jobs(admin_id, kind,
                                                            since_iso=since_iso, limit=10):
                blocks.append(_format_finished_batch_job(job))
        except Exception as e:
            print(f"⚠️  خواندنِ سفارش‌هایِ تمام‌شده با خطا مواجه شد: {e}")
        try:
            for job in await get_recent_interrupted_batch_jobs(admin_id, kind,
                                                               since_iso=since_iso, limit=10):
                blocks.append(_format_interrupted_batch_job(job))
        except Exception as e:
            print(f"⚠️  خواندنِ سفارش‌هایِ قطع‌شده با خطا مواجه شد: {e}")
        for text in blocks:
            await message.reply_text(text)

    text, markup = await build_orders_page(
        admin_id, kind, "active" if want_active else "done", 0)
    await message.reply_text(text, reply_markup=markup, disable_web_page_preview=True)

    if kind == "view" and want_active:
        av_active, _ = await _auto_view_all_status_blocks(admin_id)
        for text, kb, mode in av_active:
            await message.reply_text(text, reply_markup=kb, parse_mode=mode)


