async def _as_prompt_tags(message):
    await message.reply_text(
        "🆔 تگ(هایی) که زیرِ پست‌ها می‌ذاری رو بفرست - هر خط یه تگ، مثلاً:\n"
        "🆔 @FilmNete\n🆔 @Partner2\n\n"
        "ربات پست‌هایی که هرکدوم از این تگ‌ها زیرشون هست رو از بقیه جدا می‌کنه، و "
        "بعدش خودش اون‌ها رو به ۴ «مدلِ پست» تفکیک می‌کنه تا برایِ هر مدل تعدادِ شیرِ "
        "جدا بذاری:\n\n"
        "1️⃣ پستِ معرفی (اورجینال و بدون رمز + نیم‌بها + آیدیِ کانالِ سریال)\n"
        "2️⃣ پستِ اطلاعاتی با لینکِ شیشه‌ای («دانلود کیفیت 480p» و …)\n"
        "3️⃣ فایلِ خودِ فیلم/قسمت (کیفیت + لینکِ دانلود توی کپشن)\n"
        "4️⃣ متفرقه (تیزر، کلیپ، اعلانِ زمانِ پخش و …)\n\n"
        "🧠 تشخیص رویِ *ساختارِ* پست انجام می‌شه نه اسمِ فیلم - پس هر سریالِ جدیدی هم "
        "که بذاری، درست دسته‌بندی می‌شه.\n\n"
        "اگه نمی‌خوای از این قابلیت استفاده کنی، فقط یه خط تیره (-) بفرست."
    )


async def _as_register_from_forward(update, context, origin, admin_id: str) -> bool:
    """
    ثبتِ کانالِ شیرِ خودکار از رویِ یه پستِ فوروارد‌شده - هم عمومی هم خصوصی.
    برایِ خصوصی، چون ربات ادمینِ کاناله خودش لینکِ دعوت می‌سازه (همون منطقِ
    _ar_make_invite_link که برایِ ری‌اکشنِ خودکار هم استفاده می‌شه).
    """
    chat = origin.chat
    username = getattr(chat, "username", None)
    title = getattr(chat, "title", None) or username or "کانال"

    if username:
        context.user_data["as_username"] = username
        context.user_data["as_is_private"] = False
        context.user_data["as_channel_id"] = None
        context.user_data["as_invite_link"] = None
        context.user_data["as_title"] = title
        context.user_data["_chat_id"] = update.effective_chat.id
        context.user_data["_admin_id"] = admin_id
        context.user_data["awaiting"] = "autoshare_tag"
        await update.message.reply_text(f"✅ کانالِ «{title}» (@{username}) ثبت شد.")
        await _as_prompt_tags(update.message)
        return True

    raw_id = _extract_raw_channel_id(chat.id)
    if not raw_id:
        await update.message.reply_text(
            "❌ نتونستم شناسه‌یِ این کانال رو بخونم. دوباره یه پست ازش فوروارد کن."
        )
        return False

    status = await update.message.reply_text("🔗 در حالِ ساختنِ لینکِ دعوت...")
    link_res = await _ar_make_invite_link(context, chat.id)
    if link_res["status"] != "success":
        try:
            await status.edit_text(f"❌ {link_res['message']}")
        except Exception:
            await update.message.reply_text(f"❌ {link_res['message']}")
        return False

    context.user_data["as_username"] = None
    context.user_data["as_is_private"] = True
    context.user_data["as_channel_id"] = raw_id
    context.user_data["as_invite_link"] = link_res["link"]
    context.user_data["as_title"] = title
    context.user_data["_chat_id"] = update.effective_chat.id
    context.user_data["_admin_id"] = admin_id
    context.user_data["awaiting"] = "autoshare_tag"

    try:
        await status.edit_text(
            f"✅ کانالِ خصوصیِ «{title}» ثبت شد.\n"
            f"🔗 لینکِ دعوت رو خودم ساختم - لازم نیست چیزی بفرستی.\n\n"
            f"👥 اکانتِ ناظر خودکار عضوِ کانال می‌شه تا پست‌هایِ جدید رو ببینه."
        )
    except Exception:
        pass
    await _as_prompt_tags(update.message)
    return True


async def _as_ask_count(message, context, bucket: str):
    """
    پرسیدنِ تعدادِ شیرِ یه باکت - عددِ ثابت یا بازه.
    برایِ چهار مدلِ پست، سؤال با توضیحِ خودِ مدل همراهه تا ادمین بدونه دقیقاً داره
    برایِ چه‌شکل پستی عدد می‌ذاره.
    """
    country = context.user_data.get("as_country")
    cap = await _share_potential(country)
    context.user_data["as_current_bucket"] = bucket
    context.user_data["awaiting"] = _AS_COUNT_AWAITING.get(bucket, "autoshare_count")

    model = post_models.MODEL_BY_BUCKET.get(bucket)
    if model:
        step = post_models.MODEL_BUCKETS.index(bucket) + 1
        head = (
            f"🧠 مدلِ {step} از ۴ ▸ {post_models.MODEL_LABELS[model]}\n\n"
            f"{post_models.MODEL_HINTS[model]}\n\n"
            "این مدل رویِ هر پست چند شیر بخوره؟"
        )
    elif bucket == "without_tag":
        head = (
            "◽️ پست‌هایی که نه تگِ تو رو دارن و نه شکلِ هیچ‌کدوم از اون ۴ مدل رو "
            "(پستِ کاملاً بی‌ربطِ کانال) چند شیر بخورن؟\n\n"
            "اگه نمی‌خوای این‌ها شیر بخورن، 0 بفرست."
        )
    else:
        head = "هر پستِ جدید چند شیر بخوره؟"

    tail = ""
    if model and step > 1:
        summary = _as_wizard_summary(context)
        if summary:
            tail = f"\n\nتا این‌جا:\n{summary}"
    await message.reply_text(
        f"{head}\n\n"
        "💡 می‌تونی یه عددِ ثابت بدی (مثلاً 8) یا یه بازه (مثلاً 5-10) - با بازه، هر "
        "پست یه تعدادِ رندومِ متفاوت از توی اون بازه می‌گیره. برایِ «هیچی» 0 بفرست.\n\n"
        f"{_share_capacity_hint(cap)}{tail}"
    )


async def _as_after_count(message, context, bucket: str):
    """
    بعدِ ثبتِ تعدادِ یه باکت می‌ریم سراغِ باکتِ بعدی (مدل ۱ → ۲ → ۳ → ۴ → بی‌تگ) و
    وقتی همه‌شون گرفته شد، آخرین قدم (زمان‌بندی) رو می‌پرسیم.
    """
    nxt = _as_next_tag_bucket(bucket)
    if nxt:
        await _as_ask_count(message, context, nxt)
        return
    context.user_data.pop("awaiting", None)
    context.user_data.pop("as_current_bucket", None)
    summary = _as_wizard_summary(context) or (
        f"{_fmt_share_range(_as_bucket_range(context, bucket))} شیر رویِ هر پست"
    )
    markup = timing_picker_keyboard("as_tim_now", "as_tim_sched")
    await message.reply_text(
        f"✅ تعدادها ثبت شد:\n{summary}\n\n"
        "شیرهایِ هر پستِ جدید چطور انجام بشن؟",
        reply_markup=markup
    )


async def _finalize_autoshare(context):
    """ثبتِ نهاییِ شیرِ خودکار بعدِ جمع‌شدنِ همه‌ی اطلاعات"""
    chat_id = context.user_data.get("_chat_id")
    admin_id = context.user_data.get("_admin_id")
    username = context.user_data.pop("as_username", None)
    is_private = context.user_data.pop("as_is_private", False)
    channel_id = context.user_data.pop("as_channel_id", None)
    invite_link = context.user_data.pop("as_invite_link", None)
    as_title = context.user_data.pop("as_title", None)
    country = context.user_data.pop("as_country", None)
    spread_start = context.user_data.pop("as_spread_start", 0)
    spread_end = context.user_data.pop("as_spread_end", 0)
    tags = context.user_data.pop("as_tags", None)
    bucket_ranges = dict(context.user_data.pop("as_bucket_ranges", None) or {})
    # کلیدهایِ نسخه‌یِ قبلیِ ویزارد (اگه گفت‌وگویی نصفه مونده بود)
    legacy_without = context.user_data.pop("as_range_without_tag", None)
    legacy_default = context.user_data.pop("as_range", None)
    context.user_data.pop("as_range_with_tag", None)
    if legacy_without and "without_tag" not in bucket_ranges:
        bucket_ranges["without_tag"] = legacy_without
    if legacy_default and "default" not in bucket_ranges:
        bucket_ranges["default"] = legacy_default
    range_default = bucket_ranges.get("default")
    context.user_data.pop("as_current_bucket", None)
    context.user_data.pop("awaiting", None)
    context.user_data.pop("_chat_id", None)
    context.user_data.pop("_admin_id", None)

    accounts = await get_all_accounts()
    pool = _pool_by_country(accounts, country)

    has_channel = (channel_id and invite_link) if is_private else bool(username)
    effective = 0
    if tags:
        # بزرگ‌ترین عددِ بینِ چهار مدل و باکتِ بی‌تگ - این‌قدر ظرفیت لازمه
        effective = max([(bucket_ranges.get(b) or (0, 0))[1]
                         for b in _AS_TAG_BUCKET_ORDER] or [0])
    else:
        effective = (range_default or (0, 0))[1]

    if not pool or not has_channel or effective <= 0:
        await context.bot.send_message(chat_id, "مشکلی پیش اومد - از اول امتحان کن.")
        return

    title = as_title or username or "کانالِ خصوصی"
    watcher = pool[0]

    # اکانتِ ناظر باید *قبل از* خوندنِ آخرین پست عضوِ کانال باشه، وگرنه برایِ کانالِ
    # خصوصی حتی resolve هم شکست می‌خوره و last_id خالی می‌مونه
    if is_private:
        member = await ensure_member_for_reactions(
            watcher["session_file"], is_private=True,
            channel_id=int(channel_id), invite_link=invite_link,
        )
        if member["status"] not in ("member", "joined"):
            await context.bot.send_message(
                chat_id,
                f"❌ اکانتِ ناظر نتونست عضوِ کانال بشه: {member.get('message', member['status'])}\n\n"
                "کانال ثبت نشد - دوباره امتحان کن."
            )
            return

    try:
        if is_private:
            last_id = await get_latest_message_id_private(watcher["session_file"], int(channel_id))
        else:
            last_id = await get_latest_message_id(watcher["session_file"], username)
    except Exception:
        last_id = 0

    result = await add_auto_share(
        username, watcher["id"], last_id, country_code=country, admin_id=admin_id,
        spread_start_hours=spread_start, spread_end_hours=spread_end,
        is_private=is_private, channel_id=channel_id, invite_link=invite_link,
        channel_title=title,
    )

    if result["status"] != "success":
        await context.bot.send_message(chat_id, f"❌ خطا: {result.get('message', 'نامشخص')}")
        return

    asid = result["id"]
    if tags:
        await add_auto_share_tags(asid, tags)
        for b in _AS_TAG_BUCKET_ORDER:
            rng = bucket_ranges.get(b)
            if rng:
                await set_auto_share_count(asid, b, rng[0], rng[1])
    elif range_default:
        await set_auto_share_count(asid, "default", range_default[0], range_default[1])

    if spread_end and spread_end > 0:
        spread_text = (
            f"از {_fmt_hours(spread_start)} تا {_fmt_hours(spread_end)} بعدِ هر پست، "
            "رندوم پخش می‌شه"
        )
    else:
        spread_text = "فوری انجام می‌شه"
    country_text = f"کشورِ {country}" if country else "همه‌ی کشورها"
    channel_label = f"«{title}»" if is_private else f"@{username}"
    cap = await _share_potential(country)

    if tags:
        detail_rows = [f"🆔 {len(tags)} تگ ثبت شد",
                       "🧠 مدلِ هر پست خودکار تشخیص داده می‌شه:"]
        for b in _AS_TAG_BUCKET_ORDER:
            detail_rows.append(f"{_AS_BUCKET_LABELS[b]}: "
                               f"{_fmt_share_range(bucket_ranges.get(b))} شیر")
        detail = "\n".join(detail_rows)
    else:
        detail = f"هر پست: {_fmt_share_range(range_default)} شیر"

    lines = [
        f"✅ شیرِ خودکار برای {channel_label} فعال شد.",
        detail,
        f"({country_text}) - {spread_text}.",
        "",
        "ℹ️ چند نکته:",
        "• فقط پست‌هایِ «جدید» (از همین لحظه به بعد) شیر می‌خورن، نه پست‌هایِ قبلی.",
        "• مبنایِ زمان‌بندی، زمانِ خودِ پست در تلگرامه - نه لحظه‌ای که ربات دیدش.",
        "• هر شیر یه فورواردِ واقعیِ پست توی چتِ خصوصیِ دو اکانتِ جفت‌شده‌ست: قبلش سلام و "
        "احوال‌پرسی می‌کنن، پست فرستاده می‌شه، طرف واقعاً بازش می‌کنه و بعد تشکر می‌کنه.",
        "• جمله‌ها هر بار متفاوتن و فاصله‌یِ بینشون رندومه، تا چت طبیعی به‌نظر بیاد.",
        "• تا وقتی جفتِ دست‌نخورده‌ای هست، هیچ جفتی دو بار همون پست رو نمی‌گیره.",
    ]
    if tags:
        lines += [
            "• 🧠 مدلِ هر پست از رویِ ساختارش تشخیص داده می‌شه (دکمه‌هایِ شیشه‌ای، خطِ "
            "کیفیت، لینکِ دانلود، عبارت‌هایِ معرفی، نوع و مدتِ رسانه) - نه از رویِ اسمِ "
            "فیلم. پس سریالِ جدید هم درست دسته‌بندی می‌شه.",
            "• از منویِ ویرایش، «🔬 تستِ تشخیصِ مدل» رو بزن و یه پست فوروارد کن تا "
            "ببینی ربات اون رو جزوِ کدوم مدل می‌شناسه.",
        ]
    lines += [
        "",
        _share_capacity_hint(cap),
    ]
    if effective > cap["potential"] and cap["potential"] > 0:
        lines += [
            "",
            f"⚠️ حداکثر {effective} شیر خواستی ولی ظرفیتِ نهایی {cap['potential']} ـه. "
            "برایِ ظرفیتِ بیشتر، اکانتِ بیشتری اضافه کن (هر ۲ اکانت = ۲ ظرفیتِ شیر).",
        ]
    await context.bot.send_message(chat_id, "\n".join(lines))

    menu_text, markup = await build_autoshare_menu(admin_id)
    await context.bot.send_message(chat_id, menu_text, reply_markup=markup)


# ===================== شیرِ یک‌باره =====================

async def _run_share_batch(message, context, minutes: int = 0, random_range=None,
                           admin_id: str = None):
    """
    اجرایِ «شیرِ یک‌باره» رویِ یه پستِ مشخص (فوری / پخش‌شده‌ی مساوی / رندومِ بازه‌ای) -
    از همون زیرساختِ سفارش‌هایِ دسته‌ای استفاده می‌کنه که بازدید/ری‌اکشن استفاده می‌کنن،
    پس آمارِ زنده، لغو، و ازسرگیری بعدِ ری‌استارت هم داره.
    """
    link_info = context.user_data.pop("pending_share_link", None)
    count = context.user_data.pop("share_count", 0)
    if not link_info or count <= 0:
        await message.reply_text("مشکلی پیش اومد - از اول امتحان کن.")
        return

    slots = await peer_share.select_share_slots(
        count, country_code=context.user_data.get("share_country_code")
    )
    if not slots:
        await message.reply_text(
            "❌ هیچ جفتِ آماده‌ای برایِ شیر وجود نداره.\n\n"
            "شیر بدونِ جفت ممکن نیست (تلگرام فقط فورواردِ واقعی به یه چتِ دیگه رو "
            "به‌عنوانِ share می‌شماره). از «👥 جفت‌هایِ شیر» وضعیتِ جفت‌ها رو ببین."
        )
        return

    if len(slots) < count:
        await message.reply_text(
            f"ℹ️ {count} شیر خواستی ولی الان فقط {len(slots)} ظرفیت آماده‌ست - "
            f"با همین {len(slots)} ادامه می‌دم.\n"
            "جفت‌هایِ بیشتر به‌مرورِ زمان آماده می‌شن (از «👥 جفت‌هایِ شیر» قابلِ پیگیریه)."
        )

    run_accounts = []
    for slot in slots:
        acc = await get_account(slot["account_id"])
        if not acc:
            continue
        run_accounts.append({**acc, "_share_slot": slot})

    if not run_accounts:
        await message.reply_text("مشکلی پیش اومد - اکانت‌هایِ جفت‌ها خونده نشدن.")
        return

    async def action_fn(item):
        # کلِ گفت‌وگو (سلام → فوروارد → دیده‌شدن → تشکر) داخلِ همین یه تابع انجام می‌شه،
        # پس آمارِ زنده/لغو/ازسرگیریِ سفارش‌ها دقیقاً مثلِ بازدید و ری‌اکشن کار می‌کنه.
        return await peer_share.run_share_conversation(item["_share_slot"], link_info)

    await _launch_batch(
        message, run_accounts, action_fn, minutes, random_range,
        op_label="🔀 شیرِ پست",
        title_immediate="🔀 نتیجه‌ی شیر",
        title_scheduled="🔀 نتیجه‌ی شیرِ زمان‌بندی‌شده",
        title_random="🔀 نتیجه‌ی شیرِ رندوم",
        admin_id=admin_id,
        kind="share",
        # ⚠️ شیر سقفِ زمانیِ خودشو داره (یه گفت‌وگوئه، نه یه درخواست) و چند تاش هم‌زمان
        # اجرا می‌شه - وگرنه با سقفِ ۴۵ ثانیه‌ایِ معمولی اکثرِ شیرها «رد شد» می‌خوردن و
        # ۶۰ شیر ساعت‌ها طول می‌کشید. نگاه کن به scheduling.SHARE_ACTION_TIMEOUT.
        action_timeout=SHARE_ACTION_TIMEOUT,
        max_parallel=SHARE_MAX_PARALLEL,
        gap_range=(SHARE_GAP_MIN, SHARE_GAP_MAX),
    )


