def _format_account_list_page(accounts: list, category_title: str, page: int = 0):
    """
    یه صفحه از یه لیستِ ساده و فقط‌خواندنیِ اکانت‌ها - برایِ دکمه‌ی «📋 لیستِ
    اکانت‌ها» (سه دسته: دستی / سشنی‌بدونِ‌سشنِ‌جدید / سشنی‌با‌سشنِ‌جدید).
    """
    accounts_sorted = sorted(accounts, key=lambda a: int(a.get("id") or 0))
    total = len(accounts_sorted)
    total_pages = max(1, -(-total // ACCOUNTS_PAGE_SIZE))
    page = max(0, min(page, total_pages - 1))
    start = page * ACCOUNTS_PAGE_SIZE
    page_accounts = accounts_sorted[start:start + ACCOUNTS_PAGE_SIZE]

    lines = [f"{category_title} ({total} اکانت)", ""]
    if not page_accounts:
        lines.append("هیچ اکانتی توی این دسته نیست.")
    else:
        for i, acc in enumerate(page_accounts, start=start + 1):
            name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
            phone = acc.get("phone", "")
            lines.append(f"{i}. {name} ({phone})" if phone and phone != name else f"{i}. {name}")
    lines.append("")
    lines.append(f"صفحه‌یِ {page + 1} از {total_pages}")
    return "\n".join(lines), page, total_pages


def _account_list_nav_keyboard(category: str, page: int, total_pages: int):
    row = []
    if page > 0:
        row.append(InlineKeyboardButton("⬅️ قبلی", callback_data=f"acclist_{category}_{page - 1}"))
    if page < total_pages - 1:
        row.append(InlineKeyboardButton("➡️ بعدی", callback_data=f"acclist_{category}_{page + 1}"))
    kb = []
    if row:
        kb.append(row)
    kb.append([InlineKeyboardButton("🔙 بازگشت به دسته‌ها", callback_data="acclist_menu")])
    return InlineKeyboardMarkup(kb)


def _build_migration_select_keyboard(session: "SessionMigrationSelectSession", accounts_state: list, page: int = 0):
    """
    کیبوردِ صفحه‌بندی‌شده‌یِ انتخابِ دستیِ اکانت‌ها برایِ مهاجرتِ سشن. اکانت‌هایِ
    اکانت‌هایِ قبلاً‌تعویض‌شده با 🔄 نشون داده می‌شن (قابلِ‌کلیک هستن،
    ولی کلیک‌کردنشون فقط یه پیامِ توضیحی می‌ده - نگاه کن به هندلرِ callback).
    """
    selected_ids = {a["id"] for a in session.selected_accounts}
    accounts_sorted = sorted(accounts_state, key=lambda a: int(a.get("id") or 0), reverse=session.order_desc)
    total = len(accounts_sorted)
    total_pages = max(1, -(-total // ACCOUNTS_PAGE_SIZE))
    page = max(0, min(page, total_pages - 1))
    start = page * ACCOUNTS_PAGE_SIZE
    page_accounts = accounts_sorted[start:start + ACCOUNTS_PAGE_SIZE]

    kb = []
    for acc in page_accounts:
        name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
        if acc.get("_already_migrated"):
            label = f"🔄 {name} (قبلاً تعویض شده)"
        elif acc.get("_pending_2fa"):
            label = f"🔑 {name} (منتظرِ رمز)"
        elif acc.get("is_frozen"):
            label = f"🧊 {name} (فریزشده)"
        elif acc.get("_quarantined"):
            label = f"🧪 {name} (قرنطینه‌یِ سشنِ تازه)"
        else:
            mark = "☑️" if acc["id"] in selected_ids else "☐"
            label = f"{mark} {name}"
        kb.append([InlineKeyboardButton(label, callback_data=f"bmsel_{page}_{acc['id']}")])

    nav_row = []
    if page > 0:
        nav_row.append(InlineKeyboardButton("⬅️ صفحه قبلی", callback_data=f"bmpage_{page - 1}"))
    if page < total_pages - 1:
        nav_row.append(InlineKeyboardButton("➡️ صفحه بعدی", callback_data=f"bmpage_{page + 1}"))
    if nav_row:
        kb.append(nav_row)
    kb.append([InlineKeyboardButton(f"✅ ادامه ({len(selected_ids)} انتخاب‌شده)", callback_data="bm_manual_continue")])
    kb.append([InlineKeyboardButton("🔙 بازگشت", callback_data="bm_confirm_no")])
    return InlineKeyboardMarkup(kb), page, total_pages, total



def _bulk_migration_status_text(state: dict) -> str:
    total = state.get("total", 0)
    done = state.get("done", 0)
    success = state.get("success", 0)
    failed = state.get("failed", 0)
    recent = state.get("recent") or []
    started_at = state.get("started_at") or time.monotonic()
    elapsed = max(0.001, time.monotonic() - started_at)
    percent = (done / total * 100.0) if total else 0.0
    bar = _cc_progress_bar(percent)
    throughput = done / elapsed if done > 0 else 0.0
    remaining = max(0, total - done)
    eta_text = _format_duration_seconds(remaining / throughput) if throughput > 0 else "درحالِ محاسبه…"
    in_progress = state.get("in_progress") or []
    queued = max(0, remaining - len(in_progress))

    lines = [
        "🧩 ساختِ سشنِ زاپاس" if state.get("mode") == "spare"
        else "🔄 تعویضِ سشنِ قدیمی به سشنِ جدید",
        "",
        f"[{bar}]  {percent:.1f}%",
        f"اکانت‌ها: {done}/{total}   •   ⏱ {_format_duration_seconds(elapsed)}   •   ETA ≈ {eta_text}",
        "",
        f"✅ موفق: {success}   ❌ ناموفق: {failed}",
    ]
    if state.get("already_migrated"):
        lines.append(
            f"⏭ از قبل تعویض‌شده (دست‌نخورده رد شد): {state['already_migrated']}"
        )
    if state.get("spare_built") or state.get("spare_failed"):
        lines.append(
            f"🧩 زاپاسِ تازه: ✅ {state.get('spare_built', 0)}   "
            f"⚠️ ساخته نشد: {state.get('spare_failed', 0)} (خودکار در نوبتِ نگهبانِ زاپاس)"
        )
    if state.get("needs_password"):
        lines.append(
            f"🔑 منتظرِ رمزِ دومرحله‌ای: {state['needs_password']}  "
            "(آخرِ کار یکی‌یکی ازت می‌پرسم)"
        )
    lines.append(f"🔄 درحالِ‌انجامِ واقعی: {len(in_progress)}   🕓 در صف: {queued}")
    if state.get("cancelled") and not state.get("finished"):
        lines.append("⛔️ صف متوقف شده؛ اکانت‌های باقی‌مانده بدون تغییر رد می‌شوند")
    if state.get("retrying"):
        lines.append(f"♻️ درحالِ تلاشِ دوباره (خطایِ گذرا): {state['retrying']}")
    flood_left = state.get("flood_left") or 0
    if flood_left > 0:
        lines.append(
            f"⏸ مکثِ اجباری به‌خاطرِ محدودیتِ تلگرام: {_format_duration_seconds(flood_left)} "
            "باقی مونده (ادامه‌دادن در این حالت به اکانت‌ها آسیب می‌زنه)"
        )
    if state.get("cancelled"):
        lines.append("⏹ توقف درخواست شد - اکانت‌هایِ در جریان تموم می‌شن، بقیه شروع نمی‌شن.")
    if recent:
        lines += ["", "آخرین نتیجه‌ها:"]
        lines += recent[-10:]
    if in_progress and not state.get("finished"):
        lines += ["", "⏳ در حالِ ساختِ سشنِ جدید برایِ:"]
        for lbl in in_progress[:8]:
            lines.append(f"🔄 {lbl}")
    if state.get("finished"):
        skipped = (state.get("skipped") or 0) + (state.get("not_started") or 0)
        if skipped:
            lines += ["", f"⏸ {skipped} اکانت اصلاً شروع نشد و دست‌نخورده موند "
                          f"(توقف، مکثِ طولانیِ تلگرام، یا بی‌حرکتیِ صف). توی لیستِ "
                          f"«واجدِ شرایط» می‌مونن - هیچ‌کدوم گم نشدن."]
        if state.get("stalled"):
            lines += ["", "⚠️ صف بیشتر از حدِ انتظار بی‌حرکت موند و متوقف شد - "
                          "برایِ باقی‌مونده‌ها می‌تونی دوباره امتحان کنی."]
        if state.get("needs_password"):
            lines += ["", f"🔑 {state['needs_password']} اکانت منتظرِ رمزِ دومرحله‌ای‌ان. "
                          "این لیست *ذخیره شد* - حتی با ری‌استارتِ ربات هم گم نمی‌شه و "
                          "دفعه‌یِ بعد به‌عنوانِ لیستِ اولِ همین منو نشونت می‌دم."]
        if state.get("mode") == "spare":
            lines += ["", "✅ تمام شد."]
        else:
            lines += [
                "",
                "✅ تمام شد.",
                "برایِ اکانت‌هایِ موفق: نشست‌هایِ قبلی *قبل* از ساختِ سشنِ جدید بیرون "
                "انداخته شدن، بعد یه سشنِ جدید و یه زاپاسِ تازه ساخته و تست شد، و آخر "
                "هم خودِ سشنِ قدیمی خارج شد - یعنی الان فقط ۲ نشستِ تازه رویِ اکانته: "
                "یکی که ربات باهاش کار می‌کنه و یکی زاپاس.",
                "اگه برایِ اکانتی نشستِ اضافه‌ای لجبازی کرده یا زاپاسش ساخته نشده باشه، "
                "خودکار در نوبت می‌مونه (سشنِ جدید تا ۲۵ ساعت اجازه‌یِ بستنِ نشست نداره) "
                "و ربات خودش بهت خبر می‌ده.",
            ]
    return "\n".join(lines)


async def _run_bulk_migration_queue(
    session: "BulkMigrationSession", status_message, admin_chat_id: str, accounts: list,
    twofa_password: str = None, twofa_passwords: list = None, mode: str = "migrate",
):
    """
    مهاجرتِ *دسته‌ایِ* سشنِ اکانت‌ها - با هم‌زمانیِ محدود (سرعتِ خوب، بدونِ اینکه به
    فلود بخوریم) و آمارِ لحظه‌ای که هر ۱۰ ثانیه خودکار به‌روز می‌شه + دکمه‌ی «🔄
    آپدیتِ آمار» برایِ تازه‌سازیِ فوری. کاملاً در پس‌زمینه اجرا می‌شه - بقیه‌ی ربات
    همزمان قابلِ استفاده‌ست. هم دکمه‌ی «🔄 تعویضِ سشنِ قدیمی به سشنِ جدید» و هم
    ویزاردِ «📥 افزودن با فایلِ سشن» از همین یه تابع استفاده می‌کنن.
    """
    session.running = True
    session.started_at = time.monotonic()
    total = len(accounts)
    state = {
        "total": total, "done": 0, "success": 0, "failed": 0,
        "needs_password": 0,   # منتظرِ رمز - این «شکست» نیست، فقط ناتمومه
        # اصلاً نوبتشون نشد (نگهبانِ بی‌حرکتی یا توقف) - دست‌نخورده‌ن، پس نه «موفق»
        # نه «ناموفق». بدونِ این کلید، همون اکانت‌ها به‌اشتباه «ناموفق» شمرده می‌شدن.
        "not_started": 0,
        "skipped": 0,          # اصلاً شروع نشد (توقفِ کاربر یا مکثِ طولانیِ تلگرام)
        "recent": [], "started_at": session.started_at, "finished": False,
        "in_progress": [],  # اسمِ اکانت‌هایی که همین الان دارن پردازش می‌شن (برایِ آمارِ زنده)
        "retrying": 0,      # چندتا اکانت همین الان بینِ دو تلاش منتظرن (نگاه کن به MIGRATE_MAX_ATTEMPTS)
        "flood_left": 0,    # ثانیه‌یِ باقی‌مانده‌یِ مکثِ اجباری
        "cancelled": False,
        "stalled": False,
        "started_ids": set(),
    }
    state["mode"] = mode
    session.live_state = state

    # ---- ترمزِ سراسریِ فلود ----
    # وقتی تلگرام رویِ *ورود* محدودیت می‌ده، ادامه‌دادن با بقیه‌ی اکانت‌ها فقط
    # وضع رو بدتر می‌کنه: همون محدودیت رویِ اکانت‌هایِ بعدی هم می‌شینه. پس کلِ صف
    # نگه داشته می‌شه، نه فقط همون یه اکانت.
    flood = {"until": 0.0}
    # ---- ضرباهنگِ ورود ----
    # حداکثر یه *شروعِ ورود* در هر MIGRATE_MIN_GAP_SECONDS ثانیه، در کلِ صف.
    # عمداً قفل در طولِ خوابیدن نگه داشته می‌شه - همین سریالی‌شدن، خودِ هدفه.
    pace = {"last": 0.0}
    pace_lock = asyncio.Lock()
    progress = {"at": time.monotonic()}

    def _mark_progress():
        progress["at"] = time.monotonic()

    async def _wait_out_flood() -> bool:
        """تا پایانِ مکثِ اجباری صبر می‌کنه. False یعنی وسطش توقف درخواست شد."""
        while True:
            left = flood["until"] - time.monotonic()
            if left <= 0:
                state["flood_left"] = 0
                return not session.cancelled
            if session.cancelled:
                return False
            state["flood_left"] = int(left)
            try:
                await asyncio.sleep(min(left, 5.0))
            except asyncio.CancelledError:
                return False

    def _trigger_flood(seconds: int) -> bool:
        """
        مکثِ سراسری رو فعال می‌کنه. False یعنی مدتِ خواسته‌شده از سقف بیشتره و
        ادامه‌دادن اشتباهه - یعنی کلِ دسته باید متوقف بشه.
        """
        seconds = max(0, int(seconds or 0))
        if seconds > MIGRATE_MAX_FLOOD_PAUSE:
            return False
        until = time.monotonic() + seconds + MIGRATE_FLOOD_EXTRA_SECONDS
        flood["until"] = max(flood["until"], until)
        state["flood_left"] = int(flood["until"] - time.monotonic())
        return True

    async def _pace_gate():
        """نوبتِ شروعِ این اکانت - با فاصله‌یِ رندوم از شروعِ قبلی."""
        async with pace_lock:
            gap = random.uniform(MIGRATE_MIN_GAP_SECONDS, MIGRATE_MIN_GAP_SECONDS * 1.8)
            wait = pace["last"] + gap - time.monotonic()
            if wait > 0:
                await asyncio.sleep(wait)
            pace["last"] = time.monotonic()
    # اکانت‌هایی که رمزِ دومرحله‌ای می‌خوان ولی ذخیره نشده - بعدِ اتمامِ دسته، یکی‌یکی
    # ازشون رمز می‌پرسیم (نگاه کن به needs_password_accounts پایین‌تر).
    session.needs_password_accounts = []
    stats_lock = asyncio.Lock()
    sem = asyncio.Semaphore(SESSION_MIGRATE_CONCURRENCY)

    async def publish(force: bool = False):
        now = time.monotonic()
        if not force and now - session.last_publish_at < 4.0:
            return
        session.last_publish_at = now
        try:
            await status_message.edit_text(
                _bulk_migration_status_text(state),
                reply_markup=_bulk_migration_running_keyboard(
                    finished=bool(state.get("finished"))
                ),
            )
        except Exception:
            pass

    async def _worker(acc):
        name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
        phone = acc.get("phone", "")
        label = f"{name} ({phone})" if phone and phone != name else name
        result = {"status": "error", "message": "خطایِ نامشخص"}
        try:
            # Mark the selected worker before any gate, so shutdown accounting
            # cannot incorrectly report it as an invisible not-started item.
            state["started_ids"].add(str(acc.get("id")))
            # توقفِ کاربر، *قبل* از گرفتنِ نوبت - اکانتی که هنوز شروع نشده اصلاً
            # لمس نمی‌شه (نه یه ورودِ نیمه‌کاره، نه هیچی)
            if session.cancelled:
                async with stats_lock:
                    state["skipped"] += 1
                    state["done"] += 1
                return
            async with sem:
                if session.cancelled:
                    async with stats_lock:
                        state["skipped"] += 1
                        state["done"] += 1
                    return
                # مکثِ اجباریِ فلود (اگه فعال باشه) + نوبتِ ضرباهنگ
                if not await _wait_out_flood():
                    async with stats_lock:
                        state["skipped"] += 1
                        state["done"] += 1
                    return
                await _pace_gate()
                # ---- علامت‌زدنِ «این اکانت الان *واقعاً* داره پردازش می‌شه» ----
                # ⚠️ باگی که این‌جا حل شده: قبلاً این خط *قبل* از async with sem بود -
                # یعنی همه‌ی اکانت‌هایِ باقی‌مونده (نه فقط اونایی که واقعاً نوبتشون
                # رسیده و سمافور بهشون اجازه داده) توی «درحالِ‌انجام» نشون داده
                # می‌شدن. با ۴۲ تا اکانت و هم‌زمانیِ ۱۰تایی، این یعنی به‌جایِ نمایشِ
                # درستِ «۱۰ تا الان درحالِ‌انجام، ۳۲ تا در صف»، همه‌یِ ۴۲ تا رو یک‌جا
                # «درحالِ‌انجام» نشون می‌داد - که دقیقاً همون حسِ «گیرکرده» رو ایجاد
                # می‌کرد، چون این عدد تا مدت‌ها اصلاً تکون نمی‌خورد.
                try:
                    async with stats_lock:
                        state["in_progress"].append(label)
                except Exception:
                    pass
                await publish(force=True)
                # ---- تلاشِ چندباره برایِ خطاهایِ گذرا ----
                # اکثرِ شکست‌هایِ این بخش (تایم‌اوت، دیر رسیدنِ کدِ تلگرام، افتِ
                # لحظه‌ایِ شبکه) با یه تلاشِ دوباره درست می‌شن. خطاهایِ قطعی (بن،
                # رمزِ لازم، شماره‌یِ نامعتبر) عمداً تکرار نمی‌شن - نگاه کن به
                # _is_transient_migration_error.
                for attempt in range(1, MIGRATE_MAX_ATTEMPTS + 1):
                    try:
                        # سقفِ زمانیِ سختِ هر تلاش - جلویِ گیرکردنِ نامحدودِ کلِ صف رو
                        # می‌گیره (مثلاً وقتی ensure_client رویِ یه سشنِ خراب هنگ می‌کنه).
                        # ⚠️ _mark_progress به‌عنوانِ on_step پاس داده می‌شه: هر مرحله‌یِ
                        # واقعیِ داخلِ مهاجرت (و هر پولِ انتظارِ کد) ساعتِ نگهبانِ
                        # بی‌حرکتی رو صفر می‌کنه. قبلاً نگهبان فقط «اتمامِ یه اکانت» رو
                        # پیشرفت می‌دونست، پس یه صفِ کاملاً سالم که همه‌ی کارگرهاش
                        # منتظرِ کد بودن، به‌عنوانِ «گیرکرده» کشته می‌شد.
                        _mark_progress()
                        result = await asyncio.wait_for(
                            _migrate_one_account_session(
                                acc, admin_chat_id, twofa_password=twofa_password,
                                twofa_passwords=twofa_passwords, on_step=_mark_progress,
                                mode=mode,
                            ),
                            timeout=_migrate_account_timeout(mode),
                        )
                    except asyncio.TimeoutError:
                        result = {"status": "error",
                                  "message": f"بیش از {int(_migrate_account_timeout(mode))} ثانیه طول کشید"}
                    except asyncio.CancelledError:
                        # CancelledError یه BaseException ه، نه Exception - اگه اینجا
                        # نگیریمش، از کلِ صف بالا می‌ره و باعث می‌شه شمارنده‌ها هیچ‌وقت
                        # آپدیت نشن (دقیقاً همون باگی که باعثِ «۰٪ ولی تمام شد» می‌شد).
                        result = {"status": "error", "message": "عملیات لغو شد"}
                        break
                    except Exception as e:
                        result = {"status": "error", "message": f"{type(e).__name__}: {e}"}

                    # تلاشِ دوباره‌ای که می‌بینه اکانت «قبلاً تعویض شده»، یعنی تلاشِ
                    # قبلیِ *همین صف* در واقع موفق بوده (مثلاً سقفِ زمانی بعد از
                    # تعویضِ موفق شلیک کرده). این موفقیته، نه «رد شد».
                    if result.get("status") == "already_migrated" and attempt > 1:
                        result = dict(result)
                        result["completed_in_earlier_attempt"] = True

                    # ---- ترمزِ فلود ----
                    flood_seconds = int(result.get("flood_seconds") or 0)
                    if flood_seconds:
                        if not _trigger_flood(flood_seconds):
                            # مدتِ خواسته‌شده خیلی طولانیه - ادامه‌دادن به کلِ استخر
                            # آسیب می‌زنه، پس همه‌ی صف متوقف می‌شه
                            session.cancelled = True
                            state["cancelled"] = True
                            async with stats_lock:
                                state["recent"].append(
                                    f"⛔️ محدودیتِ {flood_seconds} ثانیه‌ایِ تلگرام - کلِ صف متوقف شد"
                                )
                                state["recent"] = state["recent"][-20:]
                            await publish(force=True)
                            break
                        await publish(force=True)
                        if attempt < MIGRATE_MAX_ATTEMPTS and not session.cancelled:
                            # بعد از مکث، همین اکانت دوباره امتحان می‌شه
                            if not await _wait_out_flood():
                                break
                            await _pace_gate()
                            continue

                    if attempt >= MIGRATE_MAX_ATTEMPTS or not _is_transient_migration_error(result):
                        if attempt > 1 and result.get("status") != "success":
                            # شفافیت: معلوم باشه که واقعاً چند بار امتحان شده، نه
                            # اینکه با یه شکستِ ساده کنار گذاشته شده
                            result = dict(result)
                            result["message"] = f"{result.get('message', '')} (بعد از {attempt} تلاش)"
                        break
                    # هنوز تلاشِ باقی‌مونده هست و خطا از نوعِ گذراست - یه مکثِ کوتاه
                    # (تا شلوغیِ لحظه‌ای بخوابه) و دوباره
                    try:
                        async with stats_lock:
                            state["retrying"] = state.get("retrying", 0) + 1
                    except Exception:
                        pass
                    await publish(force=True)
                    cancelled = False
                    try:
                        await asyncio.sleep(MIGRATE_RETRY_DELAY)
                    except asyncio.CancelledError:
                        cancelled = True
                    # شمارنده‌یِ «درحالِ تلاشِ دوباره» همیشه برگردونده می‌شه - عمداً
                    # بیرونِ finally، چون awaitِ داخلِ finally حینِ لغوِ تسک می‌تونه
                    # دوباره CancelledError بده و شمارنده رو برایِ همیشه بالا نگه داره.
                    try:
                        async with stats_lock:
                            state["retrying"] = max(0, state.get("retrying", 1) - 1)
                    except Exception:
                        pass
                    if cancelled:
                        break
                # فاصله‌یِ کوچکِ تصادفی - جلویِ فلودِ هم‌زمانِ خیلی زیاد رو می‌گیره
                try:
                    await asyncio.sleep(random.uniform(0.3, 1.0))
                except asyncio.CancelledError:
                    pass
        except asyncio.CancelledError:
            result = {"status": "error", "message": "عملیات لغو شد"}
        except Exception as e:
            result = {"status": "error", "message": f"{type(e).__name__}: {e}"}

        # ---- ثبتِ نتیجه: این بخش *همیشه* اجرا می‌شه، هر اتفاقی هم بالا افتاده
        # باشه - وگرنه شمارنده‌ها عقب می‌مونن و آمار دروغ می‌شه. ----
        try:
            async with stats_lock:
                if label in state["in_progress"]:
                    state["in_progress"].remove(label)
                state["done"] += 1
                if result.get("status") == "success":
                    state["success"] += 1
                    spare_status = result.get("spare_status")
                    if spare_status == "success":
                        state["spare_built"] = state.get("spare_built", 0) + 1
                        state["recent"].append(f"✅ {label} — سشنِ جدید + زاپاسِ تازه")
                    elif spare_status in (None, "skipped"):
                        state["recent"].append(f"✅ {label}")
                    else:
                        # مهاجرت موفق بوده؛ فقط زاپاس نشد. نگهبانِ خودکارِ زاپاس
                        # خودش بعداً می‌سازش (اکانت الان بی‌زاپاسه، پس در نوبته).
                        state["spare_failed"] = state.get("spare_failed", 0) + 1
                        state["recent"].append(
                            f"✅ {label} — سشنِ جدید ساخته شد، ولی زاپاسِ تازه نه "
                            f"({result.get('spare_message') or spare_status})"
                        )
                elif result.get("status") == "already_migrated":
                    if result.get("completed_in_earlier_attempt"):
                        state["success"] += 1
                        state["recent"].append(
                            f"✅ {label} — تعویض در تلاشِ قبلی کامل شده بود"
                        )
                    else:
                        # از قبل تعویض شده بود - هیچ کاری رویِ اکانت انجام نشد
                        state["already_migrated"] = state.get("already_migrated", 0) + 1
                        state["recent"].append(
                            f"⏭ {label} — قبلاً تعویض شده بود، دوباره انجام نشد"
                        )
                elif result.get("status") == "needs_password":
                    # رمز نداریم - این اکانت رو کنار می‌ذاریم تا بعدِ دسته ازش بپرسیم.
                    # ⚠️ عمداً جزوِ «ناموفق» حساب نمی‌شه: هیچ‌چیز خراب نشده، فقط یه
                    # قدم باقی مونده. شمردنش به‌عنوانِ شکست، گزارش رو ترسناک و
                    # گمراه‌کننده می‌کرد (مثلاً «۰ موفق، ۲ ناموفق» در حالی که هر دو
                    # اکانت سالمن و فقط رمز لازم دارن).
                    state["needs_password"] += 1
                    session.needs_password_accounts.append({
                        "acc": acc, "hint": result.get("hint"),
                    })
                    state["recent"].append(f"🔑 {label} — رمزِ دومرحله‌ای لازم داره (بعداً می‌پرسم)")
                else:
                    state["failed"] += 1
                    reason = result.get("message") or result.get("status") or "خطایِ نامشخص"
                    state["recent"].append(f"❌ {label} — {reason}")
                state["recent"] = state["recent"][-20:]
                _mark_progress()
        except Exception:
            pass

        # ---- ثبتِ *پایدارِ* نتیجه‌یِ «منتظرِ رمز» ----
        # عمداً بیرونِ stats_lock (نوشتنِ دیتابیس نباید قفلِ آمار رو نگه داره) و
        # عمداً در دیتابیس نه حافظه: با ری‌استارتِ ربات یا بسته‌شدنِ چت، این لیست
        # قبلاً کاملاً از بین می‌رفت و اون اکانت‌ها بی‌سروصدا گم می‌شدن.
        status_now = result.get("status")
        # ⚠️ در حالتِ زاپاس این ثبت انجام *نمی‌شه*: لیستِ «نیازمندِ رمز» مالِ بخشِ
        # تعویضِ سشنه و اکانتی که توش بیفته از واجدِ شرایطِ تعویض حذف می‌شه. یه
        # زاپاسِ ناموفق نباید بخشِ دیگه‌ای رو قفل کنه.
        if status_now == "needs_password" and mode != "spare":
            try:
                await mark_account_needs_2fa_for_migration(
                    acc["id"], hint=result.get("hint"), last_error=result.get("message"),
                )
            except Exception:
                pass
        elif status_now == "success" or (status_now == "already_migrated" and mode != "spare"):
            # اگه این اکانت از یه دورِ قبلی توی لیستِ «منتظرِ رمز» بود، حالا حل شده
            try:
                await resolve_account_needs_2fa_for_migration(acc["id"], resolution="success")
            except Exception:
                pass
        await publish()

    async def auto_refresh_loop():
        while session.running:
            try:
                await asyncio.sleep(4)
            except asyncio.CancelledError:
                break
            if not session.running:
                break
            try:
                await publish(force=True)
            except Exception:
                pass

    await publish(force=True)
    ticker = asyncio.create_task(auto_refresh_loop())
    try:
        # return_exceptions=True یعنی هیچ استثنایی (حتی غیرمنتظره) نمی‌تونه بقیه‌ی
        # اکانت‌ها رو نصفه‌کاره متوقف کنه - هر worker خودش نتیجه‌شو ثبت می‌کنه.
        #
        # ---- نگهبانِ «بی‌حرکتی» به‌جایِ سقفِ زمانیِ ثابت ----
        # نسخه‌یِ قبلی یه بودجه‌یِ کلی (تعدادِ موج × بدترین‌حالتِ هر اکانت) حساب
        # می‌کرد و کلِ gather رو باهاش wait_for می‌کرد. دو مشکل داشت: (۱) با یه
        # مکثِ اجباریِ فلود، همون بودجه می‌سوخت و ده‌ها اکانتِ دست‌نخورده یک‌جا
        # «ناموفق» ثبت می‌شدن، (۲) با هم‌زمانیِ کمتر عدد به ساعت‌ها می‌رسید و عملاً
        # هیچ محافظتی نمی‌کرد. حالا معیار «پیشرفت» ـه، نه «زمانِ کل»: تا وقتی
        # اکانت‌ها دارن یکی‌یکی تموم می‌شن، صف هر چقدر هم طول بکشه ادامه می‌ده.
        # ⚠️ عمداً ensure_future، نه create_task: خروجیِ asyncio.gather یه Future ـه
        # نه کوروتین، و create_task رویِ Future با TypeError می‌ترکه. اون خطا توی
        # except عمومیِ همین بلوک بلعیده می‌شد و finally بلافاصله اجرا می‌شد - یعنی
        # گزارشِ نهایی *قبل* از اینکه اکانت‌ها واقعاً تموم بشن بسته می‌شد و همه‌شون
        # «در مهلتِ صف تموم نشد» ثبت می‌شدن، در حالی که پشتِ‌صحنه داشتن موفق تموم
        # می‌شدن. ensure_future هم کوروتین و هم Future رو درست هندل می‌کنه.
        gather_task = asyncio.ensure_future(
            asyncio.gather(*(_worker(acc) for acc in accounts), return_exceptions=True)
        )
        while not gather_task.done():
            done_set, _ = await asyncio.wait({gather_task}, timeout=15)
            if done_set:
                break
            if flood["until"] > time.monotonic():
                # مکثِ اجباریِ تلگرام «گیرکردن» نیست - ساعتِ بی‌حرکتی صفر می‌شه
                _mark_progress()
                await publish(force=True)
                continue
            if time.monotonic() - progress["at"] > MIGRATE_STALL_TIMEOUT:
                state["stalled"] = True
                session.cancelled = True
                state["cancelled"] = True
                gather_task.cancel()
                try:
                    await gather_task
                except (Exception, asyncio.CancelledError):
                    pass
                break
    except asyncio.TimeoutError:
        pass
    except asyncio.CancelledError:
        pass
    except Exception:
        pass
    finally:
        state["finished"] = True
        session.running = False
        # اگه سقفِ کلی شلیک کرده باشه، ممکنه چندتا اکانت هنوز ثبت‌نشده مونده باشن -
        # به‌جایِ نمایشِ آمارِ ناقص، همون‌ها رو صریح به‌عنوانِ ناموفق ثبت کن تا
        # مجموعِ شمارنده‌ها همیشه با total بخونه و گزارش دروغ نگه.
        try:
            missing = total - state["done"]
            if missing > 0:
                # These accounts were selected, but their worker callback did not
                # finish before the queue stopped. Never label them not_started.
                if session.cancelled or state.get("cancelled"):
                    state["skipped"] = state.get("skipped", 0) + missing
                    state["recent"].append(
                        f"⏭ {missing} اکانت به‌دلیل توقف/محدودیت تلگرام رد شد؛ "
                        "هیچ سشنی برایشان تغییر نکرد"
                    )
                else:
                    state["failed"] += missing
                    state["recent"].append(
                        f"❌ {missing} اکانت نتیجه نگرفتند؛ صف قبل از ثبت نتیجه متوقف شد"
                    )
                state["done"] = total
                state["in_progress"] = []
                state["recent"] = state["recent"][-20:]
        except Exception:
            pass
        ticker.cancel()
        try:
            await ticker
        except (Exception, asyncio.CancelledError):
            pass
        # اگه اکانت‌هایی رمزِ دومرحله‌ای می‌خوان، یه دکمه اضافه می‌کنیم تا کاربر
        # هروقت خواست، شروع به وارد کردنِ رمزهاشون کنه (یکی‌یکی، با نمایشِ hint).
        try:
            if session.needs_password_accounts:
                kb = InlineKeyboardMarkup([[InlineKeyboardButton(
                    f"🔑 وارد کردنِ رمزِ {len(session.needs_password_accounts)} اکانت",
                    callback_data="bm_enter_pw_start",
                )]])
                await status_message.edit_text(
                    _bulk_migration_status_text(state) + "\n\n"
                    f"🔑 {len(session.needs_password_accounts)} اکانت رمزِ دومرحله‌ای دارن که "
                    "ذخیره نشده. برایِ واردکردنِ رمزشون دکمه‌یِ زیر رو بزن.",
                    reply_markup=kb,
                )
            else:
                await publish(force=True)
        except Exception:
            pass


async def _prompt_next_bulk_migration_password(message, context):
    """
    اولین اکانتِ باقی‌مانده در صفِ bm_pw_queue رو برمی‌داره و رمزش رو از کاربر
    می‌پرسه (همراه با نمایشِ hintِ تلگرام اگه موجود باشه). اگه صف خالی شد، پیامِ
    پایانی می‌ده.
    """
    queue = context.user_data.get("bm_pw_queue") or []
    if not queue:
        context.user_data.pop("awaiting", None)
        context.user_data.pop("bm_pw_queue", None)
        context.user_data.pop("bm_pw_admin_id", None)
        # چندتا هنوز منتظر موندن؟ (ردشده‌ها و ناموفق‌ها عمداً توی لیست می‌مونن)
        try:
            still = len(await get_accounts_needing_2fa_for_migration())
        except Exception:
            still = 0
        tail = (
            f"\n\n🔑 {still} اکانت هنوز منتظرِ رمزن (ردشده یا رمزشون جواب نداد). "
            "توی لیستِ «🔑 نیازمندِ رمزِ دومرحله‌ای» موندن - هر وقت خواستی برگرد."
            if still else
            "\n\n🎉 دیگه هیچ اکانتی منتظرِ رمز نیست."
        )
        await message.reply_text(
            "✅ وارد کردنِ رمزها تمام شد.\n\n"
            "برایِ اکانت‌هایی که رمزشون درست بود، سشنِ جدید ساخته شد و سشنِ قدیمی "
            "حدودِ ۲۵ ساعتِ دیگه بسته می‌شه." + tail,
            reply_markup=BACK_TO_ACCOUNTS_KB,
        )
        return
    item = queue[0]
    acc = item["acc"]
    hint = item.get("hint")
    name = acc.get("nickname") or acc.get("phone") or str(acc["id"])
    context.user_data["awaiting"] = "bm_enter_pw"
    hint_line = f"\n\n💡 راهنماییِ رمز (Hint) که تلگرام نشون می‌ده: «{hint}»" if hint else ""
    await message.reply_text(
        f"🔑 اکانتِ «{name}»\n"
        f"({len(queue)} اکانت باقی مونده)\n\n"
        f"رمزِ دومرحله‌ایِ فعلیِ این اکانت رو بفرست."
        f"{hint_line}\n\n"
        f"اگه رمزش رو نمی‌دونی، «رد کن» رو بفرست تا بریم سراغِ بعدی.",
        reply_markup=ReplyKeyboardMarkup([["رد کن"], ["🔙 بازگشت"]], resize_keyboard=True),
    )


def _quarantine_unfinished_spare_files(spare_base: str) -> int:
    """
    فایل‌هایِ نیمه‌ساخته‌یِ یه زاپاسِ کنسل‌شده رو *قرنطینه* می‌کنه (هیچ‌وقت حذف).

    چرا قرنطینه و نه حذف: یه ساختِ کنسل‌شده ممکنه دقیقاً یک لحظه بعد از لاگینِ
    موفق قطع شده باشه - اون فایل یه نشستِ *واقعاً فعال* رویِ اکانته. حذفش یعنی
    یه نشستِ دست‌نیافتنیِ همیشگی. همون سیاستِ کلِ پروژه.
    """
    moved = 0
    try:
        targets = set(glob.glob(f"{spare_base}__building_*"))
    except Exception:
        targets = set()
    bases = set()
    for path in targets:
        base = path
        for suffix in ("-journal", "-wal", "-shm"):
            if base.endswith(suffix):
                base = base[: -len(suffix)]
                break
        if base.endswith(".session"):
            base = base[: -len(".session")]
        bases.add(base)
    for base in bases:
        try:
            if quarantine_session_files(base, reason="spare-build-cancelled"):
                moved += 1
        except Exception:
            pass
    return moved


async def _build_one_spare_session(
    acc: dict, twofa_password: str = None, twofa_passwords: list = None,
    on_step=None, lock_held: bool = False, timeout: float = None,
) -> dict:
    """
    ساختِ یه سشنِ زاپاس برایِ *یک* اکانت + ثبتش در دیتابیس.

    ⚠️ تفاوتِ حیاتی با مهاجرت: این‌جا **هیچ رکوردِ session_migrations ساخته
    نمی‌شه**. اون رکورد وظیفه‌اش اینه که ۲۵ ساعت بعد «همه‌ی نشست‌هایِ دیگه» رو
    ببنده - یعنی اگه این‌جا هم ثبتش می‌کردیم، ربات خودش زاپاسی که همین الان ساخته
    رو فردا می‌کشت. زاپاس عمداً هیچ‌وقت باعثِ بستنِ نشست نمی‌شه.

    خروجی: همون دیکشنریِ create_spare_session (success / needs_password / error)
    """
    if not twofa_password and acc.get("twofa_password"):
        twofa_password = acc["twofa_password"]

    try:
        index = await next_spare_session_index(acc["id"])
    except Exception as e:
        return {"status": "error", "message": f"شماره‌یِ زاپاسِ بعدی خونده نشد: {e}"}
    spare_base = spare_session_base(acc["session_file"], index)
    reservation = await reserve_spare_build(acc["id"], spare_base)
    if not reservation:
        return {"status": "error", "message": "سقف ساخت زاپاس (حداکثر ۱۵۰ در ۲۴ ساعت) پر شده یا ساخت هم‌زمان در جریان است"}
    reservation_id = int(reservation["id"])
    if reservation.get("status") == "success":
        return {"status": "success", "spare_base": spare_base, "idempotent": True}
    await mark_spare_build_started(reservation_id)

    # ⚠️ lock_held=True فقط از داخلِ چرخه‌یِ تعویضِ سشن میاد، که قفلِ همین سشن رو
    # از قبل در دست داره. asyncio.Lock بازگشتی نیست، پس صدازدنِ نسخه‌یِ قفل‌گیر از
    # اون‌جا یه بن‌بستِ تمام‌عیار بود.
    builder = create_spare_session_holding_lock if lock_held else create_spare_session
    try:
        coro = builder(
            acc["session_file"], acc["phone"], spare_base,
            twofa_password=twofa_password, twofa_passwords=twofa_passwords,
            on_step=on_step,
        )
        if timeout:
            result = await asyncio.wait_for(coro, timeout=float(timeout))
        else:
            result = await coro
    except asyncio.TimeoutError:
        await finish_spare_build(reservation_id, False, "تایم‌اوتِ ساختِ زاپاس")
        _quarantine_unfinished_spare_files(spare_base)
        return {"status": "error",
                "message": f"ساختِ زاپاس بیش از {int(float(timeout or 0))} ثانیه طول کشید"}
    except Exception as exc:
        await finish_spare_build(reservation_id, False, str(exc))
        raise
    if result.get("status") != "success":
        await finish_spare_build(reservation_id, False, result.get("message"))
        return result

    # ---- ثبتِ ردیف: باید *بلافاصله* بعدِ ساخت انجام بشه ----
    # تا این ردیف نباشه، «بیرون انداختنِ نشست‌ها» این زاپاس رو نمی‌شناسه و
    # ممکنه ببندش. اگه ثبت شکست بخوره، فایل رو رها نمی‌کنیم: صریحاً به‌عنوانِ
    # خطا برمی‌گردونیم تا کاربر ببینه و دوباره تلاش کنه (خودِ فایل سرِ جاشه و
    # با «🩺 بررسیِ سلامتِ زاپاس‌ها» قابلِ شناسایی و ثبتِ دوباره‌ست).
    try:
        await add_spare_session(
            acc["id"], spare_base,
            auth_hash=result.get("auth_hash"),
            telegram_id=result.get("telegram_id"),
            dc_id=result.get("dc_id"),
            device_model=result.get("device_model"),
            # هویتِ دستگاهِ همین زاپاس - باید ذخیره بشه تا هر اتصالِ بعدی هم عیناً
            # همون دستگاه رو گزارش کنه (وگرنه تلگرام هر بار «ورودِ دستگاهِ جدید» می‌بینه)
            device_profile=result.get("device_profile"),
        )
    except Exception as e:
        await finish_spare_build(reservation_id, False, str(e))
        return {
            "status": "error",
            "message": (
                f"سشنِ زاپاس ساخته شد ولی در دیتابیس ثبت نشد: {e} - "
                "فایلش سرِ جاشه، از «🩺 بررسیِ سلامتِ زاپاس‌ها» دوباره ثبتش کن"
            ),
            "spare_base": spare_base,
        }

    await finish_spare_build(reservation_id, True)
    confirmed_password = result.get("confirmed_password")
    if confirmed_password:
        try:
            await set_account_twofa_credentials(
                acc["id"], password=confirmed_password, verified=True
            )
        except Exception:
            pass
    if result.get("auth_hash") is None:
        # ---- تستِ دومِ زاپاس: یه‌بار خودش باز می‌شه و hashش از تلگرام پرسیده می‌شه ----
        # بدونِ این عدد، «بیرون انداختنِ نشست‌ها» برایِ همین اکانت کاملاً متوقف
        # می‌مونه (قاعده‌یِ سختِ پروژه: چیزی که نمی‌شناسیم رو نمی‌بندیم). پس به‌جایِ
        # اینکه فقط هشدار بدیم و کار رو به ادمین بسپریم، همین‌جا یه‌بار واقعاً
        # تستش می‌کنیم - همون کاری که «🩺 بررسیِ سلامتِ زاپاس‌ها» دستی می‌کرد.
        try:
            probe = await asyncio.wait_for(
                probe_spare_session(spare_base, acc["session_file"],
                                    expected_telegram_id=result.get("telegram_id")),
                timeout=120,
            )
        except Exception as e:
            probe = {"status": "error", "message": f"{type(e).__name__}: {e}"}
        if probe.get("status") == "success" and probe.get("auth_hash") is not None:
            try:
                await mark_spare_verified(
                    spare_base, telegram_id=probe.get("telegram_id"),
                    auth_hash=probe.get("auth_hash"),
                )
                result["auth_hash"] = probe.get("auth_hash")
            except Exception:
                pass
    if result.get("auth_hash") is None:
        # سشن سالمه، فقط hashش خونده نشد. این یعنی «بیرون انداختنِ نشست‌ها» تا
        # وقتی شناساییش نکنیم اجرا نمی‌شه - پس صریح گزارشش می‌کنیم.
        result["warning"] = (
            "شناسه‌یِ نشستِ زاپاس خونده نشد - از «🩺 بررسیِ سلامتِ زاپاس‌ها» "
            "یک‌بار تأییدش کن، وگرنه «بیرون انداختنِ نشست‌ها» متوقف می‌مونه"
        )
    return result


async def _preclean_all_sessions_for_switch(acc: dict, on_step=None) -> dict:
    """
    فازِ اولِ چرخه‌یِ «تعویضِ سشن»: *قبل* از ساختنِ هر سشنِ جدید، همه‌ی نشست‌هایِ
    دیگه‌یِ اکانت بیرون انداخته می‌شن - هم غریبه‌ها (کپیِ فروشنده، دستگاهِ ناشناس)
    و هم زاپاسِ نسلِ قبلِ خودِ ربات.

    ⚠️ چرا *این‌جا* و نه بعدِ مهاجرت: تلگرام به نشستی که کمتر از ۲۴ ساعت از
    ساختش گذشته اجازه‌یِ بستنِ نشستِ دیگه نمی‌ده (FRESH_RESET_AUTHORISATION_
    FORBIDDEN) - نه با درخواستِ جمعی و نه تکی. یعنی سشنِ *جدید* تا ۲۵ ساعت دستش
    بسته‌ست و تنها نشستی که همین الان می‌تونه خونه رو تمیز کنه، همین سشنِ قدیمیه.

    ⚠️ چرا زاپاسِ قدیمی هم می‌ره: خروجیِ خواسته‌شده‌یِ این چرخه دقیقاً «دو نشستِ
    تازه» است؛ زاپاسِ قبلی با کلیدِ نسلِ گذشته ساخته شده. ردیفش «بازنشسته» می‌شه،
    فایلش *قرنطینه* (هیچ‌وقت os.remove) و با mark_spare_needs_rebuild توی نوبتِ
    ساختِ زاپاس هم می‌مونه - پس اگه زاپاسِ تازه‌ی همین چرخه ساخته نشه، نگهبانِ
    خودکارِ زاپاس خودش پیگیرشه.

    همه‌ی کارِ واقعیِ خارج‌کردنِ زاپاس از همون تکْ‌تابعِ _retire_broken_spare
    می‌گذره (همونی که نگهبانِ خودکار و دکمه‌هایِ دستی استفاده می‌کنن) تا امکان
    نداشته باشه دو مسیر دو رفتارِ متفاوت داشته باشن.

    خروجی: {"status": "ok"|"pending", "retired", "kicked", "kick_failed",
             "terminate_status", "notes": [...]}
    """
    out = {"status": "ok", "retired": 0, "kicked": 0, "kick_failed": 0,
           "terminate_status": None, "notes": []}

    def _beat():
        if on_step is not None:
            try:
                on_step()
            except Exception:
                pass

    # ---- ۱) زاپاس‌هایِ نسلِ قبل ----
    try:
        rows = await get_spare_sessions(account_id=acc["id"])
    except Exception as e:
        rows = []
        out["status"] = "pending"
        out["notes"].append(f"لیستِ زاپاس‌ها خونده نشد: {type(e).__name__}: {e}")
    for row in rows or []:
        _beat()
        row = dict(row)
        # _retire_broken_spare مسیرِ سشنِ اصلی رو از همین کلید می‌خونه
        row["main_session_file"] = acc["session_file"]
        try:
            res = await _retire_broken_spare(
                row, "جایگزینی با زاپاسِ تازه در چرخه‌یِ تعویضِ سشن", kick=True)
        except Exception as e:
            out["kick_failed"] += 1
            out["notes"].append(f"{type(e).__name__}: {e}")
            continue
        if res.get("retired"):
            out["retired"] += 1
        if res.get("kicked"):
            out["kicked"] += 1
        if res.get("kick_message"):
            out["kick_failed"] += 1
            out["notes"].append(str(res["kick_message"]))

    # ---- ۲) هر نشستِ دیگه‌ای که مونده ----
    # بعدِ مرحله‌یِ ۱ هیچ زاپاسِ *فعالی* ثبت نیست، پس این‌جا همون مسیرِ سریع و
    # قطعیِ ResetAuthorizations اجرا می‌شه و چیزی جا نمی‌مونه. اگه به هر دلیلی یه
    # ردیفِ زاپاسِ فعال مونده باشه، خودِ اون تابع محافظتش می‌کنه - بدترین حالتش
    # «یه نشستِ اضافه» است که فازِ تأییدِ پایانی گزارشش می‌ده، نه خرابی.
    _beat()
    try:
        term = await asyncio.wait_for(
            terminate_all_other_sessions(acc["session_file"]),
            timeout=TERMINATE_ALL_MAX_SECONDS,
        )
    except asyncio.TimeoutError:
        term = {"status": "error", "message": "بستنِ نشست‌ها بیش‌ازحد طول کشید"}
    except Exception as e:
        term = {"status": "error", "message": f"{type(e).__name__}: {e}"}
    out["terminate_status"] = term.get("status")
    out["closed"] = int(term.get("closed") or 0)
    if term.get("status") != "success":
        out["status"] = "pending"
        if term.get("message"):
            out["notes"].append(str(term["message"]))
    return out


async def _migrate_one_account_session(
    acc: dict, admin_chat_id: str, twofa_password: str = None, twofa_passwords: list = None,
    on_step=None, mode: str = "migrate",
) -> dict:
    """
    مهاجرتِ سشنِ *یک* اکانت (ساختِ auth_key جدید) + کارهایِ جانبیِ لازم در صورتِ
    موفقیت: ثبتِ رکوردِ session_migrations (تا حلقه‌ی پس‌زمینه بتونه سشنِ قدیمی رو
    ببنده) و ذخیره‌یِ دائمیِ رمزِ دومرحله‌ای اگه برایِ عبور از این مرحله لازم بوده و
    تأیید شده (نگاه کن به confirmed_password در migrate_session_to_new_login).

    این تابع هم توسطِ ویزاردِ «📥 افزودن با فایلِ سشن» و هم توسطِ دکمه‌ی «🔄 تعویضِ
    سشنِ قدیمی به سشنِ جدید» استفاده می‌شه - تا هر دو مسیر دقیقاً یک رفتار داشته
    باشن.

    خروجی: همون دیکشنریِ migrate_session_to_new_login (status: success/needs_password/error)
    یا {"status": "already_migrated"} اگه این اکانت از قبل تعویض شده باشه (هیچ
    تماسی با تلگرام گرفته نمی‌شه و هیچ‌چیزی رویِ اکانت تغییر نمی‌کنه).
    """
    # اگه رمزِ صریح داده نشده، از رمزِ ذخیره‌شده‌یِ همین اکانت (اگه قبلاً ربات
    # سیوش کرده) استفاده می‌کنیم - تا اکانت‌هایِ دارایِ 2FA که رمزشون رو می‌دونیم،
    # خودکار و بدونِ پرسیدن مهاجرت کنن.
    # حالتِ «زاپاس» عیناً از همون صف، همون سقف‌ها و همون گزارش استفاده می‌کنه؛
    # فقط قدمِ آخر فرق داره (فایلِ اصلی جایگزین نمی‌شه). نگاه کن به
    # _build_one_spare_session.
    if mode == "spare":
        return await _build_one_spare_session(
            acc, twofa_password=twofa_password, twofa_passwords=twofa_passwords,
            on_step=on_step,
        )

    # ---- گاردِ «فقط یک‌بار» ----
    # ⚠️ هر اکانت فقط *یک‌بار* تعویض می‌شه. این‌جا، زیرِ قفلِ اختصاصیِ همین اکانت و
    # *قبل* از هر تماسی با تلگرام، دوباره از دیتابیس پرسیده می‌شه. دلیل: لیستی که
    # کاربر تأیید کرده ممکنه کهنه باشه (دو صفِ هم‌زمان، دو ادمین، یا تلاشِ دوباره‌یِ
    # خودکارِ صف بعدِ تایم‌اوتی که در واقع *بعد* از تعویضِ موفق شلیک کرده). اجرایِ
    # دوباره رویِ اکانتِ تعویض‌شده یعنی پاکسازیِ اولیه زاپاسِ تازه‌ش رو بیرون می‌ندازه
    # و یه ورودِ کاملاً بی‌دلیلِ دیگه ثبت می‌شه - دقیقاً چیزی که نباید به اکانت برسه.
    lock = _account_migration_lock(acc["id"])
    if lock.locked():
        # پیام عمداً شاملِ «قفلِ یک عملیاتِ دیگه» ـه تا صف یه بارِ دیگه (بعدِ مکث)
        # امتحان کنه؛ اون موقع همین گارد می‌بینه که تعویض انجام شده و ردش می‌کنه.
        return {"status": "error",
                "message": "این اکانت همین الان در قفلِ یک عملیاتِ دیگه‌یِ تعویضِ سشنه"}
    async with lock:
        try:
            await _sync_migration_records_from_receipts()
        except Exception:
            pass
        try:
            already = await has_session_migration_record(acc["id"])
        except Exception as e:
            # نمی‌دونیم قبلاً تعویض شده یا نه - ریسکِ تعویضِ دوباره رو نمی‌پذیریم
            return {"status": "error",
                    "message": f"وضعیتِ تعویضِ قبلیِ اکانت از دیتابیس خونده نشد: {type(e).__name__}"}
        if already:
            return {"status": "already_migrated",
                    "message": "این اکانت قبلاً تعویض شده - دوباره انجام نشد"}
        return await _switch_account_session_once(
            acc, admin_chat_id, twofa_password=twofa_password,
            twofa_passwords=twofa_passwords, on_step=on_step,
        )


# قفلِ «یک تعویض در هر لحظه» برایِ هر اکانت (کلید: شناسه‌یِ اکانت). جدا از قفلِ
# مسیرِ سشن در telethon_handler: اون فقط خودِ ورود رو می‌پوشونه، ولی این یکی کلِ
# چرخه (بررسیِ «قبلاً تعویض شده؟» + پاکسازیِ اولیه + تعویض + ثبت در دیتابیس) رو.
_account_migration_locks: Dict[int, asyncio.Lock] = {}


def _account_migration_lock(account_id) -> asyncio.Lock:
    key = int(account_id)
    lock = _account_migration_locks.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _account_migration_locks[key] = lock
    return lock


async def _persist_migration_success(acc: dict, result: dict) -> Optional[str]:
    """
    ثبتِ *پایدارِ* «این اکانت تعویض شد» - بلافاصله بعدِ موفقیت و قبل از هر کارِ
    کندِ دیگه (تأییدِ پایانی و ...)، تا اگه سقفِ زمانیِ صف بعدش شلیک کرد، این ثبت
    گم نشه.

      • سشنِ قدیمی همین الان logout شده → ردیفِ کامل‌شده (done=1).
      • سشنِ قدیمی هنوز بازه → همون ردیفِ در انتظارِ همیشگی (done=0) تا حلقه‌یِ
        ۲۵ ساعته ببندش.

    با asyncio.shield اجرا می‌شه: حتی اگه کوروتینِ بیرونی وسطِ کار لغو بشه، نوشتن تا
    آخر ادامه پیدا می‌کنه. چند بار هم تلاش می‌شه (دیتابیسِ قفل‌شده‌یِ لحظه‌ای).
    خروجی: None یعنی ثبت شد؛ وگرنه متنِ خطا.
    """
    account_id = acc["id"]
    logged_out = bool(result.get("old_session_logged_out"))

    async def _write():
        last_error = None
        for attempt in range(4):
            try:
                if logged_out:
                    # only_if_absent: گاردِ بالا مطمئن شده که قبلاً ردیفی نبوده، پس
                    # این فقط تلاشِ دوباره رو (اگه commitِ قبلی در واقع انجام شده
                    # بوده) بی‌خطر و بدونِ ردیفِ تکراری می‌کنه.
                    await record_completed_session_migration(
                        account_id, ADMIN_USER_ID, only_if_absent=True,
                    )
                else:
                    first_attempt_at = (
                        utcnow() + timedelta(hours=SESSION_MIGRATION_FIRST_ATTEMPT_HOURS)
                    ).isoformat(timespec="seconds")
                    await create_session_migration(
                        account_id, str(ADMIN_USER_ID), first_attempt_at
                    )
                return None
            except Exception as e:
                last_error = f"{type(e).__name__}: {e}"
                try:
                    await asyncio.sleep(1.5 * (attempt + 1))
                except asyncio.CancelledError:
                    break
        return last_error

    return await asyncio.shield(asyncio.ensure_future(_write()))


async def _switch_account_session_once(
    acc: dict, admin_chat_id: str, twofa_password: str = None,
    twofa_passwords: list = None, on_step=None,
) -> dict:
    """
    خودِ چرخه‌یِ تعویضِ سشن برایِ یک اکانت. فقط از _migrate_one_account_session و
    زیرِ قفلِ همون اکانت (بعدِ تأییدِ «هنوز تعویض نشده») صدا زده می‌شه.
    """
    if not twofa_password and acc.get("twofa_password"):
        twofa_password = acc["twofa_password"]

    # ---- فازِ ۱: خالی‌کردنِ اکانت از نشست‌هایِ نسلِ قبل، با سشنِ قدیمی ----
    # ⚠️ عمداً «شکستِ کشنده» نیست: اگه کامل نشه، مهاجرت ادامه پیدا می‌کنه و همون
    # صفِ ری‌ترایِ موجود (که خودش زاپاس رو حفظ می‌کنه) بقیه‌یِ نشست‌ها رو بعداً
    # می‌بنده. متوقف‌کردنِ کلِ تعویض به‌خاطرِ یه نشستِ لجباز، اکانت رو رویِ همون
    # سشنِ احتمالاً-لو‌رفته نگه می‌داشت - یعنی برعکسِ هدف.
    precleanup = None
    if SESSION_SWITCH_FULL_CYCLE:
        try:
            precleanup = await asyncio.wait_for(
                _preclean_all_sessions_for_switch(acc, on_step=on_step),
                timeout=SWITCH_PRECLEAN_TIMEOUT,
            )
        except asyncio.TimeoutError:
            precleanup = {"status": "pending",
                          "notes": ["پاکسازیِ اولیه در مهلتِ خودش تموم نشد"]}
        except Exception as e:
            precleanup = {"status": "pending", "notes": [f"{type(e).__name__}: {e}"]}

    # ---- فازِ ۲: سشنِ جدید + زاپاسِ جدید، و *بعد* خروجِ سشنِ قدیمی ----
    async def _build_fresh_spare():
        """مرحله‌یِ زاپاسِ همین چرخه - با قفلی که مهاجرت از قبل گرفته."""
        return await _build_one_spare_session(
            acc, twofa_password=twofa_password, twofa_passwords=twofa_passwords,
            on_step=on_step, lock_held=True, timeout=SWITCH_SPARE_BUILD_TIMEOUT,
        )

    result = await migrate_session_to_new_login(
        acc["session_file"], acc["phone"], twofa_password=twofa_password,
        twofa_passwords=twofa_passwords, on_step=on_step,
        build_spare=_build_fresh_spare if SESSION_SWITCH_FULL_CYCLE else None,
    )
    if precleanup is not None:
        result["precleanup"] = precleanup
    if result.get("status") == "success":
        # ---- ثبتِ «تعویض‌شده» - همیشه، در هر دو حالت ----
        # ⚠️ ریشه‌یِ باگِ «اکانتِ تعویض‌شده دوباره توی واجدِ شرایط میاد» همین‌جا
        # بود: وقتی سشنِ قدیمی همین الان logout می‌شد (مسیرِ عادیِ فعلی)، هیچ ردیفی
        # ثبت نمی‌شد - در حالی که تنها معیارِ «تعویض‌شده» در کلِ ربات وجودِ همین
        # ردیفه. حالا در حالتِ logout یه ردیفِ کامل‌شده (done=1) ثبت می‌شه که نه
        # حلقه‌یِ ۲۵ ساعته سراغش می‌ره و نه توی «منتظرِ حذفِ سشنِ قدیمی» میاد.
        persist_error = await _persist_migration_success(acc, result)
        if persist_error:
            print(f"⚠️  ثبتِ تعویضِ سشنِ اکانتِ {acc['id']} در دیتابیس نشد: {persist_error}")
            note = ("سشن تعویض شد، ولی ثبتش در دیتابیس نشد - از رویِ رسیدِ نصب، "
                    "خودکار ترمیم می‌شه")
            result["warning"] = f"{result['warning']} | {note}" if result.get("warning") else note
        if result.get("old_session_logged_out") and result.get("cleanup_pending"):
            # مهاجرت کامل شد و سشنِ قدیمی هم logout شد، ولی بستنِ *بعضی* نشست‌هایِ
            # دیگه موند (زاپاسِ ناشناس، سقفِ زمانی، خطایِ موقتِ تلگرام...). همون صفِ
            # ری‌ترایِ موجود پیگیرشه - و اون مسیر خودش زاپاس‌ها رو حفظ می‌کنه.
            # نگاه کن به _register_terminate_retry و session_migration_retry_loop.
            await _register_terminate_retry(acc["id"], admin_chat_id)
        confirmed_password = result.get("confirmed_password")
        if confirmed_password:
            try:
                await set_account_twofa_credentials(acc["id"], password=confirmed_password)
            except Exception:
                pass
        # ---- فازِ ۳: تأییدِ پایانی «فقط دو نشست» ----
        # کاملاً خواندنیه و هیچ‌وقت خودش چیزی نمی‌بنده: سشنِ جدید تا ۲۵ ساعت
        # اجازه‌یِ بستنِ نشست نداره، پس اگه نشستِ اضافه‌ای مونده باشه همون صفِ
        # ری‌ترایِ موجود (با محافظتِ زاپاس) تمومش می‌کنه.
        if SESSION_SWITCH_FULL_CYCLE:
            try:
                audit = await asyncio.wait_for(
                    describe_account_sessions(acc["session_file"]),
                    timeout=SWITCH_AUDIT_TIMEOUT,
                )
            except Exception as e:
                audit = {"status": "error", "message": f"{type(e).__name__}: {e}"}
            result["audit"] = audit
            if audit.get("status") == "success" and int(audit.get("strangers") or 0) > 0:
                await _register_terminate_retry(acc["id"], admin_chat_id)
    return result


def _zip_bad_sessions_sync(bad_sessions_dir: str) -> Optional[io.BytesIO]:
    """نسخه‌یِ sync (برایِ asyncio.to_thread) - همه‌یِ فایل‌هایِ داخلِ پوشه‌یِ نگه‌داریِ
    موقتِ سشن‌هایِ فریز/دیلیت‌شده رو توی یه zipِ حافظه‌ای می‌ذاره. اگه پوشه خالی یا
    ناموجود بود، None برمی‌گردونه."""
    if not bad_sessions_dir or not os.path.isdir(bad_sessions_dir):
        return None
    names = sorted(os.listdir(bad_sessions_dir))
    if not names:
        return None
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for name in names:
            full = os.path.join(bad_sessions_dir, name)
            if os.path.isfile(full):
                zf.write(full, arcname=name)
    buf.seek(0)
    return buf


async def _send_bad_sessions_archive(message, bad_sessions_dir: str, stats: Dict):
    """
    فایلِ سشنِ اکانت‌هایِ فریز/دیلیت‌شده‌یِ همین دورِ ایمپورت (که به‌جایِ حذف، توی
    bad_sessions_dir نگه داشته شدن - نگاه کن به _move_session_to_holding) رو
    به‌صورتِ یه zip برایِ ادمین می‌فرسته. کاربر صراحتاً «فایلِ سشن» رو خواسته، نه
    فقط شماره‌یِ متنی. هر خطایی این‌جا (سایزِ فایل، شبکه، ...) فقط با یه پیامِ کوتاه
    گزارش می‌شه و ادامه‌یِ فرآیندِ ایمپورت (تسک‌هایِ خودکار و غیره) رو نمی‌شکنه.
    پوشه‌یِ bad_sessions_dir در هر صورت (موفق یا ناموفق) در پایان پاک می‌شه.
    """
    try:
        zip_buf = await asyncio.to_thread(_zip_bad_sessions_sync, bad_sessions_dir)
        if not zip_buf:
            return
        frozen_n = len(stats.get("frozen_files") or [])
        deleted_n = len(stats.get("deleted_files") or [])
        now = utcnow()
        filename = f"bad_sessions_{to_tehran(now).strftime('%Y%m%d_%H%M%S')}.zip"
        caption = (
            f"📎 فایلِ سشنِ اکانت‌هایِ فریز/دیلیت‌شده - این ایمپورت\n"
            f"🧊 فریز: {frozen_n}   🗑 دیلیت: {deleted_n}\n\n"
            "این اکانت‌ها به لیستِ ربات اضافه *نشدن*؛ اسمِ هر فایل شاملِ نوع و "
            "شماره (اگه معلوم بود) هست."
        )
        await message.reply_document(document=zip_buf, filename=filename, caption=caption)
    except Exception as e:
        try:
            await message.reply_text(f"⚠️ ارسالِ ضمیمه‌یِ فایل‌هایِ فریز/دیلیت ناموفق بود: {type(e).__name__}: {e}")
        except Exception:
            pass
    finally:
        if bad_sessions_dir:
            shutil.rmtree(bad_sessions_dir, ignore_errors=True)


async def _run_staged_session_import(update: Update, context: ContextTypes.DEFAULT_TYPE, password: str = None):
    """
    مرحله‌یِ *پردازش*: همه‌ی فایل‌هایِ جمع‌شده توی staging رو موازی وارد می‌کنه.
    password اگه None باشه یعنی کاربر «بدونِ رمز» رو زده - سشن‌هایِ کاملاً لاگین‌شده
    بازم درست وارد می‌شن، فقط سشن‌هایِ نیمه‌کاره (منتظرِ رمز) رد می‌شن.
    """
    staging = context.user_data.get("session_staging_dir")
    context.user_data.pop("awaiting", None)
    context.user_data.pop("session_staging_dir", None)
    # رمزِ ایمپورت همین‌جا مصرف شد (به‌صورتِ آرگومان رسیده) - نگهش نداریم تا به
    # ایمپورتِ بعدی نشت نکنه
    context.user_data.pop("session_import_password", None)

    paths = []
    if staging and os.path.isdir(staging):
        paths = [os.path.join(staging, f) for f in sorted(os.listdir(staging)) if f.endswith(".session")]

    if not paths:
        await update.message.reply_text("هیچ فایلِ سشنی برایِ وارد کردن نبود.")
        await send_accounts_menu(update.message, context=context)
        return

    total = len(paths)
    wait_msg = await update.message.reply_text(
        f"⏳ در حالِ وارد کردنِ {total} سشن (موازی، {SESSION_IMPORT_CONCURRENCY}تا هم‌زمان)..."
    )

    # پوشه‌یِ نگه‌داریِ موقتِ فایلِ سشنِ فریز/دیلیت‌شده - جدا از staging، چون staging
    # توی finally پاک می‌شه ولی این‌ها باید تا بعدِ ارسالِ ضمیمه زنده بمونن.
    bad_sessions_dir = tempfile.mkdtemp(prefix="badsessions_", dir=_session_import_tmp_dir())

    last_edit_at = [0.0]

    async def _on_progress(done, total_n, stats):
        now = time.monotonic()
        if done < total_n and now - last_edit_at[0] < 2.0:
            return  # ادیتِ کمتر - وگرنه با هزارتا فایلِ موازی به لیمیتِ ادیتِ تلگرام می‌خوریم
        last_edit_at[0] = now
        try:
            await wait_msg.edit_text(
                f"⏳ در حالِ وارد کردن... ({done}/{total_n})\n{_format_import_stats(stats)}"
            )
        except Exception:
            pass

    try:
        stats = await _import_session_batch(paths, password=password, on_progress=_on_progress, bad_sessions_dir=bad_sessions_dir)

        # ---- تلاشِ دوبارهٔ خودکار برایِ ناموفق‌ها ----
        # بیشترِ این خطاها گذرا هستن (تایم‌اوتِ شبکه، شلوغیِ لحظه‌ایِ تلگرام، قفلِ
        # موقتِ فایلِ سشن وقتی چند صدتا هم‌زمان باز می‌شن)، پس یه دورِ دوم معمولاً
        # بیشترشون رو نجات می‌ده. پوشه‌یِ staging هنوز پاک نشده، پس فایل‌ها سرِ جاشن.
        # (فایل‌هایِ فریز/دیلیت از قبل به bad_sessions_dir منتقل شدن و دیگه توی
        # staging نیستن، پس os.path.exists خودش این‌ها رو از صفِ retry کنار می‌ذاره.)
        retry_paths = [p for p in (stats.get("failed_paths") or []) if os.path.exists(p)]
        if retry_paths:
            try:
                await wait_msg.edit_text(
                    f"⏳ {len(retry_paths)} سشن ناموفق بود - یه‌بارِ دیگه امتحانشون می‌کنم...\n"
                    f"{_format_import_stats(stats)}"
                )
            except Exception:
                pass
            await asyncio.sleep(3)  # یه مکثِ کوتاه تا شلوغیِ لحظه‌ای بخوابه

            retry_stats = await _import_session_batch(retry_paths, password=password, bad_sessions_dir=bad_sessions_dir)
            # نتیجه‌یِ دورِ دوم رو با دورِ اول ادغام کن: موفق‌هایِ جدید اضافه، و
            # همون تعداد از شمارنده‌یِ خطا کم می‌شن تا آمار دوباره‌شماری نشه
            recovered = retry_stats.get("success", 0)
            stats["success"] += recovered
            stats["duplicate"] += retry_stats.get("duplicate", 0)
            stats["new_account_ids"].extend(retry_stats.get("new_account_ids") or [])
            stats["error"] = len(retry_stats.get("failed_paths") or [])
            stats["retry_attempted"] = len(retry_paths)
            stats["retry_recovered"] = recovered
            # اگه توی دورِ دوم هم فریز/دیلیتِ جدیدی کشف شد (بعیده، ولی امن‌تره)،
            # به شمارنده و لیستِ فایل‌هایِ دورِ اول اضافه‌ش کن - نه جایگزین
            stats["frozen"] += retry_stats.get("frozen", 0)
            stats["deleted"] += retry_stats.get("deleted", 0)
            stats["frozen_phones"].extend(retry_stats.get("frozen_phones") or [])
            stats["deleted_phones"].extend(retry_stats.get("deleted_phones") or [])
            stats["frozen_files"].extend(retry_stats.get("frozen_files") or [])
            stats["deleted_files"].extend(retry_stats.get("deleted_files") or [])
    except Exception:
        # خطایِ غیرمنتظره‌ای که هیچ‌جایِ دیگه گرفته نشده - چون این‌جا دیگه نمی‌رسیم
        # به _send_bad_sessions_archive (که خودش مسئولِ پاکسازیِ bad_sessions_dir
        # هست)، باید همین‌جا دستی پاکش کنیم تا فایلِ یتیم رویِ دیسک نمونه.
        shutil.rmtree(bad_sessions_dir, ignore_errors=True)
        raise
    finally:
        if staging:
            shutil.rmtree(staging, ignore_errors=True)

    lines = [f"📥 نتیجه‌یِ نهایی ({total} فایل):", _format_import_stats(stats)]
    if stats.get("retry_attempted"):
        lines.append(
            f"🔄 تلاشِ دوباره: {stats['retry_recovered']} از {stats['retry_attempted']} "
            f"اکانتِ ناموفق در دورِ دوم درست شد."
        )
    if stats.get("bad_password"):
        lines += ["", "🔑 برایِ اونایی که «رمزِ اشتباه» خوردن، رمزِ دیگه‌ای رو امتحان کن -"
                      " دوباره فایل‌هاشون رو بفرست و این بار رمزِ درست رو بده."]
    if stats.get("needs_password"):
        lines += ["", "🔒 چندتا سشن نیمه‌کاره بودن و رمزِ دومرحله‌ای لازم داشتن."
                      " دوباره بفرستشون و این بار رمز رو وارد کن."]
    if stats.get("frozen"):
        frozen_info = f"🧊 {stats['frozen']} اکانتِ فریز‌شده (موقتاً غیرفعال)"
        if stats.get("frozen_phones"):
            frozen_info += f": {', '.join(stats['frozen_phones'][:3])}"
            if len(stats['frozen_phones']) > 3:
                frozen_info += f" و {len(stats['frozen_phones']) - 3} تای دیگه"
        lines += ["", frozen_info]
    if stats.get("deleted"):
        deleted_info = f"🗑 {stats['deleted']} اکانتِ دیلیت شده (نامعتبر)"
        if stats.get("deleted_phones"):
            deleted_info += f": {', '.join(stats['deleted_phones'][:3])}"
            if len(stats['deleted_phones']) > 3:
                deleted_info += f" و {len(stats['deleted_phones']) - 3} تای دیگه"
        lines += ["", deleted_info]
    bad_file_count = len(stats.get("frozen_files") or []) + len(stats.get("deleted_files") or [])
    if bad_file_count:
        lines += ["", f"📎 فایلِ سشنِ {bad_file_count} اکانتِ فریز/دیلیت‌شده به‌صورتِ ضمیمه فرستاده می‌شه."]
    await wait_msg.edit_text("\n".join(lines))

    # ---- ارسالِ فایل‌هایِ سشنِ فریز/دیلیت‌شده به‌عنوانِ ضمیمه ----
    # کاربر صراحتاً خواسته «شماره و فایل سشن» - نه فقط گزارشِ متنی. این فایل‌ها از
    # staging حذف نشدن (bad_sessions_dir جداست)، پس هنوز رویِ دیسک هستن.
    await _send_bad_sessions_archive(update.message, bad_sessions_dir, stats)

    new_ids = stats.get("new_account_ids") or []

    # این کلیدها همیشه همینجا پاک می‌شن (چه new_ids خالی باشه چه نه)، تا اگه این
    # بار هیچ اکانتی اضافه نشد، تنظیماتِ کارهایِ خودکار به ایمپورتِ *بعدی* نشت نکنه.
    tasks_wanted = context.user_data.pop("session_auto_tasks", None) or {}
    profile_channel_ref = context.user_data.pop("session_auto_profile_channel", None)
    auto_new_password = context.user_data.pop("session_auto_2fa_new_password", None)
    auto_current_password = context.user_data.pop("session_auto_2fa_current_password", None)
    auto_hint = context.user_data.pop("session_auto_2fa_hint", None)
    auto_recovery_email = context.user_data.pop("session_auto_2fa_recovery_email", None)
    wants_migrate = context.user_data.pop("session_auto_migrate", False)

    if new_ids:
        # ⚠️ بیرون انداختنِ خودکارِ نشست‌های دیگر غیرفعال شده‌ست تا اکانت‌ها فریز نشن
        # سشن‌های تازه‌واردشده با احتیاط اضافه می‌شن و نشست‌های قدیمی
        # می‌توانند دستی از صفحه‌یِ جزئیاتِ اکانت حذف شوند
        cleanup_text = (
            f"\n✅ {len(new_ids)} اکانتِ جدید با موفقیت اضافه شدند.\n\n"
            f"⚠️ اگر نیاز به حذفِ نشست‌های قدیمی دارید، می‌توانید آن‌ها را دستی از "
            f"صفحه‌یِ جزئیاتِ هر اکانت حذف کنید."
        )
        reply_markup = None
        frozen_ids = set()
        context.user_data.pop("pending_session_cleanup_retry_ids", None)

        await update.message.reply_text(
            f"✅ ایمپورتِ {len(new_ids)} اکانتِ جدید کامل شد." + cleanup_text,
            reply_markup=reply_markup,
        )

        # ---- اجرایِ خودکارِ «🖼 تغییرِ پروفایل» و/یا «🔐 تغییرِ رمزِ دومرحله‌ای» -----
        # روی دقیقاً همون اکانت‌هایی که همین الان با موفقیت اضافه شدن (new_ids)،
        # اگه کاربر توی مرحله‌یِ قبل درخواستش کرده باشه. هر اکانتی که شکست بخوره
        # (توی هرکدوم از این دو کار) ردش می‌کنیم و می‌ریم سراغِ بعدی؛ آخرِ کار هم
        # دقیقاً لیستِ خطاها نشون داده می‌شه. تیکِ ✅ توی لیستِ انتخابِ اکانت‌هایِ
        # همون کارها (منویِ «⚙️ تنظیماتِ اکانت») خودکار می‌خوره، چون هردو تابعِ
        # پایین دقیقاً همون set_account_task_done ای رو صدا می‌زنن که مسیرِ دستی
        # صدا می‌زنه.
        if tasks_wanted.get("profile") or tasks_wanted.get("twofa"):
            new_accounts = []
            for account_id in new_ids:
                if int(account_id) in frozen_ids:
                    continue  # فریزه - نه پروفایل نه رمزِ دومرحله‌ای روش کار نمی‌کنه
                acc = await get_account(account_id)
                if acc:
                    new_accounts.append(acc)

            if tasks_wanted.get("profile") and new_accounts:
                profile_status_msg = await update.message.reply_text(
                    "🖼 در حالِ پیدا کردنِ اکانتِ ادمینِ کانالِ معرفی‌شده..."
                )
                all_accounts_now = await get_all_accounts()
                admin_result = await find_admin_account_for_channel(profile_channel_ref, all_accounts_now)
                if admin_result["status"] != "success":
                    await profile_status_msg.edit_text(
                        f"❌ تغییرِ خودکارِ پروفایل انجام نشد: {admin_result['message']}\n\n"
                        "می‌تونی بعداً از منویِ «⚙️ تنظیماتِ اکانت ← 🖼 تغییرِ پروفایل» "
                        "همینا رو دستی امتحان کنی."
                    )
                else:
                    profile_session = ProfileChangeSession()
                    profile_session.selected_accounts = new_accounts
                    profile_session.channel_ref = profile_channel_ref
                    profile_session.channel_display = _channel_display(profile_channel_ref)
                    profile_session.admin_session_file = admin_result["account"]["session_file"]
                    profile_session.pool_scan_started_at = utcnow()

                    await _apply_profile_changes_to_accounts(profile_status_msg, profile_session)

                    if profile_session.pool_scan_error:
                        await profile_status_msg.edit_text(
                            f"❌ تغییرِ خودکارِ پروفایل انجام نشد: {profile_session.pool_scan_error}\n\n"
                            "می‌تونی بعداً از منویِ «⚙️ تنظیماتِ اکانت ← 🖼 تغییرِ پروفایل» "
                            "همینا رو دستی امتحان کنی."
                        )
                    else:
                        final_text = profile_session.progress_text(
                            header="✅ تغییرِ خودکارِ پروفایل - تمام شد"
                        )
                        try:
                            await profile_status_msg.edit_text(final_text)
                        except Exception:
                            await update.message.reply_text(final_text)

            if tasks_wanted.get("twofa") and new_accounts and not auto_new_password:
                # قبلاً این حالت کاملاً بی‌صدا رد می‌شد: کاربر «تغییرِ رمز» رو خواسته
                # بود ولی هیچ اتفاقی نمی‌افتاد و هیچ توضیحی هم داده نمی‌شد.
                await update.message.reply_text(
                    "⚠️ تغییرِ خودکارِ رمزِ دومرحله‌ای انجام نشد، چون رمزِ جدیدی ثبت نشده بود.\n\n"
                    "از «⚙️ تنظیمات ← 📱 اکانت‌ها ← ⚙️ تنظیماتِ اکانت ← 🔐 تغییرِ رمزِ "
                    "دومرحله‌ای» می‌تونی همینا رو دستی انجام بدی."
                )

            if tasks_wanted.get("twofa") and new_accounts and auto_new_password:
                twofa_status_msg = await update.message.reply_text(
                    "🔐 در حالِ شروعِ تغییرِ خودکارِ رمزِ دومرحله‌ای..."
                )
                twofa_session = TwoFAChangeSession()
                twofa_session.selected_accounts = new_accounts
                twofa_session.current_twofa_code = auto_current_password
                twofa_session.new_twofa_code = auto_new_password
                twofa_session.hint = auto_hint
                twofa_session.recovery_email = auto_recovery_email
                new_accounts_by_id = {a["id"]: a for a in new_accounts}

                # زمینه‌یِ لازم برایِ ادامه‌دادنِ ویزارد بعدِ (توقفِ احتمالیِ) صفِ
                # 2FA - نگاه کن به _run_post_2fa_migration_and_finish.
                context.user_data["session_auto_post2fa_context"] = {
                    "new_ids": new_ids, "wants_migrate": wants_migrate, "password": password,
                }

                paused = await _drive_auto_2fa_queue(
                    update, context, twofa_session, twofa_status_msg, new_accounts_by_id
                )
                if paused:
                    return  # منتظرِ کدِ ایمیلِ بازیابی - ادامه با پیامِ بعدیِ کاربر
                # صف بدونِ توقف کامل شد - این زمینه دیگه لازم نیست، همینجا مصرف شد
                context.user_data.pop("session_auto_post2fa_context", None)

    await _run_post_2fa_migration_and_finish(
        update, context, {"new_ids": new_ids, "wants_migrate": wants_migrate, "password": password}
    )



async def on_document(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """دریافتِ فایلِ زیپِ بکاپ برایِ بازیابی - یا فورواردِ یه سندِ کانال برایِ ثبتِ کانالِ بکاپ -
    یا فایل/زیپِ سشن برایِ افزودنِ اکانتِ جدید"""
    awaiting = context.user_data.get("awaiting")

    if awaiting in ("session_file_upload", "session_2fa_password"):
        # حتی وقتی منتظرِ رمزیم، اگه کاربر بازم فایل فرستاد قبولش کن و به staging اضافه کن
        await _stage_session_files(update, context)
        if awaiting == "session_2fa_password":
            await update.message.reply_text(
                "این فایل هم اضافه شد. حالا رمزِ دومرحله‌ای رو بفرست یا «🔓 بدونِ رمز» رو بزن.",
                reply_markup=_session_password_keyboard()
            )
        return

    if awaiting == "autoreact_channel":
        # فورواردِ یه پستِ فایل‌دار از کانال - هندلرِ سند زودتر از هندلرِ متن
        # این پیام رو می‌گیره، پس ثبتِ کانال باید این‌جا هم پشتیبانی بشه
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پستِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانال یه پست "
                "فوروارد کن، یا برایِ کانالِ عمومی یوزرنیمش رو بفرست."
            )
            return
        await _ar_register_from_forward(update, context, origin, get_admin_id(update))
        return

    if awaiting == "autoshare_channel":
        # همون منطق، ولی برایِ «🔁 شیرِ خودکار» - پستِ فوروارد‌شده‌ی فایل‌دار/عکس‌دار هم
        # باید مثلِ پستِ متنی، کانال رو ثبت کنه
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پستِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانال یه پست "
                "فوروارد کن، یا برایِ کانالِ عمومی یوزرنیمش رو بفرست."
            )
            return
        await _as_register_from_forward(update, context, origin, get_admin_id(update))
        return

    if awaiting == "as_probe_input":
        # پستِ فایل‌دارِ فوروارد‌شده برایِ «تستِ تشخیصِ مدل» - هندلرِ سند زودتر از
        # هندلرِ متن این پیام رو می‌گیره، پس این‌جا هم باید جواب بده
        await _as_run_probe(update.message, context, get_admin_id(update))
        return

    if awaiting == "session_check_upload":
        await _stage_session_check_files(update, context)
        return

    if awaiting == "session_auto_profile_channel":
        # فورواردِ یه پستِ عکس/فایل از کانال هم باید مثلِ پستِ متنی کار کنه - چون
        # هندلرِ سند زودتر از هندلرِ متن این پیام رو می‌گیره، اینجا هم باید حلش کنیم
        origin = update.message.forward_origin
        if isinstance(origin, MessageOriginChannel):
            await _apply_session_profile_channel(
                update.message, context, _extract_raw_channel_id(origin.chat.id)
            )
        else:
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانالِ موردنظر "
                "فوروارد کن، یا یوزرنیم/آیدیِ عددیِ کانال رو به‌صورتِ متن بفرست.",
                reply_markup=_session_wizard_step_keyboard()
            )
        return

    if awaiting in _SESSION_WIZARD_STATES:
        # وسطِ سؤال‌هایِ ویزاردیم - فایل دیگه پذیرفته نمی‌شه. قبلاً کاملاً بی‌صدا
        # نادیده گرفته می‌شد و کاربر خیال می‌کرد فایلش اضافه شده.
        await update.message.reply_text(
            "⏳ الان وسطِ سؤال‌هایِ ویزاردِ افزودنیم، پس این فایل اضافه نشد.\n\n"
            "اگه می‌خوای فایلِ بیشتری بفرستی، با «🔙 بازگشت» به مرحله‌یِ فرستادنِ فایل برگرد."
        )
        return

    if awaiting == "backup_channel_forward":
        if not await _try_register_backup_channel(update.message, context):
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یه پیام رو مستقیم از داخلِ "
                "کانالِ موردنظر فوروارد کن (نه از یه چتِ دیگه)."
            )
        return

    if awaiting == "openreq_channel":
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانالِ موردنظر "
                "فوروارد کن، یا آیدیِ عددی/یوزرنیمِ کانال رو به‌صورتِ متن بفرست."
            )
            return
        context.user_data.pop("awaiting", None)
        channel_ref = _extract_raw_channel_id(origin.chat.id)
        await _resolve_openreq_channel(update.message, context, get_admin_id(update), channel_ref)
        return

    if awaiting == "bulk_jl_channel":
        origin = update.message.forward_origin
        if not await _resolve_bulk_jl_forward(update.message, context, get_admin_id(update), origin):
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانالِ موردنظر "
                "فوروارد کن، یا آیدیِ عددی/یوزرنیمِ کانال رو به‌صورتِ متن بفرست."
            )
        return

    if awaiting == "vad_channel":
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانالِ موردنظر "
                "فوروارد کن، یا آیدیِ عددی/یوزرنیمِ کانال رو به‌صورتِ متن بفرست."
            )
            return
        context.user_data.pop("awaiting", None)
        channel_ref = _extract_raw_channel_id(origin.chat.id)
        display_name = getattr(origin.chat, "title", None) or _channel_display(channel_ref)
        await _resolve_vad_channel(update.message, context, get_admin_id(update), channel_ref, display_name)
        return

    if awaiting == "mpr_collect_posts":
        origin = update.message.forward_origin
        ok = await _mpr_add_forwarded_post(update.message, context, origin)
        if not ok:
            await update.message.reply_text(
                "این یه پستِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانال یه پست "
                "فوروارد کن، یا اگه تموم شدی «✅ تمام - ادامه» رو بزن."
            )
        return

    if awaiting != "restore_backup_upload":
        await update.message.reply_text(
            "برایِ بازیابیِ بکاپ، اول از منو گزینه‌ی «💾 بکاپ» → «📥 بازیابیِ بکاپ» رو بزن."
        )
        return

    doc = update.message.document
    if doc.file_size and doc.file_size > MAX_TELEGRAM_DOWNLOAD:
        await update.message.reply_text(
            "❌ این فایل خیلی بزرگه - تلگرام اجازه‌ی دانلودِ فایل‌هایِ بالایِ ۲۰ مگابایت رو به "
            "ربات‌ها نمی‌ده. اگه بکاپ اندازه‌شه اومده، ازش با «📤 گرفتنِ بکاپ» یه نسخه‌ی جدید "
            "بساز - این بکاپ‌ها اگه لازم باشه خودکار به چند تکه‌یِ کوچیک‌تر تقسیم می‌شن."
        )
        return

    wait_msg = await update.message.reply_text("⏳ در حالِ دانلودِ فایل...")
    try:
        tg_file = await context.bot.get_file(doc.file_id)
        fd, tmp_path = tempfile.mkstemp(suffix=".bin", prefix="uploaded_backup_")
        os.close(fd)
        await tg_file.download_to_drive(tmp_path)

        # ⚠️ ترتیب اینجا مهمه و عمداً *اول* هدرِ تکه‌یِ خودمون چک می‌شه، نه
        # zipfile.is_zipfile: توضیح: زیپ آخرِ یه بکاپِ تقسیم‌شده (که شاملِ
        # Central Directory/EOCD ـه) وقتی *تنها* دانلود بشه، می‌تونه به‌تنهایی هم
        # zipfile.is_zipfile رو قبول کنه - چون این چک فقط EOCD رو از انتهایِ
        # فایل می‌خونه، نه اینکه آفست‌هایِ واقعیِ هرکدوم از entryها هم قابلِ
        # رسیدن باشن. نتیجه‌ی این باگ اگه اول is_zipfile چک می‌شد: آخرین تکه‌یِ
        # یه بکاپِ چندتکه‌ای به‌اشتباه به‌عنوانِ «کلِ بکاپ» بازیابی می‌شد و تکه‌هایِ
        # قبلی (باقیِ دیتابیس/سشن‌ها) کلاً گم می‌شدن - بدونِ هیچ خطایی!
        # از اونجا که تکه‌هایِ خودمون همیشه با هدرِ JSONِ منحصربه‌فردمون شروع
        # می‌شن (که یه زیپِ واقعی هیچ‌وقت باهاش شروع نمی‌شه)، چکِ هدر رو قطعی و
        # اول انجام می‌دیم.
        with open(tmp_path, "rb") as f:
            head = f.read(4096)
        parsed = _try_parse_part_header(head)

        if parsed is None:
            if zipfile.is_zipfile(tmp_path):
                # زیپِ کامل و یه‌تکه‌ست - دقیقاً مثلِ همیشه، بدونِ نیاز به تجمیع
                context.user_data.pop("awaiting", None)
                context.user_data.pop("restore_multipart", None)
                await _finalize_restore_candidate(wait_msg, context, tmp_path)
                return

            os.remove(tmp_path)
            await wait_msg.edit_text(
                "❌ این فایل یه بکاپِ معتبر نیست (نه زیپِ کامله، نه یکی از تکه‌هایِ "
                "استانداردِ بکاپ). همونی رو بفرست که خودِ ربات با «📤 گرفتنِ بکاپ» ساخته."
            )
            return

        header, _ = parsed
        batch_id = header.get("batch_id")
        part_idx = header.get("part")
        total_parts = header.get("total_parts")
        if not batch_id or not part_idx or not total_parts:
            os.remove(tmp_path)
            await wait_msg.edit_text("❌ هدرِ این تکه ناقصه - دوباره از «📤 گرفتنِ بکاپ» بسازش.")
            return

        # این‌بار کلِ فایل رو می‌خونیم تا بارِ اصلی (بعدِ هدر) رو جدا کنیم
        with open(tmp_path, "rb") as f:
            full_data = f.read()
        os.remove(tmp_path)
        payload = full_data[full_data.index(b"\n") + 1:]

        mp = context.user_data.get("restore_multipart")
        if not mp or mp.get("batch_id") != batch_id:
            # یا اولین تکه‌یِ این batch_id ئه، یا batchِ قبلی رها شده و این یکیِ تازه‌ست
            mp = {
                "batch_id": batch_id,
                "total_parts": total_parts,
                "expected_size": header.get("total_size"),
                "expected_sha256": header.get("sha256"),
                "received": [],
            }
            context.user_data["restore_multipart"] = mp

        parts_dir = _restore_parts_tmp_dir(batch_id)
        with open(os.path.join(parts_dir, f"part_{part_idx:04d}.bin"), "wb") as f:
            f.write(payload)
        if part_idx not in mp["received"]:
            mp["received"].append(part_idx)

        missing = sorted(set(range(1, total_parts + 1)) - set(mp["received"]))
        if missing:
            preview = ", ".join(str(m) for m in missing[:15]) + (" …" if len(missing) > 15 else "")
            await wait_msg.edit_text(
                f"📦 تکه‌یِ {part_idx} از {total_parts} دریافت شد.\n"
                f"⏳ {len(missing)} تکه‌یِ دیگه مونده: {preview}\n\n"
                "بقیه‌یِ تکه‌ها رو هم پشتِ‌هم بفرست."
            )
            return

        # همه‌ی تکه‌ها رسیدن - سرهم‌شون کن
        await wait_msg.edit_text("⏳ همه‌ی تکه‌ها رسید - در حالِ سرهم‌کردن و بررسیِ صحت...")
        combined_fd, combined_path = tempfile.mkstemp(suffix=".zip", prefix="restored_backup_")
        with os.fdopen(combined_fd, "wb") as out:
            for i in range(1, total_parts + 1):
                with open(os.path.join(parts_dir, f"part_{i:04d}.bin"), "rb") as pf:
                    out.write(pf.read())
        shutil.rmtree(parts_dir, ignore_errors=True)
        context.user_data.pop("restore_multipart", None)

        expected_hash = mp.get("expected_sha256")
        if expected_hash:
            actual_hash = await asyncio.to_thread(_sha256_of_file, combined_path)
            if actual_hash != expected_hash:
                os.remove(combined_path)
                await wait_msg.edit_text(
                    "❌ هشِ فایلِ سرهم‌شده با هشِ ثبت‌شده توی تکه‌ها یکی نیست - یعنی یه‌جایِ "
                    "انتقال خراب شده. لطفاً از اول، همه‌ی تکه‌ها رو دوباره بفرست."
                )
                return

        if not zipfile.is_zipfile(combined_path):
            os.remove(combined_path)
            await wait_msg.edit_text("❌ فایلِ سرهم‌شده یه زیپِ معتبر نیست.")
            return

        context.user_data.pop("awaiting", None)
        await _finalize_restore_candidate(wait_msg, context, combined_path)
    except Exception as e:
        await wait_msg.edit_text(f"❌ خطا توی دانلود/بررسیِ فایل: {e}")


@restricted
async def on_forwarded_media(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    عکس/ویدیویِ فوروارد‌شده (بدونِ اینکه سند/فایل باشه) - جاهایی که فعلاً لازمه اینا رو
    ببینیم: «📋 ری‌اکشن چند پست»، «📅 بازدیدِ تمامِ پست‌ها»، و «👤 ممبر → جوین/ترکِ کانال»
    (چون پستِ عکس/ویدیوداری که تلگرام به‌عنوانِ سند نفرستادتش، نه awaitingِ متنی رو رد
    می‌کنه نه بریزه تویِ on_document). خارج از این حالت‌ها، این پیام‌ها به هیچ دردی
    نمی‌خورن و نادیده گرفته می‌شن.
    """
    awaiting = context.user_data.get("awaiting")
    if awaiting == "autoreact_channel":
        # پستِ عکس/ویدیویی که از کانال فوروارد شده - همون مسیرِ ثبتِ کانال
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پستِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانال یه پست "
                "فوروارد کن، یا برایِ کانالِ عمومی یوزرنیمش رو بفرست."
            )
            return
        await _ar_register_from_forward(update, context, origin, get_admin_id(update))
        return

    if awaiting == "autoshare_channel":
        # همون منطق، ولی برایِ «🔁 شیرِ خودکار» - پستِ فوروارد‌شده‌ی فایل‌دار/عکس‌دار هم
        # باید مثلِ پستِ متنی، کانال رو ثبت کنه
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پستِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانال یه پست "
                "فوروارد کن، یا برایِ کانالِ عمومی یوزرنیمش رو بفرست."
            )
            return
        await _as_register_from_forward(update, context, origin, get_admin_id(update))
        return

    if awaiting == "as_probe_input":
        # پستِ عکس/ویدیوییِ فوروارد‌شده برایِ «تستِ تشخیصِ مدل»
        await _as_run_probe(update.message, context, get_admin_id(update))
        return

    if awaiting == "mpr_collect_posts":
        origin = update.message.forward_origin
        ok = await _mpr_add_forwarded_post(update.message, context, origin)
        if not ok:
            await update.message.reply_text(
                "این یه پستِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانال یه پست "
                "فوروارد کن، یا اگه تموم شدی «✅ تمام - ادامه» رو بزن."
            )
        return

    if awaiting == "bulk_jl_channel":
        origin = update.message.forward_origin
        if not await _resolve_bulk_jl_forward(update.message, context, get_admin_id(update), origin):
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانالِ موردنظر "
                "فوروارد کن، یا آیدیِ عددی/یوزرنیمِ کانال رو به‌صورتِ متن بفرست."
            )
        return

    if awaiting == "vad_channel":
        origin = update.message.forward_origin
        if not isinstance(origin, MessageOriginChannel):
            await update.message.reply_text(
                "این یه پیامِ فوروارد‌شده از کانال نبود. یا مستقیم از داخلِ کانالِ موردنظر "
                "فوروارد کن، یا آیدیِ عددی/یوزرنیمِ کانال رو به‌صورتِ متن بفرست."
            )
            return
        context.user_data.pop("awaiting", None)
        channel_ref = _extract_raw_channel_id(origin.chat.id)
        display_name = getattr(origin.chat, "title", None) or _channel_display(channel_ref)
        await _resolve_vad_channel(update.message, context, get_admin_id(update), channel_ref, display_name)
        return


# ===================== ازسرگیریِ خودکارِ سفارش‌هایِ نیمه‌کاره بعدِ ری‌استارت =====================

class _FakeMessageForChat:
    """
    یه شبیه‌سازِ سبکِ Update.message - فقط همون دو چیزی که _launch_batch لازم داره
    (chat_id + reply_text) رو داره. لازمه چون موقعِ ازسرگیری (استارتاپِ ربات)، هیچ
    پیامِ واقعیِ ورودی‌ای در کار نیست که بشه رویِ اون reply_text صدا زد - باید مستقیم
    با application.bot.send_message به چتِ ادمین پیام جدید فرستاد.
    """
    def __init__(self, bot, chat_id):
        self._bot = bot
        self.chat_id = chat_id

    async def reply_text(self, text, reply_markup=None):
        return await self._bot.send_message(chat_id=self.chat_id, text=text, reply_markup=reply_markup)


async def _resume_one_batch_job(application, job: dict) -> bool:
    """
    تلاش برایِ ازسرگیریِ یک سفارشِ نیمه‌کاره - True اگه با موفقیت دوباره استارت شد،
    False اگه نشد (مثلاً چت‌آیدیِ ادمین یا اکانت‌ها/کانال دیگه در دسترس نیستن) که در
    این صورت با close_batch_job_as_interrupted به‌عنوانِ «قطع‌شده» بسته می‌شه.
    """
    job_id = job["id"]
    admin_id = job["admin_id"]
    chat_id = job.get("admin_chat_id")
    if not chat_id:
        await close_batch_job_as_interrupted(job_id, job["done"], job["success"], job["fail"], "چت‌آیدیِ ادمین ثبت نشده بود")
        return False

    try:
        payload = json.loads(job["resume_payload"]) if job.get("resume_payload") else {}
        remaining_ids = json.loads(job["remaining_json"]) if job.get("remaining_json") else []
    except Exception:
        await close_batch_job_as_interrupted(job_id, job["done"], job["success"], job["fail"], "خواندنِ اطلاعاتِ ازسرگیری با خطا مواجه شد")
        return False

    if not remaining_ids:
        # چیزی برایِ ازسرگیری نمونده (همه‌شون قبلِ قطع‌شدن انجام شده بودن) - فقط ببندش
        await close_batch_job_as_interrupted(job_id, job["done"], job["success"], job["fail"])
        return False

    resume_kind = job.get("resume_kind")
    accounts = [await get_account(aid) for aid in remaining_ids]
    accounts = [a for a in accounts if a]

    if resume_kind == "view":
        link_info = payload.get("link")
        run_accounts = accounts

        async def action_fn(acc):
            membership = await check_channel_membership(
                acc["session_file"],
                channel_username=link_info.get("username") if link_info else None,
                is_private=bool(link_info.get("is_private")) if link_info else False,
                entity_id=link_info.get("channel_id") if link_info else None,
            )
            as_follower = membership.get("status") == "member"
            return await view_post(acc["session_file"], link_info, as_follower=as_follower)

        op_label = "👁 بازدید (ازسرگیری‌شده بعدِ ری‌استارت)"
        title_immediate = "👁 نتیجه‌ی بازدید"
        title_scheduled = "👁 نتیجه‌ی بازدیدِ زمان‌بندی‌شده"
        kind = "view"

    elif resume_kind == "react_single":
        link_info = payload.get("link")
        reaction = payload.get("reaction", "👍")
        run_accounts = accounts
        action_fn = lambda acc: react_to_post(acc["session_file"], link_info, reaction)
        op_label = f"👍 ری‌اکشنِ {reaction} (ازسرگیری‌شده بعدِ ری‌استارت)"
        title_immediate = f"👍 نتیجه‌ی ری‌اکشنِ {reaction}"
        title_scheduled = f"👍 نتیجه‌ی ری‌اکشنِ زمان‌بندی‌شده‌ی {reaction}"
        kind = "react"

    elif resume_kind == "react_multi":
        link_info = payload.get("link")
        reactions_by_account = payload.get("reactions_by_account") or {}
        run_accounts = []
        for acc in accounts:
            reaction = reactions_by_account.get(str(acc["id"]))
            if not reaction:
                continue  # اطلاعاتِ ری‌اکشنِ این اکانت گم شده - رد می‌شیم (نباید پیش بیاد)
            run_accounts.append({**acc, "assigned_reaction": reaction})
        action_fn = lambda item: react_to_post(item["session_file"], link_info, item["assigned_reaction"])
        op_label = "👍 ری‌اکشنِ چندگانه (ازسرگیری‌شده بعدِ ری‌استارت)"
        title_immediate = "👍 نتیجه‌ی ری‌اکشن"
        title_scheduled = "👍 نتیجه‌ی ری‌اکشنِ زمان‌بندی‌شده"
        kind = "react"

    elif resume_kind == "join_leave":
        action = payload.get("action", "join")
        channel_username = payload.get("channel_username")
        ch_id = payload.get("channel_id")
        is_private = bool(payload.get("is_private"))
        invite_hash = payload.get("invite_hash")
        entity_id = payload.get("entity_id")
        access_hash = payload.get("access_hash")
        run_accounts = accounts
        label = "جوین" if action == "join" else "ترک"

        async def action_fn(acc):
            if action == "join":
                return await join_channel(
                    acc["id"], ch_id, acc["session_file"], channel_username,
                    is_private=is_private, invite_hash=invite_hash, entity_id=entity_id, access_hash=access_hash
                )
            return await leave_channel(
                acc["id"], ch_id, acc["session_file"], channel_username,
                is_private=is_private, entity_id=entity_id, access_hash=access_hash
            )

        op_label = f"{label}ِ کانال (ازسرگیری‌شده بعدِ ری‌استارت)"
        title_immediate = f"نتیجه‌ی {label}"
        title_scheduled = f"نتیجه‌ی {label}"
        kind = "other"

    else:
        await close_batch_job_as_interrupted(job_id, job["done"], job["success"], job["fail"], f"نوعِ ازسرگیریِ ناشناخته: {resume_kind}")
        return False

    if not run_accounts:
        await close_batch_job_as_interrupted(job_id, job["done"], job["success"], job["fail"], "هیچ‌کدوم از اکانت‌هایِ باقی‌مونده دیگه در دسترس نیستن")
        return False

    # زمانِ باقی‌مونده برایِ حالتِ پخش‌شده/رندوم: کلِ مدتِ اصلی منهایِ زمانی که تا لحظه‌ی
    # قطع‌شدن گذشته - اگه دیگه چیزی نمونده (یا حالت از اول فوری بوده)، بقیه هم فوری زده می‌شه.
    mode = job.get("mode") or "immediate"
    minutes = 0
    if mode in ("scheduled", "random") and job.get("total_minutes"):
        try:
            started_at = datetime.fromisoformat(job["started_at"])
            elapsed_minutes = (utcnow() - started_at).total_seconds() / 60
            minutes = max(job["total_minutes"] - elapsed_minutes, 0)
        except Exception:
            minutes = 0

    fake_message = _FakeMessageForChat(application.bot, chat_id)
    await fake_message.reply_text(
        f"ℹ️ سرور ری‌استارت شده بود - سفارشِ زیر داره از همون‌جا که مونده ادامه پیدا می‌کنه "
        f"({len(run_accounts)} اکانتِ باقی‌مونده از {job['total']}):"
    )

    started_at_dt = None
    try:
        started_at_dt = datetime.fromisoformat(job["started_at"])
    except Exception:
        pass

    await _launch_batch(
        fake_message, run_accounts, action_fn, minutes, None,
        op_label=op_label,
        title_immediate=title_immediate,
        title_scheduled=title_scheduled,
        title_random=title_scheduled,
        admin_id=admin_id,
        kind=kind,
        progress_seed={
            "job_id": job_id,
            "total": job["total"],
            "done": job["done"],
            "success": job["success"],
            "fail": job["fail"],
            "start_time": started_at_dt,
        },
    )
    return True


async def resume_interrupted_batches(application):
    """
    موقعِ بالا اومدنِ ربات (توی start_bot) صدا زده می‌شه - هر سفارشِ یک‌باره‌ای که
    به‌خاطرِ ری‌استارتِ قبلی نیمه‌کاره مونده و اطلاعاتِ کافی برایِ ازسرگیری داره رو
    خودکار، از رویِ اکانت‌هایِ باقی‌مونده (نه از اول)، دوباره شروع می‌کنه. سفارش‌هایی که
    اطلاعاتِ کافی ندارن (مثلاً از نسخه‌ی قدیمی‌ترِ کد) طبقِ روالِ قبلی به‌عنوانِ
    «قطع‌شده» بسته می‌شن (reconcile_interrupted_batch_jobs).
    """
    try:
        jobs = await get_resumable_batch_jobs()
    except Exception as e:
        print(f"⚠️  خواندنِ سفارش‌هایِ قابلِ‌ازسرگیری با خطا مواجه شد: {e}")
        jobs = []

    resumed = 0
    for job in jobs:
        try:
            ok = await _resume_one_batch_job(application, job)
            if ok:
                resumed += 1
        except Exception as e:
            print(f"⚠️  ازسرگیریِ سفارشِ {job.get('id')} با خطا مواجه شد: {e}")
            try:
                await close_batch_job_as_interrupted(job["id"], job["done"], job["success"], job["fail"], str(e))
            except Exception:
                pass

    try:
        interrupted_count = await reconcile_interrupted_batch_jobs()
    except Exception as e:
        interrupted_count = 0
        print(f"⚠️  بازبینیِ سفارش‌هایِ نیمه‌کاره با خطا مواجه شد: {e}")

    if resumed:
        print(f"✅ {resumed} سفارشِ نیمه‌کاره از اجرایِ قبلی، از همون‌جا که مونده ادامه پیدا کرد.")
    if interrupted_count:
        print(f"ℹ️  {interrupted_count} سفارشِ نیمه‌کاره (بدونِ اطلاعاتِ ازسرگیری)، به‌عنوانِ «قطع‌شده» بسته شد.")


# ===================== راه‌اندازی =====================

async def _reconnect_all_accounts_persian():
    """
    موقعِ بالا اومدنِ ربات (مثلاً بعدِ دیپلویِ جدید روی Railway)، همه‌یِ اکانت‌هایِ
    لاگین‌شده رو یه‌بار وصل می‌کنه - چون clients_cache با هر ری‌استارت خالی می‌شه و
    اتصالِ بعدی هرکدوم (طبقِ تغییرِ telethon_handler.py) با lang_code="fa" انجام
    می‌شه. بدونِ این، اکانتی که یه مدت توی هیچ عملیاتی استفاده نمی‌شد، تا همون موقع
    با زبانِ قدیمی به تلگرام معرفی می‌موند. با فاصله‌ی کوچیکِ رندوم بینِ اکانت‌ها
    اجرا می‌شه تا هم‌زمان روی همه فشار نیاد؛ خطایِ هر اکانت بی‌سروصدا رد می‌شه (مهم‌تر
    اینه بقیه ادامه پیدا کنن، دفعه‌ی بعد که استفاده بشن بازم دوباره امتحان می‌شه).

    ⚠️ سقفِ MAX_CACHED_CLIENTS رو رعایت می‌کنه: با هزاران اکانت، رفتنِ این حلقه
    تا آخرِ لیست یعنی هزاران کانکشنِ *جدید* رویِ هم انباشته بشن - درست همون
    لحظه‌ای (بعدِ هر دیپلوی) که رمِ پردازه بیشترین فشار رو داره. قبلاً این حلقه
    کاملاً بی‌خبر از سقف بود: بعدِ رسیدن به سقف، client_reaper_loop داشت از یه
    طرف قدیمی‌ترین‌ها رو قطع می‌کرد در حالی که این حلقه هم‌زمان از طرفِ دیگه
    داشت جدید وصل می‌کرد - کلی کارِ شبکه/CPU برایِ هیچ، دقیقاً توی حساس‌ترین
    بازه‌ی بعدِ ری‌استارت. حالا به‌محضِ رسیدن به سقف، این حلقه ساکت متوقف می‌شه؛
    بقیه‌ی اکانت‌ها همون‌طور که لازم می‌شن (توسطِ خودِ auto_view/auto_react/...) و
    طبقِ همون منطقِ عادیِ ensure_client زبانشون رو می‌گیرن.
    """
    try:
        accounts = await get_all_accounts()
    except Exception:
        return
    logged_in = [a for a in accounts if a.get("is_logged_in")]
    if not logged_in:
        return
    print(f"🔤 اتصالِ اولیه‌یِ {len(logged_in)} اکانتِ لاگین‌شده با زبانِ فارسی...")
    ok = 0
    stopped_early = False
    for acc in logged_in:
        if len(telethon_handler.clients_cache) >= telethon_handler.MAX_CACHED_CLIENTS:
            stopped_early = True
            break
        try:
            await ensure_client(acc["session_file"])
            ok += 1
        except Exception:
            pass
        await asyncio.sleep(random.uniform(0.3, 0.8))
    if stopped_early:
        print(f"🔤 {ok}/{len(logged_in)} اکانت وصل شد، بعد به سقفِ کانکشنِ هم‌زمان "
              f"({telethon_handler.MAX_CACHED_CLIENTS}) رسیدیم - بقیه هروقت لازم بشن خودکار وصل می‌شن.")
    else:
        print(f"🔤 {ok}/{len(logged_in)} اکانت با موفقیت با زبانِ فارسی وصل شدن.")


# ============================================================================
# هم‌زمانیِ ادمین‌ها - «کارِ یه ادمین، بقیه رو معطل نکنه»
# ----------------------------------------------------------------------------
# ⚠️ باگی که این‌جا حل شد: python-telegram-bot به‌صورتِ پیش‌فرض آپدیت‌ها رو *کاملاً
# سریالی* پردازش می‌کنه - یعنی تا وقتی هندلرِ یه آپدیت تموم نشده، هیچ آپدیتِ
# دیگه‌ای (حتی از یه ادمینِ کاملاً دیگه) شروع نمی‌شه. نتیجه: هر عملیاتِ طولانی‌ای
# (بررسیِ سلامت، تعویضِ سشن، تغییرِ پروفایل، پاکسازیِ چت‌ها) کلِ ربات رو برایِ
# *همه‌ی* ادمین‌ها می‌خوابوند. از دیدِ بقیه، ربات کاملاً هنگ کرده بود.
#
# راه‌حلِ ساده (concurrent_updates=True) خودش یه باگِ بدترِ دیگه می‌سازه: آپدیت‌هایِ
# *همون یک* ادمین هم موازی می‌شن و می‌تونن بی‌ترتیب اجرا بشن. برایِ رباتی که
# پُر از ویزاردِ چندمرحله‌ایه (context.user_data["awaiting"]، انتخابِ صفحه‌بندی‌شده،
# مراحلِ رمز)، این یعنی خرابیِ کاملِ فلو - مثلاً جوابِ مرحله‌یِ ۲ قبل از ثبتِ
# مرحله‌یِ ۱ پردازش بشه.
#
# راه‌حلِ درست: «سریالی برایِ هر ادمین، موازی بینِ ادمین‌ها». هر کاربر یه قفلِ
# اختصاصی داره؛ آپدیت‌هایِ خودش دقیقاً به ترتیب و یکی‌یکی اجرا می‌شن (پس هیچ
# ویزاردی خراب نمی‌شه)، ولی ادمین‌هایِ مختلف کاملاً مستقل و هم‌زمان کار می‌کنن.
# ============================================================================

# ارجاعِ سراسری به Application - تا ماژول‌هایِ پس‌زمینه (مثلاً نگهبانِ
# بی‌فعالیتی در humanize.py) بتونن به ادمین هشدار بدن، بدونِ اینکه لازم باشه
# application رو از هر تابعی به تابعِ بعدی پاس بدیم.
_APPLICATION = None


async def _notify_service_messages(session_file: str, pending: list) -> None:
    """ارسال one-shot پیام‌های جدید 777000؛ retry فقط در اتصال بعدی همان حساب."""
    if _APPLICATION is None or not ADMIN_USER_ID:
        return
    acc = await get_account_by_session(session_file)
    phone = (acc or {}).get("phone") or "نامشخص"
    for row in pending:
        text = (row.get("message_text") or "")
        payload = (f"📨 پیام رسمی Telegram برای اکانت {phone}\n"
                   f"🆔 پیام: {row.get('message_id')}\n\n{text}")
        try:
            # متن کامل حفظ می‌شود؛ برای محدودیت Bot API به قطعات ترتیبی تقسیم می‌کنیم.
            chunks = [payload[i:i + 3900] for i in range(0, len(payload), 3900)] or [payload]
            for chunk in chunks:
                await _APPLICATION.bot.send_message(chat_id=int(ADMIN_USER_ID), text=chunk)
            await mark_service_delivery(session_file, int(row["message_id"]), True)
        except Exception as exc:
            await mark_service_delivery(session_file, int(row["message_id"]), False, str(exc))
            break


async def notify_owner(text: str) -> bool:
    """
    یه پیامِ هشدار به مالکِ ربات می‌فرسته. best-effort: اگه ربات هنوز بالا
    نیومده یا ارسال شکست بخوره، بی‌صدا False برمی‌گردونه - هیچ حلقه‌ی
    پس‌زمینه‌ای نباید به‌خاطرِ نرسیدنِ یه پیام بشکنه.
    """
    if _APPLICATION is None or not ADMIN_USER_ID:
        return False
    try:
        await _APPLICATION.bot.send_message(chat_id=int(ADMIN_USER_ID), text=text)
        return True
    except Exception:
        return False


class PerAdminUpdateProcessor(BaseUpdateProcessor):
    """
    آپدیت‌هایِ هر کاربر را به ترتیب و یکی‌یکی پردازش می‌کند، ولی کاربرانِ مختلف را
    کاملاً هم‌زمان - تا عملیاتِ طولانیِ یک ادمین، بقیه‌ی ادمین‌ها را معطل نکند.
    """

    def __init__(self, max_concurrent: int = 256):
        super().__init__(max_concurrent_updates=max_concurrent)
        self._user_locks: dict = {}

    def _lock_for(self, update) -> asyncio.Lock:
        # آپدیت‌هایی که کاربرِ مشخصی ندارن، همه زیرِ یه کلیدِ مشترک می‌رن - این‌ها
        # نادرن و ترتیبشون هم مهم نیست
        user = getattr(update, "effective_user", None)
        key = user.id if user is not None else "__anonymous__"
        lock = self._user_locks.get(key)
        if lock is None:
            lock = asyncio.Lock()
            self._user_locks[key] = lock
        return lock

    async def do_process_update(self, update, coroutine):
        lock = self._lock_for(update)
        async with lock:
            await coroutine

    async def initialize(self) -> None:
        return None

    async def shutdown(self) -> None:
        self._user_locks.clear()


async def on_channel_post(update, context):
    """
    پستِ جدیدِ کانال رو ثبت می‌کنه - جایگزینِ پولینگِ ۴۵ ثانیه‌ایِ اکانت‌ها.

    ⚠️ چرا این هندلر اضافه شد: قبلاً موتورِ بازدیدِ خودکار برایِ فهمیدنِ «پستِ جدید
    اومده؟» هر ۴۵ ثانیه یه اکانتِ واقعی رو مجبور می‌کرد getHistory بزنه - روزی
    ۱۹۲۰ درخواست به‌ازایِ هر کانال، از یک اکانتِ ثابت، حتی وقتی کانال هیچ پستی
    نداشت. چون ربات ادمینِ کاناله، تلگرام پستِ جدید رو خودش بهش پوش می‌کنه؛ پس
    اون پولینگ از اساس زائد بود.

    ⚠️ باگی که اینجا رفع شد («ربات نمی‌فهمه پست زده شده»): این هندلر قبلاً در
    گروهِ ۰ و *بعد از* on_text/on_document ثبت شده بود. فیلترهایِ PTB مثلِ
    filters.TEXT پستِ کانال رو هم قبول می‌کنن، و در هر گروه فقط *اولین* هندلرِ
    منطبق اجرا می‌شه. پس هر پستِ متنی به on_text می‌رسید (که رویِ
    update.message=None کرش می‌کرد) و این هندلر هیچ‌وقت صدا زده نمی‌شد - یعنی
    ربات عملاً هیچ پستِ متنی‌ای رو نمی‌دید. حالا در گروهِ ۱- (قبل از همه) ثبت
    شده و با ApplicationHandlerStop پستِ کانال رو کلاً از هندلرهایِ ادمین دور
    نگه می‌داره.

    عمداً هیچ استثنایی بیرون نمی‌ده: این مسیرِ آپدیتِ رباته و نباید بشکنه.
    """
    try:
        post = getattr(update, "channel_post", None)
        chat = getattr(post, "chat", None) if post is not None else None
        if post is not None and chat is not None:
            username = getattr(chat, "username", None)
            channel_watch.record_post(
                chat_id=getattr(chat, "id", None),
                username=username,
                message_id=post.message_id,
                date=getattr(post, "date", None),
            )
            # همون لحظه زمان‌بندی کن، نه ۴۵ ثانیه بعد در اسکنِ دوره‌ای
            auto_view.notify_channel_post(username)
    except Exception:
        pass
    # پستِ کانال (و ویرایشش) هیچ ربطی به هندلرهایِ پنلِ ادمین نداره - نذار برسه
    raise ApplicationHandlerStop


async def on_my_chat_member(update, context):
    """
    وقتی ربات در یه کانال ادمین/حذف می‌شه، کشِ «ربات این کانال رو می‌بینه؟» رو
    همون لحظه درست کن - وگرنه تا ۳۰ دقیقه (WATCHABLE_TTL) جوابِ کهنه می‌موند.
    """
    try:
        cm = getattr(update, "my_chat_member", None)
        chat = getattr(cm, "chat", None)
        if chat is None or getattr(chat, "type", None) != "channel":
            return
        status = getattr(getattr(cm, "new_chat_member", None), "status", None)
        channel_watch.note_bot_status(getattr(chat, "username", None),
                                      str(getattr(status, "value", status)))
    except Exception:
        pass


# نوعِ آپدیت‌هایی که از تلگرام می‌خوایم. ⚠️ بدونِ این لیست، start_polling
# allowed_updates رو نمی‌فرسته و تلگرام از *آخرین تنظیمِ قبلی* استفاده می‌کنه -
# اگه یه بار (مثلاً با یه نسخه‌ی قدیمی یا وبهوکِ قبلی) channel_post از لیست
# افتاده باشه، ربات هیچ‌وقت پستِ کانال رو دریافت نمی‌کنه و هیچ خطایی هم نمی‌بینی.
BOT_ALLOWED_UPDATES = [
    "message",           # منو، دستورات، فایل و متنِ ادمین
    "callback_query",    # دکمه‌هایِ شیشه‌ای
    "channel_post",      # پستِ جدیدِ کانال‌ها - پایه‌یِ بازدیدِ خودکار
    "my_chat_member",    # ادمین‌شدن/حذف‌شدنِ ربات از کانال
]


async def start_bot():
    if not BOT_TOKEN or not ADMIN_USER_ID:
        print("⚠️  BOT_TOKEN یا ADMIN_USER_ID در فایلِ .env تنظیم نشده - رباتِ تلگرام غیرفعال می‌مونه (فقط داشبوردِ وب کار می‌کنه).")
        return None

    application = (
        Application.builder()
        .token(BOT_TOKEN)
        # نگاه کن به توضیحِ کاملِ PerAdminUpdateProcessor بالاتر: بدونِ این، کارِ
        # طولانیِ یه ادمین کلِ ربات رو برایِ بقیه قفل می‌کرد.
        .concurrent_updates(PerAdminUpdateProcessor())
        .build()
    )

    # اگه ربات وسطِ یه ایمپورتِ دسته‌ایِ سشن ری‌استارت شده باشه (مثلاً دیپلویِ Railway)،
    # فایل‌هایِ نیمه‌کاره‌ی داخلِ پوشه‌ی موقت باقی می‌مونن - همین اول پاکشون کن تا Volume
    # بی‌خودی پر نشه. اکانت‌هایی که *واقعاً* ثبت شده بودن دست‌نخورده‌ن (اونا از قبل به
    # پوشه‌ی اصلیِ sessions منتقل شدن) - نگاه کن به _session_import_tmp_dir.
    try:
        _cleanup_session_import_tmp()
    except Exception as e:
        print(f"⚠️  پاکسازیِ پوشه‌ی موقتِ ایمپورتِ سشن ناموفق بود: {e}")

    # مشابهِ بالا، ولی برایِ باقی‌مانده‌هایِ یه بازیابیِ بکاپِ چندتکه‌ایِ نیمه‌کاره
    # (ادمین وسطِ فرستادنِ تکه‌ها منصرف شد، یا ربات ری‌استارت شد) - نگاه کن به
    # _restore_parts_tmp_dir.
    try:
        _cleanup_stale_restore_parts()
        try:
            _stale_bk = _cleanup_stale_backup_tmp()
            if _stale_bk:
                print(f"🧹 {_stale_bk} پوشه‌یِ موقتِ بکاپِ جامانده از اجرایِ قبلی پاک شد.")
        except Exception:
            pass
    except Exception as e:
        print(f"⚠️  پاکسازیِ پوشه‌ی موقتِ بازیابیِ چندتکه‌ای ناموفق بود: {e}")

    # وزن‌هایِ سفارشیِ ری‌اکشن (اگه ادمین قبلاً از تنظیمات چیزی ذخیره کرده) رو همین
    # اولِ کار بارگذاری کن - وگرنه تا اولین ادیت، هنوز پیش‌فرضِ کدی اعمال می‌شد
    try:
        overrides = await get_reaction_weight_overrides()
        _apply_reaction_weight_overrides(overrides["select"], overrides["share"])
    except Exception as e:
        print(f"⚠️  نشد وزن‌هایِ سفارشیِ ری‌اکشن رو بارگذاری کنیم: {e}")

    # پستِ جدیدِ کانال‌ها - گروهِ ۱- یعنی *قبل از* همه‌ی هندلرهایِ ادمین. نگاه کن
    # به توضیحِ on_channel_post: در گروهِ ۰، on_text پستِ متنی رو می‌قاپید.
    application.add_handler(
        MessageHandler(filters.UpdateType.CHANNEL_POSTS, on_channel_post), group=-1
    )
    application.add_handler(
        ChatMemberHandler(on_my_chat_member, ChatMemberHandler.MY_CHAT_MEMBER), group=-1
    )
    application.add_handler(CommandHandler("start", cmd_start))
    application.add_handler(CommandHandler(["resume_email", "resume_login_email"], cmd_resume_login_email))
    application.add_handler(CallbackQueryHandler(on_callback))
    application.add_handler(MessageHandler(filters.Document.ALL, on_document))
    application.add_handler(MessageHandler((filters.PHOTO | filters.VIDEO) & filters.FORWARDED, on_forwarded_media))
    application.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, on_text))
    application.add_handler(CommandHandler("pair_accounts", cmd_pair_accounts))
    application.add_handler(CommandHandler("view_pairs", cmd_view_pairs))
    application.add_handler(CommandHandler("test_share", cmd_test_share))

    global _APPLICATION
    _APPLICATION = application
    # دیده‌بانِ کانال باید به نمونه‌ی Bot دسترسی داشته باشه تا بتونه با getChatMember
    # بپرسه «آیا من این کانال رو می‌بینم؟» - بدونِ درگیرکردنِ هیچ اکانتی
    channel_watch.set_bot(application.bot)
    set_service_message_notifier(_notify_service_messages)

    await application.initialize()
    try:
        await resume_interrupted_batches(application)
    except Exception as e:
        print(f"⚠️  ازسرگیریِ سفارش‌هایِ نیمه‌کاره با خطا مواجه شد: {e}")
    await application.start()
    await application.updater.start_polling(allowed_updates=BOT_ALLOWED_UPDATES)

    # بررسی اینکه آیا ادمین ثبت‌شده‌ای وجود داره یا نه
    try:
        admins = await get_all_admins()
        if not admins:
            # هیچ ادمین ثبت‌شده‌ای وجود نداره - پیامی برای ADMIN_USER_ID ارسال کن
            await application.bot.send_message(
                chat_id=ADMIN_USER_ID,
                text="⚠️ هشدار: هیچ ادمین ثبت‌شده‌ای در سیستم وجود ندارد.\n\nما ادمین نیستید! 🛑"
            )
            print("⚠️  هیچ ادمین ثبت‌شده‌ای در سیستم وجود ندارد - پیام هشداری ارسال شد.")
    except Exception as e:
        print(f"⚠️  بررسیِ وضعیتِ ادمین با خطا مواجه شد: {e}")
    
    global _auto_backup_task
    _auto_backup_task = asyncio.create_task(auto_backup_loop(application))
    application.bot_data["auto_backup_task"] = _auto_backup_task
    asyncio.create_task(auto_terminate_sessions_loop())
    # این یک حلقه، الان مسئولِ *هر دویِ* «🔄 تعویضِ سشن» و «🔐 بیرون‌انداختنِ
    # نشست‌هایِ فعال» است - نگاه کن به توضیحِ یکپارچه‌سازی بالایِ
    # _register_terminate_retry.
    asyncio.create_task(session_migration_retry_loop(application))
    asyncio.create_task(_startup_sync_migration_records())
    asyncio.create_task(_reconnect_all_accounts_persian())
    asyncio.create_task(event_loop_watchdog_loop())

    # ---- وصل‌شدن به سیستمِ یگانه‌ی حافظه ----
    # gc.freeze + آستانه‌هایِ مناسبِ یه پردازه‌ی بلندمدت. این‌جا (بعدِ کاملِ
    # راه‌اندازی) صدا زده می‌شه تا همه‌ی آبجکت‌هایِ ثابتِ زمانِ بالا آمدن یک‌جا به
    # نسلِ «همیشه-زنده» بروند و در هیچ اسکنی شمرده نشوند.
    memory_hygiene.tune_gc()
    # سه رجیستریِ در-حافظه‌ی این فایل. هر سه در مسیرِ عادی خودشان پاک می‌شوند، ولی
    # اگه یه تسک وسطِ راه کرش/کنسل شود، کلیدِ مرده تا ری‌استارت می‌ماند. با live_keys
    # هر پاکسازیِ دوره‌ای همان کلیدهایِ مرده را می‌چیند.
    memory_hygiene.register_cache(
        "ربات · سفارش‌هایِ درحالِ‌اجرا", RUNNING_JOBS,
        live_keys=lambda: [k for k, p in list(RUNNING_JOBS.items())
                           if not getattr(p, "finished", False)],
    )
    memory_hygiene.register_cache(
        "ربات · منتظرانِ کدِ لاگین", _LOGIN_CODE_WAITERS,
        live_keys=lambda: [k for k, t in list(_LOGIN_CODE_WAITERS.items())
                           if t is not None and not t.done()],
    )
    try:
        import scheduling as _sched
        memory_hygiene.register_cache(
            "ربات · دسته‌هایِ فعال", _sched.ACTIVE_BATCHES,
            live_keys=lambda: [k for k, v in list(_sched.ACTIVE_BATCHES.items())
                               if not getattr(v.get("progress"), "finished", False)],
        )
    except Exception:
        pass
    print("✅ رباتِ تلگرام روشن شد و آماده‌ی دریافتِ پیامه.")
    print(f"🔄 بکاپِ خودکار هر {_fmt_backup_interval(await _current_backup_minutes())} فرستاده می‌شه"
          + (" (پاکسازیِ خودکارِ بکاپ‌هایِ قدیمی: خاموش)." if BACKUP_RETENTION_DAYS <= 0
             else f" (نگه‌داریِ {BACKUP_RETENTION_DAYS} روزِ اخیر)."))
    return application


async def stop_bot(application):
    """خاموش‌کردنِ تمیزِ ربات موقعِ بستنِ برنامه"""
    if not application:
        return
    global _auto_backup_task
    try:
        if _auto_backup_task and not _auto_backup_task.done():
            _auto_backup_task.cancel()
            try:
                await _auto_backup_task
            except asyncio.CancelledError:
                pass
            _auto_backup_task = None
        await application.updater.stop()
        await application.stop()
        await application.shutdown()
    except Exception:
        pass


# ================ Peer Pair Management UI ================
# جفت‌کردنِ *دستیِ* دو اکانت - برایِ وقتی می‌خوای خودت انتخاب کنی کی با کی جفت بشه،
# به‌جایِ اینکه حلقه‌ی خودکار (peer_share.peer_pairs_loop) رندوم جفتشون کنه.
# هر دو مسیر به همون یک موتور می‌رسن، پس نتیجه‌شون کاملاً یکدسته.


@restricted
async def cmd_pair_accounts(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """شروعِ فرآیندِ جفت‌کردنِ دستیِ دو اکانت برایِ شیرِ پست."""
    accounts_list = await get_all_accounts()
    if len(accounts_list) < 2:
        await update.message.reply_text("برایِ جفت‌کردن حداقل به ۲ اکانت نیاز داری.")
        return

    taken = await get_accounts_in_peer_pairs()
    free = [a for a in accounts_list if a["id"] not in taken]
    if len(free) < 2:
        text, markup = await build_share_pairs_view()
        await update.message.reply_text(
            "همه‌ی اکانت‌ها از قبل جفت دارن (هر اکانت فقط می‌تونه توی یک جفت باشه).\n\n" + text,
            reply_markup=markup
        )
        return

    kb = [
        [InlineKeyboardButton(
            f"{acc.get('nickname') or acc['phone']}",
            callback_data=f"pp_pair_a:{acc['id']}"
        )]
        for acc in free[:20]
    ]
    await update.message.reply_text(
        "اکانتِ اول رو انتخاب کن (فقط اکانت‌هایِ بی‌جفت):",
        reply_markup=InlineKeyboardMarkup(kb)
    )


@restricted
async def cmd_view_pairs(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """نمایشِ همه‌یِ جفت‌ها - همون صفحه‌ی «👥 جفت‌هایِ شیر»."""
    text, markup = await build_share_pairs_list(0)
    await update.message.reply_text(text, reply_markup=markup)


@restricted
async def cmd_test_share(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """
    تستِ دستیِ یه گفت‌وگویِ کاملِ شیر رویِ یه پستِ واقعی:
        /test_share <لینکِ پست>
    یه جفتِ آماده انتخاب می‌شه و کلِ سناریو (سلام → فوروارد → دیده‌شدن → تشکر) اجرا
    می‌شه، بعد دقیقاً گزارش می‌ده کدوم قدم‌ها انجام شدن.
    """
    args = context.args
    if not args:
        await update.message.reply_text(
            "فرمتِ درست: /test_share <لینکِ پست>\n"
            "مثلاً: /test_share https://t.me/channel/123"
        )
        return

    link_info = parse_post_link(" ".join(args))
    if not link_info:
        await update.message.reply_text(
            "❌ لینک معتبر نیست. باید شبیهِ https://t.me/channel/123 (عمومی) یا "
            "https://t.me/c/1234567890/123 (خصوصی) باشه."
        )
        return

    slots = await peer_share.select_share_slots(1)
    if not slots:
        await update.message.reply_text(
            "❌ هیچ جفتِ آماده‌ای نیست. از «👥 جفت‌هایِ شیر» یه جفت آماده کن."
        )
        return

    slot = slots[0]
    status_msg = await update.message.reply_text(
        f"⏳ در حالِ اجرایِ یه گفت‌وگویِ کاملِ شیر بینِ اکانتِ "
        f"«{slot.get('nickname') or slot.get('phone')}» و جفتش..."
    )
    result = await peer_share.run_share_conversation(slot, link_info)
    steps = "، ".join(result.get("steps") or []) or "هیچ‌کدوم"
    if result.get("status") == "success":
        await status_msg.edit_text(f"✅ شیر انجام شد.\nقدم‌هایِ انجام‌شده: {steps}")
    else:
        await status_msg.edit_text(
            f"❌ شیر ناموفق بود: {result.get('message', 'نامشخص')}\n"
            f"قدم‌هایِ انجام‌شده تا لحظه‌ی شکست: {steps}"
        )


async def _pp_show_second_account_menu(query, account_a_id: int):
    taken = await get_accounts_in_peer_pairs()
    accounts_list = [a for a in await get_all_accounts()
                     if a["id"] != account_a_id and a["id"] not in taken]
    if not accounts_list:
        await query.edit_message_text("هیچ اکانتِ بی‌جفتِ دیگه‌ای نمونده.")
        return
    kb = [
        [InlineKeyboardButton(
            f"{acc.get('nickname') or acc['phone']}",
            callback_data=f"pp_pair_b:{account_a_id}:{acc['id']}"
        )]
        for acc in accounts_list[:20]
    ]
    await query.edit_message_text(
        "اکانتِ دوم رو برایِ جفت‌شدن انتخاب کن:", reply_markup=InlineKeyboardMarkup(kb)
    )


async def _pp_create_pair_and_exchange(query, account_a_id: int, account_b_id: int):
    """
    جفت رو ثبت می‌کنه و **همون لحظه** مخاطب‌گیریش رو انجام می‌ده (چون کاربر خودش
    درخواست کرده و منتظره) - برخلافِ حلقه‌ی خودکار که عمداً قطره‌قطره کار می‌کنه.
    """
    planned = await plan_peer_pair(account_a_id, account_b_id)
    if planned.get("status") != "success":
        await query.edit_message_text(
            f"❌ ثبتِ جفت نشد: {planned.get('message', 'نامشخص')}\n"
            "(هر اکانت فقط می‌تونه توی یک جفت باشه.)"
        )
        return

    await query.edit_message_text(
        "⏳ جفت ثبت شد. حالا هر دو اکانت شماره‌یِ همدیگه رو به مخاطبینشون اضافه می‌کنن..."
    )

    async def _finish():
        try:
            # ⚠️ حتماً با آیدیِ *همین* جفت: قبلاً build_one_pair() بدونِ آرگومان صدا
            # زده می‌شد و قدیمی‌ترین جفتِ صف رو می‌ساخت - یعنی پیامِ «جفتت آماده شد»
            # می‌تونست مربوط به جفتِ یکی دیگه باشه، و جفتِ خودِ کاربر دست‌نخورده
            # توی صف می‌موند.
            result = await peer_share.build_one_pair(planned.get("id"))
        except Exception as e:
            result = {"status": "error", "message": str(e)}
        if result.get("status") == "ready":
            phones = " ↔ ".join(result.get("phones") or []) or "هر دو طرف"
            text = ("✅ جفت آماده شد - هر دو اکانت شماره‌یِ واقعیِ همدیگه رو ذخیره کردن "
                    f"و از این به بعد می‌تونن برایِ هم پست بفرستن.\n📞 {phones}")
            if result.get("healed_phones"):
                text += ("\n♻️ شماره‌ی این اکانت‌ها با شماره‌ی واقعیِ سشنشون اصلاح شد: "
                         + "، ".join(result["healed_phones"]))
        elif result.get("status") == "flood":
            text = (f"⏳ تلگرام موقتاً محدودمون کرد ({result.get('seconds')} ثانیه). "
                    "این جفت توی صف مونده و خودکار دوباره امتحان می‌شه.")
        else:
            text = (f"⚠️ مخاطب‌گیری کامل نشد: {result.get('message', 'نامشخص')}\n"
                    "جفت توی صف می‌مونه و حلقه‌ی خودکار بازم امتحان می‌کنه.")
        await query.message.reply_text(text)

    asyncio.create_task(_finish())
